-- Камхак — свободная камера
camHackActive  = false
camHackX, camHackY, camHackZ = 0, 0, 0
camHackYaw     = 0.0
camHackPitch   = 0.0
camHackSpeed   = 0.5
camHackFOV     = imgui.new.float(70.0)
camHackLooking = false

local masterCamHook
