local function InspectCam_Process(cam)
    if camHackActive then
        if sampIsChatInputActive() then
            return 1
        end

        local rmbDown = isKeyDown(0x02)

        if rmbDown then
            if not camHackLooking then
                camHackLooking = true
            end
            local mx, my = getPcMouseMovement()
            camHackYaw   = (camHackYaw - math.rad(mx / 4)) % (math.pi * 2)
            camHackPitch = camHackPitch - math.rad(-my / 4)
            if camHackPitch > math.pi/2 - 0.01 then camHackPitch = math.pi/2 - 0.01 end
            if camHackPitch < -math.pi/2 + 0.01 then camHackPitch = -math.pi/2 + 0.01 end
        elseif camHackLooking then
            camHackLooking = false
        end

        local fx = -math.cos(camHackYaw) * math.cos(camHackPitch)
        local fy = -math.sin(camHackYaw) * math.cos(camHackPitch)
        local fz = math.sin(camHackPitch)

        local speed = camHackSpeed
        if isKeyDown(0xA0) or isKeyDown(0xA1) then speed = speed * 3 end -- Shift = ускорение

        if isKeyDown(0x57) then -- W
            camHackX = camHackX - speed * math.cos(camHackYaw)
            camHackY = camHackY - speed * math.sin(camHackYaw)
        end
        if isKeyDown(0x53) then -- S
            camHackX = camHackX + speed * math.cos(camHackYaw)
            camHackY = camHackY + speed * math.sin(camHackYaw)
        end
        if isKeyDown(0x41) then -- A
            camHackX = camHackX + speed * math.cos(camHackYaw - math.pi/2)
            camHackY = camHackY + speed * math.sin(camHackYaw - math.pi/2)
        end
        if isKeyDown(0x44) then -- D
            camHackX = camHackX + speed * math.cos(camHackYaw + math.pi/2)
            camHackY = camHackY + speed * math.sin(camHackYaw + math.pi/2)
        end
        if isKeyDown(0x49) or isKeyDown(0x20) then camHackZ = camHackZ + speed end -- I / Space = вверх
        if isKeyDown(0x4B) or isKeyDown(0x11) then camHackZ = camHackZ - speed end -- K / Ctrl = вниз

        cam.vecSource.x = camHackX
        cam.vecSource.y = camHackY
        cam.vecSource.z = camHackZ
        cam.vecFront.x = fx
        cam.vecFront.y = fy
        cam.vecFront.z = fz
        cam.vecUp.x = -math.tan(camHackPitch) * fx
        cam.vecUp.y = -math.tan(camHackPitch) * fy
        cam.vecUp.z = math.cos(camHackPitch)

        if samem.camera.bTransitionState then
            samem.camera.bTransitionState = false
        end
        cam.fFOV = camHackFOV[0]
        return 1
    end

    local rmbDown = isKeyDown(0x02) -- ПКМ — как в камхаке: смотреть можно только пока зажата

    if rmbDown then
        local mx, my = getPcMouseMovement()
        inspectCamAngleX = (inspectCamAngleX - math.rad(mx / 4)) % (math.pi * 2)
        inspectCamAngleY = inspectCamAngleY - math.rad(-my / 4)
        if inspectCamAngleY > math.pi/2 - 0.01 then inspectCamAngleY = math.pi/2 - 0.01 end
        if inspectCamAngleY < -math.pi/2 + 0.01 then inspectCamAngleY = -math.pi/2 + 0.01 end
    end

    local fx = -math.cos(inspectCamAngleX) * math.cos(inspectCamAngleY)
    local fy = -math.sin(inspectCamAngleX) * math.cos(inspectCamAngleY)
    local fz = math.sin(inspectCamAngleY)

    if rmbDown then
        if not inspectFlying then
            -- только что зажали ПКМ - запоминаем текущую позицию камеры как стартовую для полёта
            inspectFreeX = inspectObjX - fx * inspectCamDist[0]
            inspectFreeY = inspectObjY - fy * inspectCamDist[0]
            inspectFreeZ = inspectObjZ - fz * inspectCamDist[0]
            inspectFlying = true
        end

        local yaw = inspectCamAngleX
        local speed = inspectFlySpeed
        if isKeyDown(0xA0) or isKeyDown(0xA1) then speed = speed * 3 end -- Shift = ускорение, как в камхаке

        if isKeyDown(0x57) then -- W = вперёд
            inspectFreeX = inspectFreeX - speed * math.cos(yaw)
            inspectFreeY = inspectFreeY - speed * math.sin(yaw)
        end
        if isKeyDown(0x53) then -- S = назад
            inspectFreeX = inspectFreeX + speed * math.cos(yaw)
            inspectFreeY = inspectFreeY + speed * math.sin(yaw)
        end
        if isKeyDown(0x41) then -- A = влево
            inspectFreeX = inspectFreeX + speed * math.cos(yaw - math.pi/2)
            inspectFreeY = inspectFreeY + speed * math.sin(yaw - math.pi/2)
        end
        if isKeyDown(0x44) then -- D = вправо
            inspectFreeX = inspectFreeX + speed * math.cos(yaw + math.pi/2)
            inspectFreeY = inspectFreeY + speed * math.sin(yaw + math.pi/2)
        end
        if isKeyDown(0x20) then inspectFreeZ = inspectFreeZ + speed end -- Space = вверх
        if isKeyDown(0x11) then inspectFreeZ = inspectFreeZ - speed end -- Ctrl = вниз

        cam.vecSource.x = inspectFreeX
        cam.vecSource.y = inspectFreeY
        cam.vecSource.z = inspectFreeZ
    else
        if inspectFlying then
            -- только что отпустили ПКМ - пересчитываем дистанцию, чтобы не было рывка камеры
            local dx = inspectObjX - inspectFreeX
            local dy = inspectObjY - inspectFreeY
            local dz = inspectObjZ - inspectFreeZ
            inspectCamDist[0] = math.sqrt(dx*dx + dy*dy + dz*dz)
            inspectFlying = false
        end

        cam.vecSource.x = inspectObjX - fx * inspectCamDist[0]
        cam.vecSource.y = inspectObjY - fy * inspectCamDist[0]
        cam.vecSource.z = inspectObjZ - fz * inspectCamDist[0]
    end

    cam.vecFront.x = fx
    cam.vecFront.y = fy
    cam.vecFront.z = fz

    cam.vecUp.x = -math.tan(inspectCamAngleY) * fx
    cam.vecUp.y = -math.tan(inspectCamAngleY) * fy
    cam.vecUp.z = math.cos(inspectCamAngleY)

    if samem.camera.bTransitionState then
        samem.camera.bTransitionState = false
    end

    cam.fFOV = inspectCamFOV[0]

    return 1
end

local function SceneCam_Process(cam)
    if sampIsChatInputActive() then return 1 end

    local rmbDown = isKeyDown(0x02)

    if rmbDown then
        local mx, my = getPcMouseMovement()
        sceneCamYaw   = (sceneCamYaw - math.rad(mx / 4)) % (math.pi * 2)
        sceneCamPitch = sceneCamPitch - math.rad(-my / 4)
        if sceneCamPitch > math.pi/2 - 0.01 then sceneCamPitch = math.pi/2 - 0.01 end
        if sceneCamPitch < -math.pi/2 + 0.01 then sceneCamPitch = -math.pi/2 + 0.01 end
    end

    local fx = -math.cos(sceneCamYaw) * math.cos(sceneCamPitch)
    local fy = -math.sin(sceneCamYaw) * math.cos(sceneCamPitch)
    local fz = math.sin(sceneCamPitch)

    if rmbDown then
        local speed = sceneCamSpeed
        if isKeyDown(0xA0) or isKeyDown(0xA1) then speed = speed * 3 end

        if isKeyDown(0x57) then sceneCamX = sceneCamX - speed * math.cos(sceneCamYaw); sceneCamY = sceneCamY - speed * math.sin(sceneCamYaw) end
        if isKeyDown(0x53) then sceneCamX = sceneCamX + speed * math.cos(sceneCamYaw); sceneCamY = sceneCamY + speed * math.sin(sceneCamYaw) end
        if isKeyDown(0x41) then sceneCamX = sceneCamX + speed * math.cos(sceneCamYaw - math.pi/2); sceneCamY = sceneCamY + speed * math.sin(sceneCamYaw - math.pi/2) end
        if isKeyDown(0x44) then sceneCamX = sceneCamX + speed * math.cos(sceneCamYaw + math.pi/2); sceneCamY = sceneCamY + speed * math.sin(sceneCamYaw + math.pi/2) end
        if isKeyDown(0x20) then sceneCamZ = sceneCamZ + speed end
        if isKeyDown(0x11) then sceneCamZ = sceneCamZ - speed end
    end

    cam.vecSource.x = sceneCamX
    cam.vecSource.y = sceneCamY
    cam.vecSource.z = sceneCamZ
    cam.vecFront.x = fx
    cam.vecFront.y = fy
    cam.vecFront.z = fz
    cam.vecUp.x = -math.tan(sceneCamPitch) * fx
    cam.vecUp.y = -math.tan(sceneCamPitch) * fy
    cam.vecUp.z = math.cos(sceneCamPitch)

    if samem.camera.bTransitionState then samem.camera.bTransitionState = false end
    cam.fFOV = sceneCamFOV[0]
    return 1
end

local function MasterCam_Process(cam)
    if sceneEditorActive then
        return SceneCam_Process(cam)
    elseif camHackActive or inspectActive then
        return InspectCam_Process(cam)
    end
    return 1
end

masterCamHook = hook_t.jmp.new("void(__thiscall*)(CCam *this)", MasterCam_Process, 0x526FC0)
masterCamHook.stop()
inspectCamHook = masterCamHook
sceneCamHook = masterCamHook

