local WhiteAccessories = {} -- ID аксессуаров, которые не будут скрываться. Пример: {18912, 18913}
local attachCache = {}      -- attachCache[playerId][index] = {modelId=, bone=} — что сейчас реально надето

local function isAccessoryProtected(modelId, bone)
    if bone == 5 or bone == 6 then return true end
    for _, val in ipairs(WhiteAccessories) do
        if modelId == val then return true end
    end
    return false
end

-- Принудительно снимает уже надетые аксессуары со всех видимых игроков
local function hideExistingAccessories()
    local ok, success, ids = pcall(sampGetPlayerIdArray)
    if not ok or not success or type(ids) ~= "table" then return end
    for _, pid in ipairs(ids) do
        local cache = attachCache[pid]
        if cache then
            for index, info in pairs(cache) do
                if not isAccessoryProtected(info.modelId, info.bone) then
                    pcall(sampSetPlayerAttachedObject, pid, index, false)
                    cache[index] = nil
                end
            end
        end
    end
end

sampev.onSetPlayerAttachedObject = function(playerId, index, create, object)
    attachCache[playerId] = attachCache[playerId] or {}
    if create and object then
        attachCache[playerId][index] = {modelId = object.modelId, bone = object.bone}
    else
        attachCache[playerId][index] = nil
    end

    if not (checkboxRenderAll or checkboxRenderIDsByRule) then
        return {playerId, index, create, object}
    end

    if not create or not object then
        return {playerId, index, create, object}
    end

    if isAccessoryProtected(object.modelId, object.bone) then
        return {playerId, index, create, object}
    else
        return false
    end
end


