-- EVENT BLOCK AUTO-CONFIGURATOR (Таблица и предварительное объявление)
-- ============================================================================
local eblock = {}

sampev.onServerMessage = function(color, msg)
    if eblock and eblock.onServerMessage then
        local handled = eblock.onServerMessage(color, msg)
        if handled then return false end
    end

    local cleanMsg = msg:gsub("{%x%x%x%x%x%x}", "")

    -- Проверка на блокировку сервера: отмена спавна префаба и генерации
    local lowerMsg = cleanMsg:lower()
    if (lowerMsg:find("не можете использовать", 1, true) and lowerMsg:find("в данный момент", 1, true))
       or lowerMsg:find("эту возможность в данный момент", 1, true)
       or lowerMsg:find("возможность в данный момент", 1, true)
       or (lowerMsg:find("нельзя использовать", 1, true) and lowerMsg:find("в данный момент", 1, true)) then
        if prefabPlaying then
            prefabPlaying = false
            pcall(freezeCharPosition, PLAYER_PED, false)
            pcall(lockPlayerControl, false)
            showToastQuick("Префабы", "Спавн остановлен сервером")
            sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Спавн префаба {E74C3C}остановлен{FFFFFF}!", -1)
            sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Сервер отклонил команду {AAAAAA}(действие недоступно){FFFFFF}.", -1)
        end
        if arrayRunning then
            arrayRunning = false
            pcall(freezeCharPosition, PLAYER_PED, false)
            showToastQuick("Генератор рядов", "Создание ряда остановлено")
            sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Создание ряда {E74C3C}остановлено{FFFFFF}!", -1)
            sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Сервер отклонил команду {AAAAAA}(действие недоступно){FFFFFF}.", -1)
        end
    end

    -- Авто-завершение /map перед открытием скрипта /scr
    if cleanMsg:find("Завершите процесс редактирования ивент карты", 1, true) then
        local retryId = lastSentScrId
        if (os.clock() - (lastSentScrTime or 0)) < 6.0 then
            lastSentScrTime = 0
            lua_thread.create(function()
                if retryId and retryId ~= "" then
                    sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Завершаем режим {FF9326}/map{FFFFFF} и открываем скрипт {FF9326}#%s{FFFFFF}...", tostring(retryId)), -1)
                    sampSendChat("/map")
                    wait(450)
                    sampSendChat("/scr " .. tostring(retryId))
                else
                    sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Завершаем режим {FF9326}/map{FFFFFF}...", -1)
                    sampSendChat("/map")
                    wait(450)
                    sampSendChat("/scr")
                end
            end)
            return false
        end
    end
    if oinfoSilentPendingId and (os.clock() < (oinfoSilentExpireTime or 0)) then
        local cleanMsg = msg:gsub("{%x%x%x%x%x%x}", "")
        if cleanMsg:find("базы данных", 1, true) or cleanMsg:find("Ждем ответа", 1, true) then
            local retryId = oinfoSilentPendingId
            lua_thread.create(function()
                wait(1000)
                if objScanEnabled and objScanResult and tostring(objScanResult.id) == tostring(retryId) and not oinfoCache[tostring(retryId)]
                   and not otextQueueActive and not otextPendingApplyAfterCreate and os.clock() > (otextBusyUntil or 0) then
                    oinfoSilentPendingId = retryId
                    oinfoSilentExpireTime = os.clock() + 4.0
                    oinfoLastReqTime = os.clock()
                    sampSendChat("/oinfo " .. tostring(retryId))
                end
            end)
            return false
        end
    end

    local id = msg:match("#(%d+)%.")
    if id and msg:find("\xf0\xe5\xe4\xe0\xea\xf2") then
        lastEditedObjId = id
    end

    -- Очистка текста от цветовых тегов
    local clean = msg:gsub("{%x%x%x%x%x%x}", "")

    
    -- "Вы успешно создали новый ивент блок {CC6666}#5{ffffff}." - выхватываем ID нового блока
    local newBlockId = clean:match("Вы успешно создали новый ивент блок%s*#(%d+)")
                    or clean:match("создали новый ивент блок%s*#(%d+)")
                    or clean:match("новый ивент блок%s*#(%d+)")
                    or clean:match("ивент блок%s*#(%d+)")
                    or msg:match("\xe1\xeb\xee\xea%s*{%x%x%x%x%x%x}#(%d+)")
    if newBlockId and (pendingNewBlockScriptId or scriptViewId) then
        local targetSid = pendingNewBlockScriptId or scriptViewId
        local blocks = scriptBlocks[targetSid] or {}
        local updated = false
        for j = #blocks, 1, -1 do
            if not blocks[j].serverId then
                blocks[j].serverId = tonumber(newBlockId)
                updated = true
                break
            end
        end
        if updated then
            scriptBlocks[targetSid] = blocks
            saveScriptBlocks()
            toast_text  = "Ивент-блок #" .. tostring(newBlockId) .. " привязан"
            toast_text2 = ""
            toast_tex   = nil
            toast_timer = 120
        end
        pendingNewBlockScriptId = nil
    end

    -- Уведомление по /glist и /grouplist и отслеживание /ged:
    local gedStartId = clean:match("Запущено редактирование группы элементов%s*#(%d+)")
    if gedStartId then
        activeEditingGroupId = gedStartId
        objEditorActive = true
    end
    local clonedGrpId = clean:match("Группа успешно клонирована и ей присвоен ID%s*#(%d+)")
    if clonedGrpId then
        activeEditingGroupId = clonedGrpId
        objEditorActive = true
        lua_thread.create(function()
            wait(150)
            sampSendChat("/ged " .. tostring(clonedGrpId))
        end)
    end
    if clean:find("Группа элементов", 1, true) and clean:find("успешно передвинута", 1, true) then
        activeEditingGroupId = nil
        objEditorActive = false
    end
    local groupId, objCount = clean:match("группе #(%d+) привязано (%d+) ивент")
    if groupId and objCount and notifyGlistEnabled then
        toast_text  = "Группа #" .. groupId .. " имеет " .. objCount .. " объектов."
        toast_text2 = ""
        toast_tex   = nil
        toast_timer = 150
    end

    -- Журнал истории действий (парсинг серверных сообщений об объектах и группах):
    local lowClean = cyrLower(clean)
    if clonedGrpId then
        addActionLog("group", nil, nil, "Клонирована группа — новый ID #" .. tostring(clonedGrpId), clean, "/ged " .. tostring(clonedGrpId))
    elseif gedStartId then
        addActionLog("group", nil, nil, "Начато редактирование группы #" .. tostring(gedStartId), clean, "/ged " .. tostring(gedStartId))
    elseif lowClean:find("успешно передвинута", 1, true) and lowClean:find("группа", 1, true) then
        local movedGid = clean:match("#(%d+)")
        addActionLog("group", nil, nil, "Передвинута группа #" .. tostring(movedGid or "?"), clean, movedGid and ("/ged " .. movedGid) or "")
    elseif lowClean:find("успешно удален", 1, true) or lowClean:find("успешно удалён", 1, true) or lowClean:find("удален объект", 1, true) or lowClean:find("удалён объект", 1, true) or (lowClean:find("объект", 1, true) and lowClean:find("удален", 1, true)) then
        local delId = clean:match("#(%d+)") or lastPendingObjId
        if delId then
            local mId, mName = resolveMapObjModel(delId, nil)
            local ttl = "Удалён объект #" .. tostring(delId)
            if mId then
                ttl = "Удалён объект #" .. tostring(delId) .. " (ID модели: #" .. tostring(mId) .. (mName ~= "" and (" — " .. mName) or "") .. ")"
            end
            addActionLog("delete", delId, mId, ttl, clean, mId and ("/cr " .. tostring(mId)) or "")
        end
    elseif (lowClean:find("создан", 1, true) or lowClean:find("клонирован", 1, true)) and (lowClean:find("объект", 1, true) or lowClean:find("элемент", 1, true)) then
        local crObjId = clean:match("#(%d+)")
        local isCloneMsg = lowClean:find("клонирован", 1, true) ~= nil
        local mId = lastPendingModelId
        if not mId and crObjId then
            mId = select(1, resolveMapObjModel(crObjId, nil))
        end
        local mName = getModelNameById(mId)
        local actionPrefix = isCloneMsg and "Клонирован объект" or "Создан объект"
        local ttl = actionPrefix .. (crObjId and (" #" .. tostring(crObjId)) or "")
        if mId then
            ttl = ttl .. " (ID модели: #" .. tostring(mId) .. (mName ~= "" and (" — " .. mName) or "") .. ")"
        end
        addActionLog("create", crObjId, mId, ttl, clean, crObjId and ("/gotoo " .. tostring(crObjId)) or "")
    elseif clean:find("установлен текст", 1, true) and clean:find("ивент объекта", 1, true) then
        local matNum, objNum, txtVal = clean:match("На материал%s*#(%d+)%s*ивент объекта%s*#(%d+)%s*установлен текст%s*(.-)%.?$")
        if objNum then
            otextLastObjId = tostring(objNum)
            lastEditedObjId = tostring(objNum)
        end
        if matNum then
            otextLastMatSlot = tonumber(matNum) or 0
        end
        addActionLog("tex", objNum, nil, "Установлен текст на объект #" .. tostring(objNum or "?") .. " (мат. #" .. tostring(matNum or "0") .. ")", clean, "/otext")
        if otextPendingApplyAfterCreate then
            otextPendingApplyAfterCreate = false
            otextBusyUntil = os.clock() + 15.0
            oinfoSilentPendingId = nil
            oinfoSilentExpireTime = 0
            lua_thread.create(function()
                wait(500)
                startOtextApplyAllQueue(false)
            end)
        end
    end

    -- Отслеживание установки текстуры из серверного сообщения (/mt, /mts, /mtset)
    -- "На материал {FF8282}#0{ffffff} ивент объекта {FFFF00}#10{ffffff} установлена текстура {abcdef}#1165 - 3922 bistro mp_snow{ffffff}."
    local texMatSlot, texObjNum, texTexId, texName = clean:match("материал%s*#(%d+)%s*.-объекта%s*#(%d+)%s*установлена%s*текстура%s*#(%d+)%s*-%s*(.-)%.?$")
    if not texMatSlot then
        texMatSlot, texObjNum, texTexId = clean:match("материал%s*#(%d+)%s*.-объекта%s*#(%d+)%s*установлена%s*текстура%s*#(%d+)")
    end
    if texMatSlot and texObjNum and texTexId then
        local sObj = tostring(texObjNum)
        local sMat = tostring(texMatSlot)
        local sTex = tostring(texTexId)
        trackedObjMaterials[sObj] = trackedObjMaterials[sObj] or {}
        trackedObjMaterials[sObj][sMat] = sTex
        lastEditedObjId = sObj

        local mId, mName = resolveMapObjModel(sObj, nil)
        local ttl = string.format("Текстура #%s на объект #%s (слот %s)", sTex, sObj, sMat)
        if texName and texName ~= "" then
            ttl = ttl .. " — " .. texName
        end
        addActionLog("tex", sObj, mId, ttl, clean, string.format("/mtset %s %s", sMat, sTex))
    end

    -- Отслеживание снятия/удаления текстуры с объекта
    local remMatSlot, remObjNum = clean:match("материал%s*#(%d+)%s*.-объекта%s*#(%d+)%s*.-[сС]нята%s*текстура")
    if not remMatSlot then
        remMatSlot, remObjNum = clean:match("материал%s*#(%d+)%s*.-объекта%s*#(%d+)%s*.-[уУ]далена%s*текстура")
    end
    if remMatSlot and remObjNum then
        local sObj = tostring(remObjNum)
        local sMat = tostring(remMatSlot)
        if trackedObjMaterials[sObj] then
            trackedObjMaterials[sObj][sMat] = nil
        end
        local mId, mName = resolveMapObjModel(sObj, nil)
        local ttl = string.format("Снята текстура с объекта #%s (слот %s)", sObj, sMat)
        addActionLog("tex", sObj, mId, ttl, clean, string.format("/mtset %s 0", sMat))
    end
end


