function patchSampTimeSet(enable)
    local ok, base = pcall(sampGetBase)
    if not ok or not base or base == 0 then return end
    if enable and vwTimePatchDefault == nil then
        vwTimePatchDefault = readMemory(base + 0x9C0A0, 4, true)
        writeMemory(base + 0x9C0A0, 4, 0x000008C2, true)
    elseif not enable and vwTimePatchDefault ~= nil then
        writeMemory(base + 0x9C0A0, 4, vwTimePatchDefault, true)
        vwTimePatchDefault = nil
    end
end

function applyVwTime(h, m, lockIt)
    vwHour[0] = math.max(0, math.min(23, tonumber(h) or 12))
    vwMinute[0] = math.max(0, math.min(59, tonumber(m) or 0))
    if lockIt ~= nil then vwLockTime[0] = lockIt end
    patchSampTimeSet(vwLockTime[0])
    pcall(setTimeOfDay, vwHour[0], vwMinute[0])
end

vwServerHour = 12
vwServerMinute = 0
vwServerWeather = 0
vwCustomWeatherActive = false

sampev.onSetWeather = function(weatherId)
    vwServerWeather = tonumber(weatherId) or 0
    if vwCustomWeatherActive then
        return false
    end
end

sampev.onSetWorldTime = function(hour)
    vwServerHour = tonumber(hour) or 12
    vwServerMinute = 0
end

sampev.onSetPlayerTime = function(hour, minute)
    vwServerHour = tonumber(hour) or 12
    vwServerMinute = tonumber(minute) or 0
end

function applyVwWeather(w)
    vwWeather[0] = math.max(0, math.min(45, tonumber(w) or 0))
    vwCustomWeatherActive = true
    pcall(forceWeatherNow, vwWeather[0])
end

function resetVwToServer()
    local msk = os.date("!*t", os.time() + 3 * 3600)
    local h = (msk and msk.hour) or 0
    vwLockTime[0] = false
    vwCustomWeatherActive = false
    patchSampTimeSet(false)
    vwHour[0] = h
    vwMinute[0] = 0
    vwWeather[0] = 0
    pcall(setTimeOfDay, h, 0)
    pcall(releaseWeather)
    pcall(forceWeatherNow, 0)
end

-- ===== 2. ИСТОРИЯ ДЕЙСТВИЙ (ACTION LOG) & КЭШ ОБЪЕКТОВ КАРТЫ =====
knownMapObjects = {}
actionHistoryList = {}
actionArchiveList = {}
actionHistoryViewArchive = false
actionHistoryFilter = "all" -- "all", "create", "delete", "edit", "group", "tex"
actionHistorySearchBuf = imgui.new.char[128]('')

function saveActionArchive()
    if not ACTION_HISTORY_PATH then return end
    local f = io.open(ACTION_HISTORY_PATH, "w")
    if f then
        f:write(json.encode(actionArchiveList))
        f:close()
    end
end

function loadActionArchive()
    if not ACTION_HISTORY_PATH or not doesFileExist(ACTION_HISTORY_PATH) then return end
    local f = io.open(ACTION_HISTORY_PATH, "r")
    if not f then return end
    local ok, data = pcall(json.decode, f:read("*all"))
    f:close()
    if ok and type(data) == "table" then
        actionArchiveList = data
    end
end
lastPendingModelId = nil
lastPendingObjId = nil

function getModelNameById(modelId)
    if not modelId then return "" end
    local mNum = tonumber(modelId)
    if mNum and sampObjectModelNames and sampObjectModelNames[mNum] then
        return sampObjectModelNames[mNum]
    end
    local sId = tostring(modelId)
    if allObjects then
        for _, o in ipairs(allObjects) do
            if tostring(o.id) == sId then return o.name or "" end
        end
    end
    return ""
end

function updateKnownMapObjectFromLabel(lblText, lx, ly, lz)
    if not lblText or lblText == "" then return end
    local cleanText = lblText:gsub("{%x%x%x%x%x%x}", "")
    local objNum, modelNum = cleanText:match("#(%d+)%s*[-–—]%s*#(%d+)")
    if objNum and modelNum then
        local grpNum = cleanText:match("Группа:?%s*#?(%d+)")
        knownMapObjects[tostring(objNum)] = {
            id = tostring(objNum),
            modelId = tostring(modelNum),
            modelName = getModelNameById(modelNum),
            group = grpNum,
            x = lx, y = ly, z = lz
        }
    end
end

function resolveMapObjModel(objId, fallbackModelId)
    local sObj = objId and tostring(objId) or nil
    if sObj and knownMapObjects[sObj] and knownMapObjects[sObj].modelId then
        local info = knownMapObjects[sObj]
        local mName = info.modelName
        if not mName or mName == "" then mName = getModelNameById(info.modelId) end
        return info.modelId, mName
    end
    -- Попробуем быстро просканировать активные 3D-лейблы, если ещё не в кэше
    if sObj then
        for id = 0, 2047 do
            local ok, defined = pcall(sampIs3dTextDefined, id)
            if ok and defined then
                local ok2, text3d, _, lx, ly, lz = pcall(sampGet3dTextInfoById, id)
                if ok2 and text3d then
                    updateKnownMapObjectFromLabel(text3d, lx, ly, lz)
                end
            end
        end
        if knownMapObjects[sObj] and knownMapObjects[sObj].modelId then
            local info = knownMapObjects[sObj]
            local mName = info.modelName
            if not mName or mName == "" then mName = getModelNameById(info.modelId) end
            return info.modelId, mName
        end
    end
    if fallbackModelId then
        return tostring(fallbackModelId), getModelNameById(fallbackModelId)
    end
    return nil, ""
end

-- ===== УМНОЕ ВОССТАНОВЛЕНИЕ ОБЪЕКТОВ (UNDO / SMART RESTORE) =====
restoreInProgress = false
lastDeletedSnapshot = nil
trackedObjMaterials = {}
trackedObjColors = {}
scanNearestObjLabel = nil

function fetchOinfoSync(objId, maxWaitMs)
    if not objId then return nil end
    local sId = tostring(objId)
    if oinfoCache and oinfoCache[sId] and (os.clock() - (oinfoCache[sId].time or 0)) < 3.0 then
        return oinfoCache[sId]
    end
    maxWaitMs = maxWaitMs or 450
    oinfoSilentPendingId = sId
    oinfoSilentExpireTime = os.clock() + (maxWaitMs / 1000.0) + 0.6
    oinfoLastReqTime = os.clock()
    sampSendChat("/oinfo " .. sId)

    local endTime = os.clock() + (maxWaitMs / 1000.0)
    while os.clock() < endTime do
        wait(25)
        if oinfoCache and oinfoCache[sId] and (oinfoSilentPendingId ~= sId) then
            break
        end
    end
    oinfoSilentPendingId = nil
    return oinfoCache and oinfoCache[sId]
end

function findTrinityObjectInfo(objId)
    if not objId then return nil end
    local sId = tostring(objId)

    -- 1. Проверяем кэш knownMapObjects
    if knownMapObjects and knownMapObjects[sId] and knownMapObjects[sId].modelId and knownMapObjects[sId].x then
        local inf = knownMapObjects[sId]
        local mNum = tonumber(inf.modelId)
        return {
            id = sId,
            modelId = mNum,
            modelName = inf.modelName or getModelNameById(mNum),
            x = inf.x, y = inf.y, z = inf.z
        }
    end

    -- 2. Сканируем нативные 3D-тексты SA-MP (от 0 до 2047)
    for id = 0, 2047 do
        local ok, defined = pcall(sampIs3dTextDefined, id)
        if ok and defined then
            local ok2, text3d, _, lx, ly, lz = pcall(sampGet3dTextInfoById, id)
            if ok2 and text3d and text3d ~= "" then
                local cleanText = text3d:gsub("{%x%x%x%x%x%x}", "")
                local oNum, mNum = cleanText:match("#(%d+)%s*[- —–]%s*#(%d+)")
                if not oNum then oNum, mNum = cleanText:match("#(%d+)%s*#(%d+)") end
                if oNum and oNum == sId and mNum then
                    local mIdNum = tonumber(mNum)
                    return {
                        id = sId,
                        modelId = mIdNum,
                        modelName = getModelNameById(mIdNum),
                        x = lx, y = ly, z = lz
                    }
                end
            end
        end
    end

    -- 3. Проверяем labelCache
    if labelCache then
        for _, lbl in pairs(labelCache) do
            if lbl and lbl.text then
                local cleanText = lbl.text:gsub("{%x%x%x%x%x%x}", "")
                local oNum, mNum = cleanText:match("#(%d+)%s*[- —–]%s*#(%d+)")
                if not oNum then
                    oNum, mNum = cleanText:match("#(%d+)%s*#(%d+)")
                end
                if oNum and oNum == sId and mNum then
                    local mIdNum = tonumber(mNum)
                    return {
                        id = sId,
                        modelId = mIdNum,
                        modelName = getModelNameById(mIdNum),
                        x = lbl.x, y = lbl.y, z = lbl.z
                    }
                end
            end
        end
    end

    return nil
end

function getObjectCoordsSafe(h)
    if not h or not doesObjectExist(h) then return nil end
    local ok, res, x, y, z = pcall(getObjectCoordinates, h)
    if ok then
        if type(res) == "boolean" and type(x) == "number" and type(y) == "number" and type(z) == "number" then
            if res then return x, y, z end
        elseif type(res) == "number" and type(x) == "number" and type(y) == "number" then
            return res, x, y
        end
    end
    local ok2, _, fx, fy, fz = pcall(getObjectCoordinates, h)
    if ok2 and type(fx) == "number" and type(fy) == "number" and type(fz) == "number" then
        return fx, fy, fz
    end
    return nil
end

function shortestAngleDelta(target, current)
    local diff = (target - current) % 360
    if diff > 180 then diff = diff - 360 end
    return diff
end

-- (getObjectCoordsSafe и shortestAngleDelta объявлены глобально выше)

local function isValidUtf8(str)
    if not str or type(str) ~= "string" or #str == 0 then return false end
    local hasMultibyte = false
    local i, len = 1, #str
    while i <= len do
        local b = str:byte(i)
        if b < 0x80 then
            i = i + 1
        elseif b >= 0xC2 and b <= 0xDF then
            if i + 1 > len then return false end
            local b2 = str:byte(i + 1)
            if b2 < 0x80 or b2 > 0xBF then return false end
            hasMultibyte = true
            i = i + 2
        elseif b >= 0xE0 and b <= 0xEF then
            if i + 2 > len then return false end
            local b2 = str:byte(i + 1)
            local b3 = str:byte(i + 2)
            if b2 < 0x80 or b2 > 0xBF or b3 < 0x80 or b3 > 0xBF then return false end
            hasMultibyte = true
            i = i + 3
        elseif b >= 0xF0 and b <= 0xF4 then
            if i + 3 > len then return false end
            local b2 = str:byte(i + 1)
            local b3 = str:byte(i + 2)
            local b4 = str:byte(i + 3)
            if b2 < 0x80 or b2 > 0xBF or b3 < 0x80 or b3 > 0xBF or b4 < 0x80 or b4 > 0xBF then return false end
            hasMultibyte = true
            i = i + 4
        else
            return false
        end
    end
    return hasMultibyte
end

local hasUtf8 = isValidUtf8

function safeU8(s)
    if not s or s == "" then return "" end
    if type(s) ~= "string" then s = tostring(s) end
    if isValidUtf8(s) then
        local okDec, dec = pcall(function() return u8:decode(s) end)
        if okDec and dec and isValidUtf8(dec) then
            return dec
        end
        return s
    end
    local ok, r = pcall(u8, s)
    return ok and r or s
end

function safeCP1251(s)
    if not s or s == "" then return "" end
    if type(s) ~= "string" then s = tostring(s) end
    if isValidUtf8(s) then
        local ok, r = pcall(function() return u8:decode(s) end)
        if ok and r and r ~= "" then return r end
    end
    return s
end

local function getObjectEuler(objectHandle)
    if not objectHandle or not doesObjectExist(objectHandle) then return 0.0, 0.0, 0.0 end
    local ok, qx, qy, qz, qw = pcall(getObjectQuaternion, objectHandle)
    if not ok or not qx or not qw then
        return 0.0, 0.0, 0.0
    end
    local t0 = 2 * (qw * qx + qy * qz)
    local t1 = 1 - 2 * (qx * qx + qy * qy)
    local rx = math.deg(math.atan2(t0, t1))

    local t2 = 2 * (qw * qy - qz * qx)
    t2 = math.max(-1.0, math.min(1.0, t2))
    local ry = math.deg(math.asin(t2))

    local t3 = 2 * (qw * qz + qx * qy)
    local t4 = 1 - 2 * (qz * qz + qy * qy)
    local rz = math.deg(math.atan2(t3, t4))

    return rx, ry, rz
end

local function eulerToMatrix(rx, ry, rz)
    local radX = math.rad(rx or 0)
    local radY = math.rad(ry or 0)
    local radZ = math.rad(rz or 0)

    local cx, sx = math.cos(radX), math.sin(radX)
    local cy, sy = math.cos(radY), math.sin(radY)
    local cz, sz = math.cos(radZ), math.sin(radZ)

    local m = {}
    m[1] = cz * cy
    m[2] = cz * sy * sx - sz * cx
    m[3] = cz * sy * cx + sz * sx

    m[4] = sz * cy
    m[5] = sz * sy * sx + cz * cx
    m[6] = sz * sy * cx - cz * sx

    m[7] = -sy
    m[8] = cy * sx
    m[9] = cy * cx
    return m
end

local function matrixToEuler(m)
    local sy = -m[7]
    sy = math.max(-1.0, math.min(1.0, sy))
    local ry = math.deg(math.asin(sy))

    local rx, rz
    if math.abs(m[7]) < 0.99999 then
        rx = math.deg(math.atan2(m[8], m[9]))
        rz = math.deg(math.atan2(m[4], m[1]))
    else
        rx = math.deg(math.atan2(-m[6], m[5]))
        rz = 0.0
    end
    return rx, ry, rz
end

local function rotateEulerYaw(rx, ry, rz, deltaYaw)
    if not deltaYaw or math.abs(deltaYaw % 360) < 0.001 then
        return rx or 0, ry or 0, rz or 0
    end
    local curRX = rx or 0
    local curRY = ry or 0
    local curRZ = rz or 0
    if math.abs(curRX) < 0.001 and math.abs(curRY) < 0.001 then
        return 0.0, 0.0, (curRZ + deltaYaw) % 360
    end
    local m = eulerToMatrix(curRX, curRY, curRZ)
    local rad = math.rad(deltaYaw)
    local c, s = math.cos(rad), math.sin(rad)
    local r = {}
    r[1] = c * m[1] - s * m[4]
    r[2] = c * m[2] - s * m[5]
    r[3] = c * m[3] - s * m[6]

    r[4] = s * m[1] + c * m[4]
    r[5] = s * m[2] + c * m[5]
    r[6] = s * m[3] + c * m[6]

    r[7] = m[7]
    r[8] = m[8]
    r[9] = m[9]
    return matrixToEuler(r)
end

-- Поиск физического GTA-объекта, соответствующего серверному ID или ярлыку
function findGtaObjectHandle(objInfo, objId, excludedHandles)
    local targetModel = objInfo and objInfo.modelId
    local numId = tonumber(objId)
    if numId then
        local okS, h = pcall(sampGetObjectHandleBySampId, numId)
        if okS and h and h ~= -1 and doesObjectExist(h) then
            local okM, m = pcall(getObjectModel, h)
            if okM and (not targetModel or m == targetModel) then
                if not excludedHandles or not excludedHandles[h] then
                    return h
                end
            end
        end
    end

    local refX = objInfo and objInfo.x
    local refY = objInfo and objInfo.y
    local refZ = objInfo and objInfo.z

    if not refX and PLAYER_PED and doesCharExist(PLAYER_PED) then
        refX, refY, refZ = getCharCoordinates(PLAYER_PED)
    end

    local bestHandle = nil
    local bestDist = 999999.0

    for _, h in pairs(getAllObjects()) do
        if doesObjectExist(h) and (not excludedHandles or not excludedHandles[h]) then
            local okM, m = pcall(getObjectModel, h)
            if okM and (not targetModel or m == targetModel) then
                local ox, oy, oz = getObjectCoordsSafe(h)
                if ox and oy and oz and refX then
                    local d = getDistanceBetweenCoords3d(ox, oy, oz, refX, refY, refZ)
                    if d < bestDist and d < 25.0 then
                        bestDist = d
                        bestHandle = h
                    end
                end
            end
        end
    end

    return bestHandle
end

function snapshotObject(objId)
    if not objId then return nil end
    local sId = tostring(objId)

    -- 1. Сначала определяем информацию о серверном объекте (#ID) и его модели
    local objInfo = findTrinityObjectInfo(sId)
    local mId = objInfo and objInfo.modelId or nil

    if not mId then
        local resId = resolveMapObjModel(sId, nil)
        if resId then mId = tonumber(resId) end
    end

    -- 2. Ищем физический GTA-объект нужной модели рядом с меткой
    local hObj = findGtaObjectHandle(objInfo, sId)

    local ox, oy, oz = 0.0, 0.0, 0.0
    local orx, ory, orz = 0.0, 0.0, 0.0

    if hObj and doesObjectExist(hObj) then
        local gx, gy, gz = getObjectCoordsSafe(hObj)
        if gx and gy and gz then
            ox, oy, oz = gx, gy, gz
        end
        local rx, ry, rz = getObjectEuler(hObj)
        if rx then orx, ory, orz = rx, ry, rz end
        if not mId then
            local okM, m = pcall(getObjectModel, hObj)
            if okM and m then mId = m end
        end
    end

    -- 3. Если координаты из GTA объекта не получены, используем координаты лейбла
    if (ox == 0.0 and oy == 0.0 and oz == 0.0) and objInfo and objInfo.x then
        ox, oy, oz = objInfo.x, objInfo.y, objInfo.z
    end

    -- 4. Если координаты все еще 0, но игрок рядом в мире ищем перед камерой
    if (ox == 0.0 and oy == 0.0 and oz == 0.0) and PLAYER_PED and doesCharExist(PLAYER_PED) then
        local nearest = scanNearestObjLabel and scanNearestObjLabel()
        if nearest and nearest.x and (not mId or nearest.modelId == tostring(mId) or nearest.id == sId) then
            ox, oy, oz = nearest.x, nearest.y, nearest.z
            if not mId and nearest.modelId then mId = tonumber(nearest.modelId) end
        end
    end

    if not mId or (ox == 0.0 and oy == 0.0 and oz == 0.0) then
        return nil
    end

    -- 5. Сбор текстур (/mtset): 1) из oinfoCache 2) из trackedObjMaterials
    local mats = {}
    local oinfo = oinfoCache and oinfoCache[sId]
    if oinfo and oinfo.materials and #oinfo.materials > 0 then
        for _, m in ipairs(oinfo.materials) do
            if m.texId and m.texId ~= "" and m.texId ~= "0" then
                table.insert(mats, {
                    mat = tostring(m.mat),
                    texId = tostring(m.texId),
                    color = m.color or "0"
                })
            end
        end
    end

    local tracked = trackedObjMaterials and trackedObjMaterials[sId]
    if tracked then
        for slot, texId in pairs(tracked) do
            local already = false
            for _, existing in ipairs(mats) do
                if existing.mat == tostring(slot) then
                    existing.texId = tostring(texId)
                    already = true
                    break
                end
            end
            if not already and texId ~= "" and texId ~= "0" then
                table.insert(mats, {
                    mat = tostring(slot),
                    texId = tostring(texId),
                    color = "0"
                })
            end
        end
    end

    local mName = getModelNameById(mId)
    if not mName or mName == "" then mName = "Model #" .. tostring(mId) end

    return {
        objId = sId,
        modelId = tonumber(mId),
        modelName = mName,
        x = tonumber(ox) or 0.0,
        y = tonumber(oy) or 0.0,
        z = tonumber(oz) or 0.0,
        rx = tonumber(orx) or 0.0,
        ry = tonumber(ory) or 0.0,
        rz = tonumber(orz) or 0.0,
        materials = (#mats > 0) and mats or nil,
        time = os.time()
    }
end

local function getObjectCoordsSafe(h)
    if not h or not doesObjectExist(h) then return nil end
    local ok, res, x, y, z = pcall(getObjectCoordinates, h)
    if ok then
        if type(res) == "boolean" and type(x) == "number" and type(y) == "number" and type(z) == "number" then
            if res then return x, y, z end
        elseif type(res) == "number" and type(x) == "number" and type(y) == "number" then
            return res, x, y
        end
    end
    local ok2, _, fx, fy, fz = pcall(getObjectCoordinates, h)
    if ok2 and type(fx) == "number" and type(fy) == "number" and type(fz) == "number" then
        return fx, fy, fz
    end
    return nil
end

local function shortestAngleDelta(target, current)
    local diff = (target - current) % 360
    if diff > 180 then diff = diff - 360 end
    if diff < -180 then diff = diff + 360 end
    return diff
end

function restoreDeletedObject(snap)
    if not snap or not snap.modelId then
        sampAddChatMessage("{FF9326}[TMT] Ошибка:{FFFFFF} Нет данных для восстановления объекта.", -1)
        return
    end

    if restoreInProgress then
        sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Процесс восстановления уже идет...", -1)
        return
    end

    lua_thread.create(function()
        restoreInProgress = true

        -- 1. Проверяем дистанцию до места удаления
        local px, py, pz = getCharCoordinates(PLAYER_PED)
        local dist = getDistanceBetweenCoords3d(px, py, pz, snap.x, snap.y, snap.z)
        if dist > 200.0 then
            sampAddChatMessage(string.format("{FF9326}[TMT] Внимание:{FFFFFF} вы находитесь в {FF9326}%.1f м{FFFFFF} от места удаления! Подойдите ближе для корректного спавна.", dist), -1)
            restoreInProgress = false
            return
        end

        -- 2. Полное замораживание игрока (позиция + управление)
        pcall(freezeCharPosition, PLAYER_PED, true)
        pcall(lockPlayerControl, true)

        toast_text  = "Восстановление #" .. tostring(snap.modelId)
        toast_text2 = "Подождите, объект возвращаетст на место..."
        toast_timer = 200
        toast_tex   = nil
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Восстановление объекта {FF9326}#%d{FFFFFF} (%s)...", snap.modelId, snap.modelName or ""), -1)

        -- 3. Запоминаем существующие хэндлы в мире
        local existingHandles = {}
        for _, h in pairs(getAllObjects()) do
            existingHandles[h] = true
        end

        -- 4. Спавним объект
        sampSendChat("/cr " .. tostring(snap.modelId))

        -- 5. Ждем появления нового объекта (до 3 сек)
        local newHandle = nil
        local timeout = os.clock() + 3.0
        while os.clock() < timeout do
            wait(50)
            for _, h in pairs(getAllObjects()) do
                if not existingHandles[h] and doesObjectExist(h) then
                    local okM, m = pcall(getObjectModel, h)
                    if okM and m == snap.modelId then
                        newHandle = h
                        break
                    end
                end
            end
            if newHandle then break end
        end

        if not newHandle or not doesObjectExist(newHandle) then
            pcall(freezeCharPosition, PLAYER_PED, false)
            pcall(lockPlayerControl, false)
            sampAddChatMessage("{FF9326}[TMT] Мeшибка:{FFFFFF} не удалось создать объект на сервере (таймаут ответа сервера).", -1)
            restoreInProgress = false
            return
        end

        -- Пауза после /cr для регистрации объекта сервером и сброса антифлуда
        wait(550)

        -- 6. Перемещение к исходным координатам (/ox, /oy, /oz)
        local curX, curY, curZ = getObjectCoordsSafe(newHandle)
        if curX and curY and curZ then
            local targetX = tonumber(snap.x) or curX
            local targetY = tonumber(snap.y) or curY
            local targetZ = tonumber(snap.z) or curZ
            local dx = targetX - curX
            local dy = targetY - curY
            local dz = targetZ - curZ

            local function sendOffsetAxis(cmdName, delta)
                local remaining = delta
                local stepLimit = 5.0
                while math.abs(remaining) > 0.01 do
                    local step = remaining
                    if step > stepLimit then step = stepLimit end
                    if step < -stepLimit then step = -stepLimit end
                    sampSendChat(string.format("%s %.2f", cmdName, step))
                    remaining = remaining - step
                    wait(350)
                end
            end

            if math.abs(dx) > 0.01 then
                sendOffsetAxis("/ox", dx)
            end
            if math.abs(dy) > 0.01 then
                sendOffsetAxis("/oy", dy)
            end
            if math.abs(dz) > 0.01 then
                sendOffsetAxis("/oz", dz)
            end
        end

        -- 7. Поворот к исходным углам (/rx, /ry, /rz)
        local curRX, curRY, curRZ = getObjectEuler(newHandle)
        if curRX and snap.rx then
            local targetRX = tonumber(snap.rx) or curRX
            local targetRY = tonumber(snap.ry) or curRY
            local targetRZ = tonumber(snap.rz) or curRZ
            local drx = shortestAngleDelta(targetRX, curRX)
            local dry = shortestAngleDelta(targetRY, curRY)
            local drz = shortestAngleDelta(targetRZ, curRZ)

            local EPS_ROT = 0.05
            if math.abs(drx) > EPS_ROT then
                sampSendChat(string.format("/rx %.2f", drx))
                wait(350)
            end
            if math.abs(dry) > EPS_ROT then
                sampSendChat(string.format("/ry %.2f", dry))
                wait(350)
            end
            if math.abs(drz) > EPS_ROT then
                sampSendChat(string.format("/rz %.2f", drz))
                wait(350)
            end
        end

        -- 8. Нанесение текстур (/mtset)
        if snap.materials and #snap.materials > 0 then
            wait(200)
            for _, mat in ipairs(snap.materials) do
                if mat.mat and mat.texId and mat.texId ~= "" and mat.texId ~= "0" then
                    sampSendChat(string.format("/mtset %s %s", tostring(mat.mat), tostring(mat.texId)))
                    wait(350)
                end
            end
        end

        -- 9. Разморозка игрока
        pcall(freezeCharPosition, PLAYER_PED, false)
        pcall(lockPlayerControl, false)
        restoreInProgress = false

        toast_text  = "Восстановлено!"
        toast_text2 = (snap.modelName ~= "" and snap.modelName or ("Объект #" .. tostring(snap.modelId)))
        toast_timer = 150
        toast_tex   = nil
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Объект {FF9326}#%d{FFFFFF} успешно восстановлен на прежнюю позицию!", snap.modelId), -1)
    end)
end

function addActionLog(actionType, objId, modelId, titleText, descText, extraCmd, restoreData)
    local mId, mName = resolveMapObjModel(objId, modelId)
    local finalTitle = titleText or ""
    -- Если это событие с объектом и известна модель — красиво дополняем ID модельки, если ещё не указан
    if objId and mId and not finalTitle:find(tostring(mId), 1, true) then
        if mName and mName ~= "" then
            finalTitle = finalTitle .. " (Модель #" .. tostring(mId) .. " — " .. mName .. ")"
        else
            finalTitle = finalTitle .. " (Модель #" .. tostring(mId) .. ")"
        end
    end
    -- Защита от дублирования одинаковой записи в одну и ту же секунду
    local top = actionHistoryList[1]
    if top and top.actionType == actionType and tostring(top.objId or "") == tostring(objId or "")
       and top.rawTitle == (titleText or "") and (os.clock() - (top.clock or 0)) < 0.6 then
        if mId and not top.modelId then
            top.modelId = mId
            top.modelName = mName
            top.title = finalTitle
        end
        return
    end
    local newEntry = {
        date = os.date("%d.%m.%Y"),
        time = os.date("%H:%M:%S"),
        clock = os.clock(),
        actionType = actionType or "other",
        objId = objId and tostring(objId) or nil,
        modelId = mId and tostring(mId) or nil,
        modelName = mName or "",
        rawTitle = titleText or "",
        title = finalTitle,
        desc = descText or "",
        cmd = extraCmd or "",
        restoreData = restoreData
    }
    table.insert(actionHistoryList, 1, newEntry)
    if #actionHistoryList > 150 then
        table.remove(actionHistoryList)
    end
    table.insert(actionArchiveList, 1, newEntry)
    if #actionArchiveList > 500 then
        table.remove(actionArchiveList)
    end
    pcall(saveActionArchive)
end

