groupControlSubTab = 1 -- 1 = Менеджер групп, 2 = Управление группой по ID
groupMgrSelectedGroup = nil
groupMgrSearchBuf = imgui.new.char[64]('')
groupMgrSummary = {} -- { {groupNum = 1, count = 5, objects = {...}, previewModel = "1412"}, ... }

objListWinOpen = imgui.new.bool(false)
objListSearchBuf = imgui.new.char[128]('')
objListItems = {}
objListOnlyOnScreen = imgui.new.bool(false)
objListViewMode = "list" -- "list" (список вниз) или "grid" (сетка)

function refreshObjListFromLabels()
    objListItems = {}
    local seenObjIds = {}
    local px, py, pz = getCharCoordinates(PLAYER_PED)
    local sw2, sh2 = getScreenResolution()

    local function processLabelEntry(lblText, lx, ly, lz)
        if not lblText or lblText == "" then return end
        local cleanText = lblText:gsub("{%x%x%x%x%x%x}", "")
        local objNum, modelNum = cleanText:match("#(%d+)%s*[-–—]%s*#(%d+)")
        if objNum and modelNum and not seenObjIds[objNum] then
            local sx, sy = convert3DCoordsToScreen(lx, ly, lz)
            local onScr = (sx and sy and sx >= 0 and sx <= sw2 and sy >= 0 and sy <= sh2) and true or false
            if not objListOnlyOnScreen[0] or onScr then
                seenObjIds[objNum] = true
                local grpNum = cleanText:match("Группа:?%s*#?(%d+)")
                local dist = math.floor(getDistanceBetweenCoords3d(px, py, pz, lx, ly, lz))
                local mIdNum = tonumber(modelNum)
                local mName = (mIdNum and sampObjectModelNames[mIdNum]) or getModelNameById(modelNum)
                if mName == "" then mName = "Model #" .. tostring(modelNum) end
                knownMapObjects[tostring(objNum)] = {
                    id = tostring(objNum),
                    modelId = tostring(modelNum),
                    modelName = mName,
                    group = grpNum,
                    x = lx, y = ly, z = lz
                }
                table.insert(objListItems, {
                    id = objNum,
                    idNum = tonumber(objNum) or 0,
                    modelId = modelNum,
                    modelName = mName,
                    group = grpNum,
                    x = lx, y = ly, z = lz,
                    dist = dist,
                    onScreen = onScr
                })
            end
        end
    end

    -- 1. Считываем все активные 3D-лейблы SA-MP в зоне стрима (работает даже после перезагрузки скрипта)
    for id = 0, 2047 do
        local ok, defined = pcall(sampIs3dTextDefined, id)
        if ok and defined then
            local ok2, text3d, _, lx, ly, lz = pcall(sampGet3dTextInfoById, id)
            if ok2 and text3d then
                labelCache[id] = {text = text3d, x = lx, y = ly, z = lz}
                processLabelEntry(text3d, lx, ly, lz)
            end
        end
    end

    -- 2. Дополняем из labelCache
    for _, lbl in pairs(labelCache) do
        if lbl and lbl.text then
            processLabelEntry(lbl.text, lbl.x, lbl.y, lbl.z)
        end
    end

    table.sort(objListItems, function(a, b) return a.idNum < b.idNum end)
end

function refreshGroupManagerSummary()
    local savedOnlyScr = objListOnlyOnScreen[0]
    objListOnlyOnScreen[0] = false
    refreshObjListFromLabels()
    objListOnlyOnScreen[0] = savedOnlyScr

    local byGrp = {}
    for _, item in ipairs(objListItems) do
        if item.group and item.group ~= "" and tonumber(item.group) and tonumber(item.group) > 0 then
            local gNum = tonumber(item.group)
            if not byGrp[gNum] then
                byGrp[gNum] = {
                    groupNum = gNum,
                    groupStr = tostring(gNum),
                    objects = {},
                    previewModel = item.modelId,
                    minDist = item.dist or 9999
                }
            end
            table.insert(byGrp[gNum].objects, item)
            if (item.dist or 9999) < byGrp[gNum].minDist then
                byGrp[gNum].minDist = item.dist
            end
        end
    end

    groupMgrSummary = {}
    for _, grpData in pairs(byGrp) do
        table.sort(grpData.objects, function(a, b) return a.idNum < b.idNum end)
        table.insert(groupMgrSummary, grpData)
    end
    table.sort(groupMgrSummary, function(a, b) return a.groupNum < b.groupNum end)

    if groupMgrSelectedGroup then
        local found = false
        for _, g in ipairs(groupMgrSummary) do
            if g.groupNum == groupMgrSelectedGroup then found = true; break end
        end
        if not found then
            groupMgrSelectedGroup = (#groupMgrSummary > 0) and groupMgrSummary[1].groupNum or nil
        end
    elseif #groupMgrSummary > 0 then
        groupMgrSelectedGroup = groupMgrSummary[1].groupNum
    end
end

PREFAB_CMDS = { cr=true, ox=true, oy=true, oz=true, rx=true, ry=true, rz=true, clone=true, sti=true, tcopy=true, mtset=true, mtcol=true }

local function addPrefabStep(cmd, label)
    local name = cmd:match("^/(%a+)")
    if not name then return end
    local lname = name:lower()
    local merged = false

    -- /cr и /clone не суммируются, остальные — да
    if lname ~= "cr" and lname ~= "clone" and lname ~= "sti" then
        local val = tonumber(cmd:match("^/%a+%s+(-?%d+%.?%d*)%s*$"))
        local last = prefabSteps[#prefabSteps]
        if val and last then
            local lastName = last:match("^/(%a+)")
            local lastVal  = tonumber(last:match("^/%a+%s+(-?%d+%.?%d*)%s*$"))
            if lastName and lastVal and lastName:lower() == lname then
                local sum = lastVal + val
                if sum == math.floor(sum) then
                    prefabSteps[#prefabSteps] = "/" .. lastName .. " " .. string.format("%d", sum)
                else
                    prefabSteps[#prefabSteps] = "/" .. lastName .. " " .. tostring(sum)
                end
                merged = true
            end
        end
    end

    if not merged then
        table.insert(prefabSteps, cmd)
        prefabStepLabels[#prefabSteps] = label
    end
end

local lastCursorForceTime = 0
local function forceCursorNormal()
    local now = os.clock()
    if now - lastCursorForceTime > 0.5 then
        sampSetCursorMode(0, false)
        lastCursorForceTime = now
    end
end

local function fuAutoRespond(did, listIndex)
    lua_thread.create(function()
        local waited = 0
        while not sampIsDialogActive() and waited < 2000 do wait(20); waited = waited + 20 end
        wait(120)

        if listIndex and sampSetCurrentDialogListItem then pcall(sampSetCurrentDialogListItem, listIndex) end
        if listIndex then pcall(sampSendDialogResponse, did, 1, listIndex, "") end

        wait(150)
        if sampIsDialogActive() and sampCloseCurrentDialogWithButton then
            pcall(sampCloseCurrentDialogWithButton, 1)
        end
    end)
end

local function findDialogRow(text, pattern, isExact)
    if not text or not pattern or pattern == "" then return nil end
    local clean = text:gsub('{%x%x%x%x%x%x}', '')
    local pRaw = tostring(pattern)

    local pDec = nil
    if u8 and u8.decode then
        local ok, dec = pcall(function() return u8:decode(pRaw) end)
        if ok and dec and #dec >= math.floor(#pRaw / 2) and dec ~= " " then
            pDec = dec
        end
    end

    -- 1 проход: точное совпадение первой колонки до табуляции
    local row = 0
    for line in clean:gmatch('[^\r\n]+') do
        local trimmed = line:gsub('^%s*(.-)%s*$', '%1')
        local col0 = trimmed:match('^([^\t]+)') or trimmed
        col0 = col0:gsub('^%s*(.-)%s*$', '%1')
        if col0 == pRaw or (pDec and col0 == pDec) then
            return row
        end
        row = row + 1
    end

    -- 2 проход: поиск подстроки
    row = 0
    for line in clean:gmatch('[^\r\n]+') do
        local trimmed = line:gsub('^%s*(.-)%s*$', '%1')
        if isExact then
            if trimmed == pRaw or (pDec and trimmed == pDec) then return row end
        else
            if trimmed:find(pRaw, 1, true) or (pDec and trimmed:find(pDec, 1, true)) then return row end
        end
        row = row + 1
    end
    return nil
end

local function getDialogRowCleanText(text, rowIndex)
    local i = 0
    for line in text:gmatch('[^\r\n]+') do
        if i == rowIndex then
            return line:gsub('{%x%x%x%x%x%x}', ''):gsub('^%s*(.-)%s*$', '%1')
        end
        i = i + 1
    end
    return ''
end

local function blockRespondAsync(did, btn, listItem, text, dialogText)
    local inputText = text or ''
    if (inputText == '' or inputText == nil) and listItem and listItem >= 0 and dialogText then
        inputText = getDialogRowCleanText(dialogText, listItem)
    end
    print(string.format("[BlockMacro] RESPOND: did=%s btn=%s list=%s input='%s'", tostring(did), tostring(btn), tostring(listItem or -1), tostring(inputText or '')))
    lua_thread.create(function()
        wait(160)
        sampSendDialogResponse(did, btn, listItem or -1, inputText or '')
    end)
end

local function getPickupMode(s)
    if not s or s == "" then return 0 end
    local hasTransport = (s:find("транспорт", 1, true) or s:find("Транспорт", 1, true) or s:find("авто", 1, true) or s:find("Авто", 1, true))
    local hasFoot = (s:find("пешком", 1, true) or s:find("Пешком", 1, true))
    if hasTransport and hasFoot then
        return 2 -- Пешком и в транспорте / авто
    elseif hasTransport then
        return 3 -- Только в транспорте / авто
    elseif hasFoot then
        return 1 -- Только пешком
    end
    return 0
end
sampev.onShowDialog = function(dialogId, style, title, button1, button2, text)
    if eblock and eblock.handleDialog then
        local handled, res = eblock.handleDialog(dialogId, style, title, button1, button2, text)
        if handled then return res end
    end
    local cleanTitle = title:gsub('{%x%x%x%x%x%x}', '')
    local cleanText  = text:gsub('{%x%x%x%x%x%x}', '')

    -- Защита от промежуточных окон БД сервера Trinity
    if cleanText:find('Ждем ответа', 1, true) or cleanTitle:find('Ждем ответа', 1, true) then
        if dialogMacroQueue then
            dialogMacroTimeout = os.clock() + 15
        end
        if oinfoSilentPendingId then
            oinfoSilentExpireTime = os.clock() + 5.0
        end
        return false
    end

    -- Автоматизация диалогов /otext ("Управление текстом")
    if otextQueueActive and otextTaskQueue then
        if handleOtextDialog(dialogId, style, cleanTitle, button1, button2, cleanText) then
            return false
        end
    end

    -- Перехват и парсинг /oinfo для Ассистента объектов
    if cleanTitle:find('Информация об ивент объекте', 1, true) then
        local mapObjId = cleanText:match('IDX на карте:%s*#?(%d+)') or tostring(oinfoSilentPendingId or "")
        local gIdxFull = cleanText:match('Глобальный IDX:%s*(global%s+%d+)')
        local gIdxNum  = cleanText:match('Глобальный IDX:%s*global%s*(%d+)') or cleanText:match('Глобальный IDX:%s*(%S+)')
        local materials = {}
        local noTextures = false
        for line in cleanText:gmatch('[^\r\n]+') do
            local tr = line:gsub('^%s*(.-)%s*$', '%1')
            if tr:find('Текстуры и цвета отсутствуют', 1, true) then
                noTextures = true
            elseif tr:find('^Материал') then
                local matNum = tr:match('^Материал%s+#?(%d+)') or "?"
                local texId, texModel, texTxd, texName = tr:match('Текстура%s+#(%d+)%s*%-%s*(%d+)%s+(%S+)%s+(%S+)')
                local texPart = tr:match('Текстура%s+(.-)%s+Цвет%s+') or tr:match('Текстура%s+(.+)$') or ""
                local colPart = tr:match('Цвет%s+(%S+)') or "0"
                table.insert(materials, {
                    mat = matNum,
                    texId = texId,
                    texModel = texModel,
                    texTxd = texTxd,
                    texName = texName,
                    tex = texPart,
                    color = colPart,
                    raw = tr
                })
            end
        end
        if mapObjId ~= "" then
            oinfoCache[tostring(mapObjId)] = {
                gIdxFull = gIdxFull or (gIdxNum and ("global " .. gIdxNum) or "неизвестно"),
                gIdxNum  = gIdxNum or "",
                materials = materials,
                noTextures = noTextures or (#materials == 0),
                time = os.clock()
            }
        end
        if oinfoSilentPendingId or (oinfoSilentExpireTime and os.clock() < oinfoSilentExpireTime) then
            oinfoSilentPendingId = nil
            oinfoSilentExpireTime = 0
            sampSendDialogResponse(dialogId, 0, -1, '')
            return false
        end
    end

    -- Обработка макроса применения шаблона блока (/blockcp)
    if activeBlockMacro then
        print(string.format("[BlockMacro] RECV: did=%s style=%s title='%s' b1='%s' b2='%s'", tostring(dialogId), tostring(style), tostring(cleanTitle), tostring(button1), tostring(button2)))
        for mk, mv in pairs(activeBlockMacro) do
            print(string.format("[BlockMacro] activeBlockMacro.%s = %s", tostring(mk), tostring(mv)))
        end
        local lNum = 0
        for dl in cleanText:gmatch('[^\r\n]+') do
            print(string.format("  [%d] '%s'", lNum, dl))
            lNum = lNum + 1
        end

        if os.clock() > (activeBlockMacro.timeout or 0) then
            print("[BlockMacro] TIMEOUT EXPIRED, resetting macro")
            activeBlockMacro = nil
            return
        end

        activeBlockMacro.timeout = os.clock() + 15
        local did = dialogId

        -- 1. ГЛАВНЫЙ ДИАЛОГ: "Управление ивент блоком"
        if cleanTitle:find('Управление', 1, true) and cleanTitle:find('блок', 1, true) then

            -- А) Визуал-блок: тип отображения (Лейбл / Актёр)
            if activeBlockMacro.visualType then
                if activeBlockMacro.visDone then
                    blockRespondAsync(did, 0, -1, '')
                    local vt = activeBlockMacro.visualType
                    activeBlockMacro = nil
                    toast_text  = "Тип отображения: " .. tostring(vt)
                    toast_text2 = ""
                    toast_tex   = nil
                    toast_timer = 120
                    return false
                else
                    local curVis = cleanText:match("Тип отображения:%s*([^\r\n]+)")
                    local visTrimmed = curVis and curVis:gsub('^%s*(.-)%s*$', '%1') or ""
                    local targetVis  = activeBlockMacro.visualType
                    local isVisMatched = (visTrimmed ~= "" and (visTrimmed:find(targetVis, 1, true) or targetVis:find(visTrimmed, 1, true)))

                    if not isVisMatched then
                        local rIdx = findDialogRow(cleanText, "Тип отображения")
                        if rIdx then
                            blockRespondAsync(did, 1, rIdx, '', cleanText)
                            return false
                        end
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Тип отображения: " .. targetVis
                        toast_text2 = ""
                        toast_tex   = nil
                        toast_timer = 120
                        return false
                    end
                end
            end

            -- Б) Визуал-блок: скин актёра
            if activeBlockMacro.actorSkin then
                if activeBlockMacro.skinDone then
                    blockRespondAsync(did, 0, -1, '')
                    local sk = activeBlockMacro.actorSkin
                    activeBlockMacro = nil
                    toast_text  = "Скин актёра изменен"
                    toast_text2 = "Установлен скин #" .. tostring(sk)
                    toast_tex   = nil
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "Скин актёра") or findDialogRow(cleanText, "Скин")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Ошибка настройки"
                        toast_text2 = "Пункт скина не найден"
                        toast_timer = 150
                        return false
                    end
                end
            end

            -- В) Визуал-блок: имя актёра
            if activeBlockMacro.actorName then
                if activeBlockMacro.nameDone then
                    blockRespondAsync(did, 0, -1, '')
                    local nm = activeBlockMacro.actorName
                    activeBlockMacro = nil
                    toast_text  = "Имя актёра сохранено"
                    toast_text2 = tostring(nm)
                    toast_tex   = nil
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "Имя актёра") or findDialogRow(cleanText, "Имя")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Ошибка настройки"
                        toast_text2 = "Пункт имени не найден"
                        toast_timer = 150
                        return false
                    end
                end
            end

            -- Г) Визуал-блок: анимация актёра
            if activeBlockMacro.actorAnim then
                if activeBlockMacro.animDone then
                    blockRespondAsync(did, 0, -1, '')
                    local an = activeBlockMacro.actorAnim
                    activeBlockMacro = nil
                    toast_text  = "Анимация актёра сохранена"
                    toast_text2 = tostring(an)
                    toast_tex   = nil
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "Анимация")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Ошибка настройки"
                        toast_text2 = "Пункт анимации не найден"
                        toast_timer = 150
                        return false
                    end
                end
            end

            -- Д) Визуал-блок: текст лейбла
            if activeBlockMacro.labelText then
                if activeBlockMacro.labelDone then
                    blockRespondAsync(did, 0, -1, '')
                    local lt = activeBlockMacro.labelText
                    activeBlockMacro = nil
                    toast_text  = "Текст лейбла сохранен"
                    toast_text2 = tostring(lt)
                    toast_tex   = nil
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "Текст сообщения") or findDialogRow(cleanText, "Текст лейбла") or findDialogRow(cleanText, "Текст")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Ошибка настройки"
                        toast_text2 = "Пункт текста не найден"
                        toast_timer = 150
                        return false
                    end
                end
            end

            -- Е) Триггер-блок: тип отображения (Пикап, Зона, Зона с кнопкой)
            if activeBlockMacro.trigType then
                if activeBlockMacro.trigTypeDone then
                    blockRespondAsync(did, 0, -1, '')
                    local tt = activeBlockMacro.trigType
                    activeBlockMacro = nil
                    toast_text  = "Тип триггера: " .. tostring(tt)
                    toast_timer = 120
                    return false
                else
                    local curT = cleanText:match("Тип отображения:%s*([^\r\n]+)")
                    local tTrimmed = curT and curT:gsub('^%s*(.-)%s*$', '%1') or ""
                    local targetT  = activeBlockMacro.trigType

                    local isMatched = false
                    if targetT == "Зона с кнопкой" then
                        isMatched = (tTrimmed:find("кнопк", 1, true) or tTrimmed:find("Кнопк", 1, true)) ~= nil
                    elseif targetT == "Зона" then
                        isMatched = (tTrimmed:find("Зона", 1, true) or tTrimmed:find("зона", 1, true)) and not (tTrimmed:find("кнопк", 1, true) or tTrimmed:find("Кнопк", 1, true))
                    elseif targetT == "Пикап" then
                        isMatched = (tTrimmed:find("Пикап", 1, true) or tTrimmed:find("пикап", 1, true)) ~= nil
                    else
                        isMatched = (tTrimmed == targetT)
                    end

                    print(string.format("[BlockMacro] TRIG TYPE CHECK: cur='%s' target='%s' isMatched=%s", tTrimmed, targetT, tostring(isMatched)))

                    if isMatched then
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Тип триггера: " .. targetT
                        toast_timer = 120
                        return false
                    else
                        local rIdx = findDialogRow(cleanText, "Тип отображения")
                        if rIdx then
                            blockRespondAsync(did, 1, rIdx, '', cleanText)
                            return false
                        end
                    end
                end
            end

            -- Ж) Триггер-блок: размер зоны подбора
            if activeBlockMacro.trigRadius then
                if activeBlockMacro.radiusDone then
                    blockRespondAsync(did, 0, -1, '')
                    local tr = activeBlockMacro.trigRadius
                    activeBlockMacro = nil
                    toast_text  = "Размер зоны: " .. tostring(tr) .. " м"
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "Размер зоны")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Ошибка: зона не найдена"
                        toast_timer = 120
                        return false
                    end
                end
            end

            -- З) Триггер-блок: модель пикапа
            if activeBlockMacro.trigModel then
                if activeBlockMacro.modelDone then
                    blockRespondAsync(did, 0, -1, '')
                    local tm = activeBlockMacro.trigModel
                    activeBlockMacro = nil
                    toast_text  = "Модель пикапа: #" .. tostring(tm)
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "с моделью") or findDialogRow(cleanText, "модель") or findDialogRow(cleanText, "Пикап с моделью")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Ошибка: пункт не найден"
                        toast_timer = 120
                        return false
                    end
                end
            end

            -- И) Триггер-блок: кнопка активации
            if activeBlockMacro.trigKey then
                if activeBlockMacro.keyDone then
                    blockRespondAsync(did, 0, -1, '')
                    local tk = activeBlockMacro.trigKey
                    activeBlockMacro = nil
                    toast_text  = "Кнопка активации: " .. tostring(tk)
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "Кнопка активации") or findDialogRow(cleanText, "Кнопка")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Ошибка: кнопка не найдена"
                        toast_timer = 120
                        return false
                    end
                end
            end

            -- К) Триггер-блок: тип подбора (циклическое переключение!)
            if activeBlockMacro.targetPickup then
                local curRowText = ""
                for line in cleanText:gmatch('[^\r\n]+') do
                    if line:find("Тип подбора", 1, true) then
                        curRowText = line
                        break
                    end
                end

                local curMode = getPickupMode(curRowText)
                local targetMode = getPickupMode(activeBlockMacro.targetPickup)

                print(string.format("[BlockMacro] PICKUP TYPE CHECK: curMode=%d targetMode=%d curRow='%s' target='%s'", curMode, targetMode, curRowText, tostring(activeBlockMacro.targetPickup)))

                if curMode == targetMode and curMode > 0 then
                    blockRespondAsync(did, 0, -1, '')
                    activeBlockMacro = nil
                    toast_text  = "Тип подбора установлен!"
                    toast_text2 = curRowText:match("Тип подбора:%s*([^\r\n]+)") or ""
                    toast_timer = 120
                    return false
                else
                    activeBlockMacro.pickupTries = (activeBlockMacro.pickupTries or 0) + 1
                    if activeBlockMacro.pickupTries > 6 then
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Не удалось переключить тип"
                        toast_timer = 120
                        return false
                    else
                        local rIdx = findDialogRow(cleanText, "Тип подбора")
                        if rIdx then
                            blockRespondAsync(did, 1, rIdx, '', cleanText)
                            return false
                        end
                    end
                end
            end

            -- Л) Триггер-блок: добавить вызываемый блок
            if activeBlockMacro.addCallIdx then
                if activeBlockMacro.callDone then
                    blockRespondAsync(did, 0, -1, '')
                    local cid = activeBlockMacro.addCallIdx
                    activeBlockMacro = nil
                    toast_text  = "Блок добавлен: #" .. tostring(cid)
                    toast_timer = 120
                    return false
                else
                    local rIdx = findDialogRow(cleanText, "Добавить вызываемый блок") or findDialogRow(cleanText, "вызываемый блок")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    else
                        blockRespondAsync(did, 0, -1, '')
                        activeBlockMacro = nil
                        toast_text  = "Кнопка добавления не найдена"
                        toast_timer = 120
                        return false
                    end
                end
            end

            -- М) Блок действия (Action): targetAction
            if activeBlockMacro.targetAction then
                local curAction = cleanText:match("Тип действия:%s*([^\r\n]+)")
                local actTrimmed = curAction and curAction:gsub('^%s*(.-)%s*$', '%1') or ""
                local targetAct  = activeBlockMacro.targetAction
                local isActionMatched = (actTrimmed ~= "" and (actTrimmed:find(targetAct, 1, true) or targetAct:find(actTrimmed, 1, true)))

                if not isActionMatched then
                    local rIdx = findDialogRow(cleanText, "Тип действия")
                    if rIdx then
                        blockRespondAsync(did, 1, rIdx, '', cleanText)
                        return false
                    end
                else
                    if not activeBlockMacro.paramDone then
                        local actRow = findDialogRow(cleanText, "Тип действия")
                        local pRow = actRow and (actRow + 1) or nil
                        if pRow then
                            blockRespondAsync(did, 1, pRow, '', cleanText)
                            return false
                        end
                    end
                    blockRespondAsync(did, 0, -1, '')
                    activeBlockMacro = nil
                    toast_text  = "Действие сохранено"
                    toast_text2 = ""
                    toast_tex   = nil
                    toast_timer = 120
                    return false
                end
            end

            -- Если ни одно поле не подошло, но открыто главное меню — просто закрываем его
            blockRespondAsync(did, 0, -1, '')
            activeBlockMacro = nil
            return false
        end

        -- 2. ДИАЛОГИ ВЫБОРА ИЗ СПИСКА (style == 2, 4, 5, а также по заголовку)
        local isListStyle = (style == 2 or style == 4 or style == 5)
        local isListTitle = (cleanTitle:find('Выберите', 1, true) or cleanTitle:find('вид', 1, true) or cleanTitle:find('Редактирование', 1, true) or cleanTitle:find('отображения', 1, true))

        if isListStyle or isListTitle then
            print(string.format("[BlockMacro] LIST DIALOG DETECTED: did=%s style=%s title='%s'", tostring(did), tostring(style), tostring(cleanTitle)))

            -- Тип отображения триггера (Пикап, Зона, Зона с кнопкой)
            if activeBlockMacro.trigType and not activeBlockMacro.trigTypeDone then
                local targetT = activeBlockMacro.trigType
                local rIdx = findDialogRow(cleanText, targetT)
                print(string.format("[BlockMacro] findDialogRow for trigType '%s' = %s", tostring(targetT), tostring(rIdx)))
                if rIdx then
                    activeBlockMacro.trigTypeDone = true
                    blockRespondAsync(did, 1, rIdx, '', cleanText)
                    return false
                end
            end

            -- Вид отображения визуал-блока (Лейбл, Актёр)
            if activeBlockMacro.visualType and not activeBlockMacro.visDone then
                local targetVis = activeBlockMacro.visualType or "Лейбл"
                local rIdx = findDialogRow(cleanText, targetVis)
                print(string.format("[BlockMacro] findDialogRow for visualType '%s' = %s", tostring(targetVis), tostring(rIdx)))
                if rIdx then
                    activeBlockMacro.visDone = true
                    blockRespondAsync(did, 1, rIdx, '', cleanText)
                    return false
                end
            end

            -- Кнопка активации триггера (LMB, RMB, SPACE, ENTER, ALT, Y, N, H)
            if activeBlockMacro.trigKey and not activeBlockMacro.keyDone then
                local rIdx = findDialogRow(cleanText, activeBlockMacro.trigKey)
                print(string.format("[BlockMacro] findDialogRow for trigKey '%s' = %s", tostring(activeBlockMacro.trigKey), tostring(rIdx)))
                if rIdx then
                    activeBlockMacro.keyDone = true
                    blockRespondAsync(did, 1, rIdx, '', cleanText)
                    return false
                end
            end

            -- Тип действия для action блока
            if activeBlockMacro.targetAction then
                local targetAct = activeBlockMacro.targetAction
                local rIdx = findDialogRow(cleanText, targetAct)
                if rIdx then
                    blockRespondAsync(did, 1, rIdx, '', cleanText)
                    return false
                end
            end
        end

        -- 3. ИНФОРМАЦИОННЫЕ ДИАЛОГИ (подтверждения, ошибки, уведомления с кнопкой "X" / "OK" / "Закрыть")
        if button1 == 'X' or button1 == 'Х' or button1 == 'Закрыть' or button1 == 'ОК' or button1 == 'OK'
           or cleanText:find('изменен на', 1, true)
           or cleanText:find('будет вызываться при подборе', 1, true)
           or cleanText:find('нет ивент блока с указанным вами IDX', 1, true)
           or cleanText:find('успешно', 1, true)
           or (style == 0 and (button2 == '' or button2 == nil)) then

            if cleanText:find('нет ивент блока', 1, true) then
                toast_text  = "Ошибка: блок не найден!"
                toast_text2 = "Проверьте IDX блока"
                toast_timer = 150
            end

            blockRespondAsync(did, 1, -1, '')
            return false
        end

        -- 4. ДИАЛОГИ ВВОДА ЗНАЧЕНИЯ (style == 1 or style == 3)
        if style == 1 or style == 3 or cleanTitle:find('Укажите', 1, true) or cleanTitle:find('Новый', 1, true) or cleanTitle:find('Редактирование', 1, true) then
            if activeBlockMacro.trigRadius and not activeBlockMacro.radiusDone then
                activeBlockMacro.radiusDone = true
                blockRespondAsync(did, 1, -1, tostring(activeBlockMacro.trigRadius))
                return false
            end
            if activeBlockMacro.trigModel and not activeBlockMacro.modelDone then
                activeBlockMacro.modelDone = true
                blockRespondAsync(did, 1, -1, tostring(activeBlockMacro.trigModel))
                return false
            end
            if activeBlockMacro.addCallIdx and not activeBlockMacro.callDone then
                activeBlockMacro.callDone = true
                blockRespondAsync(did, 1, -1, tostring(activeBlockMacro.addCallIdx))
                return false
            end
            if activeBlockMacro.actorSkin and not activeBlockMacro.skinDone then
                activeBlockMacro.skinDone = true
                blockRespondAsync(did, 1, -1, tostring(activeBlockMacro.actorSkin))
                return false
            end
            if activeBlockMacro.actorAnim and not activeBlockMacro.animDone then
                activeBlockMacro.animDone = true
                blockRespondAsync(did, 1, -1, tostring(activeBlockMacro.actorAnim))
                return false
            end
            if activeBlockMacro.actorName and not activeBlockMacro.nameDone then
                activeBlockMacro.nameDone = true
                blockRespondAsync(did, 1, -1, tostring(activeBlockMacro.actorName))
                return false
            end
            if activeBlockMacro.labelText and not activeBlockMacro.labelDone then
                activeBlockMacro.labelDone = true
                blockRespondAsync(did, 1, -1, tostring(activeBlockMacro.labelText))
                return false
            end
            if activeBlockMacro.paramValue then
                local val = tostring(activeBlockMacro.paramValue)
                activeBlockMacro.paramDone = true
                blockRespondAsync(did, 1, -1, val)
                return false
            end
        end

        -- 5. Дополнительно: выбор оружия (weaponName)
        if activeBlockMacro.weaponName and style == 2 then
            local wIdx = findDialogRow(cleanText, activeBlockMacro.weaponName)
            if wIdx then
                activeBlockMacro.weaponName = nil
                activeBlockMacro.paramDone  = true
                blockRespondAsync(did, 1, wIdx, '', cleanText)
                return false
            end
        end
    end

    if not pendingFuAction then return end

    if pendingFuAction.mode == "closet" then
        local idx = findDialogRow(cleanText, "чулан")
        if idx then
            fuAutoRespond(dialogId, idx)
            pendingFuAction = {mode = "confirm", left = 2}
        else
            pendingFuAction = nil
        end
    else
        fuAutoRespond(dialogId, nil)
        pendingFuAction.left = pendingFuAction.left - 1
        if pendingFuAction.left <= 0 then
            pendingFuAction = nil
        end
    end
end

sampev.onSendCommand = function(cmd)
    local name = cmd:match("^/(%a+)")
    if name then
        local lname = name:lower()
        if lname == "scr" then
            local sid = cmd:match("^/%a+%s+(%d+)")
            if sid then
                lastSentScrId = sid
                lastSentScrTime = os.clock()
            end
        elseif lname == "ed" then
            activeEditingGroupId = nil
            objEditorActive = true
            forceCursorNormal()
        elseif lname == "ged" then
            local gid = cmd:match("^/%a+%s+(%d+)")
            if gid then
                activeEditingGroupId = gid
                objEditorActive = true
                forceCursorNormal()
            end
        elseif lname == "sel" or lname == "clone" or lname == "cr" then
            activeEditingGroupId = nil
            objEditorActive = false
            sampSetCursorMode(0, false)
            forceCursorNormal()
        elseif lname == "del" or lname == "gdel" or lname == "map" then
            activeEditingGroupId = nil
        end

        -- Логирование команд маппера в Историю действий
        local arg1, arg2, arg3 = cmd:match("^/%a+%s+(%S+)%s*(%S*)%s*(%S*)")
        if lname == "cr" and arg1 then
            lastPendingModelId = arg1
            local mName = getModelNameById(arg1)
            addActionLog("create", nil, arg1, "Создан объект (ID модели: #" .. tostring(arg1) .. (mName ~= "" and (" — " .. mName) or "") .. ")", "Команда: " .. cmd, "/cr " .. tostring(arg1))
        elseif lname == "del" then
            local targetObj = (arg1 and arg1 ~= "") and arg1 or (objScanResult and objScanResult.id) or lastEditedObjId
            if not targetObj then
                local nearest = scanNearestObjLabel and scanNearestObjLabel()
                if nearest and nearest.id then targetObj = nearest.id end
            end
            lastPendingObjId = targetObj
            local snap = snapshotObject(targetObj)
            if snap then lastDeletedSnapshot = snap end
            if targetObj then
                local mId, mName = resolveMapObjModel(targetObj, objScanResult and objScanResult.modelId)
                local ttl = "Удалён объект #" .. tostring(targetObj)
                if mId then
                    ttl = "Удалён объект #" .. tostring(targetObj) .. " (ID модели: #" .. tostring(mId) .. (mName ~= "" and (" — " .. mName) or "") .. ")"
                end
                addActionLog("delete", targetObj, mId, ttl, "Команда: " .. cmd, mId and ("/cr " .. tostring(mId)) or "", snap)
            else
                addActionLog("delete", nil, nil, "Удалён объект под прицелом (/del)", "Команда: " .. cmd, "", snap)
            end
        elseif lname == "clone" then
            local targetObj = (arg1 and arg1 ~= "") and arg1 or (objScanResult and objScanResult.id) or lastEditedObjId
            local mId, mName = resolveMapObjModel(targetObj, (objScanResult and objScanResult.modelId) or lastPendingModelId)
            lastPendingModelId = mId
            local ttl = "Клонирован объект" .. (targetObj and (" #" .. tostring(targetObj)) or "")
            if mId then
                ttl = ttl .. " (ID модели: #" .. tostring(mId) .. (mName ~= "" and (" — " .. mName) or "") .. ")"
            end
            addActionLog("create", targetObj, mId, ttl, "Команда: " .. cmd, mId and ("/cr " .. tostring(mId)) or "")
        elseif lname == "ed" or lname == "sel" then
            local targetObj = (arg1 and arg1 ~= "") and arg1 or (objScanResult and objScanResult.id) or lastEditedObjId
            if targetObj then lastEditedObjId = targetObj end
            local mId, mName = resolveMapObjModel(targetObj, objScanResult and objScanResult.modelId)
            local actTitle = (lname == "ed") and "Редактирование объекта" or "Взят в фокус объект"
            local ttl = actTitle .. (targetObj and (" #" .. tostring(targetObj)) or "")
            if mId then
                ttl = ttl .. " (ID модели: #" .. tostring(mId) .. (mName ~= "" and (" — " .. mName) or "") .. ")"
            end
            addActionLog("edit", targetObj, mId, ttl, "Команда: " .. cmd, targetObj and ("/gotoo " .. tostring(targetObj)) or "")
        elseif lname == "mtset" and arg1 then
            local trackObj = lastEditedObjId or (objScanResult and objScanResult.id)
            if trackObj then
                trackedObjMaterials[tostring(trackObj)] = trackedObjMaterials[tostring(trackObj)] or {}
                trackedObjMaterials[tostring(trackObj)][tostring(arg1)] = tostring(arg2 or "0")
            end
            local targetObj = lastEditedObjId or (objScanResult and objScanResult.id)
            local mId, mName = resolveMapObjModel(targetObj, nil)
            local ttl = (arg2 == "0") and ("Сброшена текстура (слот " .. tostring(arg1) .. ")") or ("Нанесена текстура #" .. tostring(arg2 ~= "" and arg2 or "?") .. " (слот " .. tostring(arg1) .. ")")
            if targetObj then
                ttl = ttl .. " на объект #" .. tostring(targetObj)
            end
            addActionLog("tex", targetObj, mId, ttl, "Команда: " .. cmd, cmd)
        elseif lname == "gmtset" and arg1 then
            local ttl = (arg3 == "0") and ("Сброшена текстура группы #" .. tostring(arg1) .. " (слот " .. tostring(arg2) .. ")")
                or ("Нанесена текстура #" .. tostring(arg3 ~= "" and arg3 or "?") .. " группе #" .. tostring(arg1) .. " (слот " .. tostring(arg2) .. ")")
            addActionLog("tex", nil, nil, ttl, "Команда: " .. cmd, cmd)
        elseif lname == "gr" and arg1 and arg2 ~= "" then
            local mId, mName = resolveMapObjModel(arg1, nil)
            local ttl = (arg2 == "0") and ("Объект #" .. tostring(arg1) .. " убран из группы")
                or ("Объект #" .. tostring(arg1) .. " добавлен в группу #" .. tostring(arg2))
            addActionLog("group", arg1, mId, ttl, "Команда: " .. cmd, "/gotoo " .. tostring(arg1))
        elseif lname == "gclone" and arg1 then
            addActionLog("group", nil, nil, "Запрошено клонирование группы #" .. tostring(arg1), "Команда: " .. cmd, "/ged " .. tostring(arg1))
        elseif lname == "groupdelete" or lname == "gdel" then
            if arg1 and arg1 ~= "" then
                addActionLog("group", nil, nil, "Удалена группа объектов #" .. tostring(arg1), "Команда: " .. cmd, "")
            end
        end

        if prefabRecording and not prefabPlaying then
            if PREFAB_CMDS[lname] then
                local label = nil
                if lname == "clone" and cloneObjHotkey_key[0] and cloneObjHotkey_key[0] > 0 then
                    label = u8"Клонирование: " .. ffi.string(cloneObjHotkey_display)
                end
                addPrefabStep(cmd, label)
            end
        end
    end
    return true
end

