function applyBlockPreset(bId, actionName, paramSearch, paramValue)
    if not bId then return end
    activeBlockMacro = {
        targetId     = tonumber(bId),
        targetAction = actionName,
        paramSearch  = paramSearch,
        paramValue   = paramValue and tostring(paramValue) or nil,
        weaponName   = nil,
        paramDone    = (paramValue == nil and paramSearch == nil),
        timeout      = os.clock() + 15
    }
    lua_thread.create(function()
        -- Закрываем любые активные диалоговые окна перед /blockcp,
        -- чтобы сервер не выдавал ошибку "Перед использованием данной возможности следует закрыть все активные диалоговые окна."
        local closeTries = 0
        while sampIsDialogActive() and closeTries < 4 do
            if sampCloseCurrentDialogWithButton then
                pcall(sampCloseCurrentDialogWithButton, 0)
            end
            wait(150)
            closeTries = closeTries + 1
        end
        wait(120)
        sampSendChat("/blockcp " .. tostring(bId))
    end)
end

