local function renderSampColoredText(str)
    if not str or str == '' then return end
    local curColor = imgui.ImVec4(1.0, 1.0, 1.0, 1.0)
    local lastPos = 1
    local len = #str
    local hasDrawn = false
    while lastPos <= len do
        local tagStart, tagEnd, hex = str:find('{([%x%X][%x%X][%x%X][%x%X][%x%X][%x%X])}', lastPos)
        if tagStart then
            if tagStart > lastPos then
                local chunk = str:sub(lastPos, tagStart - 1)
                if hasDrawn then imgui.SameLine(0, 0) end
                imgui.TextColored(curColor, chunk)
                hasDrawn = true
            end
            local r = tonumber(hex:sub(1, 2), 16) / 255.0
            local g = tonumber(hex:sub(3, 4), 16) / 255.0
            local b = tonumber(hex:sub(5, 6), 16) / 255.0
            curColor = imgui.ImVec4(r or 1.0, g or 1.0, b or 1.0, 1.0)
            lastPos = tagEnd + 1
        else
            local chunk = str:sub(lastPos)
            if #chunk > 0 then
                if hasDrawn then imgui.SameLine(0, 0) end
                imgui.TextColored(curColor, chunk)
            end
            break
        end
    end
end

