lastGizmoPlayerObject = false
lastGizmoObjectId = nil
lastGizmoPos = nil
lastGizmoRot = nil

sampev.onSendEditObject = function(playerObject, objectId, response, pos, rot)
    lastGizmoPlayerObject = playerObject
    lastGizmoObjectId = objectId
        -- [STAGE 1] Привязка к координатной сетке и углам
    if pos and (response == 1 or response == 2) and gridSnapEnabled[0] then
        local gStep = getGridSnapStep()
        pos.x = snapCoord(pos.x, gStep)
        pos.y = snapCoord(pos.y, gStep)
        pos.z = snapCoord(pos.z, gStep)
    end
    if rot and (response == 1 or response == 2) and angleSnapEnabled[0] then
        local aStep = getAngleSnapStep()
        rot.x = snapCoord(rot.x, aStep)
        rot.y = snapCoord(rot.y, aStep)
        rot.z = snapCoord(rot.z, aStep)
    end

    if pos then lastGizmoPos = {x = pos.x, y = pos.y, z = pos.z} end
    if rot then lastGizmoRot = {x = rot.x, y = rot.y, z = rot.z} end

    if prefabRecording and not prefabPlaying and pos and rot then
        if response == 1 or response == 2 then
            local prev = editObjTrackLast[objectId]
            if prev then
                local EPS = 0.005
                local dx, dy, dz    = pos.x - prev.x,  pos.y - prev.y,  pos.z - prev.z
                local drx, dry, drz = rot.x - prev.rx, rot.y - prev.ry, rot.z - prev.rz
                if math.abs(dx)  > EPS then addPrefabStep("/ox " .. string.format("%.2f", dx))  end
                if math.abs(dy)  > EPS then addPrefabStep("/oy " .. string.format("%.2f", dy))  end
                if math.abs(dz)  > EPS then addPrefabStep("/oz " .. string.format("%.2f", dz))  end
                if math.abs(drx) > EPS then addPrefabStep("/rx " .. string.format("%.2f", drx)) end
                if math.abs(dry) > EPS then addPrefabStep("/ry " .. string.format("%.2f", dry)) end
                if math.abs(drz) > EPS then addPrefabStep("/rz " .. string.format("%.2f", drz)) end
            end
            editObjTrackLast[objectId] = {x = pos.x, y = pos.y, z = pos.z, rx = rot.x, ry = rot.y, rz = rot.z}
        end
    end

    if response == 0 or response == 1 then
        editObjTrackLast[objectId] = nil
        objEditorActive = false
        activeEditingGroupId = nil
        objScanSubmenu  = false -- false = основное меню, "tex"/"group" = подменю
        pendingFuAction = nil   -- ожидание диалога /fu для автовыбора пункта (см. sampev.onShowDialog)
        pendingNewBlockScriptId = nil -- ждём сообщение сервера с ID только что созданного блока
        weaponPresetTargetId    = nil -- ID блока, для которого сейчас выбирается оружие
        dialogMacroQueue = nil
        dialogMacroStep  = 0
        if oinfoCache and objectId then
            oinfoCache[tostring(objectId)] = nil
        end
        forceCursorNormal()
    end
    return {playerObject, objectId, response, pos, rot}
end

