-- ===== Универсальная fade-анимация появления/закрытия всплывающих окон =====
popupAnim = {} -- [key] = {alpha = 0..1}

-- Возвращает текущую альфу для окна с данным ключом, плавно ведя её к 1 (если isOpen) или к 0 (если нет)
function popupFadeAlpha(key, isOpen)
    local st = popupAnim[key]
    if not st then st = {alpha = 0}; popupAnim[key] = st end
    local step
    if tabAnimationsEnabled[0] then
        step = imgui.GetIO().DeltaTime * 10.0 -- быстро, но плавно (~0.1с)
    else
        step = 1.0 -- анимации выключены в настройках - меняем мгновенно
    end
    if isOpen then
        st.alpha = math.min(1.0, st.alpha + step)
    else
        st.alpha = math.max(0.0, st.alpha - step)
    end
    return st.alpha
end

-- true, пока окно либо реально открыто, либо ещё доигрывает fade-out (используется вместо "if showX then")
function popupShouldDraw(key, isOpen)
    if isOpen then return true end
    local st = popupAnim[key]
    return st ~= nil and st.alpha > 0.01
end

function SwitchTab(newTab)
    if activeTab ~= newTab then
        activeTab = newTab
        animTabAlpha = tabAnimationsEnabled[0] and 0.0 or 1.0
    end
end

function UpdateAnimations()
    if not tabAnimationsEnabled[0] then
        animTabAlpha = 1.0
        return
    end
    if animTabAlpha < 1.0 then
        animTabAlpha = animTabAlpha + (imgui.GetIO().DeltaTime * 4.0)
        if animTabAlpha > 1.0 then animTabAlpha = 1.0 end
    end
end

