local interiorsList = {}
local activeInterior = nil
local interiorImgCache = {}
local interiorImgFailed = {}

local function getInteriorImg(filename)
    if not filename or filename == "" then return nil end
    if interiorImgCache[filename] then return interiorImgCache[filename] end
    if interiorImgFailed[filename] then return nil end
    local p = INTERIORS_IMG_DIR .. filename
    if not doesFileExist(p) then interiorImgFailed[filename] = true; return nil end
    local ok, t = pcall(imgui.CreateTextureFromFile, p)
    if ok and t then
        interiorImgCache[filename] = t
        return t
    end
    interiorImgFailed[filename] = true
    return nil
end

function loadInteriors()
    if not doesFileExist(INTERIORS_PATH) then return end
    local f = io.open(INTERIORS_PATH, "r")
    if not f then return end
    local raw = f:read("*all")
    f:close()
    local ok, data = pcall(json.decode, raw)
    if ok and type(data) == "table" then
        interiorsList = data
        for _, item in ipairs(interiorsList) do
            local mSet = {}
            for _, mid in ipairs(item.models or {}) do
                local n = tonumber(mid)
                if n then mSet[n] = true end
            end
            item.model_map = mSet
        end
    end
end

