local function buildCatCounts()
    local gtaTotal = 0
    for _, o in ipairs(allObjects) do
        local n = tonumber(o.id)
        if n and gtaSaAllIds[n] then gtaTotal = gtaTotal + 1 end
    end
    gtaCatCounts[0] = (gtaTotal > 0 and gtaTotal or #allObjects)

    for i, cat in ipairs(gtaSaCategories) do
        local count = 0
        if cat.id_map then
            for _, o in ipairs(allObjects) do
                local n = tonumber(o.id)
                if n and cat.id_map[n] then count = count + 1 end
            end
        end
        gtaCatCounts[i] = count
    end

    local sampTotal = 0
    for _, o in ipairs(allObjects) do
        local n = tonumber(o.id)
        if n and sampAllIds[n] then sampTotal = sampTotal + 1 end
    end
    sampCatCounts[0] = (sampTotal > 0 and sampTotal or 1435)

    for i, cat in ipairs(sampCategories) do
        local count = 0
        if cat.id_map then
            for _, o in ipairs(allObjects) do
                local n = tonumber(o.id)
                if n and cat.id_map[n] then count = count + 1 end
            end
        end
        sampCatCounts[i] = count
    end

    if catGameMode == 2 then
        catCounts = sampCatCounts
    else
        catCounts = gtaCatCounts
    end
end

