    return gridSnapSteps[idx] or 1.0
end

function getAngleSnapStep()
    local idx = angleSnapStepIdx[0]
    return angleSnapSteps[idx] or 15.0
end

function snapCoord(val, step)
    if not step or step <= 0.0001 then return val end
    return math.floor(val / step + 0.5) * step
end

-- Вспомогательная функция быстрого показа тоста
local function showToastQuick(title, subtitle)
    toast_text  = title or ""
    toast_text2 = subtitle or ""
    toast_tex   = nil
    toast_timer = 130
end

-- Функция приземления объекта на поверхность коллизии
function dropObjectToSurface(objId, x, y, z)
    if not objId and not x then
        if objEditorActive and lastGizmoObjectId then
            objId = tostring(lastGizmoObjectId)
            if lastGizmoPos then
                x, y, z = lastGizmoPos.x, lastGizmoPos.y, lastGizmoPos.z
            end
        else
            local selOid = ffi.string(objCtrlIdBuf)
            if selOid ~= "" then
                objId = selOid
            end
        end
    end

    if not objId and not x then
        local px, py, pz = getCharCoordinates(PLAYER_PED)
        local bestObj = nil
        local bestDist = 999999
        for _, item in ipairs(objListItems) do
            if item.x and item.y and item.z then
                local d = getDistanceBetweenCoords3d(px, py, pz, item.x, item.y, item.z)
                if d < bestDist then
                    bestDist = d
                    bestObj = item
                end
            end
        end
        if bestObj then
            objId = tostring(bestObj.id)
            x, y, z = bestObj.x, bestObj.y, bestObj.z
        end
    end

    if not x or not y or not z then
        if objId then
            local item = knownMapObjects[tostring(objId)]
            if item and item.x then
                x, y, z = item.x, item.y, item.z
            end
        end
    end

    if not objId or not x or not y or not z then
        showToastQuick("Приземление", "Не удалось определить объект или его координаты")
        return
    end

    local ok, hit, colPt = pcall(processLineOfSight, x, y, z + 0.35, x, y, z - 45.0, true, true, false, true, false, false, false, false)
    if not ok or not hit or not colPt or not colPt.pos then
        showToastQuick("Поверхность не найдена", "Под объектом #" .. tostring(objId) .. " нет коллизии пола")
        return
    end

    local hitZ = colPt.pos[3] or colPt.pos.z
    local dz = hitZ - z

    if math.abs(dz) < 0.015 then
        showToastQuick("Объект #" .. tostring(objId), "Уже идеально стоит на поверхности (dZ < 1.5 см)")
        return
    end

    lua_thread.create(function()
        if not objEditorActive or tostring(lastGizmoObjectId) ~= tostring(objId) then
            sampSendChat("/ed " .. tostring(objId))
            wait(200)
        end

        local remaining = dz
        local stepLimit = 5.0
        while math.abs(remaining) > 0.008 do
            local step = remaining
            if step > stepLimit then step = stepLimit end
            if step < -stepLimit then step = -stepLimit end
            sampSendChat(string.format("/oz %.2f", step))
            remaining = remaining - step
            wait(180)
        end

        if lastGizmoPos then
            lastGizmoPos.z = hitZ
        end
        if knownMapObjects[tostring(objId)] then
            knownMapObjects[tostring(objId)].z = hitZ
        end

        showToastQuick("Объект #" .. tostring(objId) .. " приземлен", string.format("Смещение по высоте: %+.2f м", dz))
    end)
end

