arrayWinOpen       = imgui.new.bool(false)
arrayRunning       = false
arrayProgress      = 0
arrayTotal         = 0
arrayObjIdBuf      = imgui.new.char[16]('')
arrayCount         = imgui.new.int(5)
arrayMode          = imgui.new.int(0) -- 0: linear, 1: circle
arrayStepX         = imgui.new.float(0.0)
arrayStepY         = imgui.new.float(2.0)
arrayStepZ         = imgui.new.float(0.0)
arrayStepRZ        = imgui.new.float(0.0)
arrayPresetDist    = imgui.new.float(2.0)
arrayRadius        = imgui.new.float(5.0)
arrayArcAngle      = imgui.new.float(360.0)
arrayPreview3D     = imgui.new.bool(true)

function cmd_array(params)
    local argId = params and params:match("^%s*(%d+)%s*$")
    if argId then
        imgui.StrCopy(arrayObjIdBuf, argId)
    elseif ffi.string(arrayObjIdBuf) == "" then
        if objEditorActive and lastGizmoObjectId then
            imgui.StrCopy(arrayObjIdBuf, tostring(lastGizmoObjectId))
        else
            local selOid = ffi.string(objCtrlIdBuf)
            if selOid ~= "" then
                imgui.StrCopy(arrayObjIdBuf, selOid)
            elseif #objListItems > 0 then
                imgui.StrCopy(arrayObjIdBuf, tostring(objListItems[1].id))
            end
        end
    end
    arrayWinOpen[0] = not arrayWinOpen[0]
    if arrayWinOpen[0] then
        showToastQuick("Генератор рядов", "Открыто меню настройки ряда объектов")
    end
end

function calculateArrayStepOffset(stepIdx, baseObj)
    if not stepIdx or stepIdx <= 0 then return 0, 0, 0, 0 end
    local mode = arrayMode[0]
    if mode == 0 then
        local dx = stepIdx * arrayStepX[0]
        local dy = stepIdx * arrayStepY[0]
        local dz = stepIdx * arrayStepZ[0]
        local drz = stepIdx * arrayStepRZ[0]
        return dx, dy, dz, drz
    else
        local totalCopies = arrayCount[0]
        local R = arrayRadius[0]
        local totalAngleRad = math.rad(arrayArcAngle[0])
        local stepAngleRad = (totalCopies > 0) and (totalAngleRad / totalCopies) or 0
        local curAngle = stepIdx * stepAngleRad

        local dx = R * (math.cos(curAngle) - 1.0)
        local dy = R * math.sin(curAngle)
        local dz = (totalCopies > 0) and ((stepIdx / totalCopies) * arrayStepZ[0]) or 0
        local drz = math.deg(curAngle)
        return dx, dy, dz, drz
    end
end

function startArrayGeneration()
    if arrayRunning then return end
    local sId = ffi.string(arrayObjIdBuf):gsub("^%s*(.-)%s*$", "%1")
    if sId == "" then
        showToastQuick("Ошибка", "Укажите ID базового объекта для генератора")
        return
    end

    local baseObj = knownMapObjects[sId] or findTrinityObjectInfo(sId)
    if not baseObj then
        showToastQuick("Ошибка", "Объект #" .. sId .. " не найден в стриме")
        return
    end

    local count = arrayCount[0]
    if count < 1 then count = 1 end
    if count > 50 then count = 50 end

    arrayRunning = true
    arrayTotal = count
    arrayProgress = 0

    lua_thread.create(function()
        pcall(freezeCharPosition, PLAYER_PED, true)
        for i = 1, count do
            if not arrayRunning then break end
            arrayProgress = i
            sampSendChat("/clone " .. sId)
            wait(400)

            local dx, dy, dz, drz = calculateArrayStepOffset(i, baseObj)
            if math.abs(dx) > 0.01 then sendOffsetAxisSafe("/ox", dx) end
            if math.abs(dy) > 0.01 then sendOffsetAxisSafe("/oy", dy) end
            if math.abs(dz) > 0.01 then sendOffsetAxisSafe("/oz", dz) end
            if math.abs(drz) > 0.05 then
                sampSendChat(string.format("/rz %.2f", drz))
                wait(350)
            end
            wait(200)
        end
        pcall(freezeCharPosition, PLAYER_PED, false)
        local doneCount = arrayProgress
        arrayRunning = false
        showToastQuick("Генератор рядов", string.format("Ряд из %d объектов успешно создан!", doneCount))
    end)
end

function stopArrayGeneration()
    arrayRunning = false
    pcall(freezeCharPosition, PLAYER_PED, false)
    showToastQuick("Генератор рядов", "Создание ряда остановлено")
end

function renderArrayToolWindow()
    if not arrayWinOpen[0] then return end
    local sw, sh = getScreenResolution()
    local winW, winH = 440, 530
    imgui.SetNextWindowPos(imgui.ImVec2(sw * 0.5 - winW * 0.5, sh * 0.5 - winH * 0.5), imgui.Cond.FirstUseEver)
    imgui.SetNextWindowSize(imgui.ImVec2(winW, winH), imgui.Cond.FirstUseEver)
    imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, 0.0)
    imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(0, 0, 0, 0))
    local flags = imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse
    if imgui.Begin(fa.ICON_OBJECT_GROUP .. u8"  Генератор рядов и линий##array_main_win", arrayWinOpen, flags) then
        imgui.TextColored(accentColorA(1), u8"Базовый объект (ID):")
        imgui.SameLine()
        imgui.PushItemWidth(100)
        imgui.InputText("##arr_src_id", arrayObjIdBuf, 16)
        imgui.PopItemWidth()
        imgui.SameLine()
        if imgui.Button(u8"Текущий##arr_pick_cur", imgui.ImVec2(80, 0)) then
            if objEditorActive and lastGizmoObjectId then
                imgui.StrCopy(arrayObjIdBuf, tostring(lastGizmoObjectId))
            else
                local selOid = ffi.string(objCtrlIdBuf)
                if selOid ~= "" then
                    imgui.StrCopy(arrayObjIdBuf, selOid)
                elseif #objListItems > 0 then
                    imgui.StrCopy(arrayObjIdBuf, tostring(objListItems[1].id))
                end
            end
        end

        local curIdStr = ffi.string(arrayObjIdBuf):gsub("^%s*(.-)%s*$", "%1")
        local curObjInfo = (curIdStr ~= "") and (knownMapObjects[curIdStr] or findTrinityObjectInfo(curIdStr)) or nil
        if curObjInfo then
            imgui.TextDisabled(string.format(u8"Модель: %s (ID: %s)", curObjInfo.modelName or "Unknown", tostring(curObjInfo.modelId or "?")))
        else
            imgui.TextDisabled(u8"Объект не выбран или не найден в стриме")
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        imgui.SliderInt(u8"Количество копий##arr_cnt_slider", arrayCount, 1, 50)
        imgui.Spacing()

        local mode = arrayMode[0]
        local modeW = math.floor((imgui.GetContentRegionAvail().x - 6) / 2)
        if mode ~= 0 then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.18, 0.18, 0.22, 1.0)) end
        if imgui.Button(u8"Линейный шаг (dX/dY)##arr_m0", imgui.ImVec2(modeW, 26)) then
            arrayMode[0] = 0
        end
        if mode ~= 0 then imgui.PopStyleColor() end
        imgui.SameLine(0, 6)
        if mode ~= 1 then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.18, 0.18, 0.22, 1.0)) end
        if imgui.Button(u8"Круговой массив (Дуга)##arr_m1", imgui.ImVec2(modeW, 26)) then
            arrayMode[0] = 1
        end
        if mode ~= 1 then imgui.PopStyleColor() end

        imgui.Spacing()

        if mode == 0 then
            imgui.PushItemWidth(140)
            imgui.DragFloat(u8"Шаг X (м)##arr_dx", arrayStepX, 0.05, -50.0, 50.0, "%.2f")
            imgui.SameLine(0, 12)
            imgui.DragFloat(u8"Шаг Y (м)##arr_dy", arrayStepY, 0.05, -50.0, 50.0, "%.2f")
            imgui.DragFloat(u8"Шаг Z (м)##arr_dz", arrayStepZ, 0.05, -20.0, 20.0, "%.2f")
            imgui.SameLine(0, 12)
            imgui.DragFloat(u8"Поворот RZ (град.)##arr_drz", arrayStepRZ, 0.5, -180.0, 180.0, "%.1f")
            imgui.PopItemWidth()

            imgui.Spacing()
            imgui.TextColored(accentColorA(1), u8"Быстрые направления:")
            imgui.PushItemWidth(100)
            imgui.DragFloat(u8"Дистанция##arr_pdist", arrayPresetDist, 0.1, 0.1, 30.0, "%.2f")
            imgui.PopItemWidth()

            local preW = math.floor((imgui.GetContentRegionAvail().x - 12) / 3)
            if imgui.Button(u8"Взгляд (Вперед)##pre_fwd", imgui.ImVec2(preW, 26)) then
                local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
                local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
                if okCam and okAt then
                    local fx, fy = atX - camX, atY - camY
                    local flen = math.sqrt(fx*fx + fy*fy)
                    if flen > 0.001 then
                        arrayStepX[0] = (fx / flen) * arrayPresetDist[0]
                        arrayStepY[0] = (fy / flen) * arrayPresetDist[0]
                        arrayStepZ[0] = 0.0
                    end
                end
            end
            imgui.SameLine(0, 6)
            if imgui.Button(u8"Вправо##pre_right", imgui.ImVec2(preW, 26)) then
                local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
                local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
                if okCam and okAt then
                    local fx, fy = atX - camX, atY - camY
                    local flen = math.sqrt(fx*fx + fy*fy)
                    if flen > 0.001 then
                        arrayStepX[0] = (fy / flen) * arrayPresetDist[0]
                        arrayStepY[0] = -(fx / flen) * arrayPresetDist[0]
                        arrayStepZ[0] = 0.0
                    end
                end
            end
            imgui.SameLine(0, 6)
            if imgui.Button(u8"Влево##pre_left", imgui.ImVec2(preW, 26)) then
                local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
                local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
                if okCam and okAt then
                    local fx, fy = atX - camX, atY - camY
                    local flen = math.sqrt(fx*fx + fy*fy)
                    if flen > 0.001 then
                        arrayStepX[0] = -(fy / flen) * arrayPresetDist[0]
                        arrayStepY[0] = (fx / flen) * arrayPresetDist[0]
                        arrayStepZ[0] = 0.0
                    end
                end
            end

            if imgui.Button(u8"Колонна (Вверх)##pre_col", imgui.ImVec2(preW, 26)) then
                arrayStepX[0] = 0.0; arrayStepY[0] = 0.0; arrayStepZ[0] = arrayPresetDist[0]
            end
            imgui.SameLine(0, 6)
            if imgui.Button(u8"Ступени (+Z)##pre_stairs", imgui.ImVec2(preW, 26)) then
                local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
                local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
                if okCam and okAt then
                    local fx, fy = atX - camX, atY - camY
                    local flen = math.sqrt(fx*fx + fy*fy)
                    if flen > 0.001 then
                        arrayStepX[0] = (fx / flen) * arrayPresetDist[0]
                        arrayStepY[0] = (fy / flen) * arrayPresetDist[0]
                        arrayStepZ[0] = 0.25
                    end
                end
            end
            imgui.SameLine(0, 6)
            if imgui.Button(u8"Сброс##pre_reset", imgui.ImVec2(preW, 26)) then
                arrayStepX[0] = 0.0; arrayStepY[0] = 0.0; arrayStepZ[0] = 0.0; arrayStepRZ[0] = 0.0
            end
        else
            imgui.PushItemWidth(180)
            imgui.DragFloat(u8"Радиус круга (м)##arr_c_rad", arrayRadius, 0.1, 0.5, 100.0, "%.2f")
            imgui.DragFloat(u8"Угол дуги (град.)##arr_c_arc", arrayArcAngle, 1.0, 10.0, 360.0, "%.0f")
            imgui.DragFloat(u8"Подъем Z на весь круг (м)##arr_c_z", arrayStepZ, 0.05, -30.0, 30.0, "%.2f")
            imgui.PopItemWidth()
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        imgui.Checkbox(u8"3D Предпросмотр траектории в мире##arr_p3d", arrayPreview3D)

        local cnt = arrayCount[0]
        if mode == 0 then
            local totLen = math.sqrt((cnt * arrayStepX[0])^2 + (cnt * arrayStepY[0])^2 + (cnt * arrayStepZ[0])^2)
            imgui.TextColored(imgui.ImVec4(0.7, 0.9, 0.7, 1.0), string.format(u8"Итоговая длина ряда: %.2f м (копий: %d)", totLen, cnt))
        else
            imgui.TextColored(imgui.ImVec4(0.7, 0.9, 0.7, 1.0), string.format(u8"Радиус: %.2f м | Дуга: %.0f град. | Шаг угла: %.1f град.", arrayRadius[0], arrayArcAngle[0], (cnt > 0) and (arrayArcAngle[0]/cnt) or 0))
        end

        imgui.Spacing()

        if not arrayRunning then
            imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.12, 0.55, 0.25, 1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.18, 0.68, 0.32, 1.0))
            if imgui.Button(fa.ICON_PLAY .. string.format(u8"  Создать ряд (%d копий)##arr_start_btn", cnt), imgui.ImVec2(-1, 36)) then
                startArrayGeneration()
            end
            imgui.PopStyleColor(2)
        else
            local pct = (arrayTotal > 0) and (arrayProgress / arrayTotal) or 0.0
            imgui.ProgressBar(pct, imgui.ImVec2(-1, 22), string.format(u8"Создано: %d / %d", arrayProgress, arrayTotal))
            imgui.Spacing()
            imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.75, 0.15, 0.15, 1.0))
            if imgui.Button(fa.ICON_STOP .. u8"  Остановить создание##arr_stop_btn", imgui.ImVec2(-1, 32)) then
                stopArrayGeneration()
            end
            imgui.PopStyleColor()
        end
    end
    imgui.End()
    imgui.PopStyleColor()
    imgui.PopStyleVar()
end

function renderArray3DPreview(drawList)
    if not arrayPreview3D[0] or not arrayWinOpen[0] then return end
    local sId = ffi.string(arrayObjIdBuf):gsub("^%s*(.-)%s*$", "%1")
    if sId == "" then return end
    local baseObj = knownMapObjects[sId] or findTrinityObjectInfo(sId)
    if not baseObj or not baseObj.x then return end

    local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
    local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
    if not okCam or not okAt then return end
    local fwdX, fwdY, fwdZ = atX - camX, atY - camY, atZ - camZ

    local x0, y0, z0 = baseObj.x, baseObj.y, baseObj.z
    local prevX, prevY, prevZ = x0, y0, z0
    local count = arrayCount[0]

    for i = 1, count do
        local dx, dy, dz = calculateArrayStepOffset(i, baseObj)
        local curX, curY, curZ = x0 + dx, y0 + dy, z0 + dz

        local dot1 = (prevX - camX)*fwdX + (prevY - camY)*fwdY + (prevZ - camZ)*fwdZ
        local dot2 = (curX - camX)*fwdX + (curY - camY)*fwdY + (curZ - camZ)*fwdZ

        if dot1 > 0.1 and dot2 > 0.1 then
            local sx1, sy1 = convert3DCoordsToScreen(prevX, prevY, prevZ)
            local sx2, sy2 = convert3DCoordsToScreen(curX, curY, curZ)
            if sx1 and sy1 and sx2 and sy2 then
                drawList:AddLine(imgui.ImVec2(sx1, sy1), imgui.ImVec2(sx2, sy2), 0xAA00E5FF, 2.5)
            end
        end

        if dot2 > 0.1 then
            local sx, sy = convert3DCoordsToScreen(curX, curY, curZ)
            if sx and sy then
                drawList:AddCircleFilled(imgui.ImVec2(sx, sy), 5.0, 0xFF00FF88)
                drawList:AddCircle(imgui.ImVec2(sx, sy), 8.0, 0xFFFFFFFF, 12, 1.2)
                local markerText = u8("#" .. i)
                drawList:AddRectFilled(imgui.ImVec2(sx + 8, sy - 9), imgui.ImVec2(sx + 34, sy + 9), 0xDD111822, 3.0)
                drawList:AddText(imgui.ImVec2(sx + 11, sy - 8), 0xFFFFFFFF, markerText)
            end
        end

        prevX, prevY, prevZ = curX, curY, curZ
    end
end

-- ============================================================================
-- [STAGE 2] ТЕКСТУРНАЯ ПИПЕТКА (TEXTURE EYEDROPPER)
-- ============================================================================
-- [STAGE 2] ТЕКСТУРНАЯ ПИПЕТКА (TEXTURE EYEDROPPER)
-- ============================================================================
eyedropperActive       = false
eyedropperBuffer       = nil -- { objId, modelId, modelName, slot, texId, texName, gtaTexture, isCustom, color }
eyedropperSlot         = imgui.new.int(0)
eyedropperHoverObj     = nil
eyedropperHoverPoint   = nil
lastEyedropActionTime  = 0

-- Безопасная проверка доступности адреса в памяти (Win32 IsBadReadPtr)
local function isMemoryReadable(ptr, size)
    if ptr == nil or ptr == 0 then return false end
    local okCast, num = pcall(function() return tonumber(ffi.cast("uintptr_t", ptr)) end)
    if not okCast or not num or num < 0x10000 or num > 0x7FFFFFFF then return false end
    local ok, res = pcall(ffi.C.IsBadReadPtr, ffi.cast("const void*", ptr), size or 4)
    return ok and (res == 0)
end

-- Извлечение оригинальных нативных текстур RenderWare из 3D-объекта GTA:SA
local function getObjectGtaTextures(handle)
    local results = {}
    if not handle or not doesObjectExist(handle) then return results end

    local okPtr, pObj = pcall(getObjectPointer, handle)
    if not okPtr or not pObj or pObj == 0 then return results end
    if not isMemoryReadable(pObj, 0x24) then return results end

    -- CEntity: смещение 0x18 - это указатель на RwObject (RpClump* или RpAtomic*)
    local pRw = ffi.cast("uintptr_t*", pObj + 0x18)[0]
    if not isMemoryReadable(pRw, 0x10) then return results end

    -- Проверяем тип объекта RenderWare (байт 0)
    -- Type 1 = RpAtomic, Type 2 = RpClump
    local rwType = ffi.cast("uint8_t*", pRw)[0]
    local atomic = nil

    if rwType == 1 then
        atomic = pRw
    else
        -- RpClump: вызываем штатную функцию GetFirstAtomic(pRw) по адресу 0x734820
        local okAt, resAt = pcall(function()
            local fn = ffi.cast("uintptr_t (__cdecl *)(uintptr_t)", 0x734820)
            return fn(pRw)
        end)
        if okAt and resAt and resAt ~= 0 then
            atomic = resAt
        end
    end

    if not atomic or not isMemoryReadable(atomic, 0x30) then return results end

    -- В RpAtomic смещение geometry = 0x18 (или 0x14)
    local geom = nil
    for _, off in ipairs({0x18, 0x14, 0x1C, 0x0C}) do
        local g = ffi.cast("uintptr_t*", atomic + off)[0]
        if isMemoryReadable(g, 0x30) then
            local matPtr = ffi.cast("uintptr_t*", g + 0x24)[0]
            local numMat = ffi.cast("int32_t*", g + 0x28)[0]
            if numMat > 0 and numMat <= 64 and isMemoryReadable(matPtr, numMat * 4) then
                geom = g
                break
            end
        end
    end

    if not geom then return results end

    local matPtr = ffi.cast("uintptr_t*", geom + 0x24)[0]
    local numMat = ffi.cast("int32_t*", geom + 0x28)[0]

    for slot = 0, numMat - 1 do
        local rpMat = ffi.cast("uintptr_t*", matPtr)[slot]
        if isMemoryReadable(rpMat, 0x10) then
            local rwTex = ffi.cast("uintptr_t*", rpMat)[0] -- offset 0x00 is RwTexture*
            if isMemoryReadable(rwTex, 0x50) then
                local namePtr = ffi.cast("const char*", rwTex + 0x10)
                local maskPtr = ffi.cast("const char*", rwTex + 0x30)
                local tName = ffi.string(namePtr, 32):match("^[^%z]+") or ""
                local mName = ffi.string(maskPtr, 32):match("^[^%z]+") or ""
                if tName ~= "" then
                    results[slot] = {
                        slot = slot,
                        name = tName,
                        mask = mName
                    }
                end
            end
        end
    end

    return results
end

-- Multi-layer real-time object & label scanner for Eyedropper and Ruler
function getHoveredObject(aimX, aimY)
    local sw, sh = getScreenResolution()
    local cx, cy = sw * 0.5, sh * 0.5
    aimX = aimX or cx
    aimY = aimY or cy

    local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
    local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
    if not okCam or not okAt or not camX or not atX then return nil end

    local fwdX, fwdY, fwdZ = atX - camX, atY - camY, atZ - camZ
    local flen = math.sqrt(fwdX*fwdX + fwdY*fwdY + fwdZ*fwdZ)
    if flen > 0.0001 then fwdX, fwdY, fwdZ = fwdX/flen, fwdY/flen, fwdZ/flen end

    local bestObj = nil
    local bestDist = 65.0

    -- 1. Scan SA-MP 3D Text Labels (Trinity map objects)
    for id = 0, 2047 do
        local okDef, defined = pcall(sampIs3dTextDefined, id)
        if okDef and defined then
            local okInfo, text3d, _, lx, ly, lz = pcall(sampGet3dTextInfoById, id)
            if okInfo and text3d and text3d ~= "" then
                local toX, toY, toZ = lx - camX, ly - camY, lz - camZ
                local inFront = (toX * fwdX + toY * fwdY + toZ * fwdZ) > 0.2
                if inFront then
                    local sx, sy = convert3DCoordsToScreen(lx, ly, lz)
                    if sx and sy then
                        local sd = math.sqrt((sx - aimX)^2 + (sy - aimY)^2)
                        if sd < bestDist then
                            local cleanText = text3d:gsub("{%x%x%x%x%x%x}", "")
                            local objNum, modelNum = cleanText:match("#(%d+)%s*[- —–]%s*#(%d+)")
                            if not objNum then objNum, modelNum = cleanText:match("#(%d+)%s*#(%d+)") end
                            local furnIdx = cleanText:match("IDX:%s*(%d+)")
                            if objNum and modelNum then
                                local mNum = tonumber(modelNum) or 0
                                local mName = getModelNameById(mNum)
                                local sNum = tonumber(objNum)
                                local h = nil
                                if sNum then
                                    local okH, resH = pcall(sampGetObjectHandleBySampId, sNum)
                                    if okH and resH and doesObjectExist(resH) then h = resH end
                                end
                                bestDist = sd
                                bestObj = {
                                    id = tostring(objNum),
                                    modelId = mNum,
                                    modelName = mName,
                                    x = lx, y = ly, z = lz,
                                    handle = h,
                                    isFurniture = false
                                }
                            elseif furnIdx then
                                bestDist = sd
                                bestObj = {
                                    id = tostring(furnIdx),
                                    modelId = 0,
                                    modelName = "Furniture #" .. tostring(furnIdx),
                                    x = lx, y = ly, z = lz,
                                    isFurniture = true
                                }
                            end
                        end
                    end
                end
            end
        end
    end

    -- 2. Scan GTA SA Streamed Objects (getAllObjects)
    for _, h in pairs(getAllObjects()) do
        if isObjectOnScreen(h) then
            local okC, ox, oy, oz = getObjectCoordinates(h)
            if okC and ox then
                local toX, toY, toZ = ox - camX, oy - camY, oz - camZ
                local inFront = (toX * fwdX + toY * fwdY + toZ * fwdZ) > 0.2
                if inFront then
                    local sx, sy = convert3DCoordsToScreen(ox, oy, oz)
                    if sx and sy then
                        local sd = math.sqrt((sx - aimX)^2 + (sy - aimY)^2)
                        if sd < bestDist then
                            local sId = sampGetObjectSampIdByHandle(h)
                            local mId = getObjectModel(h)
                            local mName = getModelNameById(mId)
                            bestDist = sd
                            bestObj = {
                                id = (sId ~= -1) and tostring(sId) or (bestObj and bestObj.id or nil),
                                modelId = mId,
                                modelName = mName,
                                x = ox, y = oy, z = oz,
                                handle = h
                            }
                        end
                    end
                end
            end
        end
    end

    -- 3. Raycast Line of Sight check
    local maxRay = 140.0
    local toX, toY, toZ = camX + fwdX * maxRay, camY + fwdY * maxRay, camZ + fwdZ * maxRay
    local okLos, hit, colPt = pcall(processLineOfSight, camX, camY, camZ, toX, toY, toZ, true, true, false, true, false, false, false, false)
    if okLos and hit and colPt and colPt.pos then
        local hx = colPt.pos[1] or colPt.pos.x
        local hy = colPt.pos[2] or colPt.pos.y
        local hz = colPt.pos[3] or colPt.pos.z
        if not bestObj or bestDist > 30.0 then
            for _, h in pairs(getAllObjects()) do
                local okC, ox, oy, oz = getObjectCoordinates(h)
                if okC and ox then
                    local dWorld = getDistanceBetweenCoords3d(hx, hy, hz, ox, oy, oz)
                    if dWorld < 4.0 then
                        local sId = sampGetObjectSampIdByHandle(h)
                        local mId = getObjectModel(h)
                        local mName = getModelNameById(mId)
                        bestObj = {
                            id = (sId ~= -1) and tostring(sId) or nil,
                            modelId = mId,
                            modelName = mName,
                            x = ox, y = oy, z = oz,
                            handle = h
                        }
                        break
                    end
                end
            end
        end
    end

    return bestObj
end

function cmd_eyedrop()
    eyedropperActive = not eyedropperActive
    if eyedropperActive then
        winOpen[0] = false
        showToastQuick("Текстурная пипетка", "ЛКМ - Взять текстуру | ПКМ - Применить | ESC - Выход")
    else
        showToastQuick("Текстурная пипетка", "Пипетка отключена")
    end
end

function sampleTextureFromObj(obj, forceSlot)
    if not obj then return end
    local sId = tostring(obj.id or "")
    local mId = tonumber(obj.modelId) or 0
    local mName = obj.modelName or getModelNameById(mId) or ("Model #" .. mId)

    -- Получаем хендл объекта для извлечения геометрии
    local handle = obj.handle
    if not handle or not doesObjectExist(handle) then
        if sId ~= "" and tonumber(sId) then
            local okH, h = pcall(sampGetObjectHandleBySampId, tonumber(sId))
            if okH and h and doesObjectExist(h) then
                handle = h
                obj.handle = h
            end
        end
    end

    local gtaMats = handle and getObjectGtaTextures(handle) or {}
    local customSlot = forceSlot or (eyedropperSlot and eyedropperSlot[0]) or 0

    -- 1. Проверяем, установлена ли на этот объект серверная текстура (/mtset)
    local customTex = nil
    local oinfo = (sId ~= "") and oinfoCache and oinfoCache[sId] or nil
    if oinfo and oinfo.materials and #oinfo.materials > 0 then
        for _, m in ipairs(oinfo.materials) do
            if tonumber(m.mat) == customSlot and m.texId and m.texId ~= "" and m.texId ~= "0" then
                customTex = m
                break
            end
        end
        if not customTex then
            for _, m in ipairs(oinfo.materials) do
                if m.texId and m.texId ~= "" and m.texId ~= "0" then
                    customTex = m
                    customSlot = tonumber(m.mat) or customSlot
                    break
                end
            end
        end
    end
    if not customTex and (sId ~= "") and trackedObjMaterials and trackedObjMaterials[sId] then
        if trackedObjMaterials[sId][tostring(customSlot)] then
            local tid = trackedObjMaterials[sId][tostring(customSlot)]
            customTex = { mat = customSlot, texId = tid, texName = "Tex #" .. tostring(tid), color = "0" }
        else
            for slot, tid in pairs(trackedObjMaterials[sId]) do
                if tid and tid ~= "" and tid ~= "0" then
                    customTex = { mat = slot, texId = tid, texName = "Tex #" .. tostring(tid), color = "0" }
                    customSlot = tonumber(slot) or customSlot
                    break
                end
            end
        end
    end

    -- 2. Извлекаем реальное нативное имя текстуры GTA:SA из модели
    local gtaTexOnSlot = gtaMats[customSlot] or gtaMats[0]
    local gtaTexName = gtaTexOnSlot and gtaTexOnSlot.name or ""
    if gtaTexName == "" then
        for _, gm in pairs(gtaMats) do
            if gm.name and gm.name ~= "" then
                gtaTexName = gm.name
                break
            end
        end
    end
    if gtaTexName == "" then
        gtaTexName = mName
    end

    if eyedropperSlot then eyedropperSlot[0] = customSlot end

    if customTex then
        -- Объект перекрашен серверной текстурой через /mtset
        eyedropperBuffer = {
            isCustom = true,
            objId = sId,
            modelId = mId,
            modelName = mName,
            slot = customSlot,
            texId = tostring(customTex.texId),
            texName = customTex.texName or ("Tex #" .. tostring(customTex.texId)),
            gtaTexture = gtaTexName,
            color = customTex.color or "0"
        }
        pcall(addAudioEventAtCoord, 1052, obj.x or 0, obj.y or 0, obj.z or 0)
        showToastQuick("Пипетка: Серверная текстура", string.format("Слот #%d: ID #%s (%s)", customSlot, eyedropperBuffer.texId, eyedropperBuffer.texName))
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Пипетка: Взята серверная текстура {FF9326}#%s (%s){FFFFFF} со слота {00E5FF}#%d{FFFFFF}", eyedropperBuffer.texId, eyedropperBuffer.texName, customSlot), -1)
    else
        -- Нативная текстура оригинальной GTA:SA
        eyedropperBuffer = {
            isCustom = false,
            objId = sId,
            modelId = mId,
            modelName = mName,
            slot = customSlot,
            texId = "",
            texName = gtaTexName,
            gtaTexture = gtaTexName,
            color = "0"
        }
        pcall(addAudioEventAtCoord, 1052, obj.x or 0, obj.y or 0, obj.z or 0)
        showToastQuick("Пипетка: Текстура GTA:SA", string.format("Слот #%d: \"%s\" (Модель #%d)", customSlot, gtaTexName, mId))
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Пипетка: Взята текстура GTA:SA {00E5FF}\"%s\"{FFFFFF} (Слот #%d, Модель #%d %s)", gtaTexName, customSlot, mId, mName), -1)
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Пипетка: Нажмите {FF9326}[ПКМ]{FFFFFF} чтобы скопировать {00E5FF}\"%s\"{FFFFFF} в буфер или нанести на объект!", gtaTexName), -1)
    end
end

function applyTextureToObj(obj)
    if not obj or not eyedropperBuffer then
        showToastQuick("Пипетка", "Буфер пуст! Сначала возьмите текстуру на [ЛКМ]")
        return
    end

    local targetSlot = (eyedropperSlot and eyedropperSlot[0]) or eyedropperBuffer.slot or 0
    local texVal = ""
    if eyedropperBuffer.texId and eyedropperBuffer.texId ~= "" and eyedropperBuffer.texId ~= "0" then
        texVal = tostring(eyedropperBuffer.texId)
    else
        texVal = eyedropperBuffer.gtaTexture or eyedropperBuffer.texName or ""
    end

    -- Копируем название/ID текстуры в буфер обмена на ПКМ
    if texVal ~= "" then
        setClipboardText(texVal)
    end

    local sId = tostring(obj.id or "")
    if sId == "" or sId == "0" then
        pcall(addAudioEventAtCoord, 1057, obj.x or 0, obj.y or 0, obj.z or 0)
        showToastQuick("Пипетка: Скопировано", string.format("Текстура \"%s\" скопирована в буфер обмена!", texVal))
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Пипетка: Текстура {00E5FF}\"%s\"{FFFFFF} скопирована в буфер обмена! Нанесите её через Текстуризацию или /mtset %d %s", texVal, targetSlot, texVal), -1)
        return
    end

    local col = eyedropperBuffer.color
    pcall(addAudioEventAtCoord, 1057, obj.x or 0, obj.y or 0, obj.z or 0)
    lua_thread.create(function()
        sampSendChat("/sel " .. sId)
        wait(160)
        sampSendChat(string.format("/mtset %d %s", targetSlot, texVal))
        if col and col ~= "" and col ~= "0" and col ~= "00000000" then
            wait(250)
            sampSendChat(string.format("/mtcol %d %s", targetSlot, col))
        end

        if not trackedObjMaterials then trackedObjMaterials = {} end
        if not trackedObjMaterials[sId] then trackedObjMaterials[sId] = {} end
        trackedObjMaterials[sId][targetSlot] = texVal

        if oinfoCache and oinfoCache[sId] then
            local found = false
            for _, m in ipairs(oinfoCache[sId].materials or {}) do
                if tonumber(m.mat) == targetSlot then
                    m.texId = texVal
                    m.color = col or "0"
                    m.texName = eyedropperBuffer.texName
                    found = true
                    break
                end
            end
            if not found then
                if not oinfoCache[sId].materials then oinfoCache[sId].materials = {} end
                table.insert(oinfoCache[sId].materials, {
                    mat = tostring(targetSlot),
                    texId = tostring(texVal),
                    color = col or "0",
                    texName = eyedropperBuffer.texName
                })
            end
        end

        showToastQuick("Пипетка: Применено", string.format("Объект #%s: Слот #%d -> %s (скопировано в буфер)", sId, targetSlot, texVal))
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Пипетка: Текстура {00E5FF}\"%s\"{FFFFFF} применена на слот {FF9326}#%d{FFFFFF} объекта {00E5FF}#%s{FFFFFF} и скопирована в буфер!", texVal, targetSlot, sId), -1)
    end)
end

function renderEyedropperHUD(self)
    if not eyedropperActive then return end
    local altDown = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
    if self then
        self.HideCursor = not altDown
        self.LockPlayer = altDown
    end

    local drawList = imgui.GetBackgroundDrawList()
    local sw, sh = getScreenResolution()
    local cx, cy = sw * 0.5, sh * 0.5
    local aimX, aimY = cx, cy
    if altDown then
        local mp = imgui.GetMousePos()
        aimX, aimY = mp.x, mp.y
        drawList:AddCircle(imgui.ImVec2(aimX, aimY), 6.5, 0xFF00FF88, 16, 1.8)
        drawList:AddCircleFilled(imgui.ImVec2(aimX, aimY), 2.5, 0xFFFFFFFF)
    end

    -- Прицел по центру экрана
    drawList:AddCircle(imgui.ImVec2(cx, cy), 7.0, 0xFFFFAA00, 16, 1.5)
    drawList:AddCircleFilled(imgui.ImVec2(cx, cy), 2.5, 0xFFFFFFFF)
    drawList:AddLine(imgui.ImVec2(cx - 14, cy), imgui.ImVec2(cx - 5, cy), 0xEEFFAA00, 1.8)
    drawList:AddLine(imgui.ImVec2(cx + 5, cy), imgui.ImVec2(cx + 14, cy), 0xEEFFAA00, 1.8)
    drawList:AddLine(imgui.ImVec2(cx, cy - 14), imgui.ImVec2(cx, cy - 5), 0xEEFFAA00, 1.8)
    drawList:AddLine(imgui.ImVec2(cx, cy + 5), imgui.ImVec2(cx, cy + 14), 0xEEFFAA00, 1.8)

    -- Подсветка наведенного объекта
    eyedropperHoverObj = getHoveredObject(aimX, aimY)

    if eyedropperHoverObj then
        local sx, sy = convert3DCoordsToScreen(eyedropperHoverObj.x, eyedropperHoverObj.y, eyedropperHoverObj.z)
        if sx and sy then
            local colRing = eyedropperBuffer and 0xFF00FF88 or 0xFFFFAA00
            drawList:AddCircle(imgui.ImVec2(sx, sy), 10.0, colRing, 16, 2.0)
            drawList:AddCircleFilled(imgui.ImVec2(sx, sy), 3.0, 0xFFFFFFFF)
            
            local idTag = (eyedropperHoverObj.id and eyedropperHoverObj.id ~= "") and ("#" .. eyedropperHoverObj.id) or "GTA:SA"
            local badge = string.format("%s | %s (#%d)", idTag, eyedropperHoverObj.modelName or "Object", eyedropperHoverObj.modelId or 0)
            local badgeU8 = safeU8(badge)
            local tw = imgui.CalcTextSize(badgeU8).x
            drawList:AddRectFilled(imgui.ImVec2(sx - tw*0.5 - 6, sy - 28), imgui.ImVec2(sx + tw*0.5 + 6, sy - 8), 0xEE111822, 5.0)
            drawList:AddText(imgui.ImVec2(sx - tw*0.5, sy - 26), 0xFFFFFFFF, badgeU8)

            local sId = tostring(eyedropperHoverObj.id or "")
            local curSlot = eyedropperSlot[0] or 0
            local matStr = nil

            -- Проверяем серверную текстуру
            local oinfo = (sId ~= "") and oinfoCache and oinfoCache[sId] or nil
            if oinfo and oinfo.materials and #oinfo.materials > 0 then
                for _, m in ipairs(oinfo.materials) do
                    if tonumber(m.mat) == curSlot and m.texId and m.texId ~= "" and m.texId ~= "0" then
                        matStr = string.format("Слот #%d: Серверная #%s (%s)", curSlot, m.texId, m.texName or "")
                        break
                    end
                end
            elseif (sId ~= "") and trackedObjMaterials and trackedObjMaterials[sId] and trackedObjMaterials[sId][tostring(curSlot)] then
                local tid = trackedObjMaterials[sId][tostring(curSlot)]
                matStr = string.format("Слот #%d: Серверная #%s", curSlot, tid)
            end

            -- Если серверной текстуры нет, читаем нативную текстуру GTA:SA из модели
            if not matStr then
                local h = eyedropperHoverObj.handle
                if not h and sId ~= "" and tonumber(sId) then
                    local okH, resH = pcall(sampGetObjectHandleBySampId, tonumber(sId))
                    if okH and resH and doesObjectExist(resH) then h = resH end
                end
                local gMats = h and getObjectGtaTextures(h) or {}
                local gTex = gMats[curSlot] or gMats[0]
                if gTex and gTex.name and gTex.name ~= "" then
                    matStr = string.format("Слот #%d: GTA:SA \"%s\"", curSlot, gTex.name)
                elseif eyedropperHoverObj.modelName then
                    matStr = string.format("Слот #%d: GTA:SA \"%s\"", curSlot, eyedropperHoverObj.modelName)
                elseif eyedropperHoverObj.modelId and eyedropperHoverObj.modelId > 0 then
                    matStr = string.format("Слот #%d: Модель #%d", curSlot, eyedropperHoverObj.modelId)
                end
            end

            if matStr then
                local matU8 = safeU8(matStr)
                local twm = imgui.CalcTextSize(matU8).x
                drawList:AddRectFilled(imgui.ImVec2(sx - twm*0.5 - 6, sy + 10), imgui.ImVec2(sx + twm*0.5 + 6, sy + 28), 0xEE111822, 5.0)
                drawList:AddText(imgui.ImVec2(sx - twm*0.5, sy + 12), 0xFFFFAA00, matU8)
            end
        end
    end

    -- Горячие клавиши управления
    local now = os.clock()
    if not sampIsChatInputActive() and not sampIsDialogActive() then
        if isKeyJustPressed(0x43) then -- C: сброс буфера
            eyedropperBuffer = nil
            showToastQuick("Пипетка", "Буфер очищен")
        end

        local wheel = imgui.GetIO().MouseWheel
        if wheel > 0.2 or isKeyJustPressed(0x51) then
            eyedropperSlot[0] = (eyedropperSlot[0] - 1 + 16) % 16
        elseif wheel < -0.2 or isKeyJustPressed(0x45) then
            eyedropperSlot[0] = (eyedropperSlot[0] + 1) % 16
        end

        -- ЛКМ = Взять текстуру (Sample)
        local lmb = isKeyJustPressed(0x01) or (altDown and imgui.IsMouseClicked(0)) or isKeyJustPressed(0x20) or isKeyJustPressed(0x0D)
        if lmb and (now - lastEyedropActionTime > 0.22) and eyedropperHoverObj then
            lastEyedropActionTime = now
            sampleTextureFromObj(eyedropperHoverObj, eyedropperSlot[0])
        end

        -- ПКМ = Применить текстуру (Apply)
        local rmb = isKeyJustPressed(0x02) or (altDown and imgui.IsMouseClicked(1))
        if rmb and (now - lastEyedropActionTime > 0.22) and eyedropperHoverObj then
            lastEyedropActionTime = now
            applyTextureToObj(eyedropperHoverObj)
        end
    end

    -- Верхний плавающий HUD (Адаптивный размер, чтобы никогда не вылезал текст)
    local titleStr = safeU8"ТЕКСТУРНАЯ ПИПЕТКА"
    local slotBadge = safeU8(string.format("[ Слот: #%d ]", eyedropperSlot[0]))

    local bufDesc
    local textOffsetX = 16.0
    local previewTex = nil

    if not eyedropperBuffer then
        bufDesc = safeU8"Наведите прицел на объект и нажмите [ ЛКМ ] чтобы скопировать текстуру"
    else
        local tNum = tonumber(eyedropperBuffer.texId)
        if tNum and getTex then previewTex = getTex(tNum) end
        if previewTex then
            textOffsetX = 58.0
        end

        if eyedropperBuffer.isCustom and eyedropperBuffer.texId ~= "" then
            bufDesc = safeU8(string.format("Буфер: Серверная текстура #%s (%s)   |   Слот #%d", eyedropperBuffer.texId, eyedropperBuffer.texName or "", eyedropperBuffer.slot or 0))
        else
            local gName = eyedropperBuffer.gtaTexture or eyedropperBuffer.texName or "Texture"
            bufDesc = safeU8(string.format("Буфер: Текстура GTA:SA \"%s\"   [ Слот #%d | Модель #%d %s ]", gName, eyedropperBuffer.slot or 0, eyedropperBuffer.modelId or 0, eyedropperBuffer.modelName or ""))
        end
    end

    local actionStr
    if not eyedropperBuffer then
        actionStr = safeU8"[ЛКМ] Взять   |   [Q / E / Колесико] Слот   |   [Alt] Курсор   |   [ESC] Выход"
    else
        actionStr = safeU8"[ЛКМ] Взять другую   |   [ПКМ] Применить/Копировать   |   [C] Сброс   |   [Alt] Курсор   |   [ESC] Выход"
    end

    local titleW = imgui.CalcTextSize(titleStr).x
    local slotBadgeW = imgui.CalcTextSize(slotBadge).x
    local line1W = titleW + slotBadgeW + 50.0
    local line2W = imgui.CalcTextSize(bufDesc).x + textOffsetX + 28.0
    local line3W = imgui.CalcTextSize(actionStr).x + textOffsetX + 28.0

    local maxTextW = math.max(line1W, math.max(line2W, line3W))
    local hudW = math.max(780.0, maxTextW + 36.0)
    if hudW > sw - 24.0 then hudW = sw - 24.0 end
    local hudH = 78.0
    local hx = (sw - hudW) * 0.5
    local hy = 32.0

    drawList:AddRectFilled(imgui.ImVec2(hx, hy), imgui.ImVec2(hx + hudW, hy + hudH), 0xEE111822, 8.0)
    drawList:AddRect(imgui.ImVec2(hx, hy), imgui.ImVec2(hx + hudW, hy + hudH), 0x33FFFFFF, 8.0, 15, 1.0)

    -- Строка 1: Заголовок и текущий слот
    drawList:AddText(imgui.ImVec2(hx + 14.0, hy + 8.0), 0xFFFFFFFF, titleStr)
    drawList:AddText(imgui.ImVec2(hx + hudW - slotBadgeW - 14.0, hy + 8.0), 0xFF00E5FF, slotBadge)
    drawList:AddLine(imgui.ImVec2(hx + 12.0, hy + 26.0), imgui.ImVec2(hx + hudW - 12.0, hy + 26.0), 0x33FFFFFF, 1.0)

    -- Строка 2: Описание буфера
    if previewTex then
        drawList:AddImage(previewTex, imgui.ImVec2(hx + 14.0, hy + 31.0), imgui.ImVec2(hx + 50.0, hy + 67.0))
    end
    local colDesc = eyedropperBuffer and 0xFF00FF88 or 0xFFFFAA00
    drawList:AddText(imgui.ImVec2(hx + textOffsetX, hy + 32.0), colDesc, bufDesc)

    -- Строка 3: Подсказки управления
    drawList:AddText(imgui.ImVec2(hx + textOffsetX, hy + 52.0), 0xFFDDDDDD, actionStr)
end

-- ============================================================================
batchTexRunning        = false
batchTexProgress       = 0
batchTexTotal          = 0
batchTexSrcTexBuf      = imgui.new.char[16]('')
batchTexNewTexBuf      = imgui.new.char[16]('')
batchTexSlot           = imgui.new.int(0)
batchTexUseSlotOnly    = imgui.new.bool(false)
batchTexScope          = imgui.new.int(0) -- 0 = Radius, 1 = Group, 2 = All
batchTexRadius         = imgui.new.float(30.0)
batchTexGroupBuf       = imgui.new.char[16]('1')

function cmd_batchtex()
    winOpen[0] = true
    activeTab = 5
    texSubTab = 2
end

function getBatchRetextureTargets()
    local targets = {}
    local px, py, pz = 0, 0, 0
    if PLAYER_PED and doesCharExist(PLAYER_PED) then
        px, py, pz = getCharCoordinates(PLAYER_PED)
    end
    local scope = batchTexScope[0]
    local rad = batchTexRadius[0]
    local grpStr = ffi.string(batchTexGroupBuf):gsub("^%s*(.-)%s*$", "%1")
    local srcTex = ffi.string(batchTexSrcTexBuf):gsub("^%s*(.-)%s*$", "%1")
    local slotOnly = batchTexUseSlotOnly[0]

    for _, it in ipairs(objListItems) do
        local matchScope = false
        if scope == 0 then
            if it.x and it.y and it.z then
                local d = getDistanceBetweenCoords3d(px, py, pz, it.x, it.y, it.z)
                if d <= rad then matchScope = true end
            end
        elseif scope == 1 then
            if grpStr ~= "" and tostring(it.group) == grpStr then
                matchScope = true
            end
        elseif scope == 2 then
            matchScope = true
        end

        if matchScope then
            if slotOnly or srcTex == "" then
                table.insert(targets, it)
            else
                local sId = tostring(it.id)
                local hasTex = false
                local oinfo = oinfoCache and oinfoCache[sId]
                if oinfo and oinfo.materials then
                    for _, m in ipairs(oinfo.materials) do
                        if tostring(m.texId) == srcTex then
                            hasTex = true
                            break
                        end
                    end
                end
                if not hasTex and trackedObjMaterials and trackedObjMaterials[sId] then
                    for _, tid in pairs(trackedObjMaterials[sId]) do
                        if tostring(tid) == srcTex then
                            hasTex = true
                            break
                        end
                    end
                end
                if hasTex then
                    table.insert(targets, it)
                end
            end
        end
    end
    return targets
end

function startBatchRetexture()
    if batchTexRunning then return end
    local targets = getBatchRetextureTargets()
    local newTex = ffi.string(batchTexNewTexBuf):gsub("^%s*(.-)%s*$", "%1")
    if newTex == "" then
        showToastQuick("Ошибка", "Укажите новый ID текстуры (или 0 для сброса)")
        return
    end
    if #targets == 0 then
        showToastQuick("Предупреждение", "Не найдено подходящих объектов для замены")
        return
    end

    local slot = batchTexSlot[0]
    batchTexRunning = true
    batchTexTotal = #targets
    batchTexProgress = 0

    lua_thread.create(function()
        for idx, obj in ipairs(targets) do
            if not batchTexRunning then break end
            batchTexProgress = idx
            sampSendChat("/sel " .. tostring(obj.id))
            wait(160)
            sampSendChat(string.format("/mtset %d %s", slot, newTex))
            local sId = tostring(obj.id)
            if not trackedObjMaterials[sId] then trackedObjMaterials[sId] = {} end
            trackedObjMaterials[sId][tostring(slot)] = newTex
            wait(280)
        end
        local doneCount = batchTexProgress
        batchTexRunning = false
        showToastQuick("Пакетная замена завершена", string.format("Обновлено объектов: %d из %d", doneCount, batchTexTotal))
    end)
end

function stopBatchRetexture()
    batchTexRunning = false
    showToastQuick("Пакетная замена", "Процесс остановлен")
end

function renderTabTextureBatch()
    imgui.Spacing()
    imgui.TextColored(accentColorA(1), fa.ICON_OBJECT_GROUP .. u8"  Пакетная замена текстур на объектах")
    imgui.TextDisabled(u8"Позволяет одновременно заменить текстуру сразу на множестве объектов (в радиусе, группе или на всей карте).")
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        imgui.TextColored(accentColor(), u8"1. Область применения:")
    if imgui.RadioButtonBool(u8"В радиусе от игрока##sc_r", batchTexScope[0] == 0) then batchTexScope[0] = 0 end
    imgui.SameLine(0, 16)
    if imgui.RadioButtonBool(u8"В выбранной группе##sc_g", batchTexScope[0] == 1) then batchTexScope[0] = 1 end
    imgui.SameLine(0, 16)
    if imgui.RadioButtonBool(u8"Все объекты маппинга##sc_a", batchTexScope[0] == 2) then batchTexScope[0] = 2 end
    imgui.Spacing()

    if batchTexScope[0] == 0 then
        imgui.PushItemWidth(260)
        imgui.SliderFloat(u8"Радиус поиска (м)##batch_rad", batchTexRadius, 5.0, 150.0, "%.1f")
        imgui.PopItemWidth()
    elseif batchTexScope[0] == 1 then
        imgui.Text(u8"Номер группы:")
        imgui.SameLine()
        imgui.PushItemWidth(100)
        imgui.InputText("##batch_grp_id", batchTexGroupBuf, 16)
        imgui.PopItemWidth()
    end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    imgui.TextColored(accentColor(), u8"2. Какую текстуру заменять:")
    imgui.Checkbox(u8"Заменять только в определенном слоте##b_slotsel", batchTexUseSlotOnly)
    imgui.Text(u8"Целевой слот (0..14):")
    imgui.SameLine()
    imgui.PushItemWidth(120)
    imgui.SliderInt("##batch_slot_idx", batchTexSlot, 0, 14)
    imgui.PopItemWidth()

    if not batchTexUseSlotOnly[0] then
        imgui.Text(u8"Исходный ID текстуры:")
        imgui.SameLine()
        imgui.PushItemWidth(140)
        imgui.InputTextWithHint("##batch_src_tex", u8"Например: 8993", batchTexSrcTexBuf, 16)
        imgui.PopItemWidth()
        imgui.SameLine()
        if imgui.Button(u8"x##b_clr_src", imgui.ImVec2(24, 0)) then ffi.fill(batchTexSrcTexBuf, 16, 0) end
    end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    imgui.TextColored(accentColor(), u8"3. Новая текстура (на что заменить):")
    imgui.Text(u8"Новый ID текстуры:")
    imgui.SameLine()
    imgui.PushItemWidth(140)
    imgui.InputTextWithHint("##batch_new_tex", u8"ID (0 - сброс)", batchTexNewTexBuf, 16)
    imgui.PopItemWidth()
    imgui.SameLine()
    if imgui.Button(fa.ICON_EYEDROPPER .. u8"  Из пипетки##b_paste_eye", imgui.ImVec2(125, 0)) then
        if eyedropperBuffer and eyedropperBuffer.texId then
            imgui.StrCopy(batchTexNewTexBuf, tostring(eyedropperBuffer.texId))
            batchTexSlot[0] = eyedropperBuffer.slot or 0
            showToastQuick("Пакетная замена", "Текстура #" .. eyedropperBuffer.texId .. " вставлена из буфера пипетки")
        else
            showToastQuick("Пипетка", "Буфер пипетки пуст")
        end
    end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    local targets = getBatchRetextureTargets()
    imgui.TextColored(imgui.ImVec4(0.8, 0.9, 0.5, 1.0), string.format(u8"Подходит объектов для замены: %d шт.", #targets))
    imgui.Spacing()

    if not batchTexRunning then
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.15, 0.55, 0.30, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.20, 0.68, 0.38, 1.0))
        if imgui.Button(fa.ICON_PLAY .. string.format(u8"  Запустить замену на %d объектах##b_run_btn", #targets), imgui.ImVec2(340, 34)) then
            startBatchRetexture()
        end
        imgui.PopStyleColor(2)
    else
        local pct = (batchTexTotal > 0) and (batchTexProgress / batchTexTotal) or 0.0
        imgui.ProgressBar(pct, imgui.ImVec2(340, 22), u8(string.format("Обновлено: %d / %d", batchTexProgress, batchTexTotal)))
        imgui.Spacing()
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.75, 0.15, 0.15, 1.0))
        if imgui.Button(fa.ICON_STOP .. u8"  Остановить замену##b_stop_btn", imgui.ImVec2(200, 30)) then
            stopBatchRetexture()
        end
        imgui.PopStyleColor()
    end
end


