function rgbToHex(r,g,b)
    local rgb = (r * 0x10000) + (g * 0x100) + b
    return bit.tohex(rgb, 6)
end

-- ==========================================
-- КАСТОМНЫЕ ЭЛЕМЕНТЫ ИНТЕРФЕЙСА
-- ==========================================
function RenderToggle(label, bool_ptr)
    local p = imgui.GetCursorScreenPos()
    local draw_list = imgui.GetWindowDrawList()
    local height = imgui.GetTextLineHeightWithSpacing() - 2
    local width = height * 1.8
    local radius = height * 0.5

    -- Невидимая кнопка для обработки клика
    if imgui.InvisibleButton(label, imgui.ImVec2(width, height)) then
        bool_ptr[0] = not bool_ptr[0]
    end

    -- Цвета в зависимости от состояния и темы
    local col_bg = bool_ptr[0] and imgui.GetColorU32(imgui.Col.ButtonActive) or imgui.GetColorU32(imgui.Col.FrameBgHovered)
    local col_circle = imgui.GetColorU32(imgui.Col.Text)

    -- Позиция кружочка
    local t = bool_ptr[0] and 1.0 or 0.0 
    
    -- Отрисовка
    draw_list:AddRectFilled(p, imgui.ImVec2(p.x + width, p.y + height), col_bg, radius)
    local circle_x = p.x + radius + (t * (width - radius * 2))
    draw_list:AddCircleFilled(imgui.ImVec2(circle_x, p.y + radius), radius - 1.5, col_circle)

    imgui.SameLine()
    imgui.Text(label)
end

