local function loadSettings()
    local defaultIni = {
        hotkey  = { alt="true",  ctrl="false", shift="false", key="78" },
        quick   = { alt="false", ctrl="false", shift="false", key="0"  },
        catalog = { cols="5" },
        hints    = { enabled = "true" },
        theme   = { current="bee" },
        notify  = { glist="true" },
        xmenu = { key = "71" },
        favmaps  = { alt="false", ctrl="false", shift="false", key="0" },
        favobj   = { alt="false", ctrl="false", shift="false", key="0" },
        delobj   = { alt="false", ctrl="false", shift="false", key="0" },
        jetpack = { alt="false", ctrl="false", shift="false", key="0" },
        editobj  = { alt="false", ctrl="false", shift="false", key="0" },
        objscan  = { alt="false", ctrl="false", shift="false", key="75" }, -- 75 это K
}
local ini = inicfg.load(defaultIni, INI_PATH)
    if ini and ini.snapping then
