function updateQuickGrpDisplay()
    local parts = {}
    if quickGrpHotkey_alt[0]   then parts[#parts+1] = "Alt"   end
    if quickGrpHotkey_ctrl[0]  then parts[#parts+1] = "Ctrl"  end
    if quickGrpHotkey_shift[0] then parts[#parts+1] = "Shift" end
    local kname = keyName(quickGrpHotkey_key[0])
    if parts[#parts] ~= kname then parts[#parts+1] = kname end
    imgui.StrCopy(quickGrpHotkey_display, table.concat(parts, " + "))
end

function updateQuickObjDisplay()
    local parts = {}
    if quickObjHotkey_alt[0]   then parts[#parts+1] = "Alt"   end
    if quickObjHotkey_ctrl[0]  then parts[#parts+1] = "Ctrl"  end
    if quickObjHotkey_shift[0] then parts[#parts+1] = "Shift" end
    local kname = keyName(quickObjHotkey_key[0])
    if parts[#parts] ~= kname then parts[#parts+1] = kname end
    imgui.StrCopy(quickObjHotkey_display, table.concat(parts, " + "))
end

function isQuickObjPressed()
    local vk = quickObjHotkey_key[0]
    if vk <= 0 then return false end
    if sampIsChatInputActive() then return false end
    if sampIsDialogActive()    then return false end
    if (isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)) ~= (quickObjHotkey_alt[0] == true)   then return false end
    if (isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)) ~= (quickObjHotkey_ctrl[0] == true)  then return false end
    if (isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)) ~= (quickObjHotkey_shift[0] == true) then return false end
    return isVkJustPressed(vk)
end

function isQuickGrpPressed()
