    if (isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)) ~= (quickGrpHotkey_shift[0] == true) then return false end
    return isVkJustPressed(vk)
end

function isVkJustPressed(vk)
    if vk == 0x12 or vk == 0xA4 or vk == 0xA5 then
        return isKeyJustPressed(0x12) or isKeyJustPressed(0xA4) or isKeyJustPressed(0xA5)
    elseif vk == 0x11 or vk == 0xA2 or vk == 0xA3 then
        return isKeyJustPressed(0x11) or isKeyJustPressed(0xA2) or isKeyJustPressed(0xA3)
    elseif vk == 0x10 or vk == 0xA0 or vk == 0xA1 then
        return isKeyJustPressed(0x10) or isKeyJustPressed(0xA0) or isKeyJustPressed(0xA1)
    end
    return isKeyJustPressed(vk)
end

