local function scanNearestObjLabel()
    local px, py, pz = getCharCoordinates(PLAYER_PED)
    local sw2, sh2 = getScreenResolution()
    local cx, cy = sw2 / 2, sh2 / 2
    local best = nil
    -- если круг выключен в настройках - используем маленький "точный" порог наведения
    local bestScreenDist = objScanCircleEnabled[0] and objScanCircleRadius or 18.0
    -- направление взгляда камеры (чтобы отсеивать лейблы за спиной)
    local camX, camY, camZ = getActiveCameraCoordinates()
    local atX, atY, atZ = getActiveCameraPointAt()
    local fwdX, fwdY, fwdZ = atX - camX, atY - camY, atZ - camZ
    if not next(labelCache) then
        for id = 0, 2047 do
            local ok, defined = pcall(sampIs3dTextDefined, id)
            if ok and defined then
                local ok2, text3d, _, lx, ly, lz = pcall(sampGet3dTextInfoById, id)
                if ok2 and text3d and text3d ~= "" then
                    labelCache[id] = {text = text3d, x = lx, y = ly, z = lz}
                    if updateKnownMapObjectFromLabel then
                        updateKnownMapObjectFromLabel(text3d, lx, ly, lz)
                    end
                end
            end
        end
    end
    for id, label in pairs(labelCache) do
        local cleanText = (label.text or ""):gsub("{%x%x%x%x%x%x}", "")
        local objNum, modelNum = cleanText:match("#(%d+)%s*[-–—]%s*#(%d+)")
        local furnIdx = cleanText:match("IDX:%s*(%d+)")

        if objNum or furnIdx then
            local dist = getDistanceBetweenCoords3d(px, py, pz, label.x, label.y, label.z)
            if dist < 40.0 then
                local toX, toY, toZ = label.x - camX, label.y - camY, label.z - camZ
                local inFront = (fwdX * toX + fwdY * toY + fwdZ * toZ) > 0
                local sx, sy = convert3DCoordsToScreen(label.x, label.y, label.z)
                if inFront and sx and sy then
                    local screenDist = math.sqrt((sx - cx)^2 + (sy - cy)^2)
                    if screenDist < bestScreenDist then
                        bestScreenDist = screenDist
                        if objNum then
                            best = {type = "object", id = objNum, modelId = modelNum, x = label.x, y = label.y, z = label.z, sx = sx, sy = sy, dist = math.floor(dist)}
                        else
                            best = {type = "furniture", id = furnIdx, x = label.x, y = label.y, z = label.z, sx = sx, sy = sy, dist = math.floor(dist)}
                        end
                    end
                end
            end
        end
    end
    return best
end

local function sendObjScanCommand(command)
    lua_thread.create(function()
        wait(50)
        sampSendChat(command)
        if command:match("^/sel") then
            wait(50)
            objEditorActive = false
            sampSetCursorMode(0, false)
        end
    end)
end

local function isObjScanActionPressed(vk)
    local down = isKeyDown(vk)
    local wasDown = objScanActionDown[vk] == true
    objScanActionDown[vk] = down
    return down and not wasDown
end

-- Опрос позиции объекта в фокусе для записи префаба
local prefabPosTrack = {}

lua_thread.create(function()
    while true do
        wait(150)
        if prefabRecording and not prefabPlaying then
            local best = scanNearestObjLabel()
            if best then
                if prefabPosTrack.id == best.id then
                    local EPS = 0.03
                    local dx = best.x - prefabPosTrack.x
                    local dy = best.y - prefabPosTrack.y
                    local dz = best.z - prefabPosTrack.z
                    if math.abs(dx) > EPS then addPrefabStep("/ox " .. string.format("%.2f", dx)) end
                    if math.abs(dy) > EPS then addPrefabStep("/oy " .. string.format("%.2f", dy)) end
                    if math.abs(dz) > EPS then addPrefabStep("/oz " .. string.format("%.2f", dz)) end
                end
                prefabPosTrack = {id = best.id, x = best.x, y = best.y, z = best.z}
            else
                prefabPosTrack = {}
            end
        else
            prefabPosTrack = {}
        end
    end
end)

local function isHotkeyPressed()
    local vk = hotkey_key[0]
    if vk <= 0 then return false end
    if sampIsChatInputActive() then return false end
    if sampIsDialogActive()    then return false end
    if (isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)) ~= _hk_alt   then return false end
    if (isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)) ~= _hk_ctrl  then return false end
    if (isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)) ~= _hk_shift then return false end
    return isVkJustPressed(vk)
end


function loadDB()
    if not doesFileExist(DB_PATH) then
        print("[TMT] БД не найдена: " .. DB_PATH)
        return
    end
    local f = io.open(DB_PATH, "r")
    if not f then return end
    local raw = f:read("*all")
    f:close()
    local ok, data = pcall(json.decode, raw)
    if not ok or type(data) ~= "table" then
        print("[TMT] Ошибка парсинга БД")
        return
    end
    for id, info in pairs(data) do
        if info and info.model_name then
            table.insert(allObjects, {
                id     = tostring(id),
                name   = tostring(info.model_name),
                radius = info.radius or 0,
                length = info.length or 0,
                width  = info.width  or 0,
                height = info.height or 0,
            })
            ::skip_obj::
        end
    end
        print("[TMT] Загружено: " .. #allObjects .. " объектов")
end

