local function loadCategoryFile(filePath, orderList)
    if not doesFileExist(filePath) then return nil, nil end
    local f = io.open(filePath, "r")
    if not f then return nil, nil end
    local raw_data = f:read("*all")
    f:close()
    local ok, data = pcall(json.decode, raw_data)
    if not ok or type(data) ~= "table" then return nil, nil end

    local cats = {}
    local allIds = {}
    for _, catKey in ipairs(orderList) do
        local catInfo = data[catKey]
        if catInfo then
            local idMap = {}
            for _, idNum in ipairs(catInfo.ids or {}) do
                local n = tonumber(idNum)
                if n and n ~= 3 then
                    idMap[n] = true
                    allIds[n] = true
                end
            end
            table.insert(cats, {
                key    = catKey,
                name   = catInfo.name or catKey,
                img    = catInfo.img or "cat_box.png",
                id_map = idMap,
                keys   = {}
            })
        end
    end
    return cats, allIds
end

function loadIdebaseCategories()
    loadInteriors()
    local gtaCats, gtaIds = loadCategoryFile(IDEBASE_PATH, idebaseCategoryOrder)
    if gtaCats and #gtaCats > 0 then
        gtaSaCategories = gtaCats
        gtaSaAllIds = gtaIds or {}
    end

    local sampCats, sIds = loadCategoryFile(SAMP_CAT_PATH, sampCategoryOrder)
    if sampCats and #sampCats > 0 then
        sampCategories = sampCats
        sampAllIds = sIds or {}
    end

    if #allObjects > 0 then
        buildCatCounts()
    end

    if catGameMode == 2 and #sampCategories > 0 then
        objCategories = sampCategories
        catCounts = sampCatCounts
    elseif #gtaSaCategories > 0 then
        objCategories = gtaSaCategories
        catCounts = gtaCatCounts
    end

    return true
end

