local function addToRecent(obj)
    lastCreatedObj = obj
    for i, r in ipairs(recentObjects) do
        if r.id == obj.id then table.remove(recentObjects, i); break end
    end
    local d = os.date("*t")
    local dateStr = string.format("%02d.%02d.%04d", d.day, d.month, d.year)
    table.insert(recentObjects, 1, {id=obj.id, name=obj.name, radius=obj.radius,
        length=obj.length, width=obj.width, height=obj.height, date=dateStr})
    if #recentObjects > 200 then table.remove(recentObjects) end
    saveRecent()
end

local function isQuickPressed()
    local vk = quick_key[0]
    if vk == 0 then return false end
    if (isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)) ~= quick_alt[0]   then return false end
    if (isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)) ~= quick_ctrl[0]  then return false end
    if (isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)) ~= quick_shift[0] then return false end
    return isVkJustPressed(vk)
end

