local function applyFilter()
    local q = ffi.string(searchBuf):lower()

    local ruKeywords = nil
    if q ~= "" then
        local qCyr = cyrLower(ffi.string(searchBuf))
        for _, entry in ipairs(ruSearchSynonyms) do
            for _, ruWord in ipairs(entry.ru) do
                if qCyr:find(ruWord, 1, true) or ruWord:find(qCyr, 1, true) then
                    ruKeywords = entry.keys
                    break
                end
            end
            if ruKeywords then break end
        end
        if not ruKeywords then
            for _, cat in ipairs(objCategories) do
                local catNameLow = cyrLower(cat.name)
                if catNameLow:find(qCyr, 1, true) or qCyr:find(catNameLow, 1, true) then
                    ruKeywords = cat.keys
                    break
                end
            end
        end
    end
    local t = {}
    for _, o in ipairs(allObjects) do
        -- фильтр по поиску
        local matchSearch = q == "" or o.id:find(q, 1, true) or (o.name or ""):lower():find(q, 1, true)
        if not matchSearch and ruKeywords then
            local nameLow = (o.name or ""):lower()
            for _, kw in ipairs(ruKeywords) do
                if nameLow:find(kw, 1, true) then matchSearch = true; break end
            end
        end
        -- фильтр по категории
        local matchCat = true
        if activeInterior then
            local numId = tonumber(o.id)
            if not (numId and activeInterior.model_map and activeInterior.model_map[numId]) then
                matchCat = false
            end
        elseif activeCatFilter > 0 then
            local cat = objCategories[activeCatFilter]
            matchCat = false
            if cat then
                if cat.id_map then
                    local numId = tonumber(o.id)
                    if numId and cat.id_map[numId] then
                        matchCat = true
                    end
                elseif cat.keys then
                    local nameLow = (o.name or ""):lower()
                    for _, kw in ipairs(cat.keys) do
                        if nameLow:find(kw, 1, true) then
                            matchCat = true
                            break
                        end
                    end
                end
            end
        else
            if catGameMode == 2 then
                local numId = tonumber(o.id)
                if not (numId and sampAllIds[numId]) then
                    matchCat = false
                end
            end
        end
        local matchRadius = not sceneSpawnPickMode or (tonumber(o.radius) or 0) <= 15
        if matchSearch and matchCat and matchRadius then
            t[#t + 1] = o
        end
    end
    if sortMode == 0 then
        table.sort(t, function(a, b) return (tonumber(a.id) or 0) < (tonumber(b.id) or 0) end)
    elseif sortMode == 1 then
        table.sort(t, function(a, b)
            local na = tonumber(a.name:match("^#?(%d+)"))
            local nb = tonumber(b.name:match("^#?(%d+)"))
            if na and nb then return na < nb end
            if na then return true end
            if nb then return false end
            return a.name:lower() < b.name:lower()
        end)
    elseif sortMode == 2 then
        table.sort(t, function(a, b)
            local na = tonumber(a.name:match("^#?(%d+)"))
            local nb = tonumber(b.name:match("^#?(%d+)"))
            if na and nb then return na > nb end
            if na then return false end
            if nb then return true end
            return a.name:lower() > b.name:lower()
        end)
    elseif sortMode == 3 then
        table.sort(t, function(a, b) return (a[sizeMetric] or 0) > (b[sizeMetric] or 0) end)
    elseif sortMode == 4 then
        table.sort(t, function(a, b) return (a[sizeMetric] or 0) < (b[sizeMetric] or 0) end)
    end
    shownObjects = t
    currentPage  = 1
end

local MAX_TEX_PER_FRAME  = 6
local MAX_CACHED_TEXTURES = 500
local texLoadedThisFrame = 0
texLastUsed = texLastUsed or {}

local function resetTexCounter()
    texLoadedThisFrame = 0
end

local function loadTexInternal(id, isPreload)
    if textures[id] then
        texLastUsed[id] = os.clock()
        return textures[id]
    end
    if texFailed[id] then return nil end

    if not imgui.IsInitialized() then return nil end
    if texLoadedThisFrame >= MAX_TEX_PER_FRAME then return nil end

    local path = IMG_DIR .. id .. ".png"
    if not doesFileExist(path) then
        texFailed[id] = true
        return nil
    end

    texLoadedThisFrame = texLoadedThisFrame + 1
    local ok, t = pcall(imgui.CreateTextureFromFile, path)
    if ok and t then
        textures[id] = t
        local now = os.clock()
        texLastUsed[id] = now
        -- Предзагруженные заранее текстуры не должны ждать fade-in анимацию при открытии страницы
        texLoadTimes[id] = isPreload and (now - 0.25) or now
        return t
    end
    texLoadedThisFrame = texLoadedThisFrame - 1
    return nil
end

local function getTex(id)
    return loadTexInternal(id, false)
end

local function preloadTex(id)
    return loadTexInternal(id, true)
end

local nativeTexCache = {}
local nativeTexFailed = {}
local function getNativeTex(id)
    if nativeTexCache[id] then return nativeTexCache[id] end
    if nativeTexFailed[id] then return nil end
    local path = IMG_DIR .. id .. ".png"
    if not doesFileExist(path) then nativeTexFailed[id] = true; return nil end
    local ok, tex = pcall(renderLoadTextureFromFile, path)
    if ok and tex then nativeTexCache[id] = tex; return tex end
    nativeTexFailed[id] = true
    return nil
end

