function accentColor()
    local t = THEMES[currentTheme]
    return (t and t.HeaderA) or imgui.ImVec4(0.90, 0.45, 0.00, 1.0)
end

function accentColorHex()
    local c = accentColor()
    local r = math.floor(c.x * 255 + 0.5)
    local g = math.floor(c.y * 255 + 0.5)
    local b = math.floor(c.z * 255 + 0.5)
    return r * 0x10000 + g * 0x100 + b
end

function accentColorA(a)
    local c = accentColor()
    return imgui.ImVec4(c.x, c.y, c.z, a)
end

function cardBgHex()
    local t = THEMES[currentTheme]
    local c = (t and t.FrameBg) or imgui.ImVec4(0.16, 0.16, 0.16, 1.0)
    local r = math.floor(c.x * 255 + 0.5)
    local g = math.floor(c.y * 255 + 0.5)
    local b = math.floor(c.z * 255 + 0.5)
    return r * 0x10000 + g * 0x100 + b
end

function getBrightThemeBtnColors()
    local t = THEMES and THEMES[currentTheme]
    local btn = (t and t.ButtonH) or accentColorA(0.85)
    local hov = (t and t.ButtonA) or accentColorA(1.00)
    local act = (t and t.HeaderA) or accentColorA(0.70)
    return btn, hov, act
end

local logoTex = nil
local logoTexFailed = false
local function getLogoTex()
    if logoTex or logoTexFailed then return logoTex end
    if not doesFileExist(LOGO_PATH) then logoTexFailed = true; return nil end
    local ok, t = pcall(imgui.CreateTextureFromFile, LOGO_PATH)
    if ok and t then logoTex = t else logoTexFailed = true end
    return logoTex
end

local function applyTheme(key)
    local t = THEMES[key] or THEMES.bee
    local s = imgui.GetStyle()
    local c = s.Colors
    
    -- Основные цвета из темы
    c[imgui.Col.WindowBg]             = t.WindowBg
    c[imgui.Col.ChildBg]              = t.ChildBg
    c[imgui.Col.FrameBg]              = t.FrameBg
    c[imgui.Col.FrameBgHovered]       = t.FrameBgH
    c[imgui.Col.ScrollbarBg]          = t.ScrollBg
    c[imgui.Col.ScrollbarGrab]        = t.ScrollG
    c[imgui.Col.ScrollbarGrabHovered] = t.ScrollGH
    c[imgui.Col.Button]               = t.Button
    c[imgui.Col.ButtonHovered]        = t.ButtonH
    c[imgui.Col.ButtonActive]         = t.ButtonA
    c[imgui.Col.Header]               = t.Header
    c[imgui.Col.HeaderHovered]        = t.HeaderH
    c[imgui.Col.HeaderActive]         = t.HeaderA
    c[imgui.Col.Separator]            = t.Separator
    c[imgui.Col.Text]                 = t.Text
    
    -- Дополняем современные элементы интерфейса (наследуем от существующих цветов)
    c[imgui.Col.TitleBg]              = t.ChildBg
    c[imgui.Col.TitleBgActive]        = t.FrameBgH
    c[imgui.Col.TitleBgCollapsed]     = t.WindowBg
    
    c[imgui.Col.CheckMark]            = t.ButtonA
    c[imgui.Col.SliderGrab]           = t.ButtonH
    c[imgui.Col.SliderGrabActive]     = t.ButtonA
    
    c[imgui.Col.Tab]                  = t.FrameBg
    c[imgui.Col.TabHovered]           = t.ButtonH
    c[imgui.Col.TabActive]            = t.Button
    
    c[imgui.Col.Border]               = imgui.ImVec4(t.Separator.x, t.Separator.y, t.Separator.z, 0.50)
    c[imgui.Col.BorderShadow]         = imgui.ImVec4(0.00, 0.00, 0.00, 0.00)
    
    -- Настройка толщины рамок (убираем лишние контуры для минимализма)
    s.WindowBorderSize = 0.0
    s.ChildBorderSize  = 1.0
    s.PopupBorderSize  = 1.0
    s.FrameBorderSize  = 0.0
