local cyrLowerMap = {
    [u8"А"]=u8"а", [u8"Б"]=u8"б", [u8"В"]=u8"в", [u8"Г"]=u8"г", [u8"Д"]=u8"д",
    [u8"Е"]=u8"е", [u8"Ё"]=u8"ё", [u8"Ж"]=u8"ж", [u8"З"]=u8"з", [u8"И"]=u8"и",
    [u8"Й"]=u8"й", [u8"К"]=u8"к", [u8"Л"]=u8"л", [u8"М"]=u8"м", [u8"Н"]=u8"н",
    [u8"О"]=u8"о", [u8"П"]=u8"п", [u8"Р"]=u8"р", [u8"С"]=u8"с", [u8"Т"]=u8"т",
    [u8"У"]=u8"у", [u8"Ф"]=u8"ф", [u8"Х"]=u8"х", [u8"Ц"]=u8"ц", [u8"Ч"]=u8"ч",
    [u8"Ш"]=u8"ш", [u8"Щ"]=u8"щ", [u8"Ъ"]=u8"ъ", [u8"Ы"]=u8"ы", [u8"Ь"]=u8"ь",
    [u8"Э"]=u8"э", [u8"Ю"]=u8"ю", [u8"Я"]=u8"я",
}

function cyrLower(s)
    s = s:lower() -- латиница как обычно
    local out = {}
    local i, len = 1, #s
    while i <= len do
        local b = s:byte(i)
        if b == 0xD0 or b == 0xD1 then -- начало 2-байтового UTF-8 символа кириллицы
            local ch2 = s:sub(i, i + 1)
            out[#out + 1] = cyrLowerMap[ch2] or ch2
            i = i + 2
        else
            out[#out + 1] = s:sub(i, i)
            i = i + 1
        end
    end
    return table.concat(out)
end

local function destroyInspectGhost()
    if not inspectHandle then return end
    local h = inspectHandle
    inspectHandle = nil
    -- пробуем оба варианта напрямую, без проверки doesObjectExist —
    -- локально созданный через createObject() объект не синхронизирован с сервером,
    -- поэтому doesObjectExist() для него мог всегда возвращать false и блокировать удаление
    pcall(deleteObject, h)
    pcall(destroyObject, h)
end

local function stopInspect(spawn)
    destroyInspectGhost()
    inspectActive = false
    pcall(masterCamHook.stop)
    camHackActive = false
    camHackLooking = false
    pcall(freezeCharPosition, PLAYER_PED, false)
    lockPlayerControl(false)
    sampSetCursorMode(0, false) -- Принудительно отдаем управление
    pcall(restoreCameraJumpcut)
    pcall(setCameraBehindPlayer)

    if spawn and inspectObj then
        local rx, ry, rz = inspectRX, inspectRY, inspectRZ
        sampSendChat("/cr " .. inspectObj.id)
        lua_thread.create(function()
            wait(400)
            if rx ~= 0 then sampSendChat("/rx " .. string.format("%.0f", rx)); wait(300) end
            if ry ~= 0 then sampSendChat("/ry " .. string.format("%.0f", ry)); wait(300) end
            if rz ~= 0 then sampSendChat("/rz " .. string.format("%.0f", rz)) end
        end)
    end

    inspectObj = nil
end

local function clearSceneObjects()
    for _, o in ipairs(sceneObjects) do
        pcall(deleteObject, o.handle)
        pcall(destroyObject, o.handle)
    end
    sceneObjects  = {}
    sceneSelected = nil
end

local function startSceneEditor()
    clearSceneObjects()
    sceneSteps = {}

    local px, py, pz = getCharCoordinates(PLAYER_PED)
    sceneOrigX, sceneOrigY, sceneOrigZ = px, py, SCENE_SKY_Z

    sceneCamX, sceneCamY, sceneCamZ = px, py, SCENE_SKY_Z + 3.0
    sceneCamYaw, sceneCamPitch = 0.0, 0.0

    pcall(freezeCharPosition, PLAYER_PED, true)
    pcall(masterCamHook.start)

    sceneEditorActive = true
    winOpen[0] = false

    toast_text  = "Редактор объектов включён"
    toast_text2 = "ПКМ + мышь/WASD — камера, клик по объекту в каталоге — спавн"
    toast_tex   = nil
    toast_timer = 150
end

local function loadPrefabIntoScene(prefab)
    startSceneEditor()

    local curId, curDX, curDY, curDZ, curRX, curRY, curRZ = nil, 0,0,0, 0,0,0

    local function flushCurrent()
        if not curId then return end
        local x = sceneOrigX + curDX
        local y = sceneOrigY + curDY
        local z = sceneOrigZ + curDZ
        local ok, handle = pcall(createObject, tonumber(curId), x, y, z)
        if ok and handle then
            pcall(setObjectRotation, handle, curRX, curRY, curRZ)
            local nm = curId
            for _, ao in ipairs(allObjects) do
                if ao.id == curId then nm = ao.name; break end
            end
            table.insert(sceneObjects, {handle=handle, id=curId, name=nm, x=x, y=y, z=z, rx=curRX, ry=curRY, rz=curRZ})
        end
    end

    for _, step in ipairs(prefab.steps or {}) do
        local nm, arg = step:match("^/(%a+)%s*(.-)%s*$")
        if nm then
            nm = nm:lower()
            if nm == "cr" then
                flushCurrent()
                curId = arg:match("%d+")
                curDX, curDY, curDZ, curRX, curRY, curRZ = 0,0,0,0,0,0
            elseif nm == "ox" then curDX = curDX + (tonumber(arg) or 0)
            elseif nm == "oy" then curDY = curDY + (tonumber(arg) or 0)
            elseif nm == "oz" then curDZ = curDZ + (tonumber(arg) or 0)
            elseif nm == "rx" then curRX = curRX + (tonumber(arg) or 0)
            elseif nm == "ry" then curRY = curRY + (tonumber(arg) or 0)
            elseif nm == "rz" then curRZ = curRZ + (tonumber(arg) or 0)
            end
        end
    end
    flushCurrent()

    sceneSelected = (#sceneObjects > 0) and 1 or nil

    toast_text  = "Постройка загружена в редактор"
    toast_text2 = prefab.name .. " — " .. #sceneObjects .. u8" объектов"
    toast_tex   = nil
    toast_timer = 150
end

local function stopSceneEditor()
    clearSceneObjects()
    sceneEditorActive = false
    pcall(masterCamHook.stop)
    pcall(freezeCharPosition, PLAYER_PED, false)
    lockPlayerControl(false)
    sampSetCursorMode(0, false)
    pcall(restoreCameraJumpcut)
    pcall(setCameraBehindPlayer)
    winOpen[0] = true
end

local function sceneSpawnObject(obj)
    local dist = math.max(5.0, (tonumber(obj.radius) or 0) * 2.5)
    local fx = -math.cos(sceneCamYaw) * math.cos(sceneCamPitch)
    local fy = -math.sin(sceneCamYaw) * math.cos(sceneCamPitch)
    local fz = math.sin(sceneCamPitch)
    local x = sceneCamX + fx * dist
    local y = sceneCamY + fy * dist
    local z = sceneCamZ + fz * dist

    local ok, handle = pcall(createObject, tonumber(obj.id), x, y, z, 0, 0, 0)
    if not ok then return end

    table.insert(sceneObjects, {handle=handle, id=obj.id, name=obj.name, x=x, y=y, z=z, rx=0, ry=0, rz=0})
    sceneSelected = #sceneObjects

    -- запись шага (относительно точки отсчёта сцены)
    table.insert(sceneSteps, {type="spawn", id=obj.id,
        dx = x - sceneOrigX, dy = y - sceneOrigY, dz = z - sceneOrigZ, rx=0, ry=0, rz=0})
end

local function sceneDeleteSelected()
    if not sceneSelected or not sceneObjects[sceneSelected] then return end
    local o = sceneObjects[sceneSelected]
    pcall(deleteObject, o.handle)
    pcall(destroyObject, o.handle)
    table.remove(sceneObjects, sceneSelected)
    sceneSelected = nil
end

local function buildCommandsFromScene()
    local cmds = {}
    for _, o in ipairs(sceneObjects) do
        table.insert(cmds, "/cr " .. o.id)
        local dx = o.x - sceneOrigX
        local dy = o.y - sceneOrigY
        local dz = o.z - sceneOrigZ
        if math.abs(dx) > 0.001 then table.insert(cmds, "/ox " .. string.format("%.2f", dx)) end
        if math.abs(dy) > 0.001 then table.insert(cmds, "/oy " .. string.format("%.2f", dy)) end
        if math.abs(dz) > 0.001 then table.insert(cmds, "/oz " .. string.format("%.2f", dz)) end
        if math.abs(o.rx) > 0.001 then table.insert(cmds, "/rx " .. string.format("%.1f", o.rx)) end
        if math.abs(o.ry) > 0.001 then table.insert(cmds, "/ry " .. string.format("%.1f", o.ry)) end
        if math.abs(o.rz) > 0.001 then table.insert(cmds, "/rz " .. string.format("%.1f", o.rz)) end
    end
    return cmds
end

