    } GdiplusStartupInput;
    typedef struct {
        unsigned long  Data1;
        unsigned short Data2;
        unsigned short Data3;
        unsigned char  Data4[8];
    } CLSID;

    int GdiplusStartup(unsigned long* token, const GdiplusStartupInput* input, void* output);
    void GdiplusShutdown(unsigned long token);
    int GdipLoadImageFromFile(const wchar_t* filename, GpImage** image);
    int GdipGetImageWidth(GpImage* image, uint32_t* width);
    int GdipGetImageHeight(GpImage* image, uint32_t* height);
    int GdipCreateBitmapFromScan0(int width, int height, int stride, int format, unsigned char* scan0, GpBitmap** bitmap);
    int GdipGetImageGraphicsContext(GpImage* image, GpGraphics** graphics);
    int GdipSetInterpolationMode(GpGraphics* graphics, int interpolationMode);
    int GdipDrawImageRectRectI(GpGraphics* graphics, GpImage* image, int dstx, int dsty, int dstwidth, int dstheight, int srcx, int srcy, int srcwidth, int srcheight, int srcUnit, void* imageAttributes, void* callback, void* callbackData);
    int GdipGetImageThumbnail(GpImage* image, uint32_t thumbWidth, uint32_t thumbHeight, GpImage** thumbImage, void* callback, void* callbackData);
    int GdipSaveImageToFile(GpImage* image, const wchar_t* filename, const CLSID* clsidEncoder, void* encoderParams);
    int GdipDisposeImage(GpImage* image);
    int GdipDeleteGraphics(GpGraphics* graphics);

    int MultiByteToWideChar(unsigned int CodePage, unsigned long dwFlags, const char* lpMultiByteStr, int cbMultiByte, wchar_t* lpWideCharStr, int cchWideChar);
    int SHGetFolderPathA(void* hwnd, int csidl, void* hToken, unsigned long dwFlags, char* pszPath);
    void keybd_event(unsigned char bVk, unsigned char bScan, unsigned long dwFlags, void* dwExtraInfo);

    typedef struct {
        unsigned long dwLowDateTime;
        unsigned long dwHighDateTime;
    } FILETIME;
    typedef struct {
        unsigned long dwFileAttributes;
        FILETIME ftCreationTime;
        FILETIME ftLastAccessTime;
        FILETIME ftLastWriteTime;
        unsigned long nFileSizeHigh;
        unsigned long nFileSizeLow;
        unsigned long dwReserved0;
        unsigned long dwReserved1;
        char cFileName[260];
        char cAlternateFileName[14];
    } WIN32_FIND_DATAA;

    void* FindFirstFileA(const char* lpFileName, WIN32_FIND_DATAA* lpFindFileData);
    int FindNextFileA(void* hFindFile, WIN32_FIND_DATAA* lpFindFileData);
    int FindClose(void* hFindFile);
]]

PREFAB_PREVIEWS_DIR = ROOT .. "\\resource\\Trinity Mapper Tools Resource\\prefab-previews"
