    pcall(createDirectory, PREFAB_PREVIEWS_DIR)
end

prefabPreviewCache = {}
prefabPhotoMode = false
prefabPhotoCapturing = false
prefabPhotoHideOverlay = false
prefabSnapTargetIdx = nil
newPrefabPreviewName = nil

local gdiplusLib = nil
local pngClsidStruct = nil
local jpgClsidStruct = nil

local function initGdiplus()
    if gdiplusLib then return true end
    local ok, g = pcall(ffi.load, "gdiplus.dll")
    if not ok or not g then
        ok, g = pcall(ffi.load, "gdiplus")
    end
    if ok and g then
        gdiplusLib = g
        pngClsidStruct = ffi.new("CLSID", {
            0x557cf406, 0x1a04, 0x11d3,
            {0x9a, 0x73, 0x00, 0x00, 0xf8, 0x1e, 0xf3, 0x2e}
        })
        jpgClsidStruct = ffi.new("CLSID", {
            0x557cf401, 0x1a04, 0x11d3,
            {0x9a, 0x73, 0x00, 0x00, 0xf8, 0x1e, 0xf3, 0x2e}
        })
        return true
    end
    return false
end

local function strToWide(str)
    if not str then return nil end
    local len = ffi.C.MultiByteToWideChar(0, 0, str, -1, nil, 0)
    if len <= 0 then
        len = ffi.C.MultiByteToWideChar(65001, 0, str, -1, nil, 0)
    end
    if len <= 0 then return nil end
    local buf = ffi.new("wchar_t[?]", len)
    ffi.C.MultiByteToWideChar(0, 0, str, -1, buf, len)
    return buf
end

function getScreensDirectory()
    local path = (os.getenv("USERPROFILE") or "") .. "\\Documents\\GTA San Andreas User Files\\SAMP\\screens"
    if doesDirectoryExist(path) then
        return path
    end
    local buf = ffi.new("char[260]")
    if pcall(ffi.C.SHGetFolderPathA, nil, 5, nil, 0, buf) then
        local docs = ffi.string(buf)
        local p2 = docs .. "\\GTA San Andreas User Files\\SAMP\\screens"
        if doesDirectoryExist(p2) then
            return p2
        end
    end
    return path
end

local function getLatestScreenshotFile(screensDir)
    if not screensDir then return nil end
    local fd = ffi.new("WIN32_FIND_DATAA")
    local pattern = screensDir .. "\\*.*"
    local h = ffi.C.FindFirstFileA(pattern, fd)
    if h == ffi.cast("void*", -1) then return nil end

    local bestName = nil
    local bestTime = 0
    repeat
        local fname = ffi.string(fd.cFileName)
        local low = fname:lower()
        if low:match("%.png$") or low:match("%.jpg$") then
            local timeHigh = tonumber(fd.ftLastWriteTime.dwHighDateTime)
            local timeLow = tonumber(fd.ftLastWriteTime.dwLowDateTime)
            local ftime = timeHigh * 4294967296 + timeLow
            if ftime > bestTime then
                bestTime = ftime
                bestName = fname
            end
        end
    until ffi.C.FindNextFileA(h, fd) == 0

    ffi.C.FindClose(h)
    return bestName, bestTime
end

local function cropAndResizePrefabPreview(srcPath, dstPath, normX0, normY0, normW, normH, targetSize)
    if not initGdiplus() then return false, "initGdiplus failed" end
    targetSize = targetSize or 160
    local token = ffi.new("unsigned long[1]")
    local input = ffi.new("GdiplusStartupInput", {1, nil, 0, 0})
    if gdiplusLib.GdiplusStartup(token, input, nil) ~= 0 then
        return false, "GdiplusStartup failed"
    end

    local img = ffi.new("GpImage*[1]")
    local wSrc = strToWide(srcPath)
    if not wSrc then
        gdiplusLib.GdiplusShutdown(token[0])
        return false, "strToWide failed: " .. tostring(srcPath)
    end

    -- Retry-цикл: ждём, пока SA-MP полностью запишет и закроет файл на диске
    local loaded = false
    local retryDeadline = os.clock() + 3.0
    while os.clock() < retryDeadline do
        local st = gdiplusLib.GdipLoadImageFromFile(wSrc, img)
        if st == 0 and img[0] ~= nil then
            loaded = true
            break
        end
        wait(100)
    end

    if not loaded then
        gdiplusLib.GdiplusShutdown(token[0])
        return false, "GdipLoadImageFromFile failed (файл заблокирован): " .. tostring(srcPath)
    end

    local w = ffi.new("uint32_t[1]")
    local h = ffi.new("uint32_t[1]")
    gdiplusLib.GdipGetImageWidth(img[0], w)
    gdiplusLib.GdipGetImageHeight(img[0], h)

    local width = tonumber(w[0])
    local height = tonumber(h[0])

    local cropX = math.floor((normX0 or 0.25) * width)
    local cropY = math.floor((normY0 or 0.25) * height)
    local cropW = math.floor((normW or 0.5) * width)
    local cropH = math.floor((normH or 0.5) * height)

    if cropX < 0 then cropX = 0 end
    if cropY < 0 then cropY = 0 end
    if cropX + cropW > width then cropW = width - cropX end
    if cropY + cropH > height then cropH = height - cropY end

    local bmp = ffi.new("GpBitmap*[1]")
    if gdiplusLib.GdipCreateBitmapFromScan0(targetSize, targetSize, 0, 0x26200A, nil, bmp) ~= 0 then
        gdiplusLib.GdipDisposeImage(img[0])
        gdiplusLib.GdiplusShutdown(token[0])
        return false, "GdipCreateBitmapFromScan0 failed"
    end

    local gfx = ffi.new("GpGraphics*[1]")
    gdiplusLib.GdipGetImageGraphicsContext(ffi.cast("GpImage*", bmp[0]), gfx)
    gdiplusLib.GdipSetInterpolationMode(gfx[0], 7) -- HighQualityBicubic

    gdiplusLib.GdipDrawImageRectRectI(gfx[0], img[0], 0, 0, targetSize, targetSize, cropX, cropY, cropW, cropH, 2, nil, nil, nil)

    local wDst = strToWide(dstPath)
    local saveRes = gdiplusLib.GdipSaveImageToFile(ffi.cast("GpImage*", bmp[0]), wDst, pngClsidStruct, nil)

    gdiplusLib.GdipDeleteGraphics(gfx[0])
    gdiplusLib.GdipDisposeImage(ffi.cast("GpImage*", bmp[0]))
    gdiplusLib.GdipDisposeImage(img[0])
    gdiplusLib.GdiplusShutdown(token[0])

    if saveRes ~= 0 then
        return false, "GdipSaveImageToFile failed: " .. tostring(saveRes)
    end
    return true
end

function generateGalleryThumbnail(srcPath, dstPath, thumbW, thumbH)
    if not initGdiplus() then return false end
    thumbW = thumbW or 320
    thumbH = thumbH or 180

    local token = ffi.new("unsigned long[1]")
    local input = ffi.new("GdiplusStartupInput", {1, nil, 0, 0})
    if gdiplusLib.GdiplusStartup(token, input, nil) ~= 0 then return false end

    local wSrc = strToWide(srcPath)
    local wDst = strToWide(dstPath)
    if not wSrc or not wDst then
        gdiplusLib.GdiplusShutdown(token[0])
        return false
    end

    local img = ffi.new("GpImage*[1]")
    if gdiplusLib.GdipLoadImageFromFile(wSrc, img) ~= 0 then
        gdiplusLib.GdiplusShutdown(token[0])
        return false
    end

    local thumb = ffi.new("GpImage*[1]")
    local okThumb = (gdiplusLib.GdipGetImageThumbnail(img[0], thumbW, thumbH, thumb, nil, nil) == 0)
    if okThumb and thumb[0] ~= nil then
        gdiplusLib.GdipSaveImageToFile(thumb[0], wDst, jpgClsidStruct or pngClsidStruct, nil)
        gdiplusLib.GdipDisposeImage(thumb[0])
    end

    gdiplusLib.GdipDisposeImage(img[0])
    gdiplusLib.GdiplusShutdown(token[0])
    return okThumb and doesFileExist(dstPath)
end


function getPrefabPreviewTex(fileName)
    if not fileName or fileName == "" then return nil end
    if prefabPreviewCache[fileName] then
        return prefabPreviewCache[fileName]
    end
    local fullPath = PREFAB_PREVIEWS_DIR .. "\\" .. fileName
    if doesFileExist(fullPath) then
        local ok, t = pcall(imgui.CreateTextureFromFile, fullPath)
        if ok and t then
            prefabPreviewCache[fileName] = t
            return t
        end
    end
    return nil
end

local function takePrefabSnapshot()
    if prefabPhotoCapturing then return end
    prefabPhotoCapturing = true

    lua_thread.create(function()
        pcall(playSound, 1131, 0, 0, 0)
        prefabPhotoHideOverlay = true
        wait(120)

        local okProc, errProc = pcall(function()
            local screensDir = getScreensDirectory()
            if not screensDir or not doesDirectoryExist(screensDir) then
                error("Папка скриншотов не найдена: " .. tostring(screensDir))
            end

            -- 1. Запоминаем текущие файлы в папке screens
            local beforeFiles = {}
            local fd = ffi.new("WIN32_FIND_DATAA")
            local h = ffi.C.FindFirstFileA(screensDir .. "\\*.*", fd)
            if h ~= ffi.cast("void*", -1) then
                repeat
                    local fname = ffi.string(fd.cFileName)
                    local low = fname:lower()
                    if low:match("%.png$") or low:match("%.jpg$") then
                        beforeFiles[fname] = true
                    end
                until ffi.C.FindNextFileA(h, fd) == 0
                ffi.C.FindClose(h)
            end

            -- 2. Надежный вызов скриншота: Screenshot.asi + SA-MP TakeScreenshot + F8 скан-код
            pcall(function()
                local sc = require('screenshot')
                if sc and sc.request then sc.request() end
            end)
            pcall(function()
                local base = sampGetBase()
                if base and base ~= 0 then
                    local pTake = ffi.cast('void (__cdecl *)(void)', base + 0x070FC0)
                    pTake()
                end
            end)
            pcall(function()
                local scan = 0x42
                ffi.C.keybd_event(0x77, scan, 0, nil)       -- F8 down
            end)
            wait(50)
            pcall(function()
                local scan = 0x42
                ffi.C.keybd_event(0x77, scan, 0x0002, nil)  -- F8 up
            end)

            -- 3. Ждем появления нового файла
            local newFileName = nil
            local deadline = os.clock() + 4.5
            while os.clock() < deadline do
                wait(60)
                local hSearch = ffi.C.FindFirstFileA(screensDir .. "\\*.*", fd)
                if hSearch ~= ffi.cast("void*", -1) then
                    repeat
                        local fname = ffi.string(fd.cFileName)
                        local low = fname:lower()
                        if (low:match("%.png$") or low:match("%.jpg$")) and not beforeFiles[fname] then
                            newFileName = fname
                            break
                        end
                    until ffi.C.FindNextFileA(hSearch, fd) == 0
                    ffi.C.FindClose(hSearch)
                end
                if newFileName then break end
            end

            if not newFileName then
                local bestName, _ = getLatestScreenshotFile(screensDir)
                if bestName and not beforeFiles[bestName] then
                    newFileName = bestName
                end
            end

            if not newFileName then
                error("Скриншот не найден в папке screens.")
            end

            wait(200) -- ждём завершения записи кадра
            local srcPath = screensDir .. "\\" .. newFileName
            local outName = string.format("pref_%d_%s.png", os.time(), tostring(prefabSnapTargetIdx or "new"))
            if not doesDirectoryExist(PREFAB_PREVIEWS_DIR) then
                pcall(createDirectory, PREFAB_PREVIEWS_DIR)
            end
            local dstPath = PREFAB_PREVIEWS_DIR .. "\\" .. outName

            local sw, sh = getScreenResolution()
            local viewSize = math.floor(math.min(sw, sh) * 0.52)
            local x0 = math.floor((sw - viewSize) / 2)
            local y0 = math.floor((sh - viewSize) / 2)
            local normX0 = x0 / sw
            local normY0 = y0 / sh
            local normW  = viewSize / sw
            local normH  = viewSize / sh

            local okCrop, cropErr = cropAndResizePrefabPreview(srcPath, dstPath, normX0, normY0, normW, normH, 160)
            if not okCrop then
                error(tostring(cropErr or "Ошибка обрезки GDI+"))
            end

            pcall(os.remove, srcPath)

            if prefabSnapTargetIdx == "new" then
                newPrefabPreviewName = outName
            elseif prefabSnapTargetIdx and prefabs[prefabSnapTargetIdx] then
                prefabs[prefabSnapTargetIdx].preview = outName
                savePrefabs()
            end

            if prefabPreviewCache then
                prefabPreviewCache[outName] = nil
            end

            toast_text  = "Снимок сохранён!"
            toast_text2 = "Миниатюра префаба обновлена"
            toast_tex   = nil
            toast_timer = 120
        end)

        if not okProc then
            print("[TMT Prefab Photo Error] " .. tostring(errProc))
            toast_text  = "Ошибка снимка"
            toast_text2 = tostring(errProc):gsub("^.-:%d+:%s*", "")
            toast_tex   = nil
            toast_timer = 150
        end

        -- Гарантированное завершение фоторежима и возврат интерфейса с активным курсором
        stopCamHack()
        prefabPhotoMode = false
        prefabPhotoCapturing = false
        prefabPhotoHideOverlay = false

        wait(80)
        winOpen[0] = true
        editPrefabIdx = prefabSnapTargetIdx
        cursorForceBurst = 15
        pcall(sampSetCursorMode, 2, false)
    end)
end

function startPrefabPhotoMode(prefabIdx)
    prefabSnapTargetIdx = prefabIdx
    prefabPhotoMode = true
    prefabPhotoCapturing = false
    prefabPhotoHideOverlay = false
    winOpen[0] = false
    startCamHack()
    toast_text  = "ФОТОРЕЖИМ ПРЕФАБА"
    toast_text2 = "Наведите рамку 1:1 на постройку и нажмите ЛКМ"
    toast_tex   = nil
    toast_timer = 180
end

local prefabPhotoFrame
prefabPhotoFrame = imgui.OnFrame(
    function()
        return prefabPhotoMode and not prefabPhotoHideOverlay
    end,
    function(self)
        if not prefabPhotoMode then return end
        if self then
            self.HideCursor = true
            self.LockPlayer = false
        end

        if isKeyJustPressed(0x1B) then
            stopCamHack()
            prefabPhotoMode = false
            prefabPhotoCapturing = false
            prefabPhotoHideOverlay = false
            winOpen[0] = true
            editPrefabIdx = prefabSnapTargetIdx
            pcall(sampSetCursorMode, 2, false)
            return
        end

        if not prefabPhotoCapturing then
            if isKeyJustPressed(0x01) then -- ТОЛЬКО ЛКМ!
                takePrefabSnapshot()
                return
            end
        end

        if prefabPhotoCapturing then return end

        local sw, sh = getScreenResolution()
        local viewSize = math.floor(math.min(sw, sh) * 0.52)
        local x0 = math.floor((sw - viewSize) / 2)
        local y0 = math.floor((sh - viewSize) / 2)
        local x1 = x0 + viewSize
        local y1 = y0 + viewSize

        imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(sw, sh), imgui.Cond.Always)
        imgui.SetNextWindowBgAlpha(0)
        imgui.Begin("##prefab_photo_overlay", nil,
            imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize +
            imgui.WindowFlags.NoMove + imgui.WindowFlags.NoInputs +
            imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoSavedSettings)

            local dl = imgui.GetWindowDrawList()

            -- 1. Затемнение фона вокруг видоискателя
            local darkCol = 0xB2000000
            dl:AddRectFilled(imgui.ImVec2(0, 0),   imgui.ImVec2(sw, y0), darkCol)
            dl:AddRectFilled(imgui.ImVec2(0, y1),  imgui.ImVec2(sw, sh), darkCol)
            dl:AddRectFilled(imgui.ImVec2(0, y0),  imgui.ImVec2(x0, y1), darkCol)
            dl:AddRectFilled(imgui.ImVec2(x1, y0), imgui.ImVec2(sw, y1), darkCol)

            -- 2. Обводка видоискателя 1:1
            local borderCol = 0xFF2ECC71
            dl:AddRect(imgui.ImVec2(x0, y0), imgui.ImVec2(x1, y1), borderCol, 0.0, 15, 2.0)

            -- 3. Фото-уголки
            local cl = 26
            dl:AddLine(imgui.ImVec2(x0 - 2, y0), imgui.ImVec2(x0 + cl, y0), 0xFFFFFFFF, 3.5)
            dl:AddLine(imgui.ImVec2(x0, y0 - 2), imgui.ImVec2(x0 + cl, y0), 0xFFFFFFFF, 3.5)
            dl:AddLine(imgui.ImVec2(x1 + 2, y0), imgui.ImVec2(x1 - cl, y0), 0xFFFFFFFF, 3.5)
            dl:AddLine(imgui.ImVec2(x1, y0 - 2), imgui.ImVec2(x1, y0 + cl), 0xFFFFFFFF, 3.5)
            dl:AddLine(imgui.ImVec2(x0 - 2, y1), imgui.ImVec2(x0 + cl, y1), 0xFFFFFFFF, 3.5)
            dl:AddLine(imgui.ImVec2(x0, y1 + 2), imgui.ImVec2(x0 - cl, y1), 0xFFFFFFFF, 3.5)
            dl:AddLine(imgui.ImVec2(x1 + 2, y1), imgui.ImVec2(x1 - cl, y1), 0xFFFFFFFF, 3.5)
            dl:AddLine(imgui.ImVec2(x1, y1 + 2), imgui.ImVec2(x1 - cl, y1), 0xFFFFFFFF, 3.5)

            -- 4. Перекрестие в центре
            local cx = (x0 + x1) / 2
            local cy = (y0 + y1) / 2
            dl:AddLine(imgui.ImVec2(cx - 10, cy), imgui.ImVec2(cx + 10, cy), 0x88FFFFFF, 1.5)
            dl:AddLine(imgui.ImVec2(cx, cy - 10), imgui.ImVec2(cx, cy + 10), 0x88FFFFFF, 1.5)

            -- 5. Подсказки
            dl:AddText(imgui.ImVec2(cx - 75, y0 - 32), 0xFF2ECC71, u8"ФОТОРЕЖИМ ПРЕФАБА")
            dl:AddText(imgui.ImVec2(cx - 160, y1 + 16), 0xFFFFFFFF, u8"[ ЛКМ ] — Сделать снимок      [ ESC ] — Отмена")
            dl:AddText(imgui.ImVec2(cx - 215, y1 + 38), 0xFFAAAAAA, u8"WASD + Мышь (ПКМ) — Управление камерой   |   Shift — Ускорение")
        imgui.End()
    end
)
prefabPhotoFrame.HideCursor = true
prefabPhotoFrame.LockPlayer = false

INSPECT_SKY_Z = 1500.0   -- высота в небе, выше любых карт/текстур

local function startInspect(obj)
    destroyInspectGhost()

    local px, py, pz = getCharCoordinates(PLAYER_PED)

    inspectObjX = px
    inspectObjY = py
    inspectObjZ = INSPECT_SKY_Z

    inspectObj = obj
    inspectRX, inspectRY, inspectRZ = 0, 0, 0
    inspectRXRef[0] = 0; inspectRYRef[0] = 0; inspectRZRef[0] = 0
    inspectCamAngleX, inspectCamAngleY = 0.0, 0.0
    inspectCamDist[0] = 6.0

    local ok, handle = pcall(createObject, tonumber(obj.id), inspectObjX, inspectObjY, inspectObjZ, 0, 0, 0)
    if ok then inspectHandle = handle end

    pcall(freezeCharPosition, PLAYER_PED, true)
    pcall(masterCamHook.start)

    inspectActive = true
    winOpen[0] = false
end

local function drawObjInspectPickerGrid()
    local query = cyrLower(ffi.string(inspectSearchBuf))
    if query == "" then
        imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"Введите название или ID объекта для поиска")
        return
    end

    local CARD_W, CARD_H = 90, 118
    local PAD = 10
    local avail = imgui.GetContentRegionAvail().x
    local cols = math.max(1, math.floor((avail + PAD) / (CARD_W + PAD)))
    local col = 0

    for _, obj in ipairs(allObjects) do
        if cyrLower(obj.name or ""):find(query, 1, true) or tostring(obj.id):find(query, 1, true) then
            if col > 0 then imgui.SameLine(0, PAD) end
            imgui.BeginGroup()
                local tex = getTex(obj.id)
                if tex then
                    imgui.Image(tex, imgui.ImVec2(CARD_W, CARD_W))
                else
                    imgui.Dummy(imgui.ImVec2(CARD_W, CARD_W))
                end
                if imgui.IsItemClicked(0) then
                    startInspect({id = obj.id, name = obj.name})
                end
                imgui.PushTextWrapPos(imgui.GetCursorPosX() + CARD_W)
                imgui.TextColored(imgui.ImVec4(0.8,0.8,0.8,1), obj.name)
                imgui.PopTextWrapPos()
            imgui.EndGroup()

            col = col + 1
            if col >= cols then col = 0 end
        end
    end
end


local function renderTabInspect()
    imgui.Spacing()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_EYE .. u8" ОСМОТР ОБЪЕКТА")
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    if not inspectObj then
        imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1), u8"Объект не выбран")
        imgui.Spacing()
        if imgui.Button(u8"Выбрать объект##inspselect", imgui.ImVec2(-1, 32)) then
            showInspectPicker = not showInspectPicker
        end
        if showInspectPicker then
            imgui.Spacing()
            imgui.PushItemWidth(-1)
            imgui.InputTextWithHint(u8"##inspsearch", u8"Поиск объекта...", inspectSearchBuf, 128)
            imgui.PopItemWidth()
            imgui.Spacing()
            imgui.BeginChild(u8"##inspgrid", imgui.ImVec2(0, 320), true)
            drawObjInspectPickerGrid()
            imgui.EndChild()
        end
    else
        imgui.Text(inspectObj.name .. " (" .. tostring(inspectObj.id) .. ")")
        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        imgui.PushItemWidth(-1)
        imgui.Text(u8"Поворот X:")
        if imgui.SliderFloat(u8"##inspx", inspectRXRef, -180, 180, "%.0f") then
            inspectRX = inspectRXRef[0]
            if inspectHandle then pcall(setObjectRotation, inspectHandle, inspectRX, inspectRY, inspectRZ) end
        end
        imgui.Text(u8"Поворот Y:")
        if imgui.SliderFloat(u8"##inspy", inspectRYRef, -180, 180, "%.0f") then
            inspectRY = inspectRYRef[0]
            if inspectHandle then pcall(setObjectRotation, inspectHandle, inspectRX, inspectRY, inspectRZ) end
        end
        imgui.Text(u8"Поворот Z:")
        if imgui.SliderFloat(u8"##inspz", inspectRZRef, -180, 180, "%.0f") then
            inspectRZ = inspectRZRef[0]
            if inspectHandle then pcall(setObjectRotation, inspectHandle, inspectRX, inspectRY, inspectRZ) end
        end
        imgui.PopItemWidth()

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        if imgui.Button(u8"Создать##inspspawn", imgui.ImVec2(150, 32)) then
            stopInspect(true)
        end
        imgui.SameLine()
        if imgui.Button(u8"Отмена##inspcancel", imgui.ImVec2(150, 32)) then
            stopInspect(false)
        end
    end
end

function renderTabGroupControl()
    imgui.Indent(10)
    imgui.Spacing()
    local ac = accentColorA(1.0)
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_OBJECT_GROUP .. u8"  МЕНЕДЖЕР И УПРАВЛЕНИЕ ГРУППАМИ")
    imgui.Spacing()

    -- Переключатель вкладок: Менеджер групп | Управление по ID
    local availW = imgui.GetContentRegionAvail().x - 10
    local subW = math.floor((availW - 8) * 0.5)
    local isMgr = (groupControlSubTab == 1)

    if not isMgr then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.19, 1.0)) end
    if imgui.Button(fa.ICON_TH_LIST .. u8"  Менеджер групп на карте##grpsub_mgr", imgui.ImVec2(subW, 30)) then
        groupControlSubTab = 1
        refreshGroupManagerSummary()
    end
    if not isMgr then imgui.PopStyleColor() end

    imgui.SameLine(0, 8)
    if isMgr then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.19, 1.0)) end
    if imgui.Button(fa.ICON_SLIDERS .. u8"  Поворот и текстуризация группы##grpsub_ctrl", imgui.ImVec2(subW, 30)) then
        groupControlSubTab = 2
    end
    if isMgr then imgui.PopStyleColor() end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    if groupControlSubTab == 1 then
        if #groupMgrSummary == 0 then
            refreshGroupManagerSummary()
        end

        -- Верхняя строка Менеджера групп
        imgui.PushItemWidth(220)
        imgui.InputTextWithHint(u8"##grpmgrsearch", u8"Поиск группы (#) или модели...", groupMgrSearchBuf, 64)
        imgui.PopItemWidth()
        imgui.SameLine(0, 10)
        if imgui.Button(fa.ICON_REFRESH .. u8"  Обновить группы##grpmgrref", imgui.ImVec2(150, 26)) then
            refreshGroupManagerSummary()
        end
        imgui.SameLine(0, 14)
        imgui.TextColored(imgui.ImVec4(0.78, 0.78, 0.82, 1.0), u8("Найдено групп на карте: " .. tostring(#groupMgrSummary)))

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        if #groupMgrSummary == 0 then
            imgui.Spacing(); imgui.Spacing()
            imgui.TextColored(imgui.ImVec4(1.0, 0.78, 0.25, 1.0), fa.ICON_INFO_CIRCLE .. u8"  На карте сейчас не обнаружено групп объектов (или карта не в режиме /map).")
            imgui.Spacing()
            imgui.TextColored(imgui.ImVec4(0.70, 0.70, 0.72, 1.0), u8"  Добавьте объекты в группу через Ассистент объектов ([7] Группирование) или команду /gr, затем нажмите «Обновить группы».")
        else
            local leftW = 250
            local qGrp = cyrLower(ffi.string(groupMgrSearchBuf))

            -- Левая колонка: Список групп на карте
            imgui.BeginChild(u8"##grpmgr_left", imgui.ImVec2(leftW, 0), true)
                local dlL = imgui.GetWindowDrawList()
                local cardW = imgui.GetContentRegionAvail().x
                local cardH = 60

                for _, grp in ipairs(groupMgrSummary) do
                    local matchGrp = (qGrp == "")
                        or tostring(grp.groupNum):find(qGrp, 1, true)
                        or ("#" .. tostring(grp.groupNum)):find(qGrp, 1, true)
                    if not matchGrp then
                        for _, ob in ipairs(grp.objects) do
                            if tostring(ob.id):find(qGrp, 1, true) or tostring(ob.modelId):find(qGrp, 1, true) or cyrLower(ob.modelName or ""):find(qGrp, 1, true) then
                                matchGrp = true
                                break
                            end
                        end
                    end

                    if matchGrp then
                        local isSel = (groupMgrSelectedGroup == grp.groupNum)
                        local p = imgui.GetCursorScreenPos()
                        local clicked = imgui.InvisibleButton("##grpcard_" .. grp.groupNum, imgui.ImVec2(cardW, cardH))
                        local hovered = imgui.IsItemHovered()
                        if clicked then
                            groupMgrSelectedGroup = grp.groupNum
                            ffi.fill(grpIdBuf, 16, 0)
                            ffi.copy(grpIdBuf, tostring(grp.groupNum))
                        end

                        local bgCol = isSel and (0x38000000 + accentColorHex()) or (hovered and 0x24FFFFFF or 0xFF1A1A20)
                        local brdCol = isSel and (0xFF000000 + accentColorHex()) or 0x33FFFFFF
                        dlL:AddRectFilled(p, imgui.ImVec2(p.x + cardW, p.y + cardH), bgCol, 6)
                        dlL:AddRect(p, imgui.ImVec2(p.x + cardW, p.y + cardH), brdCol, 6, 0, 1.0)

                        -- Мини-превью первого объекта группы
                        local tex = getTex(grp.previewModel)
                        local imgS = 44
                        if tex then
                            dlL:AddRectFilled(imgui.ImVec2(p.x + 8, p.y + 8), imgui.ImVec2(p.x + 8 + imgS, p.y + 8 + imgS), 0xFFFFFFFF, 4)
                            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 8, p.y + 8))
                            imgui.Image(tex, imgui.ImVec2(imgS, imgS))
                        else
                            dlL:AddRectFilled(imgui.ImVec2(p.x + 8, p.y + 8), imgui.ImVec2(p.x + 8 + imgS, p.y + 8 + imgS), 0xFF282830, 4)
                            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 16, p.y + 22))
                            imgui.TextColored(imgui.ImVec4(0.6, 0.6, 0.6, 1.0), "#" .. tostring(grp.groupNum))
                        end

                        local tx = p.x + 8 + imgS + 10
                        imgui.SetCursorScreenPos(imgui.ImVec2(tx, p.y + 10))
                        imgui.TextColored(isSel and ac or imgui.ImVec4(1, 1, 1, 1), fa.ICON_OBJECT_GROUP .. u8("  Группа #" .. tostring(grp.groupNum)))
                        imgui.SetCursorScreenPos(imgui.ImVec2(tx, p.y + 32))
                        imgui.TextColored(imgui.ImVec4(0.68, 0.68, 0.72, 1.0), u8("Объектов: " .. tostring(#grp.objects) .. "  |  ~" .. tostring(grp.minDist) .. " м"))

                        imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + cardH))
                        imgui.Dummy(imgui.ImVec2(cardW, 0))
                        imgui.Spacing()
                    end
                end
            imgui.EndChild()

            imgui.SameLine(0, 10)

            -- Правая колонка: Состав выбранной группы и действия с ней
            imgui.BeginChild(u8"##grpmgr_right", imgui.ImVec2(0, 0), true)
                local selGrpObj = nil
                for _, grp in ipairs(groupMgrSummary) do
                    if grp.groupNum == groupMgrSelectedGroup then
                        selGrpObj = grp
                        break
                    end
                end

                if not selGrpObj then
                    imgui.TextColored(imgui.ImVec4(0.6, 0.6, 0.6, 1.0), u8"Выберите группу в списке слева.")
                else
                    local gNumStr = tostring(selGrpObj.groupNum)
                    imgui.TextColored(ac, fa.ICON_OBJECT_GROUP .. u8("  Группа #" .. gNumStr .. "  (" .. tostring(#selGrpObj.objects) .. " объектов)"))
                    imgui.Spacing()

                    -- Кнопки управления самой группой
                    if imgui.Button(fa.ICON_ARROWS .. u8"  Редактировать (/ged)##gm_ged", imgui.ImVec2(165, 28)) then
                        activeEditingGroupId = gNumStr
                        objEditorActive = true
                        winOpen[0] = false
                        sampSendChat("/ged " .. gNumStr)
                    end
                    imgui.SameLine(0, 6)
                    if imgui.Button(fa.ICON_CLONE .. u8"  Клонировать (/gclone)##gm_gclone", imgui.ImVec2(170, 28)) then
                        sampSendChat("/gclone " .. gNumStr)
                    end
                    imgui.SameLine(0, 6)
                    if imgui.Button(fa.ICON_SLIDERS .. u8"  Поворот / Текстуры##gm_toctrl", imgui.ImVec2(165, 28)) then
                        ffi.fill(grpIdBuf, 16, 0)
                        ffi.copy(grpIdBuf, gNumStr)
                        groupControlSubTab = 2
                    end

                    imgui.Spacing(); imgui.Separator(); imgui.Spacing()
