-- ===== АВТООБНОВЛЕНИЕ С GITHUB =====
do
local dlstatus = require('moonloader').download_status
updateModalOpen   = imgui.new.bool(false)
updateAvailable   = nil
updateChecking    = false
updateDownloading = false
updateStatusText  = ""

local function isNewerVersion(remoteVer, localVer)
    local function parseVer(v)
        local parts = {}
        for num in tostring(v or ""):gmatch("(%d+)") do
            parts[#parts + 1] = tonumber(num) or 0
        end
        return parts
    end
    local r = parseVer(remoteVer)
    local l = parseVer(localVer)
    local maxLen = math.max(#r, #l)
    for i = 1, maxLen do
        local rv = r[i] or 0
        local lv = l[i] or 0
        if rv > lv then return true end
        if rv < lv then return false end
    end
    return false
end

function checkForUpdates(isManual)
    if updateChecking or updateDownloading then return end
    updateChecking = true
    updateStatusText = u8"Проверка обновлений..."

    local tmpJson = getWorkingDirectory() .. "\\config\\tmt_version_check.json"
    pcall(os.remove, tmpJson)

    local url = UPDATE_VERSION_URL .. "?t=" .. tostring(os.time())
    downloadUrlToFile(url, tmpJson, function(id, status, p1, p2)
        if status == dlstatus.STATUSEX_ENDDOWNLOAD or status == dlstatus.STATUS_ENDDOWNLOADDATA then
            lua_thread.create(function()
                wait(100)
                updateChecking = false
                if not doesFileExist(tmpJson) then
                    updateStatusText = u8"Ошибка проверки"
                    if isManual then
                        sampAddChatMessage('{FF5555}[TMT]{CFCFCF} Не удалось проверить обновления (нет ответа от GitHub).', -1)
                    end
                    return
                end

                local f = io.open(tmpJson, "rb")
                local raw = f and f:read("*a") or nil
                if f then f:close() end
                pcall(os.remove, tmpJson)

                if not raw or raw == "" then
                    updateStatusText = u8"Ошибка проверки"
                    if isManual then
                        sampAddChatMessage('{FF5555}[TMT]{CFCFCF} Не удалось прочитать version.json с GitHub.', -1)
                    end
                    return
                end

                local okDec, info = pcall(json.decode, raw)
                if not okDec or type(info) ~= "table" or not info.version then
                    updateStatusText = u8"Неверный формат"
                    if isManual then
                        sampAddChatMessage('{FF5555}[TMT]{CFCFCF} Ошибка чтения version.json.', -1)
                    end
                    return
                end

                if isNewerVersion(info.version, SCRIPT_VERSION) then
                    updateAvailable = {
                        version   = tostring(info.version),
                        url       = (type(info.url) == "string" and info.url ~= "") and info.url or UPDATE_FALLBACK_URL,
                        changelog = tostring(info.changelog or "")
                    }
                    updateStatusText = u8("Доступна v" .. updateAvailable.version)
                    toast_text      = "Доступно обновление v" .. updateAvailable.version
                    toast_text2     = "Настройки -> Обновление"
                    toast_tex       = nil
                    toast_timer_max = 0
                    toast_timer     = 300 -- ~5 секунд при 60 FPS
                    sampAddChatMessage(string.format('{FF9326}[TMT]{CFCFCF} Доступно обновление {FF9326}v%s{CFCFCF}! Чтобы обновить, перейдите в Настройки -> {FF9326}Обновление{CFCFCF}.', updateAvailable.version), -1)
                else
                    updateAvailable = nil
                    updateStatusText = u8"Актуальная версия"
                    if isManual then
                        sampAddChatMessage(string.format('{FF9326}[TMT]{CFCFCF} У вас установлена актуальная версия {FF9326}v%s{CFCFCF}.', SCRIPT_VERSION), -1)
                    end
                end
            end)
        end
    end)
end

local function tryDownloadScriptUrl(targetUrl, tmpLua, onDone)
    pcall(os.remove, tmpLua)
    local sep = targetUrl:find("?", 1, true) and "&" or "?"
    downloadUrlToFile(targetUrl .. sep .. "t=" .. tostring(os.time()), tmpLua, function(id, status, p1, p2)
        if status == dlstatus.STATUSEX_ENDDOWNLOAD or status == dlstatus.STATUS_ENDDOWNLOADDATA then
            lua_thread.create(function()
                wait(150)
                local okValid = false
                if doesFileExist(tmpLua) then
                    local fn = loadfile(tmpLua)
                    if fn then
                        okValid = true
                    end
                end
                onDone(okValid)
            end)
        end
    end)
end

function downloadAndApplyUpdate()
    if updateDownloading or not updateAvailable then return end
    updateDownloading = true
    updateStatusText = u8"Скачивание..."

    local tmpLua = getWorkingDirectory() .. "\\config\\tmt_update_tmp.lua"
    local primaryUrl = updateAvailable.url or UPDATE_FALLBACK_URL

    local function finishWithFile(okValid)
        if not okValid then
            pcall(os.remove, tmpLua)
            updateDownloading = false
            updateStatusText = u8"Ошибка скачивания"
            sampAddChatMessage('{FF5555}[TMT]{CFCFCF} Не удалось скачать обновление. Проверьте ссылку на файл в репозитории GitHub.', -1)
            return
        end

        local srcF = io.open(tmpLua, "rb")
        local newBytes = srcF and srcF:read("*a") or nil
        if srcF then srcF:close() end
        pcall(os.remove, tmpLua)

        if not newBytes or #newBytes < 1000 then
            updateDownloading = false
            updateStatusText = u8"Ошибка файла"
            sampAddChatMessage('{FF5555}[TMT]{CFCFCF} Скачанный файл обновления повреждён.', -1)
            return
        end

        local dstF = io.open(thisScript().path, "wb")
        if not dstF then
            updateDownloading = false
            updateStatusText = u8"Ошибка записи"
            sampAddChatMessage('{FF5555}[TMT]{CFCFCF} Нет прав на перезапись файла скрипта.', -1)
            return
        end
        dstF:write(newBytes)
        dstF:close()

        updateModalOpen[0] = false
        updateDownloading = false
        sampAddChatMessage(string.format('{27F527}[TMT]{CFCFCF} Обновление до {FF9326}v%s{CFCFCF} установлено! Перезагрузка скрипта...', tostring(updateAvailable.version)), -1)
        lua_thread.create(function()
            wait(300)
            thisScript():reload()
        end)
    end

    tryDownloadScriptUrl(primaryUrl, tmpLua, function(okValid)
        if okValid then
            finishWithFile(true)
        elseif primaryUrl ~= UPDATE_FALLBACK_URL then
            tryDownloadScriptUrl(UPDATE_FALLBACK_URL, tmpLua, finishWithFile)
        else
            finishWithFile(false)
        end
    end)
end

