function float4ToArgbHex(col, forceFF)
    local a = forceFF and 255 or math.max(0, math.min(255, math.floor((col[3] or 1.0) * 255 + 0.5)))
    local r = math.max(0, math.min(255, math.floor((col[0] or 1.0) * 255 + 0.5)))
    local g = math.max(0, math.min(255, math.floor((col[1] or 1.0) * 255 + 0.5)))
    local b = math.max(0, math.min(255, math.floor((col[2] or 1.0) * 255 + 0.5)))
    return string.format("%02X%02X%02X%02X", a, r, g, b)
end

function normalizeOtextColorHex(rawStr)
    local clean = tostring(rawStr or ""):gsub("[^%x]", ""):upper()
    if clean == "0" or clean == "00000000" then
        return "00000000"
    end
    if #clean == 6 then
        return "FF" .. clean
    elseif #clean == 8 then
        return clean
    end
    return "FFFFFFFF"
end

function argbHexToFloat4(hexStr, colOut)
    local clean = tostring(hexStr or ""):gsub("[^%x]", ""):upper()
    if #clean == 6 then clean = "FF" .. clean end
    if #clean ~= 8 then return false end
    local a = tonumber(clean:sub(1, 2), 16) or 255
    local r = tonumber(clean:sub(3, 4), 16) or 255
    local g = tonumber(clean:sub(5, 6), 16) or 255
    local b = tonumber(clean:sub(7, 8), 16) or 255
    colOut[0] = r / 255.0
    colOut[1] = g / 255.0
    colOut[2] = b / 255.0
    colOut[3] = a / 255.0
    return true
end

function isOtextTaskAlreadySatisfied(cleanMainText, task)
    if not cleanMainText or not task then return false end
    for line in cleanMainText:gmatch("[^\r\n]+") do
        local tr = line:gsub("^%s*(.-)%s*$", "%1")
        if task.id == "mat" and tr:find("Материал для наложения текста:", 1, true) then
            local cur = tr:match("#(%d+)")
            return cur and tonumber(cur) == tonumber(task.val)
        elseif task.id == "text" and tr:find("Текст:", 1, true) then
            local cur = tr:match("Текст:%s*(.-)%s*$")
            return cur and cur == tostring(task.val)
        elseif task.id == "res" and tr:find("Разрешение текста:", 1, true) then
            local cur = tr:match("Разрешение текста:%s*(%S+)")
            return cur and cur:lower() == tostring(task.val):lower()
        elseif task.id == "font" and tr:find("Шрифт:", 1, true) and not tr:find("Размер", 1, true) and not tr:find("Жирный", 1, true) then
            local cur = tr:match("Шрифт:%s*(.-)%s*$")
            return cur and cur:lower() == tostring(task.val):lower()
        elseif task.id == "fontsize" and tr:find("Размер шрифта:", 1, true) then
            local cur = tr:match("Размер шрифта:%s*(%d+)")
            return cur and tonumber(cur) == tonumber(task.val)
        elseif task.id == "bold" and tr:find("Жирный шрифт:", 1, true) then
            local isYes = tr:find("ДА", 1, true) ~= nil
            return isYes == (task.val == true)
        elseif task.id == "align" and tr:find("Выравнивание:", 1, true) then
            return tr:find(tostring(task.matchWord or task.val), 1, true) ~= nil
        elseif task.id == "fontcolor" and tr:find("Цвет текста:", 1, true) then
            local cur = tr:match("Цвет текста:%s*(%S+)")
            if not cur then return false end
            local cu = cur:upper()
            local vu = tostring(task.val):upper()
            return cu == vu or ((cu == "0" or cu == "00000000") and (vu == "0" or vu == "00000000"))
        elseif task.id == "backcolor" and tr:find("Цвет фона текста:", 1, true) then
            local cur = tr:match("Цвет фона текста:%s*(%S+)")
            if not cur then return false end
            local cu = cur:upper()
            local vu = tostring(task.val):upper()
            return cu == vu or ((cu == "0" or cu == "00000000") and (vu == "0" or vu == "00000000"))
        end
    end
    return false
end

otextQueueIdx = 1

function findOtextRow(cleanText, pattern)
    if not cleanText or not pattern or pattern == "" then return nil end
    local row = 0
    for line in cleanText:gmatch("[^\n]+") do
        local trimmed = line:gsub("^%s*(.-)%s*$", "%1")
        if trimmed:find(pattern, 1, true) then
            return row
        end
        row = row + 1
    end
    return nil
end

otextTriedMainMenu = {}

function otextDebug(line)
    local f = io.open(getWorkingDirectory() .. "\\TMT-otext-debug.txt", "a")
    if f then
        f:write(os.date("%H:%M:%S") .. string.format(".%03d ", math.floor((os.clock() % 1) * 1000)) .. tostring(line) .. "\n")
        f:close()
    end
end

function getOtextRowText(cleanText, row)
    if not cleanText or not row or row < 0 then return "" end
    local i = 0
    for line in cleanText:gmatch("[^\n]+") do
        if i == row then return (line:gsub("\r", "")) end
        i = i + 1
    end
    return ""
end

function otextRespondAsync(dialogId, btn, listItem, inputStr)
    -- Как настоящий клиент SA:MP: при выборе пункта списка в inputtext передаётся текст строки
    if (inputStr == nil or inputStr == "") and listItem and listItem >= 0 and otextCurDialogText then
        inputStr = getOtextRowText(otextCurDialogText, listItem)
    end
    otextDebug(string.format("  >> ОТВЕТ: dialogId=%s btn=%s list=%s input='%s' (шаг %s/%s)",
        tostring(dialogId), tostring(btn), tostring(listItem), tostring(inputStr or ""),
        tostring(otextQueueIdx), tostring(otextTaskQueue and #otextTaskQueue or 0)))
    lua_thread.create(function()
        wait(180)
        sampSendDialogResponse(dialogId, btn, listItem, inputStr or "")
    end)
end

function handleOtextDialog(dialogId, style, cleanTitle, button1, button2, cleanText)
    if not otextQueueActive or not otextTaskQueue then return false end
    otextLastDialogRecvTime = os.clock()
    otextBusyUntil = os.clock() + 12.0
    otextCurDialogText = cleanText
    otextDebug(string.format("<< ДИАЛОГ: id=%s style=%s title='%s' b1='%s' b2='%s' шаг=%s/%s задача=%s",
        tostring(dialogId), tostring(style), tostring(cleanTitle), tostring(button1), tostring(button2),
        tostring(otextQueueIdx), tostring(#otextTaskQueue),
        tostring(otextTaskQueue[otextQueueIdx] and otextTaskQueue[otextQueueIdx].id or "-")))
    otextDebug("   ТЕКСТ: " .. tostring(cleanText):gsub("\n", " | "))

    -- Если вылезло окно ожидания базы данных: скрываем и ждём реальный диалог (как в script-helper.lua)
    if cleanText:find("Ждем ответа", 1, true) or cleanTitle:find("Ждем ответа", 1, true) then
        return true
    end

    -- 1. Главное меню "Управление текстом" (проверяем наличие "IDX ивент объекта:")
    -- Сервер сам автоматически открывает это окно после каждого применённого параметра и после нажатия X
    if cleanTitle:find("Управление текстом", 1, true) and cleanText:find("IDX ивент объекта:", 1, true) then
        local objNum = cleanText:match("IDX ивент объекта:%s*#(%d+)")
        if objNum then otextLastObjId = objNum end

        -- Пропускаем пункты, которые уже установлены в нужное значение на самом объекте
        -- ИЛИ которые уже были отправлены из главного меню в этом цикле (защита от зацикливания)
        while otextQueueIdx <= #otextTaskQueue and (
            isOtextTaskAlreadySatisfied(cleanText, otextTaskQueue[otextQueueIdx])
            or otextTriedMainMenu[otextQueueIdx]
        ) do
            otextQueueIdx = otextQueueIdx + 1
        end

        -- Если все пункты очереди для объекта применены — нажимаем "Выход" (0) и закрываем меню
        if otextQueueIdx > #otextTaskQueue then
            otextQueueActive = false
            otextTaskQueue = nil
            otextTriedMainMenu = {}
            otextBusyUntil = os.clock() + 1.0
            otextRespondAsync(dialogId, 0, -1, "")
            toast_text  = "Текст настроен"
            toast_text2 = "Все выбранные параметры /otext применены!"
            toast_tex   = nil
            toast_timer = 140
            return true
        end

        local item = otextTaskQueue[otextQueueIdx]
        local row = findOtextRow(cleanText, item.rowPattern)
        if row then
            otextTriedMainMenu[otextQueueIdx] = true
            otextRespondAsync(dialogId, 1, row, "")
            return true
        else
            otextQueueIdx = otextQueueIdx + 1
            otextRespondAsync(dialogId, 0, -1, "")
            return true
        end
    end

    local item = otextTaskQueue[otextQueueIdx]
    if not item then
        otextQueueActive = false
        otextTriedMainMenu = {}
        otextRespondAsync(dialogId, 0, -1, "")
        return true
    end

    -- 2. Диалог подтверждения или информационное окно с кнопкой X (проверяем ДО списков/ввода!)
    if cleanText:find("уже установлен", 1, true)
       or cleanText:find("установлено", 1, true)
       or cleanText:find("установлен", 1, true)
       or cleanText:find("изменен", 1, true)
       or cleanText:find("удален", 1, true)
       or style == 0 or button2 == "" or button1 == "X" or button1 == "\xd5" then
        otextQueueIdx = otextQueueIdx + 1
        -- В диалогах Trinity с единственной кнопкой "X" нажимаем её (отправляем 0 как в макросах блоков / 1 для MSGBOX)
        otextRespondAsync(dialogId, 1, -1, "")
        return true
    end

    -- 3. Диалог выбора разрешения ("Установка разрешения текста")
    if cleanTitle:find("Установка разрешения текста", 1, true) then
        otextQueueIdx = otextQueueIdx + 1
        otextRespondAsync(dialogId, 1, item.listIdx or 13, "")
        return true
    end

    -- 4. Диалог выбора шрифта ("Установка шрифта")
    if cleanTitle:find("Установка шрифта", 1, true) then
        otextQueueIdx = otextQueueIdx + 1
        otextRespondAsync(dialogId, 1, item.listIdx or 0, "")
        return true
    end

    -- 5. Диалог выбора выравнивания (содержит пункты "Выравнивание по центру" / "Выравнивание по правому краю")
    if cleanText:find("Выравнивание по правому краю", 1, true) or cleanText:find("Выравнивание левому краю", 1, true) then
        otextQueueIdx = otextQueueIdx + 1
        otextRespondAsync(dialogId, 1, item.listIdx or 1, "")
        return true
    end

    -- 6. Любой другой список (например выбор материала или ДА/НЕТ)
    if style == 2 then
        local row = item.listIdx
        if row == nil then
            row = findOtextRow(cleanText, item.subFind or tostring(item.val)) or 0
        end
        otextQueueIdx = otextQueueIdx + 1
        otextRespondAsync(dialogId, 1, row, "")
        return true
    end

    -- 7. Диалог ввода значения (Размер шрифта, Цвет шрифта, Цвет фона, Текст, Материал)
    if style == 1 or style == 3 or cleanTitle:find("Установка", 1, true) or cleanText:find("Введите", 1, true) then
        otextRespondAsync(dialogId, 1, -1, tostring(item.val or ""))
        return true
    end

    -- Неизвестный диалог — не скрываем и выключаем очередь, чтобы ничего не зависало на экране
    otextQueueActive = false
    otextTaskQueue = nil
    otextTriedMainMenu = {}
    return false
end

function buildCurrentOtextTasks(includeText)
    local tasks = {}
    local mat = otextMatSlot[0] or 0
    table.insert(tasks, { id = "mat", rowPattern = "Материал для наложения текста:", val = tostring(mat), listIdx = mat })

    if includeText then
        local txtCp = u8:decode(ffi.string(otextTextBuf))
        if txtCp ~= "" then
            table.insert(tasks, { id = "text", rowPattern = "Текст:", val = txtCp })
        end
    end

    local resName = OTEXT_RESOLUTIONS[otextResIdx] or "512x512"
    table.insert(tasks, { id = "res", rowPattern = "Разрешение текста:", val = resName, listIdx = otextResIdx - 1 })

    local fontName = OTEXT_FONTS[otextFontIdx] or "Arial"
    table.insert(tasks, { id = "font", rowPattern = "Шрифт:", val = fontName, listIdx = otextFontIdx - 1 })

    local fSize = math.max(1, math.min(255, otextFontSize[0] or 24))
    table.insert(tasks, { id = "fontsize", rowPattern = "Размер шрифта:", val = tostring(fSize) })

    local isBold = otextBold[0] == true
    table.insert(tasks, { id = "bold", rowPattern = "Жирный шрифт:", val = isBold, subFind = isBold and "ДА" or "НЕТ", listIdx = isBold and 0 or 1 })

    local alignInfo = OTEXT_ALIGNMENTS[otextAlignIdx] or OTEXT_ALIGNMENTS[2]
    local alignMatchCp = u8:decode(alignInfo.label)
    table.insert(tasks, { id = "align", rowPattern = "Выравнивание:", val = alignMatchCp, matchWord = alignInfo.match, subFind = alignInfo.match, listIdx = alignInfo.id })

    local fHex = normalizeOtextColorHex(ffi.string(otextFontHexBuf))
    imgui.StrCopy(otextFontHexBuf, fHex)
    table.insert(tasks, { id = "fontcolor", rowPattern = "Цвет текста:", val = fHex })

    local bHex = normalizeOtextColorHex(ffi.string(otextBackHexBuf))
    imgui.StrCopy(otextBackHexBuf, bHex)
    table.insert(tasks, { id = "backcolor", rowPattern = "Цвет фона текста:", val = bHex })

    return tasks
end

function startOtextApplyAllQueue(includeText)
    otextDebug("==================== СТАРТ ОЧЕРЕДИ (includeText=" .. tostring(includeText) .. ", dialogActive=" .. tostring(sampIsDialogActive()) .. ") ====================")
    otextBusyUntil = os.clock() + 18.0
    oinfoSilentPendingId = nil
    oinfoSilentExpireTime = 0
    otextTriedMainMenu = {}
    otextTaskQueue = buildCurrentOtextTasks(includeText)
    otextQueueIdx = 1
    otextQueueActive = true
    otextLastDialogRecvTime = os.clock()
    if not sampIsDialogActive() then
        sampSendChat("/otext")
    end
end

function startSingleOtextTask(taskObj)
    otextBusyUntil = os.clock() + 12.0
    oinfoSilentPendingId = nil
    oinfoSilentExpireTime = 0
    otextTriedMainMenu = {}
    otextTaskQueue = { taskObj }
    otextQueueIdx = 1
    otextQueueActive = true
    otextLastDialogRecvTime = os.clock()
    if not sampIsDialogActive() then
        sampSendChat("/otext")
    end
end

function renderTabObjectText()
    imgui.Indent(10)
    imgui.Spacing()
    local ac = accentColorA(1.0)
    local totalW = imgui.GetContentRegionAvail().x - 14

    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_FONT .. u8"  УПРАВЛЕНИЕ ТЕКСТОМ НА ОБЪЕКТЕ (/OTEXT)")
    if otextLastObjId ~= "" then
        imgui.SameLine(0, 16)
        imgui.TextColored(imgui.ImVec4(0.65, 0.90, 0.45, 1.0), u8"Последний ивент объект: #" .. tostring(otextLastObjId))
    end
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- 1. ВЫБОР ОБЪЕКТА ДЛЯ ТЕКСТА
    imgui.TextColored(ac, fa.ICON_CUBE .. u8"  1. Выберите объект, на который будет нанесён текст")
    imgui.Spacing()

    local specCardW = math.floor((totalW - 16) / 3)
    local specCardH = 68
    local dl = imgui.GetWindowDrawList()

    for idx, sp in ipairs(OTEXT_SPECIAL_OBJECTS) do
        if idx > 1 then imgui.SameLine(0, 8) end
        imgui.BeginGroup()
            local isSel = (otextSelectedModelId == sp.id)
            local p = imgui.GetCursorScreenPos()
            dl:AddRectFilled(p, imgui.ImVec2(p.x + specCardW, p.y + specCardH), isSel and 0xFF1A3622 or 0xFF1A1A22, 6)
            dl:AddRect(p, imgui.ImVec2(p.x + specCardW, p.y + specCardH), isSel and 0xFF2ECC71 or 0x55E07200, 6, 0, isSel and 2.0 or 1.0)

            imgui.InvisibleButton("##ot_sp_sel_" .. sp.id, imgui.ImVec2(specCardW, specCardH))
            if imgui.IsItemClicked(0) then
                otextSelectedModelId = sp.id
                otextSelectedModelName = sp.title
                imgui.StrCopy(otextCustomModelBuf, sp.id)
            end

            local tex = getTex(sp.id)
            if tex then
                dl:AddRectFilled(imgui.ImVec2(p.x + 8, p.y + 8), imgui.ImVec2(p.x + 60, p.y + 60), 0xFFFFFFFF, 4)
                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 8, p.y + 8))
                imgui.Image(tex, imgui.ImVec2(52, 52))
            else
                dl:AddRectFilled(imgui.ImVec2(p.x + 8, p.y + 8), imgui.ImVec2(p.x + 60, p.y + 60), 0xFF25252D, 4)
                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 18, p.y + 26))
                imgui.TextDisabled(sp.id)
            end

            local tx = p.x + 70
            imgui.SetCursorScreenPos(imgui.ImVec2(tx, p.y + 12))
            imgui.TextColored(isSel and imgui.ImVec4(0.35, 0.95, 0.50, 1.0) or ac, sp.title)
            imgui.SetCursorScreenPos(imgui.ImVec2(tx, p.y + 34))
            imgui.TextColored(imgui.ImVec4(0.65, 0.65, 0.70, 1.0), isSel and (fa.ICON_CHECK .. u8" Выбрано (ID: " .. sp.id .. ")") or (u8"ID: " .. sp.id .. u8" (нажмите для выбора)"))

            imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + specCardH))
            imgui.Dummy(imgui.ImVec2(specCardW, 0))
        imgui.EndGroup()
    end

    imgui.Spacing()
    imgui.Text(u8"Выбранная модель:")
    imgui.SameLine(0, 6)
    imgui.PushItemWidth(95)
    if imgui.InputTextWithHint(u8"##ot_crmodel", u8"ID модели", otextCustomModelBuf, 16) then
        local mid = ffi.string(otextCustomModelBuf):match("^%s*(%d+)%s*$")
        if mid and mid ~= "" then
            otextSelectedModelId = mid
            local mName = getModelNameById(mid)
            otextSelectedModelName = (mName ~= "" and u8(mName)) or (u8"Модель #" .. mid)
        else
