        end
    end
    imgui.PopItemWidth()
    imgui.SameLine(0, 8)
    local noCrSel = (otextSelectedModelId == "")
    if noCrSel then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.45)) end
    if imgui.Button(fa.ICON_HAND_POINTER_O .. u8" Уже созданный объект (без /cr)##ot_nocr", imgui.ImVec2(235, 26)) then
        otextSelectedModelId = ""
        otextSelectedModelName = u8"Уже созданный объект"
        imgui.StrCopy(otextCustomModelBuf, "")
    end
    if noCrSel then imgui.PopStyleColor() end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- 2. ВВОД ТЕКСТА И ПАРАМЕТРЫ /OTEXT
    imgui.TextColored(ac, fa.ICON_PENCIL_SQUARE_O .. u8"  2. Текст и параметры отображения (/otext)")
    imgui.Spacing()

    imgui.Text(u8"Текст:")
    imgui.SameLine(0, 8)
    imgui.PushItemWidth(totalW - 55)
