        imgui.SameLine(lblColW)
        imgui.PushItemWidth(ctrlW)
        if imgui.BeginCombo(u8"##ot_fontcombo", string.format("%d) %s", otextFontIdx, OTEXT_FONTS[otextFontIdx] or "Arial")) then
