    imgui.SameLine(0, 14)

    -- ПРАВАЯ КОЛОНКА: ПРЕВЬЮ И КНОПКИ ПРИМЕНЕНИЯ
    imgui.BeginGroup()
        imgui.TextColored(ac, fa.ICON_EYE .. u8"  Предпросмотр текста:")
        local pp = imgui.GetCursorScreenPos()
