        local bgColU32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(otextBackColor[0], otextBackColor[1], otextBackColor[2], otextBackColor[3]))
        local fgColU32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(otextFontColor[0], otextFontColor[1], otextFontColor[2], math.max(0.25, otextFontColor[3])))
