        end
        local ty = pp.y + (prevH - txtSz.y) * 0.45
        dl:AddText(imgui.ImVec2(tx, ty), fgColU32, previewStr)
        if otextBold[0] then
            dl:AddText(imgui.ImVec2(tx + 1, ty), fgColU32, previewStr)
        end

        local metaLine = string.format("%s | %dpt%s | %s",
            OTEXT_FONTS[otextFontIdx] or "Arial",
            otextFontSize[0] or 24,
            otextBold[0] and " Bold" or "",
            OTEXT_RESOLUTIONS[otextResIdx] or "512x512")
        dl:AddText(imgui.ImVec2(pp.x + 8, pp.y + prevH - 18), 0xAAFFFFFF, metaLine)

        imgui.SetCursorScreenPos(imgui.ImVec2(pp.x, pp.y + prevH + 8))

        local createLbl = (otextSelectedModelId ~= "")
            and (fa.ICON_MAGIC .. u8"  Создать #" .. otextSelectedModelId .. u8", нанести текст и настройки##ot_create_and_apply")
            or (fa.ICON_MAGIC .. u8"  Нанести текст и применить все настройки##ot_create_and_apply")

        if imgui.Button(createLbl, imgui.ImVec2(rightW, 32)) then
            winOpen[0] = false
            local txtCp = u8:decode(ffi.string(otextTextBuf))
            local modelToCr = otextSelectedModelId
            otextBusyUntil = os.clock() + 18.0
            oinfoSilentPendingId = nil
            oinfoSilentExpireTime = 0
            lua_thread.create(function()
                if modelToCr and modelToCr ~= "" then
                    lastPendingModelId = modelToCr
                    sampSendChat("/cr " .. modelToCr)
                    wait(500)
                end
                if txtCp ~= "" then
                    otextPendingApplyAfterCreate = true
