        imgui.Spacing()
        imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.48, 0.12, 0.12, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.65, 0.16, 0.16, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(0.80, 0.22, 0.22, 1.0))
        if imgui.Button(fa.ICON_TRASH .. u8"  Удалить текст с объекта##ot_deltext", imgui.ImVec2(rightW, 28)) then
            startSingleOtextTask({ id = "delete", rowPattern = "Удалить текст" })
        end
        imgui.PopStyleColor(3)
    imgui.EndGroup()

    imgui.Unindent(10)
end

