-- ============================================================================
galleryActiveSource      = 1 -- 1 = SAMP screens, 2 = Trinity Launcher screens, 3 = Превью префабов
gallerySearchBuf         = imgui.new.char[128]('')
galleryCurrentPage       = 1
galleryItemsPerPage      = 18
galleryFiles             = {}
galleryNeedsScan         = true
galleryTexCache          = {}
galleryModalImgPath      = nil
galleryModalImgTex       = nil
galleryModalImgName      = ""
galleryLastShotTime      = 0
GALLERY_CACHE_DIR        = ROOT .. "\\resource\\Trinity Mapper Tools Resource\\gallery_cache"
if not doesDirectoryExist(GALLERY_CACHE_DIR) then
    pcall(createDirectory, GALLERY_CACHE_DIR)
end

function clearGalleryCache()
    if doesDirectoryExist(GALLERY_CACHE_DIR) then
        local fd = ffi.new("WIN32_FIND_DATAA")
        local pattern = GALLERY_CACHE_DIR .. "\\*.*"
        local h = ffi.C.FindFirstFileA(pattern, fd)
        if h ~= ffi.cast("void*", -1) then
            repeat
                local fname = ffi.string(fd.cFileName)
                if fname ~= "." and fname ~= ".." then
                    pcall(os.remove, GALLERY_CACHE_DIR .. "\\" .. fname)
                end
            until ffi.C.FindNextFileA(h, fd) == 0
            ffi.C.FindClose(h)
        end
    end
end

local function getGallerySourceDir(srcIdx)
    if srcIdx == 1 then
        return getScreensDirectory()
    elseif srcIdx == 2 then
        return (os.getenv("USERPROFILE") or "") .. "\\Documents\\GTA San Andreas User Files\\SAMP\\Trinity GTA screens"
    else
        return PREFAB_PREVIEWS_DIR
    end
end

local function scanGalleryFiles()
    local dir = getGallerySourceDir(galleryActiveSource)
    galleryFiles = {}
    galleryTexCache = {}

    if not doesDirectoryExist(dir) then
        galleryNeedsScan = false
        return
    end

    local fd = ffi.new("WIN32_FIND_DATAA")
    local pattern = dir .. "\\*.*"
    local h = ffi.C.FindFirstFileA(pattern, fd)
    if h == ffi.cast("void*", -1) then
        galleryNeedsScan = false
        return
    end

    repeat
        local fname = ffi.string(fd.cFileName)
        local low = fname:lower()
        if low:match("%.png$") or low:match("%.jpg$") or low:match("%.jpeg$") or low:match("%.bmp$") then
            local timeHigh = tonumber(fd.ftLastWriteTime.dwHighDateTime)
            local timeLow = tonumber(fd.ftLastWriteTime.dwLowDateTime)
            local ftime = timeHigh * 4294967296 + timeLow
            local size = tonumber(fd.nFileSizeLow) or 0
            table.insert(galleryFiles, {
                name = fname,
                path = dir .. "\\" .. fname,
                time = ftime,
                size = size
            })
        end
    until ffi.C.FindNextFileA(h, fd) == 0

    ffi.C.FindClose(h)

    -- Сортировка: самые свежие сверху
    table.sort(galleryFiles, function(a, b) return a.time > b.time end)
    galleryNeedsScan = false
    galleryCurrentPage = 1
end

local function getGalleryTex(fullPath)
    if not fullPath or fullPath == "" then return nil end
    if galleryTexCache[fullPath] then return galleryTexCache[fullPath] end
    if doesFileExist(fullPath) then
        local ok, t = pcall(imgui.CreateTextureFromFile, fullPath)
        if ok and t then
            galleryTexCache[fullPath] = t
            return t
        end
    end
    return nil
end

local function getGalleryThumbTex(item)
    if not item or not item.path then return nil end
    if galleryTexCache[item.path] then return galleryTexCache[item.path] end

    local thumbPath = GALLERY_CACHE_DIR .. "\\" .. item.name .. ".jpg"
    if not doesFileExist(thumbPath) then
        -- Сжатие выполняется только при открытии галереи для видимых 18 карточек (~3мс на снимок)
        generateGalleryThumbnail(item.path, thumbPath, 320, 180)
    end

    if doesFileExist(thumbPath) then
        local ok, t = pcall(imgui.CreateTextureFromFile, thumbPath)
        if ok and t then
            galleryTexCache[item.path] = t
            return t
        end
    end

    if doesFileExist(item.path) then
        local ok, t = pcall(imgui.CreateTextureFromFile, item.path)
        if ok and t then
            galleryTexCache[item.path] = t
            return t
        end
    end
    return nil
end
local function takeGalleryScreenshot()
    if os.clock() - galleryLastShotTime < 1.0 then return end
    galleryLastShotTime = os.clock()

    lua_thread.create(function()
        pcall(playSound, 1131, 0, 0, 0)
        showToastQuick("Скриншот", "Снимок экрана создаётся...")
        wait(50)
        -- Виртуальное нажатие F8 (VK_F8 = 0x77)
        ffi.C.keybd_event(0x77, 0, 0, nil)
        wait(30)
        ffi.C.keybd_event(0x77, 0, 2, nil)
        wait(400)
        galleryNeedsScan = true
        showToastQuick("Скриншот", "Снимок сохранён в папку скриншотов!")
    end)
end

function renderTabGallery()
    galleryFullLoadedThisFrame = 0
    imgui.Indent(10)
    imgui.Spacing()

    -- Если открыт просмотр отдельного скриншота — показываем прямо внутри этой вкладки
    if galleryModalImgPath then
        local ac = accentColor()
        if imgui.Button(fa.ICON_ARROW_LEFT .. safeU8("  Назад к списку##gal_back"), imgui.ImVec2(170, 28)) or isKeyJustPressed(0x1B) then
            galleryModalImgPath = nil
            galleryModalImgTex = nil
            galleryModalImgName = nil
            imgui.Unindent(10)
            return
        end

        imgui.SameLine(0, 15)
        imgui.TextColored(ac, fa.ICON_PICTURE_O .. "  " .. safeU8(galleryModalImgName or "Скриншот"))

        local availW = imgui.GetContentRegionAvail().x
        local rightBtnW = 320
        if availW > rightBtnW + 20 then
            imgui.SameLine(imgui.GetCursorPosX() + availW - rightBtnW)
        else
            imgui.SameLine(0, 10)
        end

        if imgui.Button(fa.ICON_EXTERNAL_LINK .. safeU8("  В проводнике##gal_open_single"), imgui.ImVec2(160, 28)) then
            os.execute(string.format('explorer.exe /select,"%s"', galleryModalImgPath))
        end

        imgui.SameLine(0, 8)
        if imgui.Button(fa.ICON_TRASH .. safeU8("  Удалить##gal_del_single"), imgui.ImVec2(110, 28)) then
            pcall(os.remove, galleryModalImgPath)
            pcall(os.remove, GALLERY_CACHE_DIR .. "\\" .. (galleryModalImgName or "") .. ".jpg")
            galleryTexCache[galleryModalImgPath] = nil
            galleryModalImgPath = nil
            galleryModalImgTex = nil
            galleryModalImgName = nil
            galleryNeedsScan = true
            showToastQuick(safeU8("Галерея"), safeU8("Скриншот удален"))
            imgui.Unindent(10)
            return
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        local previewTex = galleryModalImgTex
        if not previewTex and doesFileExist(galleryModalImgPath) then
            local ok, t = pcall(imgui.CreateTextureFromFile, galleryModalImgPath)
            if ok and t then
                galleryModalImgTex = t
                previewTex = t
            end
        end
        if not previewTex then
            previewTex = getGalleryTex(galleryModalImgPath)
        end
        if previewTex then
            local viewW = imgui.GetContentRegionAvail().x - 10
            local viewH = imgui.GetContentRegionAvail().y - 15

            local drawW = viewW
            local drawH = viewH
            local targetH = drawW * (9.0 / 16.0)
            if targetH > viewH then
                drawH = viewH
                drawW = drawH * (16.0 / 9.0)
            else
                drawH = targetH
            end

            local offsetX = math.max(0, (viewW - drawW) * 0.5)
            if offsetX > 0 then
                imgui.SetCursorPosX(imgui.GetCursorPosX() + offsetX)
            end

            imgui.Image(previewTex, imgui.ImVec2(drawW, drawH))
        else
            imgui.Spacing(); imgui.Spacing()
            imgui.TextColored(imgui.ImVec4(0.6, 0.6, 0.6, 1.0), safeU8("Загрузка изображения..."))
        end

        imgui.Unindent(10)
        return
    end

    -- Стандартный просмотр галереи:
    local ac = accentColor()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_CAMERA .. safeU8("  Галерея скриншотов"))
    imgui.SameLine()
    imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.60, 1.0), safeU8("Снимки экрана SAMP, Trinity Launcher и превью префабов"))
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- 1. Выбор источника
    if galleryActiveSource ~= 1 then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.16, 1.0)) end
    if imgui.Button(fa.ICON_FOLDER .. safeU8("  Скрины SA-MP##gal_s1"), imgui.ImVec2(160, 28)) then
        if galleryActiveSource ~= 1 then
            galleryActiveSource = 1
            galleryNeedsScan = true
        end
    end
    if galleryActiveSource ~= 1 then imgui.PopStyleColor() end

    imgui.SameLine(0, 8)
    if galleryActiveSource ~= 2 then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.16, 1.0)) end
    if imgui.Button(fa.ICON_FOLDER_OPEN .. safeU8("  Trinity Launcher##gal_s2"), imgui.ImVec2(170, 28)) then
        if galleryActiveSource ~= 2 then
            galleryActiveSource = 2
            galleryNeedsScan = true
        end
    end
    if galleryActiveSource ~= 2 then imgui.PopStyleColor() end

    imgui.SameLine(0, 8)
    if galleryActiveSource ~= 3 then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.16, 1.0)) end
    if imgui.Button(fa.ICON_PICTURE_O .. safeU8("  Кастомная папка##gal_s3"), imgui.ImVec2(160, 28)) then
        if galleryActiveSource ~= 3 then
            galleryActiveSource = 3
            galleryNeedsScan = true
        end
    end
    if galleryActiveSource ~= 3 then imgui.PopStyleColor() end

    local availW = imgui.GetContentRegionAvail().x
    local rightToolsW = 215
    if availW > rightToolsW + 20 then
        imgui.SameLine(imgui.GetCursorPosX() + availW - rightToolsW)
    else
        imgui.SameLine(0, 8)
    end

    if imgui.Button(fa.ICON_EXTERNAL_LINK .. safeU8("  Открыть папку##gal_open_dir"), imgui.ImVec2(170, 28)) then
        local curDir = getGallerySourceDir(galleryActiveSource)
        if doesDirectoryExist(curDir) then
            os.execute(string.format('explorer.exe "%s"', curDir))
        else
            showToastQuick(safeU8("Ошибка"), safeU8("Папка не найдена: " .. curDir))
        end
    end
    if imgui.IsItemHovered() then
        imgui.SetTooltip(safeU8("Открыть папку скриншотов в Проводнике Windows"))
    end

    imgui.SameLine(0, 6)
    if imgui.Button(fa.ICON_REFRESH .. "##gal_refresh", imgui.ImVec2(34, 28)) then
        galleryNeedsScan = true
    end
    if imgui.IsItemHovered() then
        imgui.SetTooltip(safeU8("Обновить список скриншотов"))
    end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- Сканирование файлов при необходимости
    if galleryNeedsScan then
        scanGalleryFiles()
    end

    -- Фильтрация по поиску
    local q = ffi.string(gallerySearchBuf):lower()
    local filtered = {}
    for _, f in ipairs(galleryFiles) do
        if q == "" or f.name:lower():find(q, 1, true) ~= nil then
            table.insert(filtered, f)
        end
    end

    -- Поиск
    imgui.PushItemWidth(260)
    imgui.InputTextWithHint(safeU8("##galsearch"), safeU8("Поиск по имени файла..."), gallerySearchBuf, 128)
    imgui.PopItemWidth()

    local totalItems = #filtered
    local totalPages = math.max(1, math.ceil(totalItems / galleryItemsPerPage))
    if galleryCurrentPage > totalPages then galleryCurrentPage = totalPages end
    if galleryCurrentPage < 1 then galleryCurrentPage = 1 end

    imgui.SameLine(0, 20)
    imgui.TextColored(imgui.ImVec4(0.60, 0.60, 0.65, 1.0), string.format(safeU8("Найдено: %d | Страница %d из %d"), totalItems, galleryCurrentPage, totalPages))

    -- Пагинация со стрелками FontAwesome
    local rightX = imgui.GetContentRegionAvail().x - 220
    if rightX > 200 then
        imgui.SameLine(imgui.GetCursorPosX() + rightX)
        if imgui.Button(fa.ICON_ANGLE_DOUBLE_LEFT .. "##gal_pfirst", imgui.ImVec2(32, 24)) then
            if galleryCurrentPage > 1 then galleryCurrentPage = 1; galleryTexCache = {} end
        end
        imgui.SameLine(0, 4)
        if imgui.Button(fa.ICON_ANGLE_LEFT .. "##gal_pprev", imgui.ImVec2(32, 24)) then
            if galleryCurrentPage > 1 then galleryCurrentPage = galleryCurrentPage - 1; galleryTexCache = {} end
        end
        imgui.SameLine(0, 8)
        imgui.Text(string.format("%d / %d", galleryCurrentPage, totalPages))
        imgui.SameLine(0, 8)
        if imgui.Button(fa.ICON_ANGLE_RIGHT .. "##gal_pnext", imgui.ImVec2(32, 24)) then
            if galleryCurrentPage < totalPages then galleryCurrentPage = galleryCurrentPage + 1; galleryTexCache = {} end
        end
        imgui.SameLine(0, 4)
        if imgui.Button(fa.ICON_ANGLE_DOUBLE_RIGHT .. "##gal_plast", imgui.ImVec2(32, 24)) then
            if galleryCurrentPage < totalPages then galleryCurrentPage = totalPages; galleryTexCache = {} end
        end
    end

    imgui.Spacing()

    -- Сетка скриншотов
    imgui.BeginChild(safeU8("##gal_grid_scroll"), imgui.ImVec2(0, 0), false)
    if totalItems == 0 then
        imgui.Spacing(); imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), safeU8("В этой папке нет изображений (.png, .jpg). Сделайте снимок на [F8]!"))
    else
        local availW = imgui.GetContentRegionAvail().x
        local cols = 3
        local pad = 12
        local cardW = math.floor((availW - pad * (cols - 1) - 16) / cols)
        local cardH = 190
        local imgH = 135

        local startIdx = (galleryCurrentPage - 1) * galleryItemsPerPage + 1
        local endIdx = math.min(totalItems, startIdx + galleryItemsPerPage - 1)

        local col = 0
        local dl = imgui.GetWindowDrawList()

        for idx = startIdx, endIdx do
            local item = filtered[idx]
            if col > 0 then imgui.SameLine(0, pad) end

            imgui.BeginGroup()
            local p = imgui.GetCursorScreenPos()
            dl:AddRectFilled(p, imgui.ImVec2(p.x + cardW, p.y + cardH), 0xFF141922, 6.0)
            dl:AddRect(p, imgui.ImVec2(p.x + cardW, p.y + cardH), 0x33445566, 6.0, 15, 1.0)

            local tex = getGalleryThumbTex(item)
            if tex then
                dl:AddImage(tex, imgui.ImVec2(p.x + 6, p.y + 6), imgui.ImVec2(p.x + cardW - 6, p.y + imgH), imgui.ImVec2(0, 0), imgui.ImVec2(1, 1))
            else
                dl:AddRectFilled(imgui.ImVec2(p.x + 6, p.y + 6), imgui.ImVec2(p.x + cardW - 6, p.y + imgH), 0xFF1A1F2A, 4.0)
                dl:AddText(imgui.ImVec2(p.x + cardW * 0.5 - 30, p.y + imgH * 0.5 - 8), 0x88FFFFFF, safeU8("Загрузка..."))
            end

            -- Невидимая кнопка поверх карточки для клика
            imgui.InvisibleButton("##gal_card_btn_" .. idx, imgui.ImVec2(cardW, cardH))
            if imgui.IsItemHovered() then
                dl:AddRect(p, imgui.ImVec2(p.x + cardW, p.y + cardH), 0xAA00E5FF, 6.0, 15, 1.5)
            end
            if imgui.IsItemClicked(0) then
                galleryModalImgPath = item.path
                galleryModalImgTex = nil
                galleryModalImgName = item.name
            end

            -- Подписи
            local shortName = item.name
            if #shortName > 26 then shortName = shortName:sub(1, 23) .. "..." end
            dl:AddText(imgui.ImVec2(p.x + 8, p.y + imgH + 8), 0xFFFFFFFF, shortName)

            local sizeKb = math.floor(item.size / 1024)
            local metaStr = string.format("%d КБ", sizeKb)
            dl:AddText(imgui.ImVec2(p.x + 8, p.y + imgH + 28), 0x88AAAAAA, safeU8(metaStr))

            imgui.EndGroup()

            col = col + 1
            if col >= cols then
                col = 0
                imgui.Spacing()
            end
        end
    end
    imgui.EndChild()

    imgui.Unindent(10)
end
-- ===== ВКЛАДКА ИСТОРИИ ДЕЙСТВИЙ (ACTION LOG) =====
function renderTabActionHistory()
    imgui.Indent(10)
    imgui.Spacing()
    local ac = accentColorA(1.0)
    local activeList = actionHistoryViewArchive and actionArchiveList or actionHistoryList

    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_HISTORY .. (actionHistoryViewArchive and u8"  АРХИВ ИСТОРИИ ДЕЙСТВИЙ (ВСЕ СЕССИИ)" or u8"  ЖУРНАЛ ДЕЙСТВИЙ (ТЕКУЩИЙ ЗАХОД)"))

    local rightW = 330
    imgui.SameLine(math.max(260, imgui.GetContentRegionAvail().x - rightW))
    if actionHistoryViewArchive then
        imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.45))
    else
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.18, 0.18, 0.22, 1.0))
    end
    if imgui.Button(fa.ICON_BOOKMARK .. (actionHistoryViewArchive and (u8"  Текущая сессия (" .. tostring(#actionHistoryList) .. u8")##ah_arch_btn") or (u8"  Архив (" .. tostring(#actionArchiveList) .. u8")##ah_arch_btn")), imgui.ImVec2(170, 24)) then
        actionHistoryViewArchive = not actionHistoryViewArchive
    end
    imgui.PopStyleColor()

    imgui.SameLine(0, 6)
    if imgui.Button(fa.ICON_TRASH .. (actionHistoryViewArchive and u8"  Очистить архив##clr_acthist" or u8"  Очистить лист##clr_acthist"), imgui.ImVec2(145, 24)) then
        if actionHistoryViewArchive then
            actionArchiveList = {}
            pcall(saveActionArchive)
        else
            actionHistoryList = {}
        end
    end

    imgui.Spacing()
    -- Фильтры по типу действия + поиск
    local filters = {
        {id = "all",    lbl = u8"Все (" .. tostring(#activeList) .. ")"},
        {id = "create", lbl = fa.ICON_PLUS .. u8" Создание"},
        {id = "delete", lbl = fa.ICON_TRASH .. u8" Удаление"},
        {id = "edit",   lbl = fa.ICON_PENCIL .. u8" Редакт."},
        {id = "group",  lbl = fa.ICON_OBJECT_GROUP .. u8" Группы"},
        {id = "tex",    lbl = fa.ICON_PAINT_BRUSH .. u8" Текстуры"},
    }
    for fi, f in ipairs(filters) do
        if fi > 1 then imgui.SameLine(0, 5) end
        local isSel = (actionHistoryFilter == f.id)
        if not isSel then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.19, 1.0)) end
        if imgui.Button(f.lbl .. "##ahf_" .. f.id, imgui.ImVec2(0, 26)) then
            actionHistoryFilter = f.id
        end
        if not isSel then imgui.PopStyleColor() end
    end

    imgui.SameLine(0, 12)
    imgui.PushItemWidth(220)
    imgui.InputTextWithHint(u8"##ah_search", u8"Поиск по #, модели или тексту...", actionHistorySearchBuf, 128)
    imgui.PopItemWidth()

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    if #activeList == 0 then
        imgui.Spacing(); imgui.Spacing()
        if actionHistoryViewArchive then
            imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.58, 1.0), u8"  Архив действий пока пуст.")
        else
            imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.58, 1.0), u8"  За этот заход на сервер действий пока нет. Нажмите кнопку 'Архив' справа вверху, чтобы посмотреть прошлые заходы.")
        end
        imgui.Unindent(10)
        return
    end

    imgui.BeginChild(u8"##acthist_scroll", imgui.ImVec2(0, 0), false)
        local dl = imgui.GetWindowDrawList()
        local rowW = imgui.GetContentRegionAvail().x - 6
        local rowH = 68
        local q = cyrLower(ffi.string(actionHistorySearchBuf))

        for idx, entry in ipairs(activeList) do
            local matchType = (actionHistoryFilter == "all") or (entry.actionType == actionHistoryFilter)
            local matchQ = (q == "")
                or cyrLower(entry.title or ""):find(q, 1, true)
                or cyrLower(entry.desc or ""):find(q, 1, true)
                or (entry.objId and tostring(entry.objId):find(q, 1, true))
                or (entry.modelId and tostring(entry.modelId):find(q, 1, true))
                or cyrLower(entry.modelName or ""):find(q, 1, true)

            if matchType and matchQ then
                imgui.BeginGroup()
                    local p = imgui.GetCursorScreenPos()
                    dl:AddRectFilled(p, imgui.ImVec2(p.x + rowW, p.y + rowH), 0xFF18181F, 6)
                    dl:AddRect(p, imgui.ImVec2(p.x + rowW, p.y + rowH), 0x33FFFFFF, 6, 0, 1.0)

                    -- Цветная вертикальная полоска слева по типу действия
                    local barCol = 0xFF000000 + accentColorHex()
                    local typeBadgeColor = ac
                    if entry.actionType == "delete" then
                        barCol = 0xFF3838E0
                        typeBadgeColor = imgui.ImVec4(0.95, 0.35, 0.35, 1.0)
                    elseif entry.actionType == "create" then
                        barCol = 0xFF45C845
                        typeBadgeColor = imgui.ImVec4(0.35, 0.90, 0.45, 1.0)
                    elseif entry.actionType == "group" then
                        barCol = 0xFFE88235
                        typeBadgeColor = imgui.ImVec4(0.65, 0.60, 1.00, 1.0)
                    elseif entry.actionType == "tex" then
                        barCol = 0xFF35B5E8
                        typeBadgeColor = imgui.ImVec4(0.95, 0.75, 0.25, 1.0)
                    end
                    dl:AddRectFilled(p, imgui.ImVec2(p.x + 4, p.y + rowH), barCol, 6)

                    -- Слева: картинка объекта (если действие связано с объектом и известна модель)
                    local imgW, imgH = 66, 52
                    local tex = entry.modelId and getTex(entry.modelId) or nil
                    if tex then
                        dl:AddRectFilled(imgui.ImVec2(p.x + 10, p.y + 8), imgui.ImVec2(p.x + 10 + imgW, p.y + 8 + imgH), 0xFFFFFFFF, 4)
                        imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 10, p.y + 8))
                        imgui.Image(tex, imgui.ImVec2(imgW, imgH))
                    else
                        dl:AddRectFilled(imgui.ImVec2(p.x + 10, p.y + 8), imgui.ImVec2(p.x + 10 + imgW, p.y + 8 + imgH), 0xFF25252D, 4)
                        local ic = fa.ICON_CUBE
                        if entry.actionType == "delete" then ic = fa.ICON_TRASH
                        elseif entry.actionType == "group" then ic = fa.ICON_OBJECT_GROUP
                        elseif entry.actionType == "tex" then ic = fa.ICON_PAINT_BRUSH
                        elseif entry.actionType == "edit" then ic = fa.ICON_PENCIL end
                        local icSz = imgui.CalcTextSize(ic)
                        dl:AddText(imgui.ImVec2(p.x + 10 + (imgW - icSz.x) * 0.5, p.y + 8 + (imgH - icSz.y) * 0.5), 0x99FFFFFF, ic)
                    end

                    -- Справа от картинки: время, заголовок с ID объекта и моделью, подпись
                    local tx = p.x + 10 + imgW + 14
                    imgui.SetCursorScreenPos(imgui.ImVec2(tx, p.y + 11))
                    local timeLabel = (actionHistoryViewArchive and entry.date) and ("[" .. tostring(entry.date) .. " " .. tostring(entry.time) .. "]") or ("[" .. tostring(entry.time) .. "]")
                    imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.60, 1.0), timeLabel)
                    imgui.SameLine(0, 8)
                    imgui.TextColored(typeBadgeColor, u8(entry.title or ""))

                    imgui.SetCursorScreenPos(imgui.ImVec2(tx, p.y + 36))
                    local subLine = entry.desc or ""
                    if entry.modelId and entry.modelName and entry.modelName ~= "" then
                        subLine = "Модель #" .. tostring(entry.modelId) .. " (" .. entry.modelName .. ")   |   " .. subLine
                    elseif entry.modelId then
                        subLine = "Модель #" .. tostring(entry.modelId) .. "   |   " .. subLine
                    end
                    imgui.TextColored(imgui.ImVec4(0.68, 0.68, 0.72, 1.0), u8(subLine))

                    -- Кнопки быстрого действия справа (Создать снова для удалённых/созданных или ТП к объекту)
                    local btnX = p.x + rowW - 155
                    local btnY = p.y + 19
                    if entry.modelId then
                        imgui.SetCursorScreenPos(imgui.ImVec2(btnX, btnY))
                        local isDel = (entry.actionType == "delete")
                        local hasRest = isDel and (entry.restoreData ~= nil)
                        local btnLbl = isDel and (fa.ICON_UNDO .. (hasRest and u8" Восстановить" or u8" Восстановить (/cr)")) or (fa.ICON_PLUS .. u8" Создать (/cr)")
                        if imgui.Button(btnLbl .. "##ah_cr_" .. idx, imgui.ImVec2(143, 30)) then
                            if hasRest then
                                restoreDeletedObject(entry.restoreData)
                            else
                                sampSendChat("/cr " .. tostring(entry.modelId))
                            end
                        end
                        if hasRest and imgui.IsItemHovered() then
                            local r = entry.restoreData
                            local posX = (type(r.x) == "number") and r.x or 0.0
                            local posY = (type(r.y) == "number") and r.y or 0.0
                            local posZ = (type(r.z) == "number") and r.z or 0.0
                            local rotX = (type(r.rx) == "number") and r.rx or 0.0
                            local rotY = (type(r.ry) == "number") and r.ry or 0.0
                            local rotZ = (type(r.rz) == "number") and r.rz or 0.0
                            local infoStr = string.format("Координаты: X: %.2f  Y: %.2f  Z: %.2f\nПоворот: RX: %.1f  RY: %.1f  RZ: %.1f", posX, posY, posZ, rotX, rotY, rotZ)
                            if r.materials and #r.materials > 0 then
                                infoStr = infoStr .. string.format("\nТекстур наложено: %d шт.", #r.materials)
                            end
                            imgui.SetTooltip(u8(infoStr .. "\nНажмите для создания и возврата на исходное место."))
                        end
                    elseif entry.cmd and entry.cmd ~= "" then
                        imgui.SetCursorScreenPos(imgui.ImVec2(btnX, btnY))
                        if imgui.Button(fa.ICON_PLAY .. u8" Повторить##ah_rep_" .. idx, imgui.ImVec2(143, 30)) then
                            sampSendChat(entry.cmd)
                        end
                    end

                    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + rowH))
                    imgui.Dummy(imgui.ImVec2(rowW, 0))
                imgui.EndGroup()
                imgui.Spacing()
            end
        end
    imgui.EndChild()
    imgui.Unindent(10)
end

local quickObjFrame = imgui.OnFrame(
    function() return quickObjOpen end,
    function()
        local oid = ffi.string(objCtrlIdBuf)
        if quickObjPositioning then
            local mx, my = getCursorPos()
            quickObjPosX = mx - 90
            quickObjPosY = my - 100
            local sw2, sh2 = getScreenResolution()
            imgui.SetNextWindowPos(imgui.ImVec2(sw2/2 - 150, quickObjPosY - 30), imgui.Cond.Always)
            imgui.SetNextWindowSize(imgui.ImVec2(300, 24), imgui.Cond.Always)
            imgui.Begin(u8"##qoposhelp", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoInputs)
                imgui.TextColored(imgui.ImVec4(1.0,0.84,0.0,1.0), u8"\xcf\xd0\xce\xc1\xc5\xcb \xe4\xeb\xff \xf4\xe8\xea\xf1\xe0\xf6\xe8\xe8")
            imgui.End()
            if isKeyDown(0x01) or isKeyDown(0x02) or isKeyDown(0x20) then
                quickObjPositioning = false
                saveSettings()
            end
        end
        local panelW, panelH = 210, 275
        local screenW, screenH = getScreenResolution()
        quickObjPosX = math.max(0, math.min(quickObjPosX, screenW - panelW))
        quickObjPosY = math.max(0, math.min(quickObjPosY, screenH - panelH))
        imgui.SetNextWindowPos(imgui.ImVec2(quickObjPosX, quickObjPosY), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(panelW, panelH), imgui.Cond.Always)
        imgui.Begin(u8"##quickobj", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoMove)
            imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_WRENCH .. u8" \xce\xe1\xfa\xe5\xea\xf2:")
            imgui.SameLine()
            if quickObjEditingId then
                imgui.PushItemWidth(90)
                if imgui.InputText(u8"##qoidedit", objCtrlIdBuf, 16, imgui.InputTextFlags.EnterReturnsTrue) then
                    quickObjEditingId = false
                end
                imgui.PopItemWidth()
                if imgui.IsKeyPressed(imgui.Key.Escape) then
                    quickObjEditingId = false
                end
            else
                if oid ~= "" then
                    imgui.TextColored(imgui.ImVec4(1.0,1.0,1.0,1.0), oid)
                else
                    imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1.0), u8"\xed\xe5 \xe7\xe0\xe4\xe0\xed")
                end
                if imgui.IsItemClicked(0) then
                    quickObjEditingId = true
                    imgui.SetKeyboardFocusHere(-1)
                end
            end
            imgui.Separator(); imgui.Spacing()

            -- Угол поворота
            local bwp = imgui.ImVec2(40, 26)
            local presets = {-180, -90, 90, 180}
            for _, deg in ipairs(presets) do
                if imgui.Button(tostring(deg).."##qop"..deg, bwp) then
                    objRotAngle[0] = deg
                    if quickObjSelectedAxis then
                        local cmds2 = {x="/rx",y="/ry",z="/rz"}
                        sampSendChat(cmds2[quickObjSelectedAxis] .. " " .. oid .. " " .. tostring(deg))
                    end
                end
                if deg ~= 180 then imgui.SameLine(0,4) end
            end
            imgui.Spacing()

            -- Поворот
            local angle = string.format("%.0f", objRotAngle[0])
            local bw = imgui.ImVec2(56, 28)
            local axes = {"x","y","z"}
            local cmds = {x="/rx",y="/ry",z="/rz"}
            for _, ax in ipairs(axes) do
                local active = (quickObjSelectedAxis == ax)
                if active then
                    imgui.PushStyleColor(imgui.Col.Button,        accentColorA(1))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(1))
                end
                if imgui.Button(ax:upper().."##qor"..ax, bw) then
                    quickObjSelectedAxis = (quickObjSelectedAxis == ax) and nil or ax
                end
                if active then imgui.PopStyleColor(2) end
                if ax ~= "z" then imgui.SameLine(0,4) end
            end
            imgui.Spacing()

            -- Сброс вращения
            imgui.PushStyleColor(imgui.Col.Button,        accentColorA(1))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(1))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  accentColorA(1))
            if imgui.Button(u8"\xd1\xe1\xf0\xee\xf1 \xe2\xf0\xe0\xf9\xe5\xed\xe8\xff##qorclr", imgui.ImVec2(178, 26)) then
                sampSendChat("/rclr " .. oid)
            end
            imgui.Spacing()
            if imgui.Button(u8"\xca\xeb\xee\xed\xe8\xf0\xee\xe2\xe0\xf2\xfc##qoclone", imgui.ImVec2(178, 26)) then
                sampSendChat("/clone " .. oid)
            end
            imgui.Spacing()
            if imgui.Button(fa.ICON_ARROW_DOWN .. u8"  Приземлить на пол##qodrop", imgui.ImVec2(178, 26)) then
                dropObjectToSurface(oid)
            end
            imgui.Spacing()
            imgui.PopStyleColor(3)

            -- Удалить
            imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.50,0.08,0.08,1))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.68,0.13,0.13,1))
            imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(0.80,0.20,0.20,1))
            if imgui.Button(u8"\xd3\xe4\xe0\xeb\xe8\xf2\xfc##qodel", imgui.ImVec2(178, 26)) then
                sampSendChat("/del " .. oid)
            end
            imgui.PopStyleColor(3)
        imgui.End()
    end
)
quickObjFrame.HideCursor = true
quickObjFrame.LockPlayer = false

local inspectFrame
inspectFrame = imgui.OnFrame(
    function() return inspectActive end,
    function()
        inspectFrame.HideCursor = isKeyDown(0x02) -- прячем курсор, только пока зажата ПКМ (чтобы мышь давала "сырое" движение для поворота камеры)
        local sw2, sh2 = getScreenResolution()
        local panelW, panelH = 360, 140
        imgui.SetNextWindowPos(imgui.ImVec2(sw2/2 - panelW/2, sh2 - panelH - 30), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(panelW, panelH), imgui.Cond.Always)
        imgui.Begin(u8"##inspectpanel", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoMove)
            imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive],
                (inspectObj and inspectObj.name or "?") .. " (" .. (inspectObj and tostring(inspectObj.id) or "?") .. ")")
            imgui.PushTextWrapPos(panelW - 12)
            imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"ПКМ + мышь — смотреть, ПКМ + WASD — летать, колесо — зум")
            imgui.PopTextWrapPos()
            imgui.Spacing(); imgui.Separator(); imgui.Spacing()

            local btnW = (panelW - 24 - 8) / 2 -- 24 = отступы окна слева/справа, 8 = зазор между кнопками
            imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.10,0.55,0.15,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.14,0.68,0.20,1.0))
            if imgui.Button(u8"Создать объект##insp_spawn", imgui.ImVec2(btnW, 32)) then
                stopInspect(true)
            end
            imgui.PopStyleColor(2)
            imgui.SameLine(0, 8)
            if imgui.Button(u8"Покинуть осмотр##insp_leave", imgui.ImVec2(btnW, 32)) then
                stopInspect(false)
            end
        imgui.End()
    end
    
)

local renderTabCatalog -- forward declaration: функция определена ниже по файлу, но нужна раньше в sceneFrame

local sceneFrame
sceneFrame = imgui.OnFrame(
    function() return sceneEditorActive end,
    function()
        sceneFrame.HideCursor = isKeyDown(0x02)
        resetTexCounter() -- иначе лимит подгрузки текстур (2/кадр) навсегда упирается в 0, пока закрыт основной каталог

        if sceneShowFullCatalog then
            local sw4, sh4 = getScreenResolution()
            local pad = 40
            imgui.SetNextWindowPos(imgui.ImVec2(pad, pad), imgui.Cond.Always)
            imgui.SetNextWindowSize(imgui.ImVec2(sw4 - pad*2, sh4 - pad*2), imgui.Cond.Always)
            imgui.SetNextWindowBgAlpha(0.97)
            imgui.Begin(u8"##sceneFullCatalogWin", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove)
                if imgui.Button(fa.ICON_TIMES .. u8"  Закрыть##sceneFullCatClose", imgui.ImVec2(120, 28)) then
                    sceneShowFullCatalog = false
                    sceneSpawnPickMode   = false
                    applyFilter()
                end
                if imgui.IsKeyPressed(imgui.Key.Escape) then
                    sceneShowFullCatalog = false
                    sceneSpawnPickMode   = false
                    applyFilter()
                end
                imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                renderTabCatalog()
            imgui.End()
            sceneFrame.HideCursor = false
            return
        end

        local sw3, sh3 = getScreenResolution()
        local dt = imgui.GetIO().DeltaTime
        local mp = imgui.GetMousePos()

        local LEFT_FULL, RIGHT_FULL, COLLAPSED, HOTZONE = 340, 260, 10, 16
        local EASE = math.min(1.0, dt * 12.0)

        -- наведена ли мышь на зону левой/правой панели (с учётом уже раскрытой ширины)
        local leftHover  = mp.x <= math.max(sceneLeftPanelW, HOTZONE)
        local rightHover = mp.x >= sw3 - math.max(sceneRightPanelW, HOTZONE)

        sceneLeftPanelW  = sceneLeftPanelW  + ((leftHover  and LEFT_FULL  or COLLAPSED) - sceneLeftPanelW ) * EASE
        sceneRightPanelW = sceneRightPanelW + ((rightHover and RIGHT_FULL or COLLAPSED) - sceneRightPanelW) * EASE

        -- ===== ЛЕВАЯ ПАНЕЛЬ =====
        imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(sceneLeftPanelW, sh3), imgui.Cond.Always)
        imgui.SetNextWindowBgAlpha(0.92)
        imgui.Begin(u8"##scenecatalog", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollbar)
            if sceneLeftPanelW > 150 then
                imgui.TextColored(accentColorA(1), fa.ICON_OBJECT_GROUP .. u8"  РЕДАКТОР ОБЪЕКТОВ")
                imgui.Separator()

                -- вкладки
                local function tabBtn(key, label)
                    local active = (sceneLeftTab == key)
                    if active then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.35)) end
                    if imgui.Button(label .. "##scenetab" .. key, imgui.ImVec2((sceneLeftPanelW - 24 - 8) / 3, 26)) then
                        sceneLeftTab = key
                    end
                    if active then imgui.PopStyleColor() end
                end
                tabBtn("catalog", u8"Каталог")
                imgui.SameLine(0, 4)
                tabBtn("favorites", fa.ICON_STAR)
                imgui.SameLine(0, 4)
                tabBtn("categories", fa.ICON_TAGS)
                imgui.Spacing()

                if imgui.Button(fa.ICON_CUBES .. u8"  Каталог Объектов##sceneFullCat", imgui.ImVec2(sceneLeftPanelW - 24, 32)) then
                    sceneSpawnPickMode   = true
                    sceneShowFullCatalog = true
                    applyFilter()
                end
                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                if sceneLeftTab == "categories" then
                    -- список категорий
                    if imgui.Selectable(u8"Все объекты##scenecatall", sceneCatFilter == 0) then
                        sceneCatFilter = 0; sceneLeftTab = "catalog"
                    end
                    for ci, cat in ipairs(objCategories) do
                        if imgui.Selectable(cat.name .. "##scenecat" .. ci, sceneCatFilter == ci) then
                            sceneCatFilter = ci; sceneLeftTab = "catalog"
                        end
                    end

                elseif sceneLeftTab == "favorites" then
                    -- список избранных объектов
                    for oid, _ in pairs(favorites) do
                        local o = nil
                        for _, ao in ipairs(allObjects) do if ao.id == oid then o = ao; break end end
                        if o then
                            local tex = getTex(o.id)
                            if tex then imgui.Image(tex, imgui.ImVec2(40,40)) else imgui.Button("##scfph"..o.id, imgui.ImVec2(40,40)) end
                            if imgui.IsItemClicked(0) then sceneSpawnObject(o) end
                            imgui.SameLine()
                            imgui.Text("[" .. o.id .. "] " .. (o.name or ""))
                        end
                    end

                else -- catalog
                    imgui.PushItemWidth(-1)
                    imgui.InputTextWithHint(u8"##sceneSearch", u8"Поиск объекта или ID...", objSearchQuery, 128)
                    imgui.PopItemWidth()
                    imgui.Spacing()

                    local q = ffi.string(objSearchQuery):lower()
                    local selectedCat = (sceneCatFilter > 0 and objCategories[sceneCatFilter]) or nil

                    -- собираем совпадения и сортируем по размеру (маленькие сначала) - чтобы не было "каши" из огромных объектов вперемешку
                    local matches = {}
                    for _, o in ipairs(allObjects) do
                        local matchQ = (q == "" or o.id:find(q,1,true) or (o.name or ""):lower():find(q,1,true))
                        local matchCat = true
                        if selectedCat then
                            matchCat = false
                            if selectedCat.id_map then
                                local numId = tonumber(o.id)
                                if numId and selectedCat.id_map[numId] then matchCat = true end
                            elseif selectedCat.keys then
                                local nameLow = (o.name or ""):lower()
                                for _, kw in ipairs(selectedCat.keys) do
                                    if nameLow:find(kw, 1, true) then matchCat = true; break end
                                end
                            end
                        end
                        if matchQ and matchCat then
                            table.insert(matches, o)
                        end
                    end
                    table.sort(matches, function(a, b) return (a.radius or 0) < (b.radius or 0) end)

                    local shown = 0
                    for _, o in ipairs(matches) do
                        if shown >= 60 then break end
                        do
                            shown = shown + 1
                            local tex = getTex(o.id)
                            if tex then imgui.Image(tex, imgui.ImVec2(40,40)) else imgui.Button("##scph"..o.id, imgui.ImVec2(40,40)) end
                            if imgui.IsItemClicked(0) then sceneSpawnObject(o) end
                            imgui.SameLine()
                            imgui.Text("[" .. o.id .. "] " .. (o.name or ""))
                        end
                    end
                end
            else
                -- свёрнутое состояние — просто тонкая цветная полоска-индикатор
                local dl = imgui.GetWindowDrawList()
                local p = imgui.GetWindowPos()
                dl:AddRectFilled(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + sceneLeftPanelW, p.y + sh3), 0xCC000000 + accentColorHex(), 0)
            end
        imgui.End()

        -- ===== ПРАВАЯ ПАНЕЛЬ =====
        imgui.SetNextWindowPos(imgui.ImVec2(sw3 - sceneRightPanelW, 0), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(sceneRightPanelW, sh3), imgui.Cond.Always)
        imgui.SetNextWindowBgAlpha(0.92)
        imgui.Begin(u8"##scenelist", nil, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollbar)
            if sceneRightPanelW > 150 then
                imgui.TextColored(accentColorA(1), u8"Объекты в сцене: " .. #sceneObjects)
                imgui.Separator()
                for i, o in ipairs(sceneObjects) do
                    local isSel = (sceneSelected == i)
                    if isSel then imgui.PushStyleColor(imgui.Col.Text, accentColor()) end
                    if imgui.Selectable("[" .. o.id .. "] " .. o.name .. "##sceneobj" .. i, isSel) then
                        sceneSelected = i
                    end
                    if isSel then imgui.PopStyleColor() end
                end
                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                if sceneSelected and sceneObjects[sceneSelected] then
                    local o = sceneObjects[sceneSelected]
                    imgui.TextColored(accentColorA(1), u8"Выбран: [" .. o.id .. "] " .. o.name)
                    imgui.Spacing()

                    local halfW = (sceneRightPanelW - 24 - 6) / 2
                    if sceneGizmoMode == "move" then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.45)) end
                    if imgui.Button(fa.ICON_ARROWS .. u8" Двигать (G)##scgm", imgui.ImVec2(halfW, 26)) then sceneGizmoMode = "move" end
                    if sceneGizmoMode == "move" then imgui.PopStyleColor() end
                    imgui.SameLine(0, 6)
                    if sceneGizmoMode == "rotate" then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.45)) end
                    if imgui.Button(fa.ICON_REFRESH .. u8" Крутить (R)##scgr", imgui.ImVec2(halfW, 26)) then sceneGizmoMode = "rotate" end
                    if sceneGizmoMode == "rotate" then imgui.PopStyleColor() end
                    imgui.Spacing()

                    local function axisRow(label, val, step, apply)
                        imgui.Text(label)
                        imgui.SameLine(28)
                        if imgui.Button(" - ##sc" .. label .. "m", imgui.ImVec2(24, 22)) then apply(val - step) end
                        imgui.SameLine(0, 4)
                        imgui.Text(string.format("%.2f", val))
                        imgui.SameLine(0, 4)
                        if imgui.Button(" + ##sc" .. label .. "p", imgui.ImVec2(24, 22)) then apply(val + step) end
                    end

                    axisRow("X", o.x, 0.25, function(v) o.x = v; pcall(setObjectCoordinates, o.handle, o.x, o.y, o.z) end)
                    axisRow("Y", o.y, 0.25, function(v) o.y = v; pcall(setObjectCoordinates, o.handle, o.x, o.y, o.z) end)
                    axisRow("Z", o.z, 0.25, function(v) o.z = v; pcall(setObjectCoordinates, o.handle, o.x, o.y, o.z) end)
                    imgui.Spacing()
                    axisRow("RX", o.rx, 5.0, function(v) o.rx = v; pcall(setObjectRotation, o.handle, o.rx, o.ry, o.rz) end)
                    axisRow("RY", o.ry, 5.0, function(v) o.ry = v; pcall(setObjectRotation, o.handle, o.rx, o.ry, o.rz) end)
                    axisRow("RZ", o.rz, 5.0, function(v) o.rz = v; pcall(setObjectRotation, o.handle, o.rx, o.ry, o.rz) end)

                    imgui.Spacing()
                    if imgui.Button(fa.ICON_TRASH .. u8" Удалить объект##sceneDelSel", imgui.ImVec2(-1, 26)) then
                        sceneDeleteSelected()
                    end
                    imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                else
                    imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1.0), u8"Кликните по объекту в сцене\nили выберите его в списке выше")
                    imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                end

                imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1.0), u8"Del — удалить, G — двигать, R — крутить\nПКМ + мышь/WASD — камера")
                imgui.Spacing()
                if imgui.Button(u8"Завершить и сохранить##sceneSaveExit", imgui.ImVec2(-1, 30)) then
                    if #sceneObjects > 0 then
                        prefabSteps = buildCommandsFromScene()
                        prefabStepLabels = {}
                        showPrefabSaveDlg = true
                        imgui.StrCopy(prefabSaveNameBuf, u8"Постройка " .. os.date("%d.%m %H:%M"))
                    end
                    stopSceneEditor()
                end
                if imgui.Button(u8"Выйти без сохранения##sceneExit", imgui.ImVec2(-1, 30)) then
                    stopSceneEditor()
                end
            else
                local dl = imgui.GetWindowDrawList()
                local p = imgui.GetWindowPos()
                dl:AddRectFilled(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + sceneRightPanelW, p.y + sh3), 0xCC000000 + accentColorHex(), 0)
            end
        imgui.End()

        -- ===== ГИЗМО для выделенного объекта =====
        local gizmoHoverAxis = nil
        local selObj = sceneSelected and sceneObjects[sceneSelected] or nil

        local gDown = isKeyDown(0x47)
        local rDown = isKeyDown(0x52)
        if selObj and gDown and not sceneGKeyWasDown then sceneGizmoMode = "move" end
        if selObj and rDown and not sceneRKeyWasDown then sceneGizmoMode = "rotate" end
        sceneGKeyWasDown = gDown
        sceneRKeyWasDown = rDown

        if selObj and not isKeyDown(0x02) then
            local ox, oy = convert3DCoordsToScreen(selObj.x, selObj.y, selObj.z)
            if ox then
                imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
                imgui.SetNextWindowSize(imgui.ImVec2(sw3, sh3), imgui.Cond.Always)
                imgui.SetNextWindowBgAlpha(0)
                imgui.Begin(u8"##scenegizmo", nil,
                    imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoMove +
                    imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoInputs + imgui.WindowFlags.NoSavedSettings)
                local dl = imgui.GetWindowDrawList()
                local mp3 = imgui.GetMousePos()
                local hoverBestDist = 10

                if sceneGizmoMode == "move" then
                    local axesDef = {
                        {key="x", ex=selObj.x+sceneGizmoLen, ey=selObj.y, ez=selObj.z, col=0xFFFF3B3B},
                        {key="y", ex=selObj.x, ey=selObj.y+sceneGizmoLen, ez=selObj.z, col=0xFF3BFF3B},
                        {key="z", ex=selObj.x, ey=selObj.y, ez=selObj.z+sceneGizmoLen, col=0xFF3B8CFF},
                    }
                    for _, a in ipairs(axesDef) do
                        local tx, ty = convert3DCoordsToScreen(a.ex, a.ey, a.ez)
                        if tx then
                            local isActive = (sceneGizmoDragAxis == a.key)
                            local isHover  = (gizmoHoverAxis == a.key)
                            local thickness = isActive and 5.0 or (isHover and 4.0 or 3.0)
                            local tipSize = isActive and 16 or (isHover and 14 or 12)

                            -- направление стрелки от центра объекта к концу оси
                            local ax_, ay_ = tx - ox, ty - oy
                            local alen = math.sqrt(ax_*ax_ + ay_*ay_)
                            local dirx, diry = 1, 0
                            if alen > 0.001 then dirx, diry = ax_/alen, ay_/alen end
                            local perpx, perpy = -diry, dirx

                            -- линия чуть короче, чтобы наконечник не "тонул" в ней
                            local lineEndX, lineEndY = tx - dirx*tipSize*0.6, ty - diry*tipSize*0.6
                            dl:AddLine(imgui.ImVec2(ox, oy), imgui.ImVec2(lineEndX, lineEndY), a.col, thickness)

                            -- треугольный наконечник-стрелка
                            local backX, backY = tx - dirx*tipSize, ty - diry*tipSize
                            local p1x, p1y = backX + perpx*tipSize*0.5, backY + perpy*tipSize*0.5
                            local p2x, p2y = backX - perpx*tipSize*0.5, backY - perpy*tipSize*0.5
                            dl:AddTriangleFilled(imgui.ImVec2(tx, ty), imgui.ImVec2(p1x, p1y), imgui.ImVec2(p2x, p2y), a.col)

                            local dx, dy = tx - ox, ty - oy
                            local len2 = dx*dx + dy*dy
                            local t = 0
                            if len2 > 0 then
                                t = ((mp3.x-ox)*dx + (mp3.y-oy)*dy) / len2
                                t = math.max(0, math.min(1, t))
                            end
                            local px, py = ox + dx*t, oy + dy*t
                            local dist = math.sqrt((mp3.x-px)^2 + (mp3.y-py)^2)
                            if dist < hoverBestDist then
                                hoverBestDist = dist
                                gizmoHoverAxis = a.key
                            end
                        end
                    end
                    dl:AddCircleFilled(imgui.ImVec2(ox, oy), 5, 0xFFFFFFFF)

                else -- "rotate" — кольца вокруг объекта
                    local SEG = 28
                    local ringsDef = {
                        {key="x", col=0xFFFF3B3B, fn=function(t) return selObj.x, selObj.y+sceneGizmoRotR*math.cos(t), selObj.z+sceneGizmoRotR*math.sin(t) end},
                        {key="y", col=0xFF3BFF3B, fn=function(t) return selObj.x+sceneGizmoRotR*math.cos(t), selObj.y, selObj.z+sceneGizmoRotR*math.sin(t) end},
                        {key="z", col=0xFF3B8CFF, fn=function(t) return selObj.x+sceneGizmoRotR*math.cos(t), selObj.y+sceneGizmoRotR*math.sin(t), selObj.z end},
                    }
                    for _, r in ipairs(ringsDef) do
                        local isActive = (sceneGizmoDragAxis == r.key)
                        local isHover  = (gizmoHoverAxis == r.key)
                        local thickness = isActive and 4.0 or (isHover and 3.0 or 2.0)
                        local prevSx, prevSy = nil, nil
                        for i = 0, SEG do
                            local t = (i / SEG) * math.pi * 2
                            local wx, wy, wz = r.fn(t)
                            local sx, sy = convert3DCoordsToScreen(wx, wy, wz)
                            if sx and prevSx then
                                dl:AddLine(imgui.ImVec2(prevSx, prevSy), imgui.ImVec2(sx, sy), r.col, thickness)
                                local dx, dy = sx - prevSx, sy - prevSy
                                local len2 = dx*dx + dy*dy
                                local segT = 0
                                if len2 > 0 then
                                    segT = ((mp3.x-prevSx)*dx + (mp3.y-prevSy)*dy) / len2
                                    segT = math.max(0, math.min(1, segT))
                                end
                                local px, py = prevSx + dx*segT, prevSy + dy*segT
                                local dist = math.sqrt((mp3.x-px)^2 + (mp3.y-py)^2)
                                if dist < hoverBestDist then
                                    hoverBestDist = dist
                                    gizmoHoverAxis = r.key
                                end
                            end
                            prevSx, prevSy = sx, sy
                        end
                    end
                    dl:AddCircleFilled(imgui.ImVec2(ox, oy), 4, 0xFFFFFFFF)
                end

                imgui.End()
            end
        end

        -- клик по объекту / по гизмо в сцене (не по панелям, не во время осмотра камерой через ПКМ)
        local mp2 = imgui.GetMousePos()
        local inWorldArea = mp2.x > sceneLeftPanelW and mp2.x < (sw3 - sceneRightPanelW) and not isKeyDown(0x02)

        if inWorldArea and isKeyJustPressed(0x01) then
            imgui.SetWindowFocus() -- снимаем фокус с любого активного текстового поля (например, поиска)
            if gizmoHoverAxis and selObj then
                sceneGizmoDragAxis = gizmoHoverAxis
                if sceneGizmoMode == "move" then
                    local ax, ay = convert3DCoordsToScreen(selObj.x, selObj.y, selObj.z)
                    local tx, ty
                    if sceneGizmoDragAxis == "x" then tx, ty = convert3DCoordsToScreen(selObj.x+1, selObj.y, selObj.z)
                    elseif sceneGizmoDragAxis == "y" then tx, ty = convert3DCoordsToScreen(selObj.x, selObj.y+1, selObj.z)
                    else tx, ty = convert3DCoordsToScreen(selObj.x, selObj.y, selObj.z+1) end
                    local dirx, diry, pxPerUnit = 0, 0, 1
                    if ax and tx then
                        dirx, diry = tx-ax, ty-ay
                        pxPerUnit = math.sqrt(dirx*dirx + diry*diry)
                        if pxPerUnit > 0.0001 then dirx, diry = dirx/pxPerUnit, diry/pxPerUnit end
                    end
                    sceneGizmoDragStart = {mx=mp2.x, my=mp2.y, ox=selObj.x, oy=selObj.y, oz=selObj.z,
                        pxPerUnit=math.max(pxPerUnit, 1), dirx=dirx, diry=diry}
                else -- rotate
                    local cx, cy = convert3DCoordsToScreen(selObj.x, selObj.y, selObj.z)
                    local startAngle = cx and math.atan2(mp2.y - cy, mp2.x - cx) or 0
                    local startRot = (sceneGizmoDragAxis == "x" and selObj.rx)
                        or (sceneGizmoDragAxis == "y" and selObj.ry) or selObj.rz
                    sceneGizmoDragStart = {cx=cx, cy=cy, startAngle=startAngle, startRot=startRot}
                end
            else
                sceneGizmoDragAxis = nil
                local best, bestDist = nil, 40
                for i, o in ipairs(sceneObjects) do
                    local sx, sy = convert3DCoordsToScreen(o.x, o.y, o.z)
                    if sx and sy then
                        local d = math.sqrt((sx - mp2.x)^2 + (sy - mp2.y)^2)
                        if d < bestDist then bestDist = d; best = i end
                    end
                end
                sceneSelected = best -- клик в пустоту снимает выделение
            end
        end

        if sceneGizmoDragAxis and isKeyDown(0x01) and sceneGizmoDragStart and selObj then
            if sceneGizmoMode == "move" then
                local dmx = mp2.x - sceneGizmoDragStart.mx
                local dmy = mp2.y - sceneGizmoDragStart.my
                local along = dmx * sceneGizmoDragStart.dirx + dmy * sceneGizmoDragStart.diry
                local worldDelta = along / sceneGizmoDragStart.pxPerUnit
                if sceneGizmoDragAxis == "x" then selObj.x = sceneGizmoDragStart.ox + worldDelta
                elseif sceneGizmoDragAxis == "y" then selObj.y = sceneGizmoDragStart.oy + worldDelta
                else selObj.z = sceneGizmoDragStart.oz + worldDelta end
                pcall(setObjectCoordinates, selObj.handle, selObj.x, selObj.y, selObj.z)
            else -- rotate
                local curAngle = math.atan2(mp2.y - sceneGizmoDragStart.cy, mp2.x - sceneGizmoDragStart.cx)
                local deltaDeg = math.deg(curAngle - sceneGizmoDragStart.startAngle)
                local newRot = (sceneGizmoDragStart.startRot + deltaDeg) % 360
                if newRot > 180 then newRot = newRot - 360 end
                if sceneGizmoDragAxis == "x" then selObj.rx = newRot
                elseif sceneGizmoDragAxis == "y" then selObj.ry = newRot
                else selObj.rz = newRot end
                pcall(setObjectRotation, selObj.handle, selObj.rx, selObj.ry, selObj.rz)
            end
        elseif sceneGizmoDragAxis and not isKeyDown(0x01) then
            sceneGizmoDragAxis = nil
            sceneGizmoDragStart = nil
        end

        if isKeyJustPressed(0x2E) then -- Delete
            sceneDeleteSelected()
        end
    end
)
