                sampSendChat("/grclr " .. gid)
            end
            imgui.Spacing()
            if imgui.Button(u8"\xca\xeb\xee\xed\xe8\xf2\xfc##qgclone", imgui.ImVec2(178, 26)) then
                sampSendChat("/gclone " .. gid)
            end
            imgui.Spacing()
