local objScanFrame = imgui.OnFrame(
    function() return objScanEnabled and objScanResult ~= nil and not sampIsChatInputActive() end,
    function()
        resetTexCounter()
        local result = objScanResult
        if not result then return end

        local sw, sh = getScreenResolution()
        local sx, sy = convert3DCoordsToScreen(result.x, result.y, result.z)
        if sx and sy then
            result.sx = sx
            result.sy = sy
        end
        local oinfo = (result.type ~= "furniture" and result.id) and oinfoCache[tostring(result.id)] or nil
        local matLineCount = 1
        if oinfo and not oinfo.noTextures and oinfo.materials and #oinfo.materials > 0 then
            matLineCount = #oinfo.materials
        end

        local itemCount = 9 -- основное меню (включая [9] Скопировать GLOBAL IDX)
        if result.type == "furniture" then itemCount = 3
        elseif objScanSubmenu == "tex" then itemCount = 5
        elseif objScanSubmenu == "group" then itemCount = 4
        elseif objScanSubmenu == "rot" then itemCount = 7 end

        local extraOinfoH = (result.type ~= "furniture") and (34 + matLineCount * 19) or 0
        local boxW = (result.type == "furniture") and 270 or 380
        local boxH = math.max(150, 92 + extraOinfoH + itemCount * 20)
        local boxX = result.sx + 24
        local boxY = result.sy - boxH / 2
        if boxX + boxW > sw - 8 then boxX = result.sx - boxW - 24 end
        if boxY < 8 then boxY = 8 end
        if boxY + boxH > sh - 8 then boxY = sh - boxH - 8 end

        imgui.SetNextWindowPos(imgui.ImVec2(boxX, boxY), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(boxW, boxH), imgui.Cond.Always)
        imgui.Begin(u8"##objscan", nil,
            imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize +
            imgui.WindowFlags.NoMove +
            imgui.WindowFlags.NoScrollbar +
            imgui.WindowFlags.NoSavedSettings)
            local accent = accentColor()
            imgui.GetWindowDrawList():AddRectFilled(
                imgui.ImVec2(boxX, boxY), imgui.ImVec2(boxX + 4, boxY + boxH),
                imgui.GetColorU32(imgui.Col.ButtonActive))

            local imgSize = 56
            local tex = nil
            if result.type ~= "furniture" then
                tex = getTex(result.modelId)
            end
            local cursorStart = imgui.GetCursorPos()
            if tex then
                imgui.Image(tex, imgui.ImVec2(imgSize, imgSize))
            else
                imgui.GetWindowDrawList():AddRectFilled(
                    imgui.GetCursorScreenPos(),
                    imgui.ImVec2(imgui.GetCursorScreenPos().x + imgSize, imgui.GetCursorScreenPos().y + imgSize),
                    0xFF2A2A2A, 4)
                imgui.SetCursorPos(imgui.ImVec2(cursorStart.x + 6, cursorStart.y + imgSize/2 - 8))
                imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"NO IMG")
            end

            imgui.SetCursorPos(imgui.ImVec2(cursorStart.x + imgSize + 10, cursorStart.y))
            imgui.BeginGroup()
                if result.type == "furniture" then
                    imgui.TextColored(accent, u8"Мебель IDX #" .. result.id)
                else
                    imgui.TextColored(accent, u8"Объект #" .. result.id .. (result.modelId and (" (ID: " .. tostring(result.modelId) .. ")") or ""))
                    if oinfo and oinfo.gIdxFull then
                        imgui.TextColored(imgui.ImVec4(1.0, 0.85, 0.30, 1.0), u8"GLOBAL IDX: " .. u8(oinfo.gIdxFull))
                        if imgui.SmallButton(u8"Скопировать GLOBAL IDX [F]##copygidx") then
                            local copyVal = (oinfo.gIdxNum ~= "" and oinfo.gIdxNum) or oinfo.gIdxFull
                            setClipboardText(copyVal)
                            toast_text  = "GLOBAL IDX скопирован: " .. tostring(copyVal)
                            toast_text2 = "Объект #" .. tostring(result.id)
                            toast_tex   = nil
                            toast_timer = 150
                        end
                    else
                        imgui.TextColored(imgui.ImVec4(0.65, 0.65, 0.65, 1.0), u8"GLOBAL IDX: загрузка /oinfo...")
                    end
                end
            imgui.EndGroup()

            imgui.SetCursorPos(imgui.ImVec2(cursorStart.x, cursorStart.y + imgSize + 6))
            if result.type ~= "furniture" then
                imgui.Separator()
                imgui.TextColored(imgui.ImVec4(1.0, 0.82, 0.28, 1.0), u8"Наложенные текстуры и цвета:")
                if not oinfo then
                    imgui.TextColored(imgui.ImVec4(0.60, 0.60, 0.60, 1.0), u8"  Чтение данных /oinfo...")
                elseif oinfo.noTextures or not oinfo.materials or #oinfo.materials == 0 then
                    imgui.TextColored(imgui.ImVec4(0.68, 0.68, 0.68, 1.0), u8"  Текстуры и цвета отсутствуют")
                else
                    for _, m in ipairs(oinfo.materials) do
                        local dispTex
                        if m.texId and m.texName then
                            dispTex = string.format("#%s (%s %s)", m.texId, m.texModel or "", m.texName)
                        elseif m.tex and m.tex ~= "" then
                            dispTex = m.tex
                        else
                            dispTex = "нет"
                        end
                        local lineStr = string.format("Мат #%s: Текстура %s | Цвет %s", tostring(m.mat), dispTex, tostring(m.color or "0"))
                        imgui.TextColored(imgui.ImVec4(0.92, 0.92, 0.95, 1.0), u8(lineStr))
                    end
                end
                imgui.Separator()
            end

            local actionText
            if result.type == "furniture" then
                actionText = {
                    {u8"Редактировать", accent},
                    {u8"Спрятать в чулан", accent},
                    {u8"Открыть меню действий", accent},
                }
            elseif objScanSubmenu == "rot" then
                actionText = {
                    {u8"Повернуть на 45 по Z", accent},
                    {u8"Повернуть на 90 по Z", accent},
                    {u8"Повернуть на 90 по Y", accent},
                    {u8"Повернуть на 180 по Y", accent},
                    {u8"Повернуть на 45 по X", accent},
                    {u8"Повернуть на 90 по X", accent},
                    {u8"Вернуться к редактированию <<", imgui.ImVec4(1.0, 1.0, 1.0, 1.0)}
                }
            elseif objScanSubmenu == "tex" then
                local curTex = ffi.string(mtSearchBuf)
                local clipStr = getClipboardText() or ""
                clipStr = clipStr:gsub("^%s*(.-)%s*$", "%1")
                if #clipStr > 12 then clipStr = clipStr:sub(1, 12) .. ".." end
                actionText = {
                    {u8"Нанести текстуру ", accent, curTex ~= "" and curTex or u8"(не выбрана)"},
                    {u8"Сбросить слот #0", accent},
                    {u8"Очистить все слоты", accent},
                    {u8"Вставить из буфера и нанести ", accent, clipStr ~= "" and ("(" .. clipStr .. ")") or u8"(пусто)"},
                    {u8"Назад в меню <<", imgui.ImVec4(1.0, 1.0, 1.0, 1.0)}
                }
            elseif objScanSubmenu == "group" then
                local curGrpStr = tostring(objScanSelectedGroup or 1)
                actionText = {
                    {u8"Добавить в группу #" .. curGrpStr, accent},
                    {u8"Выбрать группу (сейчас: #" .. curGrpStr .. ")", accent},
                    {u8"Удалить из группы", accent},
                    {u8"Вернуться к редактированию <<", imgui.ImVec4(1.0, 1.0, 1.0, 1.0)}
                }
            else
                actionText = {
                    {u8"Взять в фокус", accent},
                    {u8"Редактировать объект", accent},
                    {u8"Удалить объект", accent},
                    {u8"Клонировать объект", accent},
                    {u8"Телепортироваться", accent},
                    {u8"Текстуризация >>", imgui.ImVec4(1.0, 1.0, 1.0, 1.0)},
                    {u8"Группирование >>", imgui.ImVec4(1.0, 1.0, 1.0, 1.0)},
                    {u8"Вращения >>", imgui.ImVec4(1.0, 1.0, 1.0, 1.0)},
                    {u8"Скопировать GLOBAL IDX", imgui.ImVec4(1.0, 0.85, 0.30, 1.0), nil, "F"}
                }
            end
            for index, entry in ipairs(actionText) do
                local keyLabel = entry[4] or tostring(index)
                imgui.TextColored(imgui.ImVec4(1.0, 1.0, 1.0, 1.0), "[" .. keyLabel .. "]")
                imgui.SameLine(0, 6)
                imgui.TextColored(entry[2], entry[1])
                if entry[3] then
                    imgui.SameLine(0, 0)
                    imgui.TextColored(imgui.ImVec4(1.0, 1.0, 1.0, 1.0), entry[3])
                end
            end
        imgui.End()
    end
)
