        imgui.Begin(u8"Выбрать группу для объекта #" .. tostring(objScanGroupPromptObjId or "?") .. u8"##objscangrpwin", closeGrp,
            imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoSavedSettings)

            imgui.Spacing()
            imgui.TextColored(accent4, u8"1. Ввести номер группы вручную:")
            imgui.PushItemWidth(180)
            if imgui.InputText(u8"##objscangrpnum", objScanGroupNumBuf, 8, imgui.InputTextFlags.CharsDecimal) then
                local typedNum = tonumber(ffi.string(objScanGroupNumBuf))
                if typedNum and typedNum >= 1 then
                    objScanSelectedGroup = typedNum
                end
            end
            imgui.PopItemWidth()
            imgui.SameLine(0, 10)
            imgui.TextColored(imgui.ImVec4(0.75, 0.75, 0.75, 1.0), u8"Выбрана группа: #" .. tostring(objScanSelectedGroup or 1))

            imgui.Spacing(); imgui.Separator(); imgui.Spacing()
            imgui.TextColored(accent4, u8"2. Или выберите группу из ячеек (1 - 100):")
            imgui.Spacing()

            local cols = 10
            local spacing = 4
            local availW = imgui.GetContentRegionAvail().x
            local cellW = math.floor((availW - spacing * (cols - 1)) / cols)
            local cellH = 25

            for i = 1, 100 do
                local isSelected = (tonumber(objScanSelectedGroup) == i)
                if isSelected then
                    imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.90))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(1.00))
                    imgui.PushStyleColor(imgui.Col.ButtonActive, accentColorA(1.00))
                else
                    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.19, 1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(0.55))
                    imgui.PushStyleColor(imgui.Col.ButtonActive, accentColorA(0.80))
                end

                if imgui.Button(tostring(i) .. "##grpcell_" .. i, imgui.ImVec2(cellW, cellH)) then
                    objScanSelectedGroup = i
                    imgui.StrCopy(objScanGroupNumBuf, tostring(i))
                end
                imgui.PopStyleColor(3)

                if i % cols ~= 0 then
                    imgui.SameLine(0, spacing)
                end
            end

            imgui.Spacing(); imgui.Separator(); imgui.Spacing()

            local btnW1 = math.floor((availW - 10) * 0.65)
            local btnW2 = availW - btnW1 - 10
            imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(1.00))
            if imgui.Button(u8"Применить группу #" .. tostring(objScanSelectedGroup or 1) .. u8"##objscangrpok", imgui.ImVec2(btnW1, 34)) then
                local num = ffi.string(objScanGroupNumBuf)
                if num == "" then num = tostring(objScanSelectedGroup or 1) end
                objScanSelectedGroup = tonumber(num) or 1
                if objScanGroupPromptObjId then
                    sendObjScanCommand("/gr " .. tostring(objScanGroupPromptObjId) .. " " .. tostring(num))
                    toast_text  = "Объект #" .. tostring(objScanGroupPromptObjId) .. " добавлен в группу #" .. tostring(num)
                    toast_text2 = ""
                    toast_tex   = nil
                    toast_timer = 150
                end
                objScanGroupPromptOpen = false
                sampSetCursorMode(0, false)
            end
            imgui.PopStyleColor(2)

            imgui.SameLine(0, 10)
            if imgui.Button(u8"Отмена##objscangrpcancel", imgui.ImVec2(btnW2, 34)) then
                objScanGroupPromptOpen = false
                sampSetCursorMode(0, false)
            end

        imgui.End()
        imgui.PopStyleVar()
        imgui.PopStyleColor(2)
        if not closeGrp[0] then
            objScanGroupPromptOpen = false
            sampSetCursorMode(0, false)
        end
    end
)
objScanGroupFrame.HideCursor = false
objScanGroupFrame.LockPlayer = false

function renderObjListContent(isEmbedded)
    local accent4 = accentColorA(1.0)
    local accentU32 = 0xFF000000 + accentColorHex()
    local suffix = isEmbedded and "_tab" or "_win"

    -- Верхняя панель поиска, выбора вида и обновления
    imgui.PushItemWidth(240)
    imgui.InputTextWithHint(u8"##objlistsearch" .. suffix, u8"Поиск по IDX (#), ID или названию...", objListSearchBuf, 128)
    imgui.PopItemWidth()
    imgui.SameLine(0, 10)
    if imgui.Checkbox(u8"Только на экране##objlistonscr" .. suffix, objListOnlyOnScreen) then
        refreshObjListFromLabels()
    end
    imgui.SameLine(0, 10)
    if imgui.Button(fa.ICON_REFRESH .. u8" Обновить##objlistref" .. suffix, imgui.ImVec2(115, 26)) then
        refreshObjListFromLabels()
    end

    -- Переключатель вида: Список / Сетка
    imgui.SameLine(0, 12)
    local isList = (objListViewMode == "list")
    if not isList then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.19, 1.0)) end
    if imgui.Button(fa.ICON_LIST .. u8" Список##objlistview_list" .. suffix, imgui.ImVec2(95, 26)) then
        objListViewMode = "list"
    end
    if not isList then imgui.PopStyleColor() end

    imgui.SameLine(0, 4)
    if isList then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.19, 1.0)) end
    if imgui.Button(fa.ICON_TH .. u8" Сетка##objlistview_grid" .. suffix, imgui.ImVec2(90, 26)) then
        objListViewMode = "grid"
    end
    if isList then imgui.PopStyleColor() end

    imgui.SameLine(0, 12)
    imgui.TextColored(imgui.ImVec4(0.80, 0.80, 0.80, 1.0), u8("Всего: " .. tostring(#objListItems)))

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    if #objListItems == 0 then
        local avail = imgui.GetContentRegionAvail()
        imgui.SetCursorPosY(imgui.GetCursorPosY() + math.max(20, avail.y * 0.35))
        local msg1 = u8"Карта сейчас не редактируется (лейблы объектов не обнаружены)."
        local msg2 = u8"Введите /map [ID карты], чтобы просмотреть объекты на карте."
        local tw1 = imgui.CalcTextSize(msg1).x
        local tw2 = imgui.CalcTextSize(msg2).x
        imgui.SetCursorPosX(math.max(16, (avail.x - tw1) * 0.5))
        imgui.TextColored(imgui.ImVec4(1.0, 0.78, 0.25, 1.0), msg1)
        imgui.Spacing()
        imgui.SetCursorPosX(math.max(16, (avail.x - tw2) * 0.5))
        imgui.TextColored(imgui.ImVec4(0.75, 0.75, 0.75, 1.0), msg2)
    else
        imgui.BeginChild(u8"##objlistgrid" .. suffix, imgui.ImVec2(0, 0), false)
            local q = cyrLower(ffi.string(objListSearchBuf))
            local availW = imgui.GetContentRegionAvail().x
            local dl = imgui.GetWindowDrawList()
            local removeIdx = nil

            if objListViewMode == "list" then
                -- РЕЖИМ 1: СПИСОК ВНИЗ (слева картинка + инфо, справа 3 кнопки)
                local rowW = availW - 4
                local rowH = 68
                for idx, item in ipairs(objListItems) do
                    local match = (q == "")
                        or tostring(item.id):find(q, 1, true)
                        or ("#" .. tostring(item.id)):find(q, 1, true)
                        or tostring(item.modelId):find(q, 1, true)
                        or item.modelName:lower():find(q, 1, true)
                    if match then
                        imgui.BeginGroup()
                            local p = imgui.GetCursorScreenPos()
                            dl:AddRectFilled(p, imgui.ImVec2(p.x + rowW, p.y + rowH), 0xFF1A1A20, 6)
                            dl:AddRect(p, imgui.ImVec2(p.x + rowW, p.y + rowH), 0x38FFFFFF, 6, 0, 1.0)

                            -- Превью слева
                            local imgW, imgH = 68, 52
                            local tex = getTex(item.modelId)
                            if tex then
                                dl:AddRectFilled(
                                    imgui.ImVec2(p.x + 8, p.y + 8),
                                    imgui.ImVec2(p.x + 8 + imgW, p.y + 8 + imgH),
                                    0xFFFFFFFF, 4)
                                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 8, p.y + 8))
                                imgui.Image(tex, imgui.ImVec2(imgW, imgH))
                            else
                                dl:AddRectFilled(
                                    imgui.ImVec2(p.x + 8, p.y + 8),
                                    imgui.ImVec2(p.x + 8 + imgW, p.y + 8 + imgH),
                                    0xFF282830, 4)
                                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 16, p.y + 26))
                                imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), u8"NO IMG")
                            end

                            -- Название и модель слева от центра
                            local textX = p.x + 8 + imgW + 14
                            imgui.SetCursorScreenPos(imgui.ImVec2(textX, p.y + 12))
                            imgui.TextColored(accent4, u8("IDX #" .. tostring(item.id)))
                            imgui.SameLine(0, 10)
                            imgui.TextColored(imgui.ImVec4(0.90, 0.90, 0.92, 1.0), u8("ID модели: #" .. tostring(item.modelId)))
                            if item.group then
                                imgui.SameLine(0, 10)
                                imgui.TextColored(imgui.ImVec4(0.75, 0.65, 1.0, 1.0), u8("(Группа #" .. tostring(item.group) .. ")"))
                            end

                            imgui.SetCursorScreenPos(imgui.ImVec2(textX, p.y + 36))
                            imgui.TextColored(imgui.ImVec4(0.65, 0.65, 0.70, 1.0), u8(item.modelName .. "   |   Дистанция: " .. tostring(item.dist) .. " м"))

                            -- Кнопки справа: Телепорт | Открыть информацию (/oinfo) | Удалить (/del)
                            local btnTpW   = 85
                            local btnDropW = 100
                            local btnInfoW = 120
                            local btnDelW  = 90
                            local btnH     = 32
                            local totalBtnsW = btnTpW + 8 + btnDropW + 8 + btnInfoW + 8 + btnDelW
                            local btnsX = p.x + rowW - totalBtnsW - 12
                            local btnsY = p.y + math.floor((rowH - btnH) * 0.5)

                            imgui.SetCursorScreenPos(imgui.ImVec2(btnsX, btnsY))
                            if imgui.Button(fa.ICON_LOCATION_ARROW .. u8"  ТП##list_tp_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(btnTpW, btnH)) then
                                sampSendChat("/gotoo " .. tostring(item.id))
                                toast_text  = "ТП к объекту #" .. tostring(item.id)
                                toast_text2 = "Модель: #" .. tostring(item.modelId) .. " (" .. item.modelName .. ")"
                                toast_tex   = nil
                                toast_timer = 130
                            end

                            imgui.SameLine(0, 8)
                            if imgui.Button(fa.ICON_ARROW_DOWN .. u8"  Пол##list_drop_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(btnDropW, btnH)) then
                                dropObjectToSurface(item.id, item.x, item.y, item.z)
                            end

                            imgui.SameLine(0, 8)
                            if imgui.Button(fa.ICON_INFO_CIRCLE .. u8"  Инфо##list_info_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(btnInfoW, btnH)) then
                                oinfoSilentPendingId = nil
                                oinfoSilentExpireTime = 0
                                sampSendChat("/oinfo " .. tostring(item.id))
                            end

                            imgui.SameLine(0, 8)
                            imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.52, 0.12, 0.12, 1.0))
                            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.70, 0.18, 0.18, 1.0))
                            imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(0.85, 0.22, 0.22, 1.0))
                            if imgui.Button(fa.ICON_TRASH .. u8" Удалить##list_del_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(btnDelW, btnH)) then
                                sampSendChat("/del " .. tostring(item.id))
                                toast_text  = "Удалён объект #" .. tostring(item.id)
                                toast_text2 = item.modelName
                                toast_tex   = nil
                                toast_timer = 130
                                removeIdx = idx
                            end
                            imgui.PopStyleColor(3)

                            imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + rowH))
                            imgui.Dummy(imgui.ImVec2(rowW, 0))
                        imgui.EndGroup()
                        imgui.Spacing()
                    end
                end
            else
                -- РЕЖИМ 2: СЕТКА КАРТОЧЕК
                local cardW = 180
                local cardH = 200
                local cols = math.max(1, math.floor(availW / (cardW + 10)))
                local col = 0
                for idx, item in ipairs(objListItems) do
                    local match = (q == "")
                        or tostring(item.id):find(q, 1, true)
                        or ("#" .. tostring(item.id)):find(q, 1, true)
                        or tostring(item.modelId):find(q, 1, true)
                        or item.modelName:lower():find(q, 1, true)
                    if match then
                        if col > 0 then imgui.SameLine(0, 10) end
                        imgui.BeginGroup()
                            local p = imgui.GetCursorScreenPos()
                            dl:AddRectFilled(p, imgui.ImVec2(p.x + cardW, p.y + cardH), 0xFF181820, 6)

                            -- Картинка сверху
                            local imgW, imgH = cardW - 16, 105
                            local tex = getTex(item.modelId)
                            if tex then
                                dl:AddRectFilled(
                                    imgui.ImVec2(p.x + 8, p.y + 8),
                                    imgui.ImVec2(p.x + 8 + imgW, p.y + 8 + imgH),
                                    0xFFFFFFFF, 4)
                                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 8, p.y + 8))
                                imgui.Image(tex, imgui.ImVec2(imgW, imgH))
                            else
                                dl:AddRectFilled(
                                    imgui.ImVec2(p.x + 8, p.y + 8),
                                    imgui.ImVec2(p.x + 8 + imgW, p.y + 8 + imgH),
                                    0xFF24242C, 4)
                                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + cardW * 0.5 - 24, p.y + 48))
                                imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), u8"NO IMG")
                            end

                            -- Бейдж IDX
                            local badge = u8("#" .. tostring(item.id))
                            local bSz = imgui.CalcTextSize(badge)
                            dl:AddRectFilled(
                                imgui.ImVec2(p.x + 12, p.y + 12),
                                imgui.ImVec2(p.x + 12 + bSz.x + 8, p.y + 12 + bSz.y + 4),
                                0xDD000000, 3)
                            dl:AddText(imgui.ImVec2(p.x + 16, p.y + 14), 0xFFFFFFFF, badge)

                            -- Бейдж группы
                            if item.group then
                                local grpBadge = u8("Гр #" .. tostring(item.group))
                                local gSz = imgui.CalcTextSize(grpBadge)
                                local gx = p.x + cardW - 12 - gSz.x - 8
                                dl:AddRectFilled(
                                    imgui.ImVec2(gx, p.y + 12),
                                    imgui.ImVec2(gx + gSz.x + 8, p.y + 12 + gSz.y + 4),
                                    0xDDAA3388, 3)
                                dl:AddText(imgui.ImVec2(gx + 4, p.y + 14), 0xFFFFFFFF, grpBadge)
                            end

                            -- Название модели
                            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 8, p.y + 118))
                            local nameTrimmed = item.modelName
                            if #nameTrimmed > 20 then nameTrimmed = nameTrimmed:sub(1, 18) .. ".." end
                            imgui.TextColored(imgui.ImVec4(0.92, 0.92, 0.94, 1.0), u8(nameTrimmed))

                            -- ID модели + дистанция
                            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 8, p.y + 138))
                            imgui.TextColored(imgui.ImVec4(0.60, 0.60, 0.65, 1.0), u8("ID: " .. tostring(item.modelId) .. "  |  " .. tostring(item.dist) .. "м"))

                            -- Кнопки внизу карточки
                            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 6, p.y + 168))
                            if imgui.Button(u8"ТП##g_tp_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(40, 22)) then
                                sampSendChat("/gotoo " .. tostring(item.id))
                                toast_text  = "ТП к объекту #" .. tostring(item.id)
                                toast_text2 = "Модель: #" .. tostring(item.modelId) .. " (" .. item.modelName .. ")"
                                toast_tex   = nil
                                toast_timer = 130
                            end

                            imgui.SameLine(0, 3)
                            if imgui.Button(fa.ICON_ARROW_DOWN .. "##g_drop_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(34, 22)) then
                                dropObjectToSurface(item.id, item.x, item.y, item.z)
                            end
                            if imgui.IsItemHovered() then imgui.SetTooltip(u8"Приземлить объект на пол") end

                            imgui.SameLine(0, 3)
                            if imgui.Button(u8"Инфо##g_info_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(46, 22)) then
                                oinfoSilentPendingId = nil
                                oinfoSilentExpireTime = 0
                                sampSendChat("/oinfo " .. tostring(item.id))
                            end

                            imgui.SameLine(0, 3)
                            imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.52, 0.12, 0.12, 1.0))
                            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.70, 0.18, 0.18, 1.0))
                            imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(0.85, 0.22, 0.22, 1.0))
                            if imgui.Button(u8"Удал.##g_del_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(52, 22)) then
                                sampSendChat("/del " .. tostring(item.id))
                                toast_text  = "Удалён объект #" .. tostring(item.id)
                                toast_text2 = item.modelName
                                toast_tex   = nil
                                toast_timer = 130
                                removeIdx = idx
                            end
                            imgui.PopStyleColor(3)

                            -- Невидимый клик по верхней части карточки (картинке) тоже телепортирует
                            imgui.SetCursorScreenPos(p)
                            if imgui.InvisibleButton("##objlistcard_" .. suffix .. "_" .. tostring(item.id), imgui.ImVec2(cardW, cardH - 32)) then
                                sampSendChat("/gotoo " .. tostring(item.id))
                                toast_text  = "Телепорт к объекту #" .. tostring(item.id)
                                toast_text2 = "Модель: #" .. tostring(item.modelId) .. " (" .. item.modelName .. ")"
                                toast_tex   = nil
                                toast_timer = 130
                            end
                            local hovered = imgui.IsItemHovered()
                            dl:AddRect(p, imgui.ImVec2(p.x + cardW, p.y + cardH), hovered and accentU32 or 0x44FFFFFF, 6, 0, hovered and 1.8 or 1.0)
                            if hovered then
                                imgui.SetTooltip(u8("ЛКМ — Телепортироваться к объекту #" .. tostring(item.id) .. "\nМодель: #" .. tostring(item.modelId) .. " (" .. item.modelName .. ")" .. (item.group and ("\nГруппа: #" .. tostring(item.group)) or "")))
                            end

                            imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + cardH))
                            imgui.Dummy(imgui.ImVec2(cardW, 0))
                        imgui.EndGroup()

                        col = col + 1
                        if col >= cols then
                            col = 0
                            imgui.Spacing()
                        end
                    end
                end
            end

            if removeIdx then
                table.remove(objListItems, removeIdx)
            end
        imgui.EndChild()
    end
end

objListFrame = imgui.OnFrame(
    function() return objListWinOpen[0] and not sampIsChatInputActive() and not sampIsDialogActive() end,
    function()
        resetTexCounter()
        local sw, sh = getScreenResolution()
        local accent4 = accentColorA(1.0)
        local accentU32 = 0xFF000000 + accentColorHex()

        -- Полноэкранное затемнение позади окна /objlist
        local dispW = math.max(sw, imgui.GetIO().DisplaySize.x) * 1.5
        local dispH = math.max(sh, imgui.GetIO().DisplaySize.y) * 1.5
        imgui.SetNextWindowPos(imgui.ImVec2(-100, -100), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(dispW, dispH), imgui.Cond.Always)
        imgui.SetNextWindowBgAlpha(0.75)
        imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0.0, 0.0, 0.0, 1.0))
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, 0.0)
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, 0.0)
        imgui.Begin(u8"##modalDimBackdropObjList", nil,
            imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize +
            imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollbar +
            imgui.WindowFlags.NoScrollWithMouse + imgui.WindowFlags.NoCollapse +
            imgui.WindowFlags.NoSavedSettings + imgui.WindowFlags.NoInputs +
            imgui.WindowFlags.NoFocusOnAppearing + imgui.WindowFlags.NoBringToFrontOnFocus)
        imgui.End()
        imgui.PopStyleVar(2)
        imgui.PopStyleColor()

        local winW = math.min(980, math.floor(sw * 0.86))
        local winH = math.min(700, math.floor(sh * 0.84))
        imgui.PushStyleColor(imgui.Col.TitleBgActive, accent4)
        imgui.PushStyleColor(imgui.Col.TitleBg, accentColorA(0.85))
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, 8.0)
        imgui.SetNextWindowSize(imgui.ImVec2(winW, winH), imgui.Cond.Always)
        imgui.SetNextWindowPos(imgui.ImVec2(sw / 2, sh / 2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))

        imgui.Begin(u8"Список объектов на карте (/objlist)##objlistwin", objListWinOpen,
            imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoSavedSettings)
            renderObjListContent(false)
        imgui.End()
        imgui.PopStyleVar()
        imgui.PopStyleColor(2)
        if not objListWinOpen[0] then
            sampSetCursorMode(0, false)
        end
    end
)
