-- Превью объекта при наборе /cr в чате
craPreviewId      = nil
craPreviewName    = nil
craPreviewObj     = nil
craPreviewEnabled = true

local function resolveCraQuery(q)
    q = (q or ""):match("^%s*(.-)%s*$")
    if q == "" then return nil end
    if q:match("^%d+$") then
        for _, o in ipairs(allObjects) do
            if o.id == q then return o.id, o.name, o end
        end
        return q, nil, nil
    end
    local ql = q:lower()
    for _, o in ipairs(allObjects) do
        if (o.name or ""):lower() == ql then return o.id, o.name, o end
    end
    for _, o in ipairs(allObjects) do
        if (o.name or ""):lower():find(ql, 1, true) then return o.id, o.name, o end
    end
    return nil
end

lua_thread.create(function()
    while true do
        wait(100)
        if sampIsChatInputActive() then
            local ok, text = pcall(sampGetChatInputText)
            if ok and text then
                local arg = text:match("^/[cC][rR]%s+(.+)")
                if arg then
                    craPreviewId, craPreviewName, craPreviewObj = resolveCraQuery(arg)
                else
                    craPreviewId, craPreviewName, craPreviewObj = nil, nil, nil
                end
            end
        else
            craPreviewId, craPreviewName, craPreviewObj = nil, nil, nil
        end
    end
end)

