local toastFrame
toastFrame = imgui.OnFrame(
    function() return toast_timer > 0 end,
    function()
        toastFrame.HideCursor = not winOpen[0]

        -- фиксируем стартовое значение таймера конкретно ЭТОГО показа уведомления,
        -- чтобы плавное появление считалось относительно него, а не хардкод-константы 120
        if not toast_active then
            toast_active = true
            toast_timer_max = toast_timer
        end

        toast_timer = toast_timer - 1
        if toast_timer <= 0 and toast_tex then
            pcall(imgui.ReleaseTexture, toast_tex)
            toast_tex = nil
        end

        if toast_timer <= 0 then
            toast_preencoded = false
            toast_active = false
        end

        local FADE = 15.0
        local alpha
        if toast_timer_max and toast_timer > toast_timer_max - FADE then
            alpha = (toast_timer_max - toast_timer) / FADE
        elseif toast_timer < FADE then
            alpha = toast_timer / FADE
        else
            alpha = 1.0
        end
        alpha = math.max(0.0, math.min(1.0, alpha))

        local titleStr = safeU8(toast_text or "")
        local subStr   = safeU8(toast_text2 or "")

        local tex = getLogoTex()
        local iconW = tex and 68.0 or 20.0
        local headerW = imgui.CalcTextSize(safeU8("TMT Mapper")).x
        local titleW  = imgui.CalcTextSize(titleStr).x
        local subW    = (subStr ~= "") and imgui.CalcTextSize(subStr).x or 0.0

        local maxContentW = math.max(headerW, math.max(titleW, subW))
        local winW = math.max(360.0, math.min(560.0, iconW + maxContentW + 36.0))
        local contentAreaW = winW - iconW - 24.0

        local subLines = (subStr ~= "") and math.max(1, math.ceil(subW / contentAreaW)) or 0
        local titleLines = math.max(1, math.ceil(titleW / contentAreaW))
        local winH = math.max(82.0, 36.0 + titleLines * 18.0 + subLines * 17.0 + 10.0)
        local slide = (1.0 - alpha) * 40.0

        imgui.SetNextWindowPos(imgui.ImVec2(sw - winW - 16.0 + slide, sh - winH - 16.0), imgui.Cond.Always)
        imgui.SetNextWindowSize(imgui.ImVec2(winW, winH), imgui.Cond.Always)
        imgui.SetNextWindowBgAlpha(0.95 * alpha)
        imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, alpha)
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowBorderSize, 0.0)
        imgui.PushStyleVarFloat(imgui.StyleVar.WindowRounding, 8.0)
        imgui.Begin(safeU8("##toast"), nil,
            imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize +
            imgui.WindowFlags.NoScrollbar + imgui.WindowFlags.NoInputs +
            imgui.WindowFlags.NoNav + imgui.WindowFlags.NoBringToFrontOnFocus +
            imgui.WindowFlags.NoSavedSettings)

            if tex then
                local logoH = 50.0
                local logoY = math.floor((winH - logoH) * 0.5)
                imgui.SetCursorPos(imgui.ImVec2(12, logoY))
                imgui.Image(tex, imgui.ImVec2(50, logoH))
                imgui.SetCursorPos(imgui.ImVec2(70, 9))
            else
                imgui.SetCursorPos(imgui.ImVec2(14, 9))
            end

            imgui.BeginGroup()
                imgui.TextColored(accentColor(), safeU8("TMT Mapper"))
                imgui.Spacing()
                imgui.TextColored(imgui.ImVec4(0.95, 0.95, 0.95, 1.0), titleStr)
                if subStr ~= "" then
                    imgui.PushTextWrapPos(imgui.GetCursorPosX() + contentAreaW)
                    imgui.TextColored(imgui.ImVec4(0.68, 0.68, 0.68, 1.0), subStr)
                    imgui.PopTextWrapPos()
                end
            imgui.EndGroup()

        imgui.End()
        imgui.PopStyleVar(3)
    end
)
toastFrame.HideCursor = true
toastFrame.LockPlayer = false

