-- 3D-подсветка (ESP) объектов, захваченных в префаб
-- 3D-подсветка (ESP) объектов, входящих в захват префаба
local prefabCaptureEspFrame
prefabCaptureEspFrame = imgui.OnFrame(
    function()
        return (prefabCaptureOpen or (activeTab == 13 and #prefabCapturedList > 0)) and (prefabCaptureEspEnabled[0] == true) and not sampIsChatInputActive()
    end,
    function(self)
        if not prefabCapturedList or #prefabCapturedList == 0 then return end

        local altHeld = isKeyDown(0x12) -- VK_MENU (ALT)
        if altHeld then
            if self then self.HideCursor = false; self.LockPlayer = true end
            if prefabCaptureEspFrame then prefabCaptureEspFrame.HideCursor = false; prefabCaptureEspFrame.LockPlayer = true end
        elseif not winOpen[0] then
            if self then self.HideCursor = true; self.LockPlayer = false end
            if prefabCaptureEspFrame then prefabCaptureEspFrame.HideCursor = true; prefabCaptureEspFrame.LockPlayer = false end
        end

        local drawList = imgui.GetBackgroundDrawList()
        local sw, sh = getScreenResolution()
        local mp = imgui.GetMousePos()

        -- Плашка подсказки при зажатии ALT
        if altHeld then
            local hintText = u8"РЕЖИМ ВЫБОРА: Наведите курсор и нажмите ПКМ на объект для исключения/возврата"
            local tw = imgui.CalcTextSize(hintText).x
            local hx = (sw - tw) / 2
            drawList:AddRectFilled(imgui.ImVec2(hx - 14, 18), imgui.ImVec2(hx + tw + 14, 46), 0xEE111E15, 5.0)
            drawList:AddRect(imgui.ImVec2(hx - 14, 18), imgui.ImVec2(hx + tw + 14, 46), 0xFF2ECC71, 5.0, 15, 1.5)
            drawList:AddText(imgui.ImVec2(hx, 24), 0xFFFFFFFF, hintText)
        end

        local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
        local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
        local fwdX, fwdY, fwdZ = 0, 1, 0
        if okCam and okAt and camX and atX then
            fwdX, fwdY, fwdZ = atX - camX, atY - camY, atZ - camZ
        end

        local px, py, pz = 0, 0, 0
        local pFwdX, pFwdY = 0, 1
        local hasPed = PLAYER_PED and doesCharExist(PLAYER_PED)
        if hasPed then
            px, py, pz = getCharCoordinates(PLAYER_PED)
            local heading = getCharHeading(PLAYER_PED)
            local rad = math.rad(-heading)
            pFwdX = math.sin(rad)
            pFwdY = math.cos(rad)
        end

        -- 1. Сбор видимых кандидатов
                -- 1. Сбор только АКТИВНЫХ кандидатов (исключенные полностью исчезают с экрана!)
        local candidates = {}
        for idx, item in ipairs(prefabCapturedList) do
            if item.selected then
                local toCamX = item.x - (camX or px)
                local toCamY = item.y - (camY or py)
                local toCamZ = item.z - (camZ or pz)
                local dotCam = fwdX * toCamX + fwdY * toCamY + fwdZ * toCamZ

                local pedFwdOk = true
                if hasPed then
                    local dx = item.x - px
                    local dy = item.y - py
                    local locFwd = dx * pFwdX + dy * pFwdY
                    if locFwd < -0.5 then
                        pedFwdOk = false
                    end
                end

                if dotCam > 0 and pedFwdOk then
                    local sx, sy = convert3DCoordsToScreen(item.x, item.y, item.z)
                    if sx and sy and sx >= 0 and sx <= sw and sy >= 0 and sy <= sh then
                        table.insert(candidates, {
                            item = item,
                            sx = sx,
                            sy = sy,
                            dist = item.dist or 0
                        })
                    end
                end
            end
        end

        -- 2. Определение активного объекта под курсором
        local bestCandidate = nil
        local bestDist = 999999
        if altHeld or winOpen[0] then
            for _, c in ipairs(candidates) do
                local distMouse = math.sqrt((mp.x - c.sx)^2 + (mp.y - c.sy)^2)
                local isHover = (distMouse <= 22)
                if not isHover then
                    local bw = 150
                    local bh = 24
                    local bx = c.sx + 10
                    local by = c.sy - 12
                    if bx + bw > sw - 10 then bx = c.sx - bw - 10 end
                    if mp.x >= bx and mp.x <= bx + bw and mp.y >= by and mp.y <= by + bh then
                        isHover = true
                    end
                end
                if isHover and c.dist < bestDist then
                    bestDist = c.dist
                    bestCandidate = c
                end
            end
        end

        -- 3. Обработка клика ПКМ с защитой от двойного срабатывания (debounce 350мс)
        local now = os.clock()
        local rmbClicked = imgui.IsMouseClicked(1) or isKeyJustPressed(0x02)
        if bestCandidate and rmbClicked and (now - lastPrefabRmbTime > 0.35) then
            lastPrefabRmbTime = now
            local it = bestCandidate.item
            it.selected = false -- Сразу исключаем! Объект мгновенно пропадает с экрана
            sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Объект {FF9326}#%s{FFFFFF} (%s) {E74C3C}исключен из префаба{FFFFFF}.", tostring(it.objId), it.modelName or tostring(it.modelId)), -1)
            bestCandidate = nil
        end

        -- 4. Отрисовка ESP элементов (только для оставшихся активных объектов)
        for _, c in ipairs(candidates) do
            local item = c.item
            local sx, sy = c.sx, c.sy
            local isHovered = (bestCandidate and bestCandidate.item == item)

            local colDot = isHovered and 0xFF00FFFF or 0xFF00FF88
            local colRing = isHovered and 0xFF00FFFF or 0xFFFFFFFF
            local colBox = isHovered and 0xFF00FFFF or 0xEE22CC55
            local colBg  = isHovered and 0xEE112A22 or 0xDD112211

            drawList:AddCircleFilled(imgui.ImVec2(sx, sy), isHovered and 6.5 or 5.0, colDot)
            drawList:AddCircle(imgui.ImVec2(sx, sy), isHovered and 9.0 or 7.0, colRing, 12, 1.5)

            if isHovered then
                local badgeW = 185
                local badgeH = 38
                local bx = sx + 10
                local by = sy - 19
                if bx + badgeW > sw - 10 then bx = sx - badgeW - 10 end

                drawList:AddRectFilled(imgui.ImVec2(bx, by), imgui.ImVec2(bx + badgeW, by + badgeH), colBg, 4.0)
                drawList:AddRect(imgui.ImVec2(bx, by), imgui.ImVec2(bx + badgeW, by + badgeH), colBox, 4.0, 15, 2.0)
                drawList:AddText(imgui.ImVec2(bx + 6, by + 3), 0xFFFFFFFF, u8(string.format("#%s: %s (%.1fм)", tostring(item.objId), item.modelName or tostring(item.modelId), item.dist or 0)))
                drawList:AddText(imgui.ImVec2(bx + 6, by + 19), 0xFFE74C3C, u8"[ПКМ] Исключить из префаба")
            else
                -- Аккуратный компактный бейдж
                local badgeW = 145
                local badgeH = 22
                local bx = sx + 10
                local by = sy - 11
                if bx + badgeW > sw - 10 then bx = sx - badgeW - 10 end

                drawList:AddRectFilled(imgui.ImVec2(bx, by), imgui.ImVec2(bx + badgeW, by + badgeH), colBg, 4.0)
                drawList:AddRect(imgui.ImVec2(bx, by), imgui.ImVec2(bx + badgeW, by + badgeH), colBox, 4.0, 15, 1.2)
                local textStr = string.format("#%s: %s", tostring(item.objId), item.modelName or tostring(item.modelId))
                if #textStr > 16 then textStr = textStr:sub(1, 15) .. ".." end
                drawList:AddText(imgui.ImVec2(bx + 6, by + 4), 0xFFFFFFFF, u8(textStr))
                drawList:AddText(imgui.ImVec2(bx + badgeW - 38, by + 4), 0xFF88FF88, u8(string.format("%.1fм", item.dist or 0)))
            end
        end
    end
)
prefabCaptureEspFrame.HideCursor = true
prefabCaptureEspFrame.LockPlayer = false

local catImgCache = {}
local catImgFailed = {}

local function getCatImg(filename)
    if catImgCache[filename] then return catImgCache[filename] end
    if catImgFailed[filename] then return nil end
    local path = CAT_IMG_DIR .. filename
    if not doesFileExist(path) then catImgFailed[filename] = true; return nil end
    local ok, t = pcall(imgui.CreateTextureFromFile, path)
    if ok and t then catImgCache[filename] = t; return t end
    catImgFailed[filename] = true
    return nil
end

local function renderTabCategories()
    imgui.Spacing()
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint(u8"##catsearch", u8"Поиск категории или интерьера...", catSearchBuf, 128)
    imgui.PopItemWidth()
    imgui.Spacing()

    -- ===== Переключатель режима: GTA:SA / SA-MP =====
    local availBtnW = imgui.GetContentRegionAvail().x
    local btnW = math.floor((availBtnW - 10) / 2)
    local btnH = 36

    local isGta = (catGameMode == 1)
    local isSamp = (catGameMode == 2)

    imgui.PushStyleVarFloat(imgui.StyleVar.FrameRounding, 6.0)

    -- Кнопка GTA-SA
    if isGta then
        imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.40))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(0.55))
        imgui.PushStyleColor(imgui.Col.ButtonActive, accentColorA(0.70))
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1, 1, 1, 1))
    else
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.16, 0.8))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.24, 0.24, 0.24, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(0.30, 0.30, 0.30, 1.0))
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.7, 0.7, 0.7, 1.0))
    end

    local gtaTotalCount = gtaCatCounts[0] or 14064
    local sampTotalCount = sampCatCounts[0] or 1435

    if imgui.Button(fa.ICON_GLOBE .. u8"  GTA-SA объекты (" .. tostring(gtaTotalCount) .. ")##modeGta", imgui.ImVec2(btnW, btnH)) then
        if catGameMode ~= 1 then
            catGameMode = 1
            objCategories = gtaSaCategories
            catCounts = gtaCatCounts
            activeCatFilter = 0
            activeInterior = nil
            applyFilter()
        end
    end
    imgui.PopStyleColor(4)

    imgui.SameLine(0, 10)

    -- Кнопка SA-MP
    if isSamp then
        imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.40))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(0.55))
        imgui.PushStyleColor(imgui.Col.ButtonActive, accentColorA(0.70))
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1, 1, 1, 1))
    else
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.16, 0.8))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.24, 0.24, 0.24, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(0.30, 0.30, 0.30, 1.0))
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.7, 0.7, 0.7, 1.0))
    end

    if imgui.Button(fa.ICON_CUBES .. u8"  SA-MP объекты (" .. tostring(sampTotalCount) .. ")##modeSamp", imgui.ImVec2(btnW, btnH)) then
        if catGameMode ~= 2 then
            catGameMode = 2
            objCategories = sampCategories
            catCounts = sampCatCounts
            activeCatFilter = 0
            activeInterior = nil
            applyFilter()
        end
    end
    imgui.PopStyleColor(4)

    -- ===== Широкая кнопка "Интерьеры" =====
    imgui.Spacing()
    local isInteriors = (catGameMode == 3)
    if isInteriors then
        imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.40))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColorA(0.55))
        imgui.PushStyleColor(imgui.Col.ButtonActive, accentColorA(0.70))
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1, 1, 1, 1))
    else
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16, 0.16, 0.16, 0.8))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.24, 0.24, 0.24, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonActive, imgui.ImVec4(0.30, 0.30, 0.30, 1.0))
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.85, 0.85, 0.85, 1.0))
    end

    local intTotalCount = #interiorsList
    if imgui.Button(fa.ICON_BUILDING .. u8"  ИНТЕРЬЕРЫ GTA:SA (" .. tostring(intTotalCount) .. u8" интерьеров)##modeInteriors", imgui.ImVec2(-1, 38)) then
        if catGameMode ~= 3 then
            catGameMode = 3
        else
            catGameMode = 1
            objCategories = gtaSaCategories
            catCounts = gtaCatCounts
            activeCatFilter = 0
            activeInterior = nil
            applyFilter()
        end
    end
    imgui.PopStyleColor(4)
    imgui.PopStyleVar()

    imgui.Spacing()
    imgui.Separator()
    imgui.Spacing()

    local catQuery = cyrLower(ffi.string(catSearchBuf))
    local dl = imgui.GetWindowDrawList()

    if catGameMode == 3 then
        -- ===== РЕЖИМ ПРОСМОТРА ИНТЕРЬЕРОВ =====
        local intQuery = cyrLower(ffi.string(catSearchBuf))
        local PAD     = 10
        local avail   = imgui.GetContentRegionAvail().x
        local minCell = 195
        local cols    = math.max(2, math.floor((avail + PAD) / (minCell + PAD)))
        local cellW   = (avail - (cols - 1) * PAD) / cols
        local col     = 0

        for idx, item in ipairs(interiorsList) do
            local matchName = (intQuery == "") or cyrLower(item.name or ""):find(intQuery, 1, true) or cyrLower(item.meta or ""):find(intQuery, 1, true) or cyrLower(item.slug or ""):find(intQuery, 1, true)
            if matchName then
                if col >= cols then
                    col = 0
                    imgui.Spacing()
                end
                if col > 0 then imgui.SameLine(0, PAD) end

                local w = cellW
                local h = 155
                local imgH = 92

                imgui.BeginGroup()
                    local p = imgui.GetCursorScreenPos()

                    dl:AddRectFilled(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + w, p.y + h),
                        0xFF000000 + cardBgHex(), 10)

                    local tex = getInteriorImg(item.img)
                    if tex then
                        imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y))
                        imgui.Image(tex, imgui.ImVec2(w, imgH))
                    end

                    imgui.SetCursorScreenPos(p)
                    imgui.InvisibleButton("##intcard" .. idx, imgui.ImVec2(w, h))
                    if imgui.IsItemClicked(0) then
                        activeInterior = item
                        activeCatFilter = 0
                        imgui.StrCopy(searchBuf, '')
                        applyFilter()
                        SwitchTab(0)
                    end
                    local hovered = imgui.IsItemHovered()

                    dl:AddRectFilled(imgui.ImVec2(p.x, p.y + imgH), imgui.ImVec2(p.x + w, p.y + h), 0xEE000000 + cardBgHex(), 10)

                    if hovered then
                        dl:AddRectFilled(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + w, p.y + h), 0x15FFFFFF, 10)
                        dl:AddRect(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + w, p.y + h), 0xAA000000 + accentColorHex(), 10)
                    else
                        dl:AddRect(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + w, p.y + h), 0x33FFFFFF, 10)
                    end

                    dl:PushClipRect(imgui.ImVec2(p.x + 6, p.y), imgui.ImVec2(p.x + w - 6, p.y + h), true)
                    dl:AddText(imgui.ImVec2(p.x + 8, p.y + h - 58), 0xFFFFFFFF, item.name or "")
                    dl:AddText(imgui.ImVec2(p.x + 8, p.y + h - 40), 0x99FFFFFF, item.meta or "")
                    dl:AddText(imgui.ImVec2(p.x + 8, p.y + h - 22), 0xFF000000 + accentColorHex(), tostring(#(item.models or {})) .. u8" моделей ->")
                    dl:PopClipRect()
                imgui.EndGroup()

                col = col + 1
            end
        end
        return
    end

    imgui.Spacing()

    -- ===== Плитки категорий одинакового размера =====
    local PAD     = 10
    local avail   = imgui.GetContentRegionAvail().x
    local minCell = 165 -- минимальная ширина плитки
    local cols    = math.max(2, math.floor((avail + PAD) / (minCell + PAD)))
    local cellW   = (avail - (cols - 1) * PAD) / cols -- растягиваем плитки, чтобы ряд занимал всю ширину без остатка
    local col     = 0

    for i, cat in ipairs(objCategories) do
        if catQuery == "" or cyrLower(cat.name or ""):find(catQuery, 1, true) then
            if col >= cols then
                col = 0
                imgui.Spacing()
            end
            if col > 0 then imgui.SameLine(0, PAD) end

            local w    = cellW
            local h    = 140
            local imgH = 84
            local count    = catCounts[i] or 0
            local isActive = (activeCatFilter == i)

            imgui.BeginGroup()
                local p = imgui.GetCursorScreenPos()

                dl:AddRectFilled(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + w, p.y + h),
                    0xFF000000 + cardBgHex(), 10)

                local tex = getCatImg(cat.img or "")
                if tex then
                    imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y))
                    imgui.Image(tex, imgui.ImVec2(w, imgH))
                end

                imgui.SetCursorScreenPos(p)
                imgui.InvisibleButton("##catcard" .. i, imgui.ImVec2(w, h))
                if imgui.IsItemClicked(0) then
                    activeCatFilter = i
                    imgui.StrCopy(searchBuf, '')
                    applyFilter()
                    SwitchTab(0)
                end
                local hovered = imgui.IsItemHovered()

                -- затемнение снизу картинки под текст
                dl:AddRectFilled(imgui.ImVec2(p.x, p.y + imgH - 26), imgui.ImVec2(p.x + w, p.y + imgH), 0x99000000, 0)
                dl:AddRectFilled(imgui.ImVec2(p.x, p.y + imgH), imgui.ImVec2(p.x + w, p.y + h), 0xEE000000 + cardBgHex(), 10)

                if isActive then
                    dl:AddRect(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + w, p.y + h), 0xCC000000 + accentColorHex(), 10)
                elseif hovered then
                    dl:AddRectFilled(imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + w, p.y + h), 0x12FFFFFF, 10)
                end

                dl:PushClipRect(imgui.ImVec2(p.x + 8, p.y), imgui.ImVec2(p.x + w - 8, p.y + h), true)
                dl:AddText(imgui.ImVec2(p.x + 10, p.y + h - 44), 0xFFFFFFFF, cat.name)
                dl:AddText(imgui.ImVec2(p.x + 10, p.y + h - 22), 0xB0FFFFFF, count .. u8" объектов")
                dl:PopClipRect()
            imgui.EndGroup()

            col = col + 1
        end
    end
end

function renderTabCatalog()
    imgui.Indent(10)
    imgui.Spacing()
    imgui.Spacing()
    if inspectPickMode then
        imgui.TextColored(imgui.ImVec4(0.2,0.9,0.2,1), u8"Выберите объект для осмотра — кликните по картинке")
        imgui.SameLine()
        if imgui.SmallButton(u8"Отмена##inspcancelpick") then
            inspectPickMode = false
        end
        imgui.Spacing()
    end
    -- Поиск с иконкой лупы
imgui.TextColored(imgui.ImVec4(0.8, 0.8, 0.8, 1.0), fa.ICON_SEARCH)
imgui.SameLine(nil, 5)
imgui.PushItemWidth(250)
if imgui.InputTextWithHint(u8"##search_obj", u8"Название объекта или ID", searchBuf, 128) then
    applyFilter()
end
imgui.PopItemWidth()

imgui.SameLine(nil, 30) -- Отступ между поиском и сортировкой

-- Сортировка (выпадающий список с иконками)
imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), fa.ICON_FILTER .. u8" Сортировка:")
imgui.SameLine(nil, 5)
imgui.PushItemWidth(210)
local sortItems = {
    fa.ICON_SORT_NUMERIC_ASC .. u8" По ID",
    fa.ICON_SORT_ALPHA_ASC .. u8" По алфавиту (А-Я)",
    fa.ICON_SORT_ALPHA_DESC .. u8" По алфавиту (Я-А)",
    fa.ICON_SORT_AMOUNT_DESC .. u8" Сначала большие",
    fa.ICON_SORT_AMOUNT_ASC .. u8" Сначала маленькие"
}

-- Рисуем красивый выпадающий список (Combo)
if imgui.BeginCombo("##sortCombo", sortItems[sortMode + 1]) then
    for i, name in ipairs(sortItems) do
        local is_selected = (sortMode == (i - 1))
        if imgui.Selectable(name, is_selected) then
            sortMode = i - 1
            applyFilter() -- Применяем фильтр при выборе
        end
        if is_selected then
            imgui.SetItemDefaultFocus()
        end
    end
    imgui.EndCombo()
end
imgui.PopItemWidth()
    imgui.SameLine(nil, 20) -- держим метрику на одной линии с поиском/сортировкой
    -- переключатель метрики (в стиле сортировки)
    imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), fa.ICON_ARROWS .. u8" Метрика:")
    imgui.SameLine(nil, 5)
    imgui.PushItemWidth(150)
    local metricKeys   = {"radius", "width", "height"}
    local metricLabels = {radius = u8"Радиус (R)", width = u8"Ширина (W)", height = u8"Высота (H)"}
    if imgui.BeginCombo("##metricCombo", metricLabels[sizeMetric]) then
        for _, key in ipairs(metricKeys) do
            local is_selected = (sizeMetric == key)
            if imgui.Selectable(metricLabels[key], is_selected) then
                sizeMetric = key
                applyFilter()
            end
            if is_selected then
                imgui.SetItemDefaultFocus()
            end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()
    if imgui.IsItemHovered() then
        imgui.SetTooltip(u8"По какому размеру объекта фильтровать/сортировать")
    end
    imgui.Spacing()
    imgui.Separator()
    imgui.Spacing()

    local total      = #shownObjects
    local totalPages = math.max(1, math.ceil(total / PAGE_SIZE))
    if currentPage > totalPages then currentPage = totalPages end
    local si = (currentPage - 1) * PAGE_SIZE + 1
    local ei = math.min(currentPage * PAGE_SIZE, total)

    imgui.Text(u8"Стр. " .. currentPage .. " / " .. totalPages .. u8"   (всего: " .. total .. ")")
    imgui.SameLine()
    if imgui.ArrowButton("##pv", imgui.Dir.Left) then
        if currentPage > 1 then currentPage = currentPage - 1 end
    end
    if imgui.IsItemHovered() then
        imgui.SetTooltip(u8"Страница назад")
    end
    imgui.SameLine(0, 2)
    if imgui.ArrowButton("##nx", imgui.Dir.Right) then
        if currentPage < totalPages then currentPage = currentPage + 1 end
    end
    if imgui.IsItemHovered() then
        imgui.SetTooltip(u8"Страница вперёд")
    end
    imgui.SameLine()
    imgui.Text(u8"  Перейти к странице:")
    imgui.SameLine()
    imgui.PushItemWidth(60)
    if imgui.InputText(u8"##gp", gotoPageBuf, 8, imgui.InputTextFlags.EnterReturnsTrue) then
        local n = tonumber(ffi.string(gotoPageBuf))
        if n then currentPage = math.max(1, math.min(math.floor(n), totalPages)) end
        imgui.StrCopy(gotoPageBuf, '')
    end
    imgui.PopItemWidth()
    imgui.SameLine()
    if imgui.Button((fa.ICON_REFRESH or "") .. u8" Перезагрузить страницу##reload_page") then
        for i = si, ei do
            local obj = shownObjects[i]
            if obj and obj.id then
                if textures[obj.id] then
                    pcall(imgui.ReleaseTexture, textures[obj.id])
                    textures[obj.id] = nil
                end
                texFailed[obj.id] = nil
                texLoadTimes[obj.id] = nil
                texLastUsed[obj.id] = nil
            end
        end
    end
    if imgui.IsItemHovered() then
        imgui.SetTooltip(u8"Сбросить и заново прогрузить картинки на текущей странице")
    end
    imgui.SameLine()

    -- "Недавние объекты" — прижимаем к правому краю этой же строки
    local recentBtnW = 160
    local curX   = imgui.GetCursorPosX()
    local availX = imgui.GetContentRegionAvail().x
    if availX > recentBtnW then
        imgui.SetCursorPosX(curX + availX - recentBtnW)
    end
    if imgui.Button(fa.ICON_HISTORY .. u8" Недавние объекты##recent_btn", imgui.ImVec2(recentBtnW, 0)) then
        SwitchTab(8)
        return
    end

    if activeInterior or catGameMode == 2 or activeCatFilter > 0 then
        imgui.Spacing()
        if activeInterior then
            imgui.TextColored(accentColorA(1.0), fa.ICON_BUILDING .. "  " .. u8"Интерьер: " .. activeInterior.name .. " (" .. tostring(#(activeInterior.models or {})) .. u8" моделей)")
        else
            local catName = (activeCatFilter > 0 and objCategories[activeCatFilter] and objCategories[activeCatFilter].name) or u8"Все объекты"
            local modeName = (catGameMode == 2) and u8"SA-MP" or u8"GTA:SA"
            imgui.TextColored(accentColorA(1.0), fa.ICON_TAG .. "  " .. u8"Категория: " .. catName .. " (" .. modeName .. ")")
        end
        imgui.SameLine()
        if imgui.SmallButton(fa.ICON_TIMES .. u8" Сбросить фильтр##clearCatFilter") then
            activeInterior = nil
            activeCatFilter = 0
            catGameMode = 1
            objCategories = gtaSaCategories
            catCounts = gtaCatCounts
            applyFilter()
        end
    end

    imgui.Separator()
    imgui.Spacing()

    imgui.BeginChild(u8"##gr", imgui.ImVec2(0, 0), false)
        local PAD         = 10
        local scrollbarW  = (imgui.GetStyle() and imgui.GetStyle().ScrollbarSize) or 16
        local SAFEMARGIN  = scrollbarW + 10
        local avail   = imgui.GetContentRegionAvail().x
        local availY  = imgui.GetContentRegionAvail().y
        local CELL    = catalogImgSize
        local cols    = math.max(1, math.floor((avail - SAFEMARGIN + PAD) / (CELL + PAD)))
        local col     = 0
        local bh0     = CELL - 40

        local textLineH = imgui.GetTextLineHeight()
        local fixedRowH = bh0 + 20 + textLineH + 6

        if fixedRowH > 0 and availY > 0 then
            local rows = math.max(1, math.floor((availY + PAD + fixedRowH * 0.25) / fixedRowH))
            local newPageSize = rows * cols
            if newPageSize ~= PAGE_SIZE then
                if pageSizePending == newPageSize then
                    pageSizeStableCount = pageSizeStableCount + 1
                    if pageSizeStableCount >= 2 then
                        PAGE_SIZE = newPageSize
                        totalPages = math.max(1, math.ceil(total / PAGE_SIZE))
                        if currentPage > totalPages then currentPage = totalPages end
                        si = (currentPage - 1) * PAGE_SIZE + 1
                        ei = math.min(currentPage * PAGE_SIZE, total)
                        pageSizePending = nil
                        pageSizeStableCount = 0
                    end
                else
                    pageSizePending = newPageSize
                    pageSizeStableCount = 1
                end
            else
                pageSizePending = nil
                pageSizeStableCount = 0
            end
        end

        for i = si, ei do
            local obj = shownObjects[i]
            if not obj then break end
            if col > 0 then imgui.SameLine(0, PAD) end
            imgui.BeginGroup()
                local tex   = getTex(obj.id)
                local bw    = CELL
                local bh    = CELL - 40
                local isFav = favorites[obj.id]
                if tex then
                    local texAlpha = 1.0
                    if tabAnimationsEnabled[0] and texLoadTimes[obj.id] then
                        texAlpha = math.min(1.0, (os.clock() - texLoadTimes[obj.id]) / 0.18)
                    end
                    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, texAlpha)
                    imgui.Image(tex, imgui.ImVec2(bw, bh))
                    imgui.PopStyleVar()
                    if imgui.IsItemClicked(0) then
                        if inspectPickMode then
                            inspectPickMode = false
                            startInspect({id = obj.id, name = obj.name})
                        else
                            selectedObj = obj
                        end
                    end
                    if imgui.IsItemHovered() then
    imgui.BeginTooltip()
        imgui.Image(tex, imgui.ImVec2(120, 120))
        imgui.Spacing()
        imgui.TextColored(accentColor(), obj.name or u8"Без имени")
        imgui.Separator()
        imgui.Spacing()

        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"ID:")
        imgui.SameLine(80)
        imgui.Text(tostring(obj.id))

        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"Ширина:")
        imgui.SameLine(80)
        imgui.Text(string.format("%.2f", obj.width or 0))

        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"Высота:")
        imgui.SameLine(80)
        imgui.Text(string.format("%.2f", obj.height or 0))

        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"Радиус:")
        imgui.SameLine(80)
        imgui.Text(string.format("%.2f", obj.radius or 0))
    imgui.EndTooltip()
end
                    if imgui.IsItemClicked(1) then
                        ctxObj = obj
                        ctxPos = {x = imgui.GetMousePos().x, y = imgui.GetMousePos().y}
                    end
                    if imgui.IsItemClicked(2) then
                        setClipboardText(obj.id)
                        if notifyCopyIdEnabled then
                            toast_text  = "ID скопирован: " .. obj.id
                            toast_text2 = obj.name
                            toast_timer = 150
                            toast_tex = tex -- текстура уже загружена и закэширована чуть выше (getTex), незачем читать файл с диска ещё раз
                        end
                    end
                    if imgui.Button(u8"Создать##cr" .. obj.id, imgui.ImVec2(bw, 20)) then
                        if inspectPickMode then
                            inspectPickMode = false
                            startInspect({id = obj.id, name = obj.name})
                        elseif sceneSpawnPickMode then
                            if (obj.radius or 0) > 15 then
                                toast_text  = "Слишком большой объект"
                                toast_text2 = "Радиус " .. string.format("%.1f", obj.radius or 0) .. " (лимит редактора — 15)"
                                toast_tex   = nil
                                toast_timer = 150
                            else
                                sceneSpawnObject(obj)
                                sceneShowFullCatalog = false
                                sceneSpawnPickMode   = false
                                applyFilter()
                            end
                        else
                            addToRecent(obj); sampSendChat("/cr " .. obj.id)
                            winOpen[0] = false
                        end
                    end
                else
                    if imgui.Button(obj.id .. u8"\nНЕТ ФОТО##nb" .. obj.id, imgui.ImVec2(bw, bh)) then
                        if inspectPickMode then
                            inspectPickMode = false
                            startInspect({id = obj.id, name = obj.name})
                        else
                            selectedObj = obj
                        end
                    end
                    if imgui.IsItemClicked(1) then
                        ctxObj = obj
                        ctxPos = {x = imgui.GetMousePos().x, y = imgui.GetMousePos().y}
                    end
                    if imgui.IsItemClicked(2) then
                        setClipboardText(obj.id)
                        if notifyCopyIdEnabled then
                            toast_text  = "ID скопирован: " .. obj.id
                            toast_text2 = obj.name
                            toast_tex   = nil
                            toast_timer = 150
                        end
                    end
                    if imgui.Button(u8"Создать##cr" .. obj.id, imgui.ImVec2(bw, 20)) then
                        if inspectPickMode then
                            inspectPickMode = false
                            startInspect({id = obj.id, name = obj.name})
                        elseif sceneSpawnPickMode then
                            sceneSpawnObject(obj)
                        else
                            addToRecent(obj); sampSendChat("/cr " .. obj.id)
                            winOpen[0] = false
                        end
                    end
                end
                imgui.SetWindowFontScale(1.0)
                imgui.PushTextWrapPos(imgui.GetCursorPosX() + bw)
                imgui.TextColored(accentColor(), (isFav and u8"* " or "") .. "[" .. obj.id .. "]")
                imgui.SameLine(0, 4)
                imgui.TextColored(imgui.ImVec4(0.50, 0.50, 0.50, 1.0), "|")
                imgui.SameLine(0, 4)
                imgui.TextColored(imgui.ImVec4(0.92, 0.92, 0.92, 1.0), obj.name)
                imgui.PopTextWrapPos()
                imgui.SetWindowFontScale(1.0)
            imgui.EndGroup()
            col = col + 1
            if col >= cols then
                col = 0
                imgui.Spacing()
            end
        end

        -- Плавная фоновая предзагрузка текстур на 1 страницу вперёд (до 2/кадр без фризов)
        if ei < total then
            local preloadEnd = math.min((currentPage + 1) * PAGE_SIZE, total)
            local bgLoaded = 0
            for i = ei + 1, preloadEnd do
                if texLoadedThisFrame >= MAX_TEX_PER_FRAME or bgLoaded >= 2 then break end
                local obj = shownObjects[i]
                if obj and obj.id and not textures[obj.id] and not texFailed[obj.id] then
                    if preloadTex(obj.id) then
                        bgLoaded = bgLoaded + 1
                    end
                end
            end
        end

    imgui.EndChild()
    imgui.Unindent(10)
end

local function renderTabFavorites()
    imgui.Indent(10)
    local W = imgui.GetContentRegionAvail().x
    imgui.Spacing()
    imgui.TextColored(accentColor(), fa.ICON_STAR .. u8"  ИЗБРАННОЕ")
    imgui.Spacing()
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint(u8"##favsearch", u8"Поиск по названию или ID...", favSearchBuf, 128)
    imgui.PopItemWidth()
    imgui.Spacing()
    if imgui.Button(u8"Все##fa0", imgui.ImVec2(60, 24)) then activeTab2 = 0 end
    imgui.SameLine()
    local ci = 1
    for catName, _ in pairs(favCategories) do
        if imgui.Button(catName .. "##fcat_" .. ci, imgui.ImVec2(100, 24)) then activeTab2 = ci end
        if imgui.IsItemClicked(1) then
            ctxCat = catName
            ctxCatPos = {x = imgui.GetMousePos().x, y = imgui.GetMousePos().y}
        end
        imgui.SameLine()
        ci = ci + 1
    end
    imgui.Spacing()

    -- сортировка избранного
    imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), fa.ICON_FILTER .. u8" Сортировка:")
    imgui.SameLine(nil, 5)
    imgui.PushItemWidth(210)
    local favSortItems = {
        fa.ICON_SORT_NUMERIC_ASC .. u8" По ID",
        fa.ICON_SORT_ALPHA_ASC .. u8" По алфавиту (А-Я)",
        fa.ICON_SORT_ALPHA_DESC .. u8" По алфавиту (Я-А)",
        fa.ICON_SORT_AMOUNT_DESC .. u8" Сначала большие",
        fa.ICON_SORT_AMOUNT_ASC .. u8" Сначала маленькие"
    }
    if imgui.BeginCombo(u8"##favSortCombo", favSortItems[favSortMode + 1]) then
        for i, name in ipairs(favSortItems) do
            local is_selected = (favSortMode == (i - 1))
            if imgui.Selectable(name, is_selected) then
                favSortMode = i - 1
            end
            if is_selected then imgui.SetItemDefaultFocus() end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()

    imgui.SameLine(nil, 20)
    imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), fa.ICON_ARROWS .. u8" Метрика:")
    imgui.SameLine(nil, 5)
    imgui.PushItemWidth(150)
    local favMetricKeys   = {"radius", "width", "height"}
    local favMetricLabels = {radius = u8"Радиус (R)", width = u8"Ширина (W)", height = u8"Высота (H)"}
    if imgui.BeginCombo(u8"##favMetricCombo", favMetricLabels[favSizeMetric]) then
        for _, key in ipairs(favMetricKeys) do
            local is_selected = (favSizeMetric == key)
            if imgui.Selectable(favMetricLabels[key], is_selected) then
                favSizeMetric = key
            end
            if is_selected then imgui.SetItemDefaultFocus() end
        end
        imgui.EndCombo()
    end
    imgui.PopItemWidth()
    if imgui.IsItemHovered() then
        imgui.SetTooltip(u8"По какому размеру объекта фильтровать/сортировать")
    end
    -- счётчик избранного
    local favTotal = 0; for _ in pairs(favorites) do favTotal = favTotal + 1 end
    imgui.SameLine()
    imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1), u8"  Всего: " .. favTotal)
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    imgui.BeginChild(u8"##fgr", imgui.ImVec2(0, 0), false, imgui.WindowFlags.AlwaysVerticalScrollbar)
        local PAD = 10
        local SAFEMARGIN = 14
        local avail = imgui.GetContentRegionAvail().x
        local CELL = math.floor((avail - SAFEMARGIN - PAD * (COLS_COUNT - 1)) / COLS_COUNT)
        local cols = COLS_COUNT
        local col = 0; local any = false
        local ci2 = 1
        catName = nil
        for cn, _ in pairs(favCategories) do
            if ci2 == activeTab2 then catName = cn; break end
            ci2 = ci2 + 1
        end
        -- собираем и сортируем избранное
        favList = {}
        for _, obj in ipairs(allObjects) do
            show = false
            if activeTab2 == 0 then show = favorites[obj.id]
            elseif catName and favCategories[catName] then show = favCategories[catName][obj.id] end
            if show then
                fq2 = ffi.string(favSearchBuf):lower()
                dname = (favAliases[obj.id] or obj.name):lower()
                if fq2 == "" or dname:find(fq2,1,true) or obj.id:lower():find(fq2,1,true) then
                    table.insert(favList, obj)
                end
            end
        end
        if favSortMode==0 then table.sort(favList,function(a,b) return (tonumber(a.id) or 0)<(tonumber(b.id) or 0) end)
        elseif favSortMode==1 then table.sort(favList,function(a,b)
            local na=tonumber(a.name:match("^#?(%d+)")); local nb=tonumber(b.name:match("^#?(%d+)"))
            if na and nb then return na<nb end; if na then return true end; if nb then return false end
            return a.name:lower()<b.name:lower() end)
        elseif favSortMode==2 then table.sort(favList,function(a,b)
            local na=tonumber(a.name:match("^#?(%d+)")); local nb=tonumber(b.name:match("^#?(%d+)"))
            if na and nb then return na>nb end; if na then return false end; if nb then return true end
            return a.name:lower()>b.name:lower() end)
        elseif favSortMode==3 then table.sort(favList,function(a,b) return (a[favSizeMetric] or 0)>(b[favSizeMetric] or 0) end)
        elseif favSortMode==4 then table.sort(favList,function(a,b) return (a[favSizeMetric] or 0)<(b[favSizeMetric] or 0) end)
        end
        for _, obj in ipairs(favList) do
            any = true
            if col > 0 then imgui.SameLine(0, PAD) end
            imgui.BeginGroup()
                tex = getTex(obj.id)
                bw, bh = CELL, CELL - 40
                if tex then
                    imgui.Image(tex, imgui.ImVec2(bw, bh))
                    if imgui.IsItemClicked(0) then selectedObj = obj end
                    if imgui.IsItemClicked(1) then ctxObj = obj; ctxPos = {x=imgui.GetMousePos().x, y=imgui.GetMousePos().y} end
                    if imgui.IsItemClicked(2) then favorites[obj.id]=nil; for _,cd in pairs(favCategories) do cd[obj.id]=nil end; saveFavorites(); saveCategories() end
                    if imgui.Button(u8"Создать##fcr"..obj.id, imgui.ImVec2(bw,20)) then addToRecent(obj); sampSendChat("/cr "..obj.id); winOpen[0]=false; end
                else
                    if imgui.Button(obj.id.."\nNO IMG##fnb"..obj.id, imgui.ImVec2(bw,bh+20)) then addToRecent(obj); sampSendChat("/cr "..obj.id); winOpen[0]=false; end
                end
                displayName = favAliases[obj.id] or obj.name
                if favNotes[obj.id] and favNotes[obj.id] ~= "" then
                    imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1), fa.ICON_COMMENT .. " " .. favNotes[obj.id])
                end
                imgui.TextColored(accentColor(), obj.id)
                imgui.SameLine()
                imgui.PushTextWrapPos(imgui.GetCursorPosX() + bw)
                imgui.TextWrapped(displayName)
                imgui.PopTextWrapPos()
            imgui.EndGroup()
            col = col+1
            if col >= cols then col=0; imgui.Spacing() end
        end
        if not any then
            imgui.Spacing()
            imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), fa.ICON_STAR_O .. u8"  Пусто. ПКМ по объекту в каталоге — добавить.")
        end

        -- ПКМ категории
        -- ПКМ категорії
        if ctxCat and ctxCatPos then
            imgui.SetNextWindowPos(imgui.ImVec2(ctxCatPos.x, ctxCatPos.y), imgui.Cond.Always)
            imgui.Begin(u8"##ctxcat", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.AlwaysAutoResize)
            
                if not imgui.IsWindowHovered() and imgui.IsMouseClicked(0) then ctxCat=nil; ctxCatPos=nil; showRename=false end
                
                if showRename then
                    imgui.PushItemWidth(140)
                    if imgui.InputText(u8"##rncn", renameCatBuf, 64, imgui.InputTextFlags.EnterReturnsTrue) then
                        newName = ffi.string(renameCatBuf)
                        if newName~="" and newName~=ctxCat and not favCategories[newName] then
                            favCategories[newName]=favCategories[ctxCat]; favCategories[ctxCat]=nil
                            if activeTab2~=0 then activeTab2=0 end; saveCategories()
                        end
                        showRename=false; ctxCat=nil; ctxCatPos=nil
                    end
                    imgui.PopItemWidth()
                else
                    if imgui.Button(u8"Изменить название##rn", imgui.ImVec2(195,0)) then showRename=true end
                    imgui.Separator()
                    if imgui.Button(u8"Удалить категорию##dc", imgui.ImVec2(195,0)) then
                        favCategories[ctxCat]=nil; saveCategories()
                        if activeTab2~=0 then activeTab2=0 end; ctxCat=nil; ctxCatPos=nil
                    end
                end
            imgui.End()
        end
    imgui.EndChild()
    imgui.Indent(10)
end

local function renderTabMaps()
    imgui.Indent(10)
    local W = imgui.GetContentRegionAvail().x
    imgui.Spacing()
    imgui.TextColored(accentColor(), fa.ICON_MAP .. u8"  ДОСТУПНЫЕ КАРТЫ")
    imgui.Spacing()
    imgui.Spacing()
    imgui.PushItemWidth(W - 115)
    imgui.InputTextWithHint(u8"##mapsearch", u8"Поиск...", mapSearchBuf, 128)
    imgui.PopItemWidth()
    imgui.SameLine()
    if imgui.Button(fa.ICON_PLUS .. u8" Добавить##mapadd", imgui.ImVec2(-1, 0)) then showMapAdd = true end
    imgui.Spacing()

    -- категории
    if imgui.Button(u8"Все##mcat0", imgui.ImVec2(60, 24)) then activeMapTab = 0 end
    imgui.SameLine()
    local mci = 1
    for catName, _ in pairs(mapCategories) do
        if imgui.Button(catName.."##mcat_"..mci, imgui.ImVec2(100, 24)) then activeMapTab = mci end
        if imgui.IsItemClicked(1) then ctxMap=catName; ctxMapPos={x=imgui.GetMousePos().x, y=imgui.GetMousePos().y} end
        imgui.SameLine(); mci = mci+1
    end
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- блоки карт
    local CARD_W = 220
    local CARD_H = 70
    local PAD    = 10
    local cols   = math.max(1, math.floor((W + PAD) / (CARD_W + PAD)))
    local col    = 0

    imgui.BeginChild(u8"##mapslist", imgui.ImVec2(0, 0), false)
    local _sm = {} for _i,_m in ipairs(maps) do table.insert(_sm,{idx=_i,map=_m}) end
    table.sort(_sm,function(a,b) local na=tonumber(a.map.name:match("#(%d+)")) or 0; local nb=tonumber(b.map.name:match("#(%d+)")) or 0; if na~=nb then return na<nb end; return a.map.name<b.map.name end)
    for _,_entry in ipairs(_sm) do local i,m = _entry.idx, _entry.map
        local show = activeMapTab == 0
        local q = ffi.string(mapSearchBuf):lower()
        if q ~= "" and not m.name:lower():find(q, 1, true) and not m.id:lower():find(q, 1, true) then
            show = false
        end
        if not show then
            local ci2 = 1
            for cn, cd in pairs(mapCategories) do
                if ci2 == activeMapTab and cd[tostring(i)] then show = true end
                ci2 = ci2+1
            end
        end
        if not show then goto continue_map end

        if col > 0 then imgui.SameLine(0, PAD) end
        imgui.BeginGroup()
            -- фон карточки
            local p = imgui.GetCursorScreenPos()
            imgui.GetWindowDrawList():AddRectFilled(
                imgui.ImVec2(p.x, p.y),
                imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                0xFF000000 + cardBgHex(), 8)
            imgui.GetWindowDrawList():AddRect(
                imgui.ImVec2(p.x, p.y),
                imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                0x55000000 + accentColorHex(), 8)

            -- невидимая кнопка на всю карточку
            imgui.InvisibleButton("##mcard_"..i, imgui.ImVec2(CARD_W, CARD_H))
            local clicked  = imgui.IsItemClicked(0)
            local rclicked = imgui.IsItemClicked(1)
            local hovered  = imgui.IsItemHovered()

            -- подсветка при наведении
            if hovered then
                imgui.GetWindowDrawList():AddRectFilled(
                    imgui.ImVec2(p.x, p.y),
                    imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                    0x15E07200, 8)
            end

            -- текст внутри карточки
            local mapIconTex = getTex("1247")
            local ip = imgui.ImVec2(p.x + 8, p.y + 8)
            if mapIconTex then
                imgui.SetCursorScreenPos(ip)
                imgui.Image(mapIconTex, imgui.ImVec2(36, 36))
            end
            imgui.GetWindowDrawList():AddRect(
                imgui.ImVec2(ip.x - 1, ip.y - 1), imgui.ImVec2(ip.x + 37, ip.y + 37),
                0xFF000000 + accentColorHex(), 4)

            imgui.GetWindowDrawList():PushClipRect(
                imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + CARD_W - 6, p.y + 44), true)
            imgui.GetWindowDrawList():AddText(imgui.ImVec2(p.x + 52, p.y + 10), 0xFFFFFFFF, m.name)
            imgui.GetWindowDrawList():PopClipRect()
            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 52, p.y + 28))
            imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"ID: " .. m.id)

            -- заметка или подсказка внизу карточки
            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 10, p.y + 50))
            if mapNotes[tostring(i)] and mapNotes[tostring(i)] ~= "" then
                imgui.TextColored(imgui.ImVec4(0.55, 0.75, 0.55, 1.0), fa.ICON_COMMENT .. " " .. mapNotes[tostring(i)])
            end

            if hovered then
                imgui.SetTooltip(u8"ЛКМ — телепорт на карту | ПКМ — меню | Колёсико — удалить карту из списка")
            end

            if clicked then
                sampSendChat("/call eventmap "..m.id)
                sampSendChat("/gotomap "..m.id)
            end
            if rclicked then ctxMap=i; ctxMapPos={x=imgui.GetMousePos().x, y=imgui.GetMousePos().y} end
            if hovered and imgui.IsMouseClicked(2) then
                table.remove(maps, i); saveMaps()
                imgui.EndGroup(); goto continue_map
            end
        imgui.EndGroup()

        col = col + 1
        if col >= cols then col = 0; imgui.Spacing() end
        ::continue_map::
    end

    if #maps == 0 then
        imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), u8"  Карт нет. Нажмите '+ Добавить'.")
    end
    imgui.EndChild()

    if ctxMap and ctxMapPos then
        imgui.SetNextWindowPos(imgui.ImVec2(ctxMapPos.x, ctxMapPos.y), imgui.Cond.Always)
        imgui.Begin(u8"##ctxmap", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.AlwaysAutoResize)
            if not imgui.IsWindowHovered() and imgui.IsMouseClicked(0) then ctxMap=nil; ctxMapPos=nil; showMapCatCreate=false end

            local isMapCtx = type(ctxMap) == "number"

            if isMapCtx then
                if imgui.Button(fa.ICON_TRASH .. u8" Удалить карту##mapdel", imgui.ImVec2(185,0)) then
                    table.remove(maps, ctxMap)
                    mapNotes[tostring(ctxMap)] = nil; saveMaps(); saveMapNotes()
                    ctxMap=nil; ctxMapPos=nil
                end
                if imgui.Button(fa.ICON_PENCIL .. u8" Переименовать##mapren", imgui.ImVec2(185,0)) then
                    renameMap = ctxMap
                    imgui.StrCopy(renameMapBuf, maps[ctxMap] and maps[ctxMap].name or "")
                    ctxMap=nil; ctxMapPos=nil
                end
                if imgui.Button(fa.ICON_PENCIL .. u8" Заметка##mapnote", imgui.ImVec2(185,0)) then
                    editMapNote = ctxMap
                    local cur = mapNotes[tostring(ctxMap)] or ""
                    imgui.StrCopy(editMapNoteBuf, cur)
                    ctxMap=nil; ctxMapPos=nil
                end
                imgui.Separator()
                imgui.Text(u8"Категория:")
                imgui.Separator()
                if showMapCatCreate then
                    imgui.PushItemWidth(140)
                    if imgui.InputText(u8"##nmcn", mapCatNameBuf, 64, imgui.InputTextFlags.EnterReturnsTrue) then
                        local cn = ffi.string(mapCatNameBuf)
                        if cn~="" then if not mapCategories[cn] then mapCategories[cn]={} end; mapCategories[cn][tostring(ctxMap)]=true; saveMapCategories() end
                        imgui.StrCopy(mapCatNameBuf,''); showMapCatCreate=false; ctxMap=nil; ctxMapPos=nil
                    end
                    imgui.PopItemWidth()
                else
                    if imgui.Button(u8"+ Создать категорию##mcc", imgui.ImVec2(185,0)) then showMapCatCreate=true end
                    for cn, cd in pairs(mapCategories) do
                        local inCat = cd[tostring(ctxMap)]
                        if imgui.Button((inCat and "- " or "+ ")..cn.."##mcc_"..cn, imgui.ImVec2(155,0)) then
                            if inCat then cd[tostring(ctxMap)]=nil else cd[tostring(ctxMap)]=true end
                            saveMapCategories(); ctxMap=nil; ctxMapPos=nil
                        end
                        imgui.SameLine()
                        if imgui.Button(u8"X##mcdel_"..cn, imgui.ImVec2(26,0)) then
                            mapCategories[cn]=nil; saveMapCategories()
                            if activeMapTab~=0 then activeMapTab=0 end; ctxMap=nil; ctxMapPos=nil
                        end
                    end
                end
            else
                -- Правый клик по вкладке категории — тут ctxMap это строка (имя категории)
                imgui.Text(u8"Категория: " .. tostring(ctxMap))
                imgui.Separator()
                if imgui.Button(fa.ICON_TRASH .. u8" Удалить категорию##mapcatdel", imgui.ImVec2(185,0)) then
                    mapCategories[ctxMap] = nil
                    saveMapCategories()
                    if activeMapTab ~= 0 then activeMapTab = 0 end
                    ctxMap=nil; ctxMapPos=nil
                end
            end
        imgui.End()
    end


    -- \xce\xea\xed\xee \xf0\xe5\xe4\xe0\xea\xf2\xe8\xf0\xee\xe2\xe0\xed\xe8\xff \xe7\xe0\xec\xe5\xf2\xea\xe8 \xea \xea\xe0\xf0\xf2\xe5
    if editMapNote then
        imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5,0.5))
        imgui.SetNextWindowSize(imgui.ImVec2(340, 148), imgui.Cond.Always)
        imgui.Begin(u8"\xc7\xe0\xec\xe5\xf2\xea\xe0##mapnotewin", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize)
            imgui.Text(u8"\xc7\xe0\xec\xe5\xf2\xea\xe0 \xea \xea\xe0\xf0\xf2\xe5:")
            imgui.PushItemWidth(-1)
            imgui.InputText(u8"##mapnoteinp", editMapNoteBuf, 256)
            imgui.PopItemWidth()
            imgui.Spacing(); imgui.Separator()
            if imgui.Button(u8"\xd1\xee\xf5\xf0\xe0\xed\xe8\xf2\xfc##mapnotesv", imgui.ImVec2(155,28)) then
                local txt = ffi.string(editMapNoteBuf)
                mapNotes[tostring(editMapNote)] = txt
                saveMapNotes(); editMapNote = nil
            end
            imgui.SameLine()
            if imgui.Button(u8"\xce\xf2\xec\xe5\xed\xe0##mapnotecn", imgui.ImVec2(155,28)) then
                editMapNote = nil
            end
        imgui.End()
    end
    imgui.Indent(10)
end

local function renderTabRecent()
    imgui.Indent(10)
    imgui.Spacing()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_HISTORY .. u8"  НЕДАВНИЕ ОБЪЕКТЫ")

    local nowClock = os.clock()
    if recentClearAllConfirm and nowClock > recentClearAllConfirmTime then
        recentClearAllConfirm = false
    end

    imgui.SameLine(imgui.GetContentRegionAvail().x - 165)
    if recentClearAllConfirm then
        imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.75, 0.15, 0.15, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.85, 0.20, 0.20, 1.0))
    end
    local clrAllLabel = recentClearAllConfirm
        and (fa.ICON_EXCLAMATION_TRIANGLE .. u8" Точно удалить?##clrrec")
        or  (fa.ICON_TRASH .. u8" Очистить всё##clrrec")
    if imgui.Button(clrAllLabel, imgui.ImVec2(155, 22)) then
        if recentClearAllConfirm then
            recentObjects = {}; saveRecent()
            recentClearAllConfirm = false
        else
            recentClearAllConfirm = true
            recentClearAllConfirmTime = nowClock + 3.0
        end
    end
    if recentClearAllConfirm then
        imgui.PopStyleColor(2)
        if imgui.IsItemHovered() then
            imgui.SetTooltip(u8"Нажмите ещё раз, чтобы подтвердить удаление всех недавних объектов")
        end
    end
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    if #recentObjects == 0 then
        imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"  Пусто. Создайте объект через каталог.")
        return
    end

    local PAD   = 10
    local SAFEMARGIN = 14
    local avail = imgui.GetContentRegionAvail().x
    local RECENT_COLS = math.max(COLS_COUNT + 1, 6) -- в "Недавних" картинки чуть мельче основного каталога, чтобы всё влезало без скролла
    local CELL  = math.floor((avail - SAFEMARGIN - PAD * (RECENT_COLS - 1)) / RECENT_COLS)

    -- собираем уникальные даты по порядку
    local dateOrder = {}
    local dateSet   = {}
    for _, obj in ipairs(recentObjects) do
        local d = obj.date or u8"Дата неизвестна"
        if not dateSet[d] then
            dateSet[d] = true
            table.insert(dateOrder, d)
        end
    end

    imgui.BeginChild(u8"##recentlist", imgui.ImVec2(0, 0), false)
    for _, date in ipairs(dateOrder) do
        -- заголовок даты + кнопка очистить день
        imgui.Spacing()
        imgui.TextColored(accentColorA(1), u8"Объекты от " .. date)
        imgui.SameLine()

        if recentClearDateConfirm[date] and nowClock > recentClearDateConfirm[date] then
            recentClearDateConfirm[date] = nil
        end
        local dateConfirm = recentClearDateConfirm[date] ~= nil

        if dateConfirm then
            imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.75, 0.15, 0.15, 1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.85, 0.20, 0.20, 1.0))
        end
        if imgui.SmallButton((dateConfirm and fa.ICON_EXCLAMATION_TRIANGLE or fa.ICON_TRASH) .. "##clrdate_" .. date) then
            if dateConfirm then
                for j = #recentObjects, 1, -1 do
                    if (recentObjects[j].date or u8"Дата неизвестна") == date then
                        table.remove(recentObjects, j)
                    end
                end
                saveRecent()
                recentClearDateConfirm[date] = nil
            else
                recentClearDateConfirm[date] = nowClock + 3.0
            end
        end
        if dateConfirm then imgui.PopStyleColor(2) end
        if imgui.IsItemHovered() then
            imgui.SetTooltip(dateConfirm and u8"Нажмите ещё раз, чтобы подтвердить удаление за " .. date
                                           or (u8"Очистить объекты за " .. date))
        end
        imgui.Separator(); imgui.Spacing()

        local col = 0
        for i, obj in ipairs(recentObjects) do
            if (obj.date or u8"Дата неизвестна") ~= date then goto continue_date end

            if col > 0 then imgui.SameLine(0, PAD) end
            imgui.BeginGroup()
                local tex = getTex(obj.id)
                local bw, bh = CELL, CELL - 40
                if tex then
                    imgui.Image(tex, imgui.ImVec2(bw, bh))
                    if imgui.IsItemClicked(0) then selectedObj = obj end
                    if imgui.Button(u8"Создать##rcr_"..i, imgui.ImVec2(bw, 20)) then
                        addToRecent(obj); sampSendChat("/cr "..obj.id)
                        winOpen[0]=false;
                    end
                else
                    if imgui.Button(obj.id.."\nNO IMG##rnb_"..i, imgui.ImVec2(bw, bh+20)) then
                        addToRecent(obj); sampSendChat("/cr "..obj.id)
                        winOpen[0]=false;
                    end
                end
                imgui.PushTextWrapPos(imgui.GetCursorPosX() + bw)
                imgui.TextColored(accentColorA(1), "[" .. obj.id .. "]")
                imgui.SameLine(0, 4)
                imgui.TextColored(imgui.ImVec4(0.50, 0.50, 0.50, 1.0), "|")
                imgui.SameLine(0, 4)
                imgui.TextColored(imgui.ImVec4(0.92, 0.92, 0.92, 1.0), obj.name)
                imgui.PopTextWrapPos()
            imgui.EndGroup()

            col = col + 1
            if col >= RECENT_COLS then col=0; imgui.Spacing() end
            ::continue_date::
        end
        imgui.Spacing()
    end
    imgui.EndChild()
    imgui.Indent(10)
end

local function drawObjSearchPickerGrid()
    imgui.Indent(10)
    local query = cyrLower(ffi.string(objSearchQuery))

    if query == "" then
        imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"Введите название или ID объекта для поиска")
        return
    end

    local CARD_W, CARD_H = 90, 118
    local PAD = 10
    local avail = imgui.GetContentRegionAvail().x
    local cols = math.max(1, math.floor((avail + PAD) / (CARD_W + PAD)))
    local col = 0

    for _, obj in ipairs(allObjects) do
        if cyrLower(obj.name or ""):find(query, 1, true) or tostring(obj.id):find(query, 1, true) then
            if col > 0 then imgui.SameLine(0, PAD) end
            imgui.BeginGroup()
                local isSelected = objSearchTargets[tonumber(obj.id)] ~= nil

                local tex = getTex(obj.id)
                if tex then
                    imgui.Image(tex, imgui.ImVec2(CARD_W, CARD_W))
                else
                    imgui.Dummy(imgui.ImVec2(CARD_W, CARD_W))
                end
                if imgui.IsItemClicked(0) then
                    local model = tonumber(obj.id)
                    if objSearchTargets[model] then
                        objSearchTargets[model] = nil
                    else
                        objSearchTargets[model] = obj.name
                    end
                end

                imgui.PushTextWrapPos(imgui.GetCursorPosX() + CARD_W)
                if isSelected then
                    imgui.TextColored(imgui.ImVec4(0.2,0.9,0.2,1), fa.ICON_CHECK .. " " .. obj.name)
                else
                    imgui.TextColored(imgui.ImVec4(0.8,0.8,0.8,1), obj.name)
                end
                imgui.PopTextWrapPos()
            imgui.EndGroup()

            col = col + 1
            if col >= cols then col = 0 end
        end
    end
    imgui.Indent(10)
end

local function drawObjExceptionGrid(list, idPrefix)
    imgui.Indent(10)
    local CARD_W, CARD_H = 90, 110
    local PAD = 10
    local avail = imgui.GetContentRegionAvail().x
    local cols = math.max(1, math.floor((avail + PAD) / (CARD_W + PAD)))
    local col = 0

    for i, model in ipairs(list) do
        if col > 0 then imgui.SameLine(0, PAD) end
        imgui.BeginGroup()
            local excepted = exceptionObjects[model] ~= nil
            local p = imgui.GetCursorScreenPos()

            imgui.GetWindowDrawList():AddRectFilled(
                imgui.ImVec2(p.x, p.y),
                imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                excepted and 0xFF7A1616 or 0xFF1E1E1E, 6)
            imgui.GetWindowDrawList():AddRect(
                imgui.ImVec2(p.x, p.y),
                imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                excepted and 0xFFFF3333 or 0x55E07200, 6)

            imgui.InvisibleButton("##" .. idPrefix .. "_" .. model .. "_" .. i, imgui.ImVec2(CARD_W, CARD_H))
            local clicked = imgui.IsItemClicked(0)
            if imgui.IsItemHovered() then
                imgui.GetWindowDrawList():AddRectFilled(
                    imgui.ImVec2(p.x, p.y),
                    imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                    0x15E07200, 6)
            end

            local tex = getTex(model)
            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 5, p.y + 5))
            if tex then
                imgui.Image(tex, imgui.ImVec2(CARD_W - 10, CARD_H - 30))
            else
                imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"NO IMG")
            end

            imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 5, p.y + CARD_H - 22))
            imgui.GetWindowDrawList():PushClipRect(
                imgui.ImVec2(p.x, p.y),
                imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                true)
            imgui.TextColored(imgui.ImVec4(0.85,0.85,0.85,1), tostring(model))
            imgui.GetWindowDrawList():PopClipRect()

            if clicked then
                if excepted then
                    exceptionObjects[model] = nil
                else
                    exceptionObjects[model] = sampObjectModelNames[model] or tostring(model)
                end
                saveObjExceptions()
            end
        imgui.EndGroup()

        col = col + 1
        if col >= cols then col = 0 end
    end
end

streamScannedObjects = {}
streamSelectedModels = {}
streamHideExceptions = imgui.new.bool(true)
streamOnlyOnScreen   = imgui.new.bool(false)
streamNewTagBuf      = imgui.new.char[64]()

function scanStreamZoneObjects()
    streamScannedObjects = {}
    streamSelectedModels = {}
    local counts = {}
    for _, hObj in pairs(getAllObjects()) do
        if doesObjectExist(hObj) then
            if not streamOnlyOnScreen[0] or isObjectOnScreen(hObj) then
                local model = getObjectModel(hObj)
                if model and sampObjectModelNames[model] then
                    if not streamHideExceptions[0] or not exceptionObjects[model] then
                        counts[model] = (counts[model] or 0) + 1
                    end
                end
            end
        end
    end
    for model, cnt in pairs(counts) do
        table.insert(streamScannedObjects, {
            model = model,
            name = sampObjectModelNames[model] or tostring(model),
            count = cnt
        })
        streamSelectedModels[model] = true
    end
    table.sort(streamScannedObjects, function(a, b)
        if a.count ~= b.count then return a.count > b.count end
        return a.model < b.model
    end)
end

function saveSelectedStreamModelsToTag(tagName, isNew)
    if not tagName or tagName == "" then return 0 end
    if not favCategories[tagName] then favCategories[tagName] = {} end
    local grpEntry = nil
    for _, grp in ipairs(objSearchGroups) do
        if grp.name == tagName then grpEntry = grp; break end
    end
    if not grpEntry then
        grpEntry = { name = tagName, models = {} }
        table.insert(objSearchGroups, grpEntry)
    end
    local added = 0
    for _, item in ipairs(streamScannedObjects) do
        if streamSelectedModels[item.model] then
            local idStr = tostring(item.model)
            favCategories[tagName][idStr] = true
            favorites[idStr] = true
            grpEntry.models[item.model] = item.name
            added = added + 1
        end
    end
    saveCategories()
    saveFavorites()
    saveObjSearchGroups()
    return added
end

function renderStreamZoneScannerSubTab()
