    if imgui.Button(fa.ICON_REFRESH .. u8"  Сканировать объекты в зоне стрима##oa_scanstream_go", imgui.ImVec2(-1, 32)) then
        scanStreamZoneObjects()
        toast_text  = "Зона стрима просканирована"
        toast_text2 = "Найдено уникальных моделей: " .. tostring(#streamScannedObjects)
        toast_tex   = nil
        toast_timer = 130
    end

    imgui.Spacing()
    imgui.Checkbox(u8"Скрывать исключения сканера##oa_str_noexc", streamHideExceptions)
    imgui.SameLine(0, 16)
    imgui.Checkbox(u8"Только объекты на экране##oa_str_onscr", streamOnlyOnScreen)

    local selCount = 0
    for _, item in ipairs(streamScannedObjects) do
        if streamSelectedModels[item.model] then selCount = selCount + 1 end
    end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    local btnW = math.floor((imgui.GetContentRegionAvail().x - 8) / 2)
    if imgui.Button(fa.ICON_PLUS .. u8"  Сохранить отдельным тэгом##oa_str_newtag", imgui.ImVec2(btnW, 28)) then
        if selCount > 0 then
            local tagCount = 0
            for _ in pairs(favCategories) do tagCount = tagCount + 1 end
            imgui.StrCopy(streamNewTagBuf, u8("Стрим #" .. tostring(tagCount + 1)))
            imgui.OpenPopup(u8"##oa_str_newtag_popup")
        else
            toast_text  = "Нет выбранных объектов"
            toast_text2 = "Сначала просканируйте зону стрима и выберите объекты."
            toast_tex   = nil
            toast_timer = 140
        end
    end
    imgui.SameLine(0, 8)
    if imgui.Button(fa.ICON_TAGS .. u8"  Добавить к существующему тэгу##oa_str_addtag", imgui.ImVec2(btnW, 28)) then
        if selCount > 0 then
            imgui.OpenPopup(u8"##oa_str_addtag_popup")
        else
            toast_text  = "Нет выбранных объектов"
            toast_text2 = "Сначала просканируйте зону стрима и выберите объекты."
            toast_tex   = nil
            toast_timer = 140
        end
    end

    if imgui.BeginPopup(u8"##oa_str_newtag_popup") then
        imgui.TextColored(accentColor(), fa.ICON_TAG .. u8"  Новый тэг (Избранное + Сканер)")
        imgui.Spacing()
        imgui.Text(u8"Название тэга:")
        imgui.PushItemWidth(240)
        imgui.InputText(u8"##oa_str_newtag_inp", streamNewTagBuf, 64)
        imgui.PopItemWidth()
        imgui.Spacing()
        if imgui.Button(fa.ICON_CHECK .. u8"  Сохранить (" .. tostring(selCount) .. u8" об.)##oa_str_newtag_ok", imgui.ImVec2(240, 26)) then
            local tname = ffi.string(streamNewTagBuf)
            if tname ~= "" then
                local cnt = saveSelectedStreamModelsToTag(tname, true)
                toast_text  = u8"Тэг сохранён"
                toast_text2 = tname .. u8" — добавлено моделей: " .. tostring(cnt)
                toast_tex   = nil
                toast_timer = 150
                toast_preencoded = true
                imgui.CloseCurrentPopup()
            end
        end
        imgui.EndPopup()
    end

    if imgui.BeginPopup(u8"##oa_str_addtag_popup") then
        imgui.TextColored(accentColor(), fa.ICON_TAGS .. u8"  Выберите существующий тэг:")
        imgui.Separator(); imgui.Spacing()
        local existingTags = {}
        local seenTag = {}
        for catName, _ in pairs(favCategories) do
            if not seenTag[catName] then
                seenTag[catName] = true
                table.insert(existingTags, catName)
            end
        end
        for _, grp in ipairs(objSearchGroups) do
            if grp.name and not seenTag[grp.name] then
                seenTag[grp.name] = true
                table.insert(existingTags, grp.name)
            end
        end
        table.sort(existingTags)
        if #existingTags == 0 then
            imgui.TextDisabled(u8"Существующих тэгов пока нет. Создайте новый тэг!")
        else
            for ti, tname in ipairs(existingTags) do
                if imgui.Button(fa.ICON_TAG .. "  " .. tname .. "##oa_str_extag_" .. ti, imgui.ImVec2(240, 26)) then
                    local cnt = saveSelectedStreamModelsToTag(tname, false)
                    toast_text  = u8"Добавлено к тэгу"
                    toast_text2 = tname .. u8" — добавлено моделей: " .. tostring(cnt)
                    toast_tex   = nil
                    toast_timer = 150
                    toast_preencoded = true
                    imgui.CloseCurrentPopup()
                end
            end
        end
        imgui.EndPopup()
    end

    imgui.Spacing()
    if #streamScannedObjects == 0 then
        imgui.TextDisabled(u8"Нажмите 'Сканировать объекты в зоне стрима', чтобы собрать все объекты вокруг вас.")
        return
    end

    imgui.TextColored(imgui.ImVec4(0.75, 0.75, 0.75, 1.0), string.format(u8"Найдено моделей: %d  |  Выбрано: %d", #streamScannedObjects, selCount))
    imgui.SameLine(0, 12)
    if imgui.SmallButton(u8"Выбрать все##oa_str_selall") then
        for _, item in ipairs(streamScannedObjects) do streamSelectedModels[item.model] = true end
    end
    imgui.SameLine(0, 6)
    if imgui.SmallButton(u8"Снять выбор##oa_str_selnone") then
        streamSelectedModels = {}
    end
    imgui.SameLine(0, 6)
    if imgui.SmallButton(u8"В поиск сканера##oa_str_tosearch") then
        local added = 0
        for _, item in ipairs(streamScannedObjects) do
            if streamSelectedModels[item.model] then
                objSearchTargets[item.model] = item.name
                added = added + 1
            end
        end
        toast_text  = "Добавлено в поиск сканера"
        toast_text2 = "Моделей добавлено: " .. tostring(added)
        toast_tex   = nil
        toast_timer = 130
    end

    imgui.TextDisabled(u8"ЛКМ — выбрать/снять для сохранения в тэг  |  ПКМ — создать объект (/cr)")
    imgui.Spacing()

    imgui.BeginChild(u8"##oa_stream_grid", imgui.ImVec2(0, 340), true)
        local CARD_W, CARD_H = 96, 122
        local PAD = 10
        local avail = imgui.GetContentRegionAvail().x
        local cols = math.max(1, math.floor((avail + PAD) / (CARD_W + PAD)))
        local col = 0
        for idx, item in ipairs(streamScannedObjects) do
            if col > 0 then imgui.SameLine(0, PAD) end
            imgui.BeginGroup()
                local isSel = streamSelectedModels[item.model] == true
                local p = imgui.GetCursorScreenPos()
                imgui.GetWindowDrawList():AddRectFilled(
                    imgui.ImVec2(p.x, p.y),
                    imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                    isSel and 0xFF1A3A22 or 0xFF1E1E1E, 6)
                imgui.GetWindowDrawList():AddRect(
                    imgui.ImVec2(p.x, p.y),
                    imgui.ImVec2(p.x + CARD_W, p.y + CARD_H),
                    isSel and 0xFF2ECC71 or 0x55E07200, 6)

                imgui.InvisibleButton("##oa_str_card_" .. item.model .. "_" .. idx, imgui.ImVec2(CARD_W, CARD_H))
                local lclick = imgui.IsItemClicked(0)
                local rclick = imgui.IsItemClicked(1)
                local hovered = imgui.IsItemHovered()

                local tex = getTex(tostring(item.model))
                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 6, p.y + 6))
                if tex then
                    imgui.Image(tex, imgui.ImVec2(CARD_W - 12, CARD_W - 12))
                else
                    imgui.Dummy(imgui.ImVec2(CARD_W - 12, CARD_W - 12))
                end

                imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 5, p.y + CARD_W - 4))
                imgui.TextColored(isSel and imgui.ImVec4(0.3, 0.95, 0.45, 1) or accentColor(), string.format("#%d (x%d)", item.model, item.count))

                if hovered then
                    imgui.SetTooltip(string.format(u8"%s [%d]\nВ зоне стрима: %d шт.\nЛКМ — выбрать/убрать\nПКМ — создать (/cr %d)", item.name, item.model, item.count, item.model))
                end
                if lclick then
                    streamSelectedModels[item.model] = not isSel
                end
                if rclick then
                    sampSendChat("/cr " .. tostring(item.model))
                end
            imgui.EndGroup()
            col = col + 1
            if col >= cols then col = 0 end
        end
    imgui.EndChild()
end

-- Функция: ассистент по объектам.
    function renderTabObjAssistant()
    imgui.Spacing()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_EYE .. u8"  СКАНЕР ОБЪЕКТОВ")
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- переключатель подраздела ("scanner" | "search" | "stream")
    local subW = math.floor((imgui.GetContentRegionAvail().x - 24) / 4)
    local curSub = objScanSettingsSubTab or "scanner"
    if curSub ~= "scanner" then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16,0.16,0.16,1.0)) end
    if imgui.Button(fa.ICON_EYE .. u8"  Сканер##oa_subtab_scanner", imgui.ImVec2(subW, 30)) then
        objScanSettingsSubTab = "scanner"
    end
    if curSub ~= "scanner" then imgui.PopStyleColor() end
    imgui.SameLine(0, 8)
    if curSub ~= "search" then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16,0.16,0.16,1.0)) end
    if imgui.Button(fa.ICON_SEARCH .. u8"  Поиск ID##oa_subtab_search", imgui.ImVec2(subW, 30)) then
        objScanSettingsSubTab = "search"
    end
    if curSub ~= "search" then imgui.PopStyleColor() end
    imgui.SameLine(0, 8)
    if curSub ~= "stream" then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16,0.16,0.16,1.0)) end
    if imgui.Button(fa.ICON_CUBES .. u8"  Стрим##oa_subtab_stream", imgui.ImVec2(subW, 30)) then
        objScanSettingsSubTab = "stream"
    end
    if curSub ~= "stream" then imgui.PopStyleColor() end
    imgui.SameLine(0, 8)
    if curSub ~= "ruler" then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.16,0.16,0.16,1.0)) end
    if imgui.Button(fa.ICON_CUBE .. u8"  3D Линейка##oa_subtab_ruler", imgui.ImVec2(subW, 30)) then
        objScanSettingsSubTab = "ruler"
    end
    if curSub ~= "ruler" then imgui.PopStyleColor() end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    if curSub == "scanner" then
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"Бинд включения/выключения")
        imgui.Spacing()
        if imgui.Checkbox(u8"Удержание (зажать)##asmodecb", assistantHotkey_mode) then
            saveSettings()
        end
        imgui.Spacing()
        imgui.Text(u8"Текущий бинд: "); imgui.SameLine(); imgui.TextColored(imgui.ImVec4(1,0.8,0.3,1), ffi.string(assistantHotkey_display))
        imgui.Spacing()
        if assistantWaiting then
            imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.80,0.20,0.10,1.0))
            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.90,0.30,0.10,1.0))
            imgui.Button(u8"  >> Нажмите клавишу <<  ##aswait", imgui.ImVec2(-1, 30))
            imgui.PopStyleColor(2)
            for vk = 1, 254 do
                if isKeyDown(vk) and vk~=0x12 and vk~=0x11 and vk~=0x10
                and vk~=0xA0 and vk~=0xA1 and vk~=0xA2 and vk~=0xA3 and vk~=0xA4 and vk~=0xA5 then
                    assistantHotkey_key[0]   = vk
                    assistantHotkey_alt[0]   = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
                    assistantHotkey_ctrl[0]  = isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)
                    assistantHotkey_shift[0] = isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)
                    assistantJustSet = true
                    assistantWaiting = false
                    updateAssistantDisplay(); saveSettings()
                    break
                end
            end
        else
            if imgui.Button(u8"  Изменить##aschange", imgui.ImVec2(150, 28)) then
                assistantWaiting = false
                lua_thread.create(function()
                    repeat wait(0) until not isKeyDown(0x01) and not isKeyDown(0x02)
                    wait(200); assistantWaiting = true
                end)
            end
            imgui.SameLine()
            if imgui.Button(u8"  Сброс##asreset", imgui.ImVec2(-1, 28)) then
                assistantHotkey_alt[0]=false; assistantHotkey_ctrl[0]=false
                assistantHotkey_shift[0]=false; assistantHotkey_key[0]=0
                updateAssistantDisplay(); saveSettings()
            end
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"Настройки сканера")

        if imgui.Checkbox(u8"Подсвечивать все объекты##oa_all", imgui.new.bool(checkboxRenderAll)) then
            checkboxRenderAll = not checkboxRenderAll
            if checkboxRenderAll then checkboxRenderByRule = false; hideExistingAccessories() end
        end

        if checkboxRenderAll then
            imgui.SameLine()
            if imgui.Checkbox(u8"ID##oa_ids", imgui.new.bool(checkboxShowIDs)) then
                checkboxShowIDs = not checkboxShowIDs
            end
            imgui.SameLine()
            if imgui.Checkbox(u8"Дистанция##oa_dist", imgui.new.bool(checkboxShowDistance)) then
                checkboxShowDistance = not checkboxShowDistance
            end
        end

        if checkboxRenderByRule then
            imgui.SameLine()
            if imgui.Checkbox(u8"ID##oa_ruleids", imgui.new.bool(checkboxRenderIDsByRule)) then
                checkboxRenderIDsByRule = not checkboxRenderIDsByRule
            end
            imgui.SameLine()
            if imgui.Checkbox(u8"Дистанция##oa_ruledist", imgui.new.bool(checkboxRenderDistanceByRule)) then
                checkboxRenderDistanceByRule = not checkboxRenderDistanceByRule
            end
        end

        imgui.Spacing()

        if imgui.Checkbox(u8"Линия-указатель до объекта##oa_traser", imgui.new.bool(traser)) then
            traser = not traser
        end
        if traser then
            imgui.SameLine()
            if imgui.Checkbox(u8"Разноцветные линии##oa_rgb", imgui.new.bool(rgbtraser)) then
                rgbtraser = not rgbtraser
            end
        end

        imgui.Spacing()

        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"Дальность отображения")
        imgui.PushItemWidth(220)
        imgui.SliderFloat(u8"##oa_maxdist", maxDrawDistance, 10.0, 500.0, u8"%.0f м")
        imgui.PopItemWidth()

    elseif curSub == "search" then
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"Поиск конкретного объекта")

        local hasSearchTargets = next(objSearchTargets) ~= nil
        if hasSearchTargets then
            imgui.TextDisabled(u8"ЛКМ — искать только этот / показать все обратно.  ПКМ — убрать из поиска.")
            imgui.Indent(6)
            local thumbSize = 40
            local first = true
            local soloAtFrameStart = objSearchSoloModel -- фиксируем состояние ДО цикла, чтобы клик не влиял на другие иконки в этом же кадре
            local pendingSoloToggle = nil
            local pendingDelete = nil

            for model, name in pairs(objSearchTargets) do
                if not first then imgui.SameLine(0, 8) end
                first = false

                local isSolo = (soloAtFrameStart == model)
                -- без соло — все зелёные; с соло — выбранный зелёный, остальные серые
                local isGreen = (not soloAtFrameStart) or isSolo
                local p = imgui.GetCursorScreenPos()
                local tex = getTex(tostring(model))

                imgui.GetWindowDrawList():AddRectFilled(
                    imgui.ImVec2(p.x - 3, p.y - 3), imgui.ImVec2(p.x + thumbSize + 3, p.y + thumbSize + 3),
                    isGreen and 0xFF1FA83A or 0xFF5A5A5A, 4)

                if tex then
                    imgui.Image(tex, imgui.ImVec2(thumbSize, thumbSize))
                else
                    imgui.InvisibleButton("##oa_searchthumb_ph" .. model, imgui.ImVec2(thumbSize, thumbSize))
                    imgui.GetWindowDrawList():AddText(imgui.ImVec2(p.x + 4, p.y + thumbSize/2 - 6), 0xFFAAAAAA, "no img")
                end

                if imgui.IsItemHovered() then
                    imgui.SetTooltip(name .. " (" .. model .. ")")
                end
                if imgui.IsItemClicked(0) then
                    pendingSoloToggle = model
                end
                if imgui.IsItemClicked(1) then
                    pendingDelete = model
                end
            end

            if pendingSoloToggle then
                if objSearchSoloModel == pendingSoloToggle then
                    objSearchSoloModel = nil
                else
                    objSearchSoloModel = pendingSoloToggle
                end
            end
            if pendingDelete then
                objSearchTargets[pendingDelete] = nil
                if objSearchSoloModel == pendingDelete then objSearchSoloModel = nil end
            end

            imgui.Unindent(6)
            imgui.Spacing()
        end

        if imgui.Button(u8"Найти определённый объект##oa_searchbtn", imgui.ImVec2(-1, 28)) then
            showObjSearchPicker = not showObjSearchPicker
        end

        if showObjSearchPicker then
            imgui.Spacing()
            imgui.PushItemWidth(-1)
            imgui.InputTextWithHint(u8"##oa_searchinput", u8"Поиск объекта по названию или ID...", objSearchQuery, 128)
            imgui.PopItemWidth()
            imgui.Spacing()
            imgui.BeginChild(u8"##oa_searchgrid", imgui.ImVec2(0, 320), true)
            drawObjSearchPickerGrid()
            imgui.EndChild()
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"Группы поиска")

        if imgui.Button(fa.ICON_PLUS .. u8"  Сохранить текущий поиск как группу##oa_savegroup", imgui.ImVec2(-1, 26)) then
            if hasSearchTargets then
                imgui.StrCopy(newGroupNameBuf, "Сохранённая группа " .. (#objSearchGroups + 1))
                imgui.OpenPopup("##savegrouppopup")
            else
                toast_text  = "Список поиска пуст"
                toast_text2 = "Сначала добавьте объекты через 'Найти определённый объект'."
                toast_tex   = nil
                toast_timer = 150
            end
        end

        if imgui.BeginPopup(u8"##savegrouppopup") then
            imgui.Text(u8"Название группы:")
            imgui.PushItemWidth(240)
            imgui.InputText(u8"##oa_groupname", newGroupNameBuf, 64)
            imgui.PopItemWidth()
            if imgui.Button(u8"Сохранить##oa_groupsaveok", imgui.ImVec2(240, 26)) then
                local models = {}
                for model, name in pairs(objSearchTargets) do models[model] = name end
                table.insert(objSearchGroups, {name = ffi.string(newGroupNameBuf), models = models})
                saveObjSearchGroups()
                imgui.CloseCurrentPopup()
            end
            imgui.EndPopup()
        end

        imgui.Spacing()

        if #objSearchGroups == 0 then
            imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"Групп пока нет.")
        else
            for gi, grp in ipairs(objSearchGroups) do
                local cnt = 0
                for _ in pairs(grp.models) do cnt = cnt + 1 end
                if imgui.Button(fa.ICON_TAGS .. "  " .. grp.name .. " (" .. cnt .. u8")##oa_grouploader" .. gi, imgui.ImVec2(imgui.GetContentRegionAvail().x - 34, 26)) then
                    for model, name in pairs(grp.models) do
                        objSearchTargets[model] = name
                    end
                    toast_text  = u8"Группа загружена"
                    toast_text2 = grp.name .. u8" — " .. cnt .. u8" объектов добавлено в поиск"
                    toast_tex   = nil
                    toast_timer = 150
                    toast_preencoded = true
                end
                imgui.SameLine(0, 4)
                if imgui.SmallButton(fa.ICON_TRASH .. "##oa_groupdel" .. gi) then
                    table.remove(objSearchGroups, gi)
                    saveObjSearchGroups()
                    break
                end
            end
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"Исключения")

        if imgui.Button(u8"Добавить исключение##oa_addexc", imgui.ImVec2(190, 24)) then
            showExceptionPicker = not showExceptionPicker
            showExceptionList = false
            if showExceptionPicker then
                exceptionPickerList = {}
                local seen = {}
                for _, v in pairs(getAllObjects()) do
                    if isObjectOnScreen(v) then
                        local model = getObjectModel(v)
                        if sampObjectModelNames[model] and not seen[model] then
                            seen[model] = true
                            table.insert(exceptionPickerList, model)
                        end
                    end
                end
            end
        end
        imgui.SameLine()
        if imgui.Button(u8"Исключения##oa_showexc", imgui.ImVec2(140, 24)) then
            showExceptionList = not showExceptionList
            showExceptionPicker = false
        end

        if showExceptionPicker then
            imgui.Spacing()
            imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"Кликните на объект — он уйдёт в исключения и подсветится синим. Клик ещё раз — уберёт.")
            imgui.BeginChild(u8"##oa_pickgrid", imgui.ImVec2(0, 300), true)
            if #exceptionPickerList == 0 then
                imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"Рядом не найдено подходящих объектов")
            else
                drawObjExceptionGrid(exceptionPickerList, "pick")
            end
            imgui.EndChild()
        end

        if showExceptionList then
            imgui.Spacing()
            local excList = {}
            for id in pairs(exceptionObjects) do table.insert(excList, id) end
            table.sort(excList)
            imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"Клик по объекту убирает его из исключений:")
            imgui.BeginChild(u8"##oa_excgrid", imgui.ImVec2(0, 300), true)
            if #excList == 0 then
                imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"Список пуст")
            else
                drawObjExceptionGrid(excList, "exc")
            end
            imgui.EndChild()
        end
    elseif curSub == "stream" then
        renderStreamZoneScannerSubTab()
    elseif curSub == "ruler" then
        imgui.Spacing()
        local rCol = rulerActive and imgui.ImVec4(0.15, 0.65, 0.40, 1.0) or imgui.ImVec4(0.20, 0.45, 0.75, 1.0)
        imgui.PushStyleColor(imgui.Col.Button, rCol)
        local btnText = rulerActive and (fa.ICON_CUBE .. u8"  3D Линейка: ВКЛЮЧЕНА (Нажмите для отключения)") or (fa.ICON_CUBE .. u8"  Включить 3D Линейку (/truler)")
        if imgui.Button(btnText, imgui.ImVec2(imgui.GetContentRegionAvail().x, 38)) then
            cmd_ruler()
        end
        imgui.PopStyleColor()

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"ТЕКУЩИЕ ДАННЫЕ ЗАМЕРА:")
        imgui.Spacing()

        imgui.BeginChild("##ruler_metrics_view", imgui.ImVec2(0, 140), true)
            if rulerPointA then
                imgui.TextColored(imgui.ImVec4(1.0, 0.7, 0.2, 1.0), u8(string.format("Точка A: X=%.2f  Y=%.2f  Z=%.2f", rulerPointA.x, rulerPointA.y, rulerPointA.z)))
            else
                imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), u8"Точка A: не установлена (наведите прицел и нажмите ЛКМ)")
            end

            if rulerPointB then
                imgui.TextColored(imgui.ImVec4(0.2, 0.9, 0.5, 1.0), u8(string.format("Точка B: X=%.2f  Y=%.2f  Z=%.2f", rulerPointB.x, rulerPointB.y, rulerPointB.z)))
            else
                imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), u8"Точка B: не установлена (наведите прицел и нажмите ЛКМ)")
            end

            imgui.Spacing(); imgui.Separator(); imgui.Spacing()

            if rulerPointA and (rulerPointB or rulerHoverPoint) then
                local pt2 = rulerPointB or rulerHoverPoint
                local dx = pt2.x - rulerPointA.x
                local dy = pt2.y - rulerPointA.y
                local dz = pt2.z - rulerPointA.z
                local d3 = math.sqrt(dx*dx + dy*dy + dz*dz)
                local d2 = math.sqrt(dx*dx + dy*dy)
                local az = math.deg(math.atan2(dy, dx))
                if az < 0 then az = az + 360 end

                imgui.TextColored(imgui.ImVec4(0.0, 0.9, 1.0, 1.0), u8(string.format("Полная 3D дистанция:  %.2f м", d3)))
                imgui.TextColored(imgui.ImVec4(0.9, 0.9, 0.9, 1.0), u8(string.format("Горизонтальное расстояние (XY):  %.2f м", d2)))
                imgui.TextColored(imgui.ImVec4(0.9, 0.9, 0.9, 1.0), u8(string.format("Перепад по высоте (dZ):  %+.2f м", dz)))
                imgui.TextColored(imgui.ImVec4(0.7, 0.7, 0.7, 1.0), u8(string.format("Азимут направления:  %.1f°", az)))
            else
                imgui.TextDisabled(u8"Установите точки в пространстве для расчета дистанции.")
            end
        imgui.EndChild()

        imgui.Spacing()
        if imgui.Button(fa.ICON_UNDO .. u8"  Сбросить точки замера##ruler_reset_btn", imgui.ImVec2(220, 28)) then
            rulerPointA = nil
            rulerPointB = nil
            rulerMode = 0
            showToastQuick("3D Линейка", "Точки сброшены")
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"ИНСТРУКЦИЯ ПО РАБОТЕ:")
        imgui.BulletText(u8"Команда в чат /ruler включает/выключает лазерный дальномер.")
        imgui.BulletText(u8"ЛКМ или клавиша 1 — зафиксировать точку А (начало замера).")
        imgui.BulletText(u8"ЛКМ или клавиша 2 — зафиксировать точку Б (конец замера).")
        imgui.BulletText(u8"ПКМ или клавиша C — сбросить замер и начать заново.")
        imgui.BulletText(u8"ESC или /ruler — закрыть линейку.")
        imgui.BulletText(u8"Прицел автоматически примагничивается к центру объектов маппинга.")
    end

    imgui.Indent(10)
end

-- ============================================================================
-- ТЕКСТУРЫ: КАТАЛОГ И ИЗБРАННЫЕ (TEXTURE CATALOG & FAVORITES)
-- ============================================================================
TEXTURES_CAT_PATH  = ROOT .. "\\config\\Trinity Mapper Tools Config\\TMT-textures.json"
TEXTURES_IMG_DIR   = ROOT .. "\\resource\\Trinity Mapper Tools Resource\\textures\\"

textureCatalog      = {}
textureCategories   = {}
texCatSearchBuf     = imgui.new.char[128]('')
texCatActiveFilter  = 0 -- 0 = Все, 1..N = имя категории
texCatCurrentPage   = 1
texCatItemsPerPage  = 24
texCatSlot          = imgui.new.int(0)
texCatImageCache    = {}
texCatFailed        = {}
texCatLoaded        = false

local function loadTextureCatalog()
    if texCatLoaded and #textureCatalog > 0 then return end
    texCatLoaded = true
    if doesFileExist(TEXTURES_CAT_PATH) then
        local f = io.open(TEXTURES_CAT_PATH, "r")
        if f then
            local raw = f:read("*all")
            f:close()
            local ok, data = pcall(json.decode, raw)
            if ok and type(data) == "table" then
                textureCatalog = data
                local catMap = {}
                for _, t in ipairs(textureCatalog) do
                    local c = t.category or u8"Без категории"
                    catMap[c] = (catMap[c] or 0) + 1
                end
                textureCategories = {}
                for c, count in pairs(catMap) do
                    table.insert(textureCategories, { name = c, count = count })
                end
                table.sort(textureCategories, function(a, b) return a.count > b.count end)
            end
        end
    end
end

local function getCatalogTex(fileName)
    if not fileName or fileName == "" then return nil end
    local key = fileName:lower()
    if texCatImageCache[key] then return texCatImageCache[key] end
    if texCatFailed[key] then return nil end
    local p = TEXTURES_IMG_DIR .. fileName
    if not doesFileExist(p) then
        if not p:lower():match("%.png$") then
            p = p .. ".png"
        end
        if not doesFileExist(p) then
            texCatFailed[key] = true
            return nil
        end
    end
    local ok, t = pcall(imgui.CreateTextureFromFile, p)
    if ok and t then
        texCatImageCache[key] = t
        return t
    else
        texCatFailed[key] = true
        return nil
    end
end

local favTexImageCache = {}
local function getFavTexImage(t)
    if not t then return nil end
    local rawName = tostring(t.file or t.name or t.id or "")
    if rawName ~= "" then
        local key = rawName:lower()
        if favTexImageCache[key] then return favTexImageCache[key] end
    end
    if getCatalogTex then
        if rawName ~= "" then
            local img = getCatalogTex(rawName)
            if img then favTexImageCache[rawName:lower()] = img; return img end
            local fn = rawName:lower():match("%.png$") and rawName or (rawName .. ".png")
            img = getCatalogTex(fn)
            if img then favTexImageCache[rawName:lower()] = img; return img end
        end
        if t.id and tostring(t.id) ~= rawName then
            local sId = tostring(t.id)
            local img = getCatalogTex(sId)
            if img then favTexImageCache[sId:lower()] = img; return img end
            local fn = sId:lower():match("%.png$") and sId or (sId .. ".png")
            img = getCatalogTex(fn)
            if img then favTexImageCache[sId:lower()] = img; return img end
        end
    end
    local sId = tostring(t.id or "")
    if sId ~= "" and tonumber(sId) and getTex then
        local img = getTex(tonumber(sId)) or getTex(sId)
        if img then
            favTexImageCache[sId:lower()] = img
            return img
        end
    end
    return nil
end

local function renderTabFavTextures()
    imgui.Indent(10)
    local W = imgui.GetContentRegionAvail().x
    imgui.Spacing()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_PICTURE_O .. u8"  \xc8\xc7\xc1\xd0\xc0\xcd\xcd\xdb\xc5 \xd2\xc5\xca\xd1\xd2\xd3\xd0\xdb")
    imgui.SameLine(imgui.GetContentRegionAvail().x - 110)
    if imgui.Button(u8"+ \xc4\xee\xe1\xe0\xe2\xe8\xf2\xfc##texfavadd", imgui.ImVec2(100, 22)) then showTexAdd = true end
    imgui.Spacing()
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint(u8"##texfavsearch", u8"\xcf\xee\xe8\xf1\xea...", texSearchBuf, 128)
    imgui.PopItemWidth()
    imgui.Spacing()
    if imgui.Button(u8"\xc2\xf1\xe5##tx0", imgui.ImVec2(60,24)) then activeTexTab=0 end
    imgui.SameLine()
    local txi = 1
    for catName, _ in pairs(texCategories) do
        if imgui.Button(catName.."##txcat_"..txi, imgui.ImVec2(100,24)) then activeTexTab=txi end
        if imgui.IsItemClicked(1) then ctxTex=catName; ctxTexPos={x=imgui.GetMousePos().x, y=imgui.GetMousePos().y} end
        imgui.SameLine(); txi=txi+1
    end
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    local CARD_W = 260
    local CARD_H = 80
    local PAD    = 10
    local cols   = math.max(1, math.floor((W + PAD) / (CARD_W + PAD)))
    local col    = 0

    local q = ffi.string(texSearchBuf):lower()
    imgui.BeginChild(u8"##favtexlist", imgui.ImVec2(0,0), false)
    for i, t in ipairs(favTextures) do
        local show = activeTexTab == 0
        if not show then
            local ci2 = 1
            for cn, cd in pairs(texCategories) do
                if ci2 == activeTexTab and cd[tostring(i)] then show=true end
                ci2=ci2+1
            end
        end
        if q ~= "" and not t.name:lower():find(q,1,true) and not t.id:lower():find(q,1,true) then show=false end
        if show then
            if col > 0 then imgui.SameLine(0, PAD) end
            imgui.BeginGroup()
                local p = imgui.GetCursorScreenPos()
                local dl = imgui.GetWindowDrawList()

                -- Фон карточки
                dl:AddRectFilled(
                    imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x+CARD_W, p.y+CARD_H), 0xFF000000 + cardBgHex(), 8)
                dl:AddRect(
                    imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x+CARD_W, p.y+CARD_H), 0x55000000 + accentColorHex(), 8)

                -- Невидимая кнопка поверх карточки для клика
                imgui.InvisibleButton("##txcard_"..i, imgui.ImVec2(CARD_W, CARD_H))
                local txclicked  = imgui.IsItemClicked(0)
                local txrclicked = imgui.IsItemClicked(1)
                local txhovered  = imgui.IsItemHovered()
                if txhovered then
                    dl:AddRectFilled(
                        imgui.ImVec2(p.x,p.y), imgui.ImVec2(p.x+CARD_W,p.y+CARD_H), 0x15E07200, 8)
                end

                -- Превью текстуры слева (60x60)
                local imgBoxW = 60
                local imgBoxH = 60
                local imgX = p.x + 10
                local imgY = p.y + 10
                dl:AddRectFilled(imgui.ImVec2(imgX, imgY), imgui.ImVec2(imgX + imgBoxW, imgY + imgBoxH), 0xFF141820, 6.0)
                dl:AddRect(imgui.ImVec2(imgX, imgY), imgui.ImVec2(imgX + imgBoxW, imgY + imgBoxH), 0x33445566, 6.0)

                local favImg = getFavTexImage(t)
                if favImg then
                    dl:AddImage(favImg, imgui.ImVec2(imgX + 2, imgY + 2), imgui.ImVec2(imgX + imgBoxW - 2, imgY + imgBoxH - 2), imgui.ImVec2(0, 0), imgui.ImVec2(1, 1))
                else
                    dl:AddText(imgui.ImVec2(imgX + 22, imgY + 22), 0x55FFFFFF, fa.ICON_PICTURE_O)
                end

                -- Текстовая информация справа от миниатюры
                local textX = p.x + 78

                imgui.SetCursorScreenPos(imgui.ImVec2(textX, p.y + 10))
                imgui.PushTextWrapPos(p.x + CARD_W - 8)
                imgui.TextColored(imgui.ImVec4(1.0, 1.0, 1.0, 1.0), safeU8(t.name or "Текстура"))
                imgui.PopTextWrapPos()

                imgui.SetCursorScreenPos(imgui.ImVec2(textX, p.y + 32))
                local idStr = tostring(t.id or "")
                local idLabel = tonumber(t.id) and (safeU8("Номер: ") .. idStr) or (safeU8("Текстура: ") .. idStr)
                imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.60, 1.0), idLabel)

                imgui.SetCursorScreenPos(imgui.ImVec2(textX, p.y + 52))
                if t.note and t.note ~= "" then
                    imgui.TextColored(imgui.ImVec4(0.55, 0.75, 0.55, 1.0), fa.ICON_COMMENT .. " " .. safeU8(t.note))
                else
                    imgui.TextColored(imgui.ImVec4(0.45, 0.45, 0.45, 1.0), safeU8("ЛКМ  Применить | ПКМ  меню"))
                end

                if txclicked then
                    local sId = tostring(t.id or "")
                    if tonumber(sId) then
                        imgui.StrCopy(mtSearchBuf, sId)
                        SwitchTab(5)
                    else
                        setClipboardText(sId)
                        imgui.StrCopy(mtSearchBuf, sId)
                        sampSendChat(string.format("/mtset 0 %s", sId))
                        showToastQuick(safeU8("Текстура нанесена"), safeU8("Слот #0: " .. sId))
                        SwitchTab(5)
                    end
                end
                if txrclicked then ctxTex=i; ctxTexPos={x=imgui.GetMousePos().x, y=imgui.GetMousePos().y} end
            imgui.EndGroup()
            col = col+1
            if col >= cols then col=0; imgui.Spacing() end
        end
    end
    imgui.EndChild()
    if #favTextures == 0 then
        imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1.0), u8"\xcf\xf3\xf1\xf2\xee. \xcd\xe0\xe6\xec\xe8\xf2\xe5 '+ \xc4\xee\xe1\xe0\xe2\xe8\xf2\xfc'.")
    end
    imgui.EndChild()

    -- ПКМ по текстуре
    if ctxTex and ctxTexPos and type(ctxTex) == "number" then
        imgui.SetNextWindowPos(imgui.ImVec2(ctxTexPos.x, ctxTexPos.y), imgui.Cond.Always)
        imgui.Begin(u8"##ctxtex", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.AlwaysAutoResize)
            if not imgui.IsWindowHovered() and imgui.IsMouseClicked(0) then ctxTex=nil; ctxTexPos=nil; showTexCatCreate=false end
            if imgui.Button(fa.ICON_TRASH .. u8" \xd3\xe4\xe0\xeb\xe8\xf2\xfc##txdel", imgui.ImVec2(185,0)) then
                for _, cd in pairs(texCategories) do cd[tostring(ctxTex)]=nil end
                table.remove(favTextures, ctxTex)
                saveFavTextures(); saveTexCategories()
                ctxTex=nil; ctxTexPos=nil
            end
            if imgui.Button(fa.ICON_PENCIL .. u8" \xcf\xe5\xf0\xe5\xe8\xec\xe5\xed\xee\xe2\xe0\xf2\xfc##texren", imgui.ImVec2(185,0)) then
                renameTex = ctxTex
                imgui.StrCopy(renameTexBuf, favTextures[ctxTex] and favTextures[ctxTex].name or "")
                ctxTex=nil; ctxTexPos=nil
            end
            if imgui.Button(fa.ICON_PENCIL .. u8" \xc7\xe0\xec\xe5\xf2\xea\xe0##txnote", imgui.ImVec2(185,0)) then
                editTexNote = ctxTex
                local cur = favTextures[ctxTex] and favTextures[ctxTex].note or ""
                imgui.StrCopy(editTexNoteBuf, cur)
                ctxTex=nil; ctxTexPos=nil
            end
            imgui.Separator()
            imgui.Text(u8"\xca\xe0\xf2\xe5\xe3\xee\xf0\xe8\xff:")
            imgui.Separator()
            if showTexCatCreate then
                imgui.PushItemWidth(140)
                if imgui.InputText(u8"##ntxcn", texCatNameBuf, 64, imgui.InputTextFlags.EnterReturnsTrue) then
                    local cn = ffi.string(texCatNameBuf)
                    if cn~="" then if not texCategories[cn] then texCategories[cn]={} end; texCategories[cn][tostring(ctxTex)]=true; saveTexCategories() end
                    imgui.StrCopy(texCatNameBuf,''); showTexCatCreate=false; ctxTex=nil; ctxTexPos=nil
                end
                imgui.PopItemWidth()
            else
                if imgui.Button(u8"+ \xd1\xee\xe7\xe4\xe0\xf2\xfc \xea\xe0\xf2\xe5\xe3\xee\xf0\xe8\xfe##txcc", imgui.ImVec2(185,0)) then showTexCatCreate=true end
                for cn, cd in pairs(texCategories) do
                    local inCat = cd[tostring(ctxTex)]
                    if imgui.Button((inCat and "- " or "+ ")..cn.."##txcc_"..cn, imgui.ImVec2(155,0)) then
                        if inCat then cd[tostring(ctxTex)]=nil else cd[tostring(ctxTex)]=true end
                        saveTexCategories(); ctxTex=nil; ctxTexPos=nil
                    end
                    imgui.SameLine()
                    if imgui.Button(u8"X##txdel_"..cn, imgui.ImVec2(26,0)) then
                        texCategories[cn]=nil; saveTexCategories()
                        if activeTexTab~=0 then activeTexTab=0 end; ctxTex=nil; ctxTexPos=nil
