        imgui.SetNextWindowPos(imgui.ImVec2(ctxTexPos.x, ctxTexPos.y), imgui.Cond.Always)
        imgui.Begin(u8"##ctxtexcat", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.AlwaysAutoResize)
