            imgui.PushItemWidth(-1)
            imgui.InputText(u8"##txnoteinp", editTexNoteBuf, 256)
            imgui.PopItemWidth()
            imgui.Spacing(); imgui.Separator()
            if imgui.Button(u8"\xd1\xee\xf5\xf0\xe0\xed\xe8\xf2\xfc##txnotesv", imgui.ImVec2(155,28)) then
                local txt = ffi.string(editTexNoteBuf)
                if favTextures[editTexNote] then favTextures[editTexNote].note = txt end
                saveFavTextures(); editTexNote = nil
            end
            imgui.SameLine()
            if imgui.Button(u8"\xce\xf2\xec\xe5\xed\xe0##txnotecn", imgui.ImVec2(155,28)) then
                editTexNote = nil
            end
        imgui.End()
    end

    -- Окно добавить
    imgui.Indent(10)
end

local function renderTabScripts()
    imgui.Indent(10)
    local W = imgui.GetContentRegionAvail().x
    imgui.Spacing()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_CODE .. u8"  СКРИПТЫ")
    imgui.Spacing()

    -- Переключатель подраздела: "Скрипты" (основной) / "Избранные скрипты"
    local subBtnW = (imgui.GetContentRegionAvail().x - 8) / 2
    local isFavSub = (scriptsSubSection == "fav")

    if not isFavSub then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
    if imgui.Button(fa.ICON_CODE .. u8"  Скрипты##scsub_main", imgui.ImVec2(subBtnW, 30)) then
        scriptsSubSection = "main"
    end
    if not isFavSub then imgui.PopStyleColor() end

    imgui.SameLine(0, 8)

    if isFavSub then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
    if imgui.Button(fa.ICON_STAR .. u8"  Избранные скрипты##scsub_fav", imgui.ImVec2(subBtnW, 30)) then
        scriptsSubSection = "fav"
    end
    if isFavSub then imgui.PopStyleColor() end

    imgui.Spacing()
    if imgui.Button(fa.ICON_CUBES .. u8"  Автоконфигуратор ивент-блоков (/eblock)##open_eblock_btn", imgui.ImVec2(-1, 30)) then
        eblock.windowOpen[0] = not eblock.windowOpen[0]
    end
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    if scriptsSubSection == "main" then
        local blockTypes = {
            {id = "trigger", name = u8"Блок триггер", code = "trigger", color = imgui.ImVec4(0.80, 0.20, 0.20, 1.0)},
            {id = "action",  name = u8"Блок действия", code = "action",  color = imgui.ImVec4(0.90, 0.70, 0.20, 1.0)},
            {id = "visual",  name = u8"Блок визуал",   code = "visual",  color = imgui.ImVec4(0.75, 0.40, 1.00, 1.0)},
        }

        if not scriptViewId then
            -- Сетка карточек добавленных скриптов
            if imgui.Button(fa.ICON_PLUS .. u8" Добавить скрипт##scriptcardadd", imgui.ImVec2(180, 30)) then
                showScriptCardAdd = true
                imgui.StrCopy(scriptCardNameBuf, "")
                imgui.StrCopy(scriptCardIdBuf, "")
            end
            imgui.Spacing(); imgui.Separator(); imgui.Spacing()

            if #scriptCards == 0 then
                imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), u8"Скриптов нет. Нажмите «+ Добавить скрипт».")
            else
                local cardW, cardH = 130, 165
                local imgSize = 80
                local pad = 10
                local avail = imgui.GetContentRegionAvail().x
                local cols = math.max(1, math.floor((avail + pad) / (cardW + pad)))
                local col = 0

                for i, card in ipairs(scriptCards) do
                    local p = imgui.GetCursorScreenPos()
                    imgui.GetWindowDrawList():AddRectFilled(
                        imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + cardW, p.y + cardH),
                        0xFF000000 + cardBgHex(), 8)
                    imgui.GetWindowDrawList():AddRect(
                        imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x + cardW, p.y + cardH),
                        0x66000000 + accentColorHex(), 8)

                    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + (cardW - imgSize) / 2, p.y + 10))
                    local tex = getTex("3386")
                    if tex then
                        imgui.Image(tex, imgui.ImVec2(imgSize, imgSize))
                    end

                    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 6, p.y + imgSize + 16))
                    imgui.PushTextWrapPos(p.x + cardW - 6)
                    imgui.TextColored(imgui.ImVec4(1,1,1,1), card.name)
                    imgui.PopTextWrapPos()

                    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 6, p.y + imgSize + 36))
                    imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1.0), "#" .. card.id)

                    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 6, p.y + cardH - 20))
                    imgui.TextColored(imgui.ImVec4(0.45,0.45,0.45,1.0), u8"ЛКМ: открыть")
                    imgui.SetCursorScreenPos(imgui.ImVec2(p.x + 6, p.y + cardH - 8))

                    imgui.SetCursorScreenPos(p)
                    local cardClicked = imgui.InvisibleButton("##scriptcard" .. i, imgui.ImVec2(cardW, cardH)) or imgui.IsItemClicked(0)
                    if cardClicked then
                        scriptViewId = card.id
                        local sidStr = tostring(card.id):match("%d+") or tostring(card.id)
                        safeSendScr(sidStr)
                    end
                    if imgui.IsItemClicked(1) then
                        ctxScriptCard = i
                        ctxScriptCardPos = imgui.GetMousePos()
                        imgui.OpenPopup("##ctxscriptcard")
                    end

                    col = col + 1
                    if col >= cols then
                        col = 0
                        imgui.SetCursorScreenPos(imgui.ImVec2(p.x, p.y + cardH + pad))
                    else
                        imgui.SetCursorScreenPos(imgui.ImVec2(p.x + cardW + pad, p.y))
                    end
                end
                if col ~= 0 then imgui.NewLine() end
            end

            if ctxScriptCard then
                imgui.SetNextWindowPos(ctxScriptCardPos)
                if imgui.BeginPopup("##ctxscriptcard") then
                    if imgui.Selectable(fa.ICON_PENCIL .. u8"  Переименовать") then
                        renameScriptCardIdx = ctxScriptCard
                        imgui.StrCopy(renameScriptCardBuf, scriptCards[ctxScriptCard].name)
                    end
                    if imgui.Selectable(fa.ICON_TRASH .. u8"  Удалить") then
                        table.remove(scriptCards, ctxScriptCard)
                        saveScriptCards()
                        ctxScriptCard = nil
                    end
                    imgui.EndPopup()
                else
                    ctxScriptCard = nil
                end
            end

            if popupShouldDraw("scriptcardadd", showScriptCardAdd) then
                local a = popupFadeAlpha("scriptcardadd", showScriptCardAdd)
                local closeAdd = imgui.new.bool(true)

                -- 1. ПОЛНОЭКРАННОЕ ЗАТЕМНЕНИЕ ФОНА
                imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
                imgui.SetNextWindowSize(imgui.ImVec2(sw, sh), imgui.Cond.Always)
                imgui.SetNextWindowBgAlpha(0.70 * a)
                imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0, 0, 0, 1))
                imgui.Begin("##modalDimBackdropScriptCard", nil,
                    imgui.WindowFlags.NoTitleBar +
                    imgui.WindowFlags.NoResize +
                    imgui.WindowFlags.NoMove +
                    imgui.WindowFlags.NoScrollbar +
                    imgui.WindowFlags.NoSavedSettings)
                imgui.End()
                imgui.PopStyleColor()

                -- 2. УВЕЛИЧЕННОЕ ОКНО ДОБАВЛЕНИЯ СКРИПТА
                imgui.SetNextWindowSize(imgui.ImVec2(500, 195), imgui.Cond.Always)
                imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
                imgui.SetNextWindowBgAlpha(0.98 * a)
                imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, a)
                imgui.PushStyleColor(imgui.Col.TitleBgActive, accentColorA(1.0))
                imgui.Begin(u8"Добавить скрипт##scriptcardaddwin", closeAdd, imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoScrollbar)
                    imgui.Spacing()
                    imgui.Text(u8"Название:")
                    imgui.PushItemWidth(-1)
                    imgui.InputTextWithHint(u8"##scriptcardname", u8"Введите название скрипта...", scriptCardNameBuf, 64)
                    imgui.PopItemWidth()
                    imgui.Spacing()
                    imgui.Text(u8"Номер скрипта:")
                    imgui.PushItemWidth(-1)
                    imgui.InputTextWithHint(u8"##scriptcardid", u8"Например: 51", scriptCardIdBuf, 16, imgui.InputTextFlags.CharsDecimal)
                    imgui.PopItemWidth()
                    imgui.Spacing(); imgui.Separator(); imgui.Spacing(); imgui.Spacing()

                    local btnW = (imgui.GetContentRegionAvail().x - 12) / 2
                    if imgui.Button(u8"Добавить##scriptcardok", imgui.ImVec2(btnW, 38)) then
                        local nm = ffi.string(scriptCardNameBuf)
                        local sid = ffi.string(scriptCardIdBuf)
                        if nm == "" then nm = u8"Без названия" end
                        if sid ~= "" then
                            table.insert(scriptCards, {id = sid, name = nm, date = os.time()})
                            saveScriptCards()
                            imgui.StrCopy(scriptCardNameBuf, "")
                            imgui.StrCopy(scriptCardIdBuf, "")
                            showScriptCardAdd = false
                        end
                    end
                    imgui.SameLine(0, 12)
                    if imgui.Button(u8"Отмена##scriptcardcancel", imgui.ImVec2(btnW, 38)) then
                        imgui.StrCopy(scriptCardNameBuf, "")
                        imgui.StrCopy(scriptCardIdBuf, "")
                        showScriptCardAdd = false
                    end
                imgui.PopStyleColor()
                if not closeAdd[0] then showScriptCardAdd = false end
                imgui.End()
                imgui.PopStyleVar()
            end

            if renameScriptCardIdx then
                local closeRn = imgui.new.bool(true)
                imgui.SetNextWindowSize(imgui.ImVec2(300, 120), imgui.Cond.Always)
                imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
                imgui.PushStyleColor(imgui.Col.TitleBgActive, accentColorA(1.0))
                imgui.Begin(u8"Переименовать скрипт##scriptcardrenwin", closeRn, imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse)
                    imgui.PushItemWidth(-1)
                    imgui.InputText(u8"##scriptcardrenamebuf", renameScriptCardBuf, 64)
                    imgui.PopItemWidth()
                    imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                    if imgui.Button(u8"Сохранить##scriptcardrenok", imgui.ImVec2(130, 30)) then
                        local nm = ffi.string(renameScriptCardBuf)
                        if nm ~= "" and scriptCards[renameScriptCardIdx] then
                            scriptCards[renameScriptCardIdx].name = nm
                            saveScriptCards()
                        end
                        renameScriptCardIdx = nil
                    end
                    imgui.SameLine(0, 8)
                    if imgui.Button(u8"Отмена##scriptcardrencancel", imgui.ImVec2(130, 30)) then
                        renameScriptCardIdx = nil
                    end
                imgui.PopStyleColor()
                if not closeRn[0] then renameScriptCardIdx = nil end
                imgui.End()
            end
        else
            -- Экран блоков конкретного скрипта
            local viewId = scriptViewId -- фиксируем на весь этот кадр, чтобы "Назад" не обнулял на полпути рендера
            if imgui.Button(fa.ICON_ARROW_LEFT .. u8"  Назад##scriptviewback", imgui.ImVec2(100, 26)) then
                scriptViewId = nil
                viewId = nil
            end
            if not viewId then
                imgui.Unindent(10)
                return
            end
            imgui.SameLine()
            local cardName = nil
            for _, c in ipairs(scriptCards) do if c.id == viewId then cardName = c.name end end
            imgui.TextColored(accentColor(), "  " .. (cardName and (cardName .. " ") or "") .. u8"Скрипт #" .. viewId)
            imgui.SameLine(0, 10)
            if imgui.Button(fa.ICON_CODE .. u8"  /scr " .. tostring(viewId) .. "##scrquickbtn", imgui.ImVec2(95, 26)) then
                safeSendScr(viewId)
            end
            imgui.SameLine(imgui.GetContentRegionAvail().x - 150)
            if imgui.Button(fa.ICON_PLUS .. u8" Создать блок##scriptaddblock", imgui.ImVec2(150, 0)) then
                showCreateBlock = true
                createBlockSelected = "trigger"
            end
            imgui.Spacing(); imgui.Separator(); imgui.Spacing()

            local blocks = scriptBlocks[scriptViewId] or {}
            if #blocks == 0 then
                imgui.Spacing()
                imgui.TextColored(imgui.ImVec4(0.5, 0.5, 0.5, 1.0), u8"  Блоков нет. Нажмите «+ Создать блок» вверху.")
            else
                for i, b in ipairs(blocks) do
                    local bt = nil
                    for _, t in ipairs(blockTypes) do if t.id == b.type then bt = t end end

                    imgui.PushIDInt(i)
                    imgui.Spacing()
                    imgui.TextColored(bt and bt.color or imgui.ImVec4(1,1,1,1), "[" .. (bt and bt.name or b.type) .. "]")
                    imgui.SameLine(0, 10)

                    if b.serverId then
                        imgui.TextColored(accentColor(), "#" .. tostring(b.serverId))
                    else
                        imgui.TextColored(imgui.ImVec4(0.9, 0.45, 0.45, 1.0), u8"[ID не привязан]")
                    end
                    if imgui.IsItemHovered() then
                        imgui.SetTooltip(u8"Кликните для изменения или привязки серверного ID (#)")
                    end
                    if imgui.IsItemClicked(0) and (b.type == "visual" or b.type == "trigger") then
                        activePresetBlockIdx = i
                        imgui.StrCopy(presetBlockIdBuf, b.serverId and tostring(b.serverId) or "")
                        showBlockPresetsModal = true
                    end

                    imgui.SameLine(0, 12)
                    imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), os.date("%d.%m.%Y %H:%M", b.date or 0))

                    local availW = imgui.GetContentRegionAvail().x
                    if b.type == "visual" or b.type == "trigger" then
                        imgui.SameLine(availW - 195)
                        local btnIcon = (b.type == "visual") and fa.ICON_EYE or fa.ICON_BOLT
                        if imgui.Button(btnIcon .. u8"  Настроить##scblockpreset", imgui.ImVec2(105, 24)) then
                            activePresetBlockIdx = i
                            imgui.StrCopy(presetBlockIdBuf, b.serverId and tostring(b.serverId) or "")
                            showBlockPresetsModal = true
                        end
                        imgui.SameLine(availW - 85)
                    else
                        imgui.SameLine(availW - 85)
                    end

                    if imgui.Button(fa.ICON_TRASH .. u8"  Удалить##scblockdel", imgui.ImVec2(85, 24)) then
                        table.remove(blocks, i)
                        scriptBlocks[scriptViewId] = blocks
                        saveScriptBlocks()
                        imgui.PopID()
                        break
                    end

                    imgui.Spacing()
                    imgui.Separator()
                    imgui.PopID()
                end
            end
        end

        -- Модальное окно выбора шаблонов действия (крупный современный интерфейс)
        -- Модальное окно настройки визуал-блока
        -- Модальное окно настройки визуал-блока
        -- Модальное окно настройки блока
        if showBlockPresetsModal and scriptViewId then
            local closePM = imgui.new.bool(true)
            local sw, sh = getScreenResolution()
            local curTh = THEMES[currentTheme] or THEMES.bee

            -- Затемнение фона
            imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
            imgui.SetNextWindowSize(imgui.ImVec2(sw, sh), imgui.Cond.Always)
            imgui.SetNextWindowBgAlpha(0.65)
            imgui.PushStyleColor(imgui.Col.WindowBg, imgui.ImVec4(0, 0, 0, 1))
            imgui.Begin("##modalDimBackdropPresets", nil,
                imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize +
                imgui.WindowFlags.NoMove + imgui.WindowFlags.NoScrollbar +
                imgui.WindowFlags.NoSavedSettings)
            imgui.End()
            imgui.PopStyleColor()

            local blocks = scriptBlocks[scriptViewId] or {}
            local curB = activePresetBlockIdx and blocks[activePresetBlockIdx]

            local pW, pH = 780, 560
            imgui.SetNextWindowSize(imgui.ImVec2(pW, pH), imgui.Cond.Always)
            imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
            imgui.PushStyleColor(imgui.Col.TitleBgActive, accentColorA(1.0))
            imgui.PushStyleColor(imgui.Col.WindowBg, curTh.WindowBg)
            imgui.PushStyleColor(imgui.Col.Border, accentColorA(0.4))
            imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(16, 14))

            local modalTitle = (curB and curB.type == "trigger") and (fa.ICON_BOLT .. u8"  Настройка триггер-блока##presetwin") or (fa.ICON_EYE .. u8"  Настройка визуал-блока##presetwin")
            imgui.Begin(modalTitle, closePM,
                imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoScrollbar)

                -- Верхняя панель: информация и серверный номер блока
                imgui.TextColored(accentColor(), fa.ICON_INFO_CIRCLE .. u8"  Скрипт #" .. tostring(scriptViewId))
                imgui.SameLine(0, 14)
                imgui.TextColored(imgui.ImVec4(0.75, 0.75, 0.75, 1.0), u8"|  Серверный ID блока (#):")
                imgui.SameLine(0, 8)
                imgui.PushItemWidth(70)
                imgui.InputText(u8"##blkmodalid", presetBlockIdBuf, 16, imgui.InputTextFlags.CharsDecimal)
                imgui.PopItemWidth()
                imgui.SameLine(0, 8)
                if imgui.Button(u8"Сохранить ID##savepresetidbtn", imgui.ImVec2(115, 24)) then
                    local sid = tonumber(ffi.string(presetBlockIdBuf))
                    if sid and curB then
                        curB.serverId = sid
                        scriptBlocks[scriptViewId] = blocks
                        saveScriptBlocks()
                        toast_text  = "ID #" .. sid .. " сохранен!"
                        toast_text2 = ""
                        toast_timer = 100
                    end
                end

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                local availW = imgui.GetContentRegionAvail().x

                if curB and curB.type == "trigger" then
                    -- Вкладки режимов триггера: Пикап, Зона, Зона с кнопкой
                    local isPickup  = (triggerBlockTab == "pickup")
                    local isZone    = (triggerBlockTab == "zone")
                    local isKeyZone = (triggerBlockTab == "keyzone")
                    local btnW3 = math.floor((availW - 16) / 3)

                    if isPickup then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
                    if imgui.Button(fa.ICON_DIAMOND .. u8"  Пикап##trtab_pick", imgui.ImVec2(btnW3, 36)) then
                        triggerBlockTab = "pickup"
                    end
                    if isPickup then imgui.PopStyleColor() end

                    imgui.SameLine(0, 8)
                    if isZone then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
                    if imgui.Button(fa.ICON_GLOBE .. u8"  Зона##trtab_zone", imgui.ImVec2(btnW3, 36)) then
                        triggerBlockTab = "zone"
                    end
                    if isZone then imgui.PopStyleColor() end

                    imgui.SameLine(0, 8)
                    if isKeyZone then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
                    if imgui.Button(fa.ICON_DOT_CIRCLE_O .. u8"  Зона с кнопкой##trtab_kzone", imgui.ImVec2(btnW3, 36)) then
                        triggerBlockTab = "keyzone"
                    end
                    if isKeyZone then imgui.PopStyleColor() end

                    imgui.Spacing()
                    local targetTrigTypeName = isPickup and "Пикап" or (isZone and "Зона" or "Зона с кнопкой")
                    if imgui.Button(fa.ICON_CHECK_CIRCLE .. u8"  Установить тип «" .. u8(targetTrigTypeName) .. u8"» на сервере##btnsettrigtype", imgui.ImVec2(availW, 28)) then
                        local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                        if sid and sid > 0 then
                            if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                            applyBlockTriggerType(sid, targetTrigTypeName)
                            showBlockPresetsModal = false
                        else
                            toast_text = "Укажите ID блока!"; toast_timer = 120
                        end
                    end

                    imgui.Spacing()
                    imgui.Separator()
                    imgui.Spacing()

                    -- Параметры триггера
                    imgui.TextColored(accentColor(), fa.ICON_SLIDERS .. u8"  ПАРАМЕТРЫ ТРИГГЕРА:")
                    imgui.Spacing()

                    -- 1. Размер зоны подбора
                    imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Размер зоны подбора (в метрах):")
                    imgui.PushItemWidth(100)
                    imgui.InputText(u8"##trigradinp", presetTrigRadiusBuf, 16, imgui.InputTextFlags.CharsDecimal)
                    imgui.PopItemWidth()
                    imgui.SameLine(0, 8)
                    if imgui.Button(fa.ICON_CHECK .. u8"  Применить размер##btnapplyrad", imgui.ImVec2(160, 24)) then
                        local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                        local rad = tonumber(ffi.string(presetTrigRadiusBuf))
                        if not sid or sid <= 0 then
                            toast_text = "Укажите ID блока!"; toast_timer = 120
                        elseif not rad then
                            toast_text = "Введите размер зоны!"; toast_timer = 120
                        else
                            if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                            applyBlockTriggerRadius(sid, rad)
                            showBlockPresetsModal = false
                        end
                    end
                    imgui.SameLine(0, 10)
                    imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"Быстрые:")
                    for _, rVal in ipairs({"1", "2", "3", "5", "10"}) do
                        imgui.SameLine(0, 4)
                        if imgui.Button(rVal .. u8"м##qrad_" .. rVal) then
                            imgui.StrCopy(presetTrigRadiusBuf, rVal)
                        end
                    end

                    imgui.Spacing()
                    -- 2. Тип подбора
                    imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Тип подбора (переключает режим на сервере):")
                    local pTypes = {
                        {target = "Только пешком",         label = u8"Только пешком"},
                        {target = "Пешком и в транспорте", label = u8"Пешком и в авто"},
                        {target = "Только в транспорте",   label = u8"Только в транспорте"},
                    }
                    local pBtnW = math.floor((availW - 16) / 3)
                    for pti, pt in ipairs(pTypes) do
                        if imgui.Button(pt.label .. "##ptbtn_" .. pti, imgui.ImVec2(pBtnW, 26)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            if sid and sid > 0 then
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockTriggerPickupType(sid, pt.target)
                                showBlockPresetsModal = false
                            else
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            end
                        end
                        if pti < #pTypes then imgui.SameLine(0, 8) end
                    end

                    -- 3. Если выбран Пикап: модель пикапа
                    if isPickup then
                        imgui.Spacing()
                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Модель пикапа (ID модели):")
                        imgui.PushItemWidth(100)
                        imgui.InputText(u8"##trigmodinp", presetTrigModelBuf, 16, imgui.InputTextFlags.CharsDecimal)
                        imgui.PopItemWidth()
                        imgui.SameLine(0, 8)
                        if imgui.Button(fa.ICON_CHECK .. u8"  Применить модель##btnapplymodel", imgui.ImVec2(160, 24)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            local mid = tonumber(ffi.string(presetTrigModelBuf))
                            if not sid or sid <= 0 then
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            elseif not mid then
                                toast_text = "Введите ID модели!"; toast_timer = 120
                            else
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockTriggerModel(sid, mid)
                                showBlockPresetsModal = false
                            end
                        end
                        imgui.SameLine(0, 10)
                        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"Быстрые:")
                        local qModels = {
                            {id = "1239", name = u8"Инфо (1239)"},
                            {id = "1274", name = u8"Доллар (1274)"},
                            {id = "1240", name = u8"+ HP (1240)"},
                            {id = "1242", name = u8"Броня (1242)"},
                        }
                        for _, qm in ipairs(qModels) do
                            imgui.SameLine(0, 4)
                            if imgui.Button(qm.name .. "##qmod_" .. qm.id) then
                                imgui.StrCopy(presetTrigModelBuf, qm.id)
                            end
                        end
                    end

                    -- 4. Если выбрана Зона с кнопкой: выбор клавиши
                    if isKeyZone then
                        imgui.Spacing()
                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Кнопка активации (кликните клавишу для применения на сервере):")
                        local trigKeys = {"LMB", "RMB", "SPACE", "ENTER", "ALT", "Y", "N", "H"}
                        for ki, kName in ipairs(trigKeys) do
                            if imgui.Button(kName .. "##trigkey_" .. ki, imgui.ImVec2(70, 26)) then
                                local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                                if sid and sid > 0 then
                                    if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                    applyBlockTriggerButton(sid, kName)
                                    showBlockPresetsModal = false
                                else
                                    toast_text = "Укажите ID блока!"; toast_timer = 120
                                end
                            end
                            if ki < #trigKeys then imgui.SameLine(0, 6) end
                        end
                    end

                    imgui.Spacing()
                    imgui.Separator()
                    imgui.Spacing()

                    -- Секция: Вызываемые блоки действия
                    imgui.TextColored(accentColor(), fa.ICON_SHARE_ALT .. u8"  ВЫЗЫВАЕМЫЕ БЛОКИ ДЕЙСТВИЯ (до 10 шт):")
                    imgui.Spacing()
                    imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Номер блока действия (IDX), который будет запускаться:")
                    imgui.PushItemWidth(120)
                    imgui.InputText(u8"##trigcallinp", presetTrigCallBuf, 16, imgui.InputTextFlags.CharsDecimal)
                    imgui.PopItemWidth()
                    imgui.SameLine(0, 8)
                    if imgui.Button(fa.ICON_PLUS .. u8"  Добавить вызываемый блок##btnaddcall", imgui.ImVec2(220, 24)) then
                        local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                        local cIdx = tonumber(ffi.string(presetTrigCallBuf))
                        if not sid or sid <= 0 then
                            toast_text = "Укажите ID блока!"; toast_timer = 120
                        elseif not cIdx then
                            toast_text = "Введите IDX блока действия!"; toast_timer = 120
                        else
                            if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                            applyBlockTriggerAddCall(sid, cIdx)
                            showBlockPresetsModal = false
                        end
                    end

                    -- Быстрые подсказки существующих блоков действия из текущего скрипта
                    local actionBlocks = {}
                    for bi, blk in ipairs(blocks) do
                        if blk.type == "action" and blk.serverId then
                            table.insert(actionBlocks, blk.serverId)
                        end
                    end
                    if #actionBlocks > 0 then
                        imgui.SameLine(0, 10)
                        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), u8"Действия в скрипте:")
                        for _, abId in ipairs(actionBlocks) do
                            imgui.SameLine(0, 4)
                            if imgui.Button("#" .. tostring(abId) .. "##qact_" .. abId) then
                                imgui.StrCopy(presetTrigCallBuf, tostring(abId))
                            end
                        end
                    end

                else
                    -- Вкладки режимов: Лейбл (3D Текст) или Актёр (NPC)
                    local isLabel = (visualBlockTab == "label")
                    local isActor = (visualBlockTab == "actor")
                    local btnW2 = math.floor((availW - 10) / 2)

                    if isLabel then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
                    if imgui.Button(fa.ICON_TAG .. u8"  Лейбл (3D Текст)##tab_label", imgui.ImVec2(btnW2, 36)) then
                        visualBlockTab = "label"
                    end
                    if isLabel then imgui.PopStyleColor() end

                    imgui.SameLine(0, 10)

                    if isActor then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
                    if imgui.Button(fa.ICON_USER .. u8"  Актёр (NPC)##tab_actor", imgui.ImVec2(btnW2, 36)) then
                        visualBlockTab = "actor"
                    end
                    if isActor then imgui.PopStyleColor() end

                    imgui.Spacing()
                    imgui.Separator()
                    imgui.Spacing()

                    -- РЕЖИМ 1: НАСТРОЙКИ ЛЕЙБЛА
                    if visualBlockTab == "label" then
                        if imgui.Button(fa.ICON_CHECK_CIRCLE .. u8"  Установить тип «Лейбл» на сервере##btnsettypelabel", imgui.ImVec2(availW, 28)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            if sid and sid > 0 then
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockVisualPreset(sid, "Лейбл")
                                showBlockPresetsModal = false
                            else
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            end
                        end

                        imgui.Spacing()
                        imgui.Separator()
                        imgui.Spacing()

                        imgui.TextColored(accentColor(), fa.ICON_TAG .. u8"  ПАРАМЕТРЫ ЛЕЙБЛА (3D ТЕКСТ):")
                        imgui.Spacing()

                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Текст сообщения (поддерживает цветные теги {RRGGBB}):")
                        imgui.PushItemWidth(availW - 175)
                        imgui.InputText(u8"##lbltextinput", presetBlockLabelBuf, 256)
                        imgui.PopItemWidth()
                        imgui.SameLine(0, 8)
                        if imgui.Button(fa.ICON_CHECK .. u8"  Применить текст##btnapplylbl", imgui.ImVec2(165, 24)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            local ltext = ffi.string(presetBlockLabelBuf)
                            if not sid or sid <= 0 then
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            elseif ltext == "" then
                                toast_text = "Введите текст лейбла!"; toast_timer = 120
                            else
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockLabelText(sid, ltext)
                                showBlockPresetsModal = false
                            end
                        end

                        imgui.Spacing()
                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), fa.ICON_PAINT_BRUSH .. u8"  Палитра цветов (кликните, чтобы вставить тег цвета в текст):")
                        local labelPalette = {
                            {tag = "{FFFFFF}", col = imgui.ImVec4(1.0, 1.0, 1.0, 1.0)},
                            {tag = "{FF3333}", col = imgui.ImVec4(1.0, 0.2, 0.2, 1.0)},
                            {tag = "{33FF33}", col = imgui.ImVec4(0.2, 1.0, 0.2, 1.0)},
                            {tag = "{3399FF}", col = imgui.ImVec4(0.2, 0.6, 1.0, 1.0)},
                            {tag = "{FFFF33}", col = imgui.ImVec4(1.0, 1.0, 0.2, 1.0)},
                            {tag = "{FF9933}", col = imgui.ImVec4(1.0, 0.6, 0.2, 1.0)},
                            {tag = "{CC33FF}", col = imgui.ImVec4(0.8, 0.2, 1.0, 1.0)},
                            {tag = "{FF66CC}", col = imgui.ImVec4(1.0, 0.4, 0.8, 1.0)},
                            {tag = "{999999}", col = imgui.ImVec4(0.6, 0.6, 0.6, 1.0)},
                            {tag = "{000000}", col = imgui.ImVec4(0.1, 0.1, 0.1, 1.0)}
                        }

                        for pi, pal in ipairs(labelPalette) do
                            imgui.PushStyleColor(imgui.Col.Button, pal.col)
                            imgui.PushStyleColor(imgui.Col.ButtonHovered, pal.col)
                            imgui.PushStyleColor(imgui.Col.ButtonActive, pal.col)
                            if imgui.Button("  ##palbtn_" .. pi, imgui.ImVec2(28, 22)) then
                                local curStr = ffi.string(presetBlockLabelBuf)
                                imgui.StrCopy(presetBlockLabelBuf, curStr .. pal.tag)
                            end
                            if imgui.IsItemHovered() then
                                imgui.SetTooltip(pal.tag)
                            end
                            imgui.PopStyleColor(3)
                            if pi < #labelPalette then imgui.SameLine(0, 5) end
                        end

                        imgui.SameLine(0, 10)
                        imgui.PushItemWidth(100)
                        if imgui.ColorEdit4(u8"##lblcustomcol", labelCustomColorPicker, imgui.ColorEditFlags.NoInputs + imgui.ColorEditFlags.AlphaBar) then end
                        imgui.PopItemWidth()
                        imgui.SameLine(0, 4)
                        if imgui.Button(u8"+ Свой цвет##addcusttagbtn") then
                            local r = math.floor(labelCustomColorPicker[0] * 255 + 0.5)
                            local g = math.floor(labelCustomColorPicker[1] * 255 + 0.5)
                            local b = math.floor(labelCustomColorPicker[2] * 255 + 0.5)
                            local hexTag = string.format("{%02X%02X%02X}", r, g, b)
                            local curStr = ffi.string(presetBlockLabelBuf)
                            imgui.StrCopy(presetBlockLabelBuf, curStr .. hexTag)
                        end

                        imgui.Spacing()
                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), fa.ICON_EYE .. u8"  Предпросмотр текста (как будет выглядеть в игре):")
                        imgui.BeginChild("##lblpreviewbox", imgui.ImVec2(availW, 100), true)
                            local rawText = ffi.string(presetBlockLabelBuf)
                            if rawText == "" then
                                imgui.TextDisabled(u8"(введите текст выше для предпросмотра)")
                            else
                                local curColor = imgui.ImVec4(1, 1, 1, 1)
                                local lastPos = 1
                                local isFirstSegment = true
                                while lastPos <= #rawText do
                                    local tagStart, tagEnd, hexColor = rawText:find("{(%x%x%x%x%x%x)}", lastPos)
                                    if tagStart then
                                        if tagStart > lastPos then
                                            local part = rawText:sub(lastPos, tagStart - 1)
                                            if not isFirstSegment then imgui.SameLine(0, 0) end
                                            imgui.TextColored(curColor, u8(part))
                                            isFirstSegment = false
                                        end
                                        local r = tonumber(hexColor:sub(1, 2), 16) / 255
                                        local g = tonumber(hexColor:sub(3, 4), 16) / 255
                                        local b = tonumber(hexColor:sub(5, 6), 16) / 255
                                        curColor = imgui.ImVec4(r, g, b, 1)
                                        lastPos = tagEnd + 1
                                    else
                                        local part = rawText:sub(lastPos)
                                        if not isFirstSegment then imgui.SameLine(0, 0) end
                                        imgui.TextColored(curColor, u8(part))
                                        break
                                    end
                                end
                            end
                        imgui.EndChild()

                    -- РЕЖИМ 2: НАСТРОЙКИ АКТЁРА
                    elseif visualBlockTab == "actor" then
                        if imgui.Button(fa.ICON_CHECK_CIRCLE .. u8"  Установить тип «Актёр» на сервере##btnsettypeactor", imgui.ImVec2(availW, 28)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            if sid and sid > 0 then
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockVisualPreset(sid, "Актёр")
                                showBlockPresetsModal = false
                            else
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            end
                        end

                        imgui.Spacing()
                        imgui.Separator()
                        imgui.Spacing()

                        imgui.TextColored(accentColor(), fa.ICON_USER .. u8"  ПАРАМЕТРЫ АКТЁРА (NPC):")
                        imgui.Spacing()

                        -- Скин актёра
                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Скин актёра (ID):")
                        imgui.PushItemWidth(100)
                        imgui.InputText(u8"##actskininput", presetBlockSkinBuf, 16, imgui.InputTextFlags.CharsDecimal)
                        imgui.PopItemWidth()
                        imgui.SameLine(0, 8)
                        if imgui.Button(fa.ICON_CHECK .. u8"  Применить скин##btnapplyskin", imgui.ImVec2(160, 24)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            local skinId = tonumber(ffi.string(presetBlockSkinBuf))
                            if not sid or sid <= 0 then
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            elseif not skinId then
                                toast_text = "Введите ID скина!"; toast_timer = 120
                            else
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockActorSkin(sid, skinId)
                                showBlockPresetsModal = false
                            end
                        end

                        imgui.Spacing(); imgui.Spacing()

                        -- Имя актёра
                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Имя актёра (над головой):")
                        imgui.PushItemWidth(300)
                        imgui.InputText(u8"##actnameinput", presetBlockNameBuf, 64)
                        imgui.PopItemWidth()
                        imgui.SameLine(0, 8)
                        if imgui.Button(fa.ICON_CHECK .. u8"  Применить имя##btnapplyname", imgui.ImVec2(160, 24)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            local aname = ffi.string(presetBlockNameBuf)
                            if not sid or sid <= 0 then
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            elseif aname == "" then
                                toast_text = "Введите имя актёра!"; toast_timer = 120
                            else
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockActorName(sid, aname)
                                showBlockPresetsModal = false
                            end
                        end

                        imgui.Spacing(); imgui.Spacing()

                        -- Анимация актёра
                        imgui.TextColored(imgui.ImVec4(0.85, 0.85, 0.85, 1.0), u8"Анимация при появлении (ID от 0 до 60):")
                        imgui.PushItemWidth(120)
                        imgui.InputText(u8"##actaniminput", presetBlockAnimBuf, 16)
                        imgui.PopItemWidth()
                        imgui.SameLine(0, 8)
                        if imgui.Button(fa.ICON_CHECK .. u8"  Применить анимацию##btnapplyanim", imgui.ImVec2(180, 24)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            local anm = ffi.string(presetBlockAnimBuf)
                            if not sid or sid <= 0 then
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            elseif anm == "" then
                                toast_text = "Укажите ID анимации (0-60)!"; toast_timer = 120
                            else
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockActorAnim(sid, anm)
                                showBlockPresetsModal = false
                            end
                        end
                        imgui.SameLine(0, 8)
                        if imgui.Button(fa.ICON_UNDO .. u8"  RESET (сброс)##btnresetanim", imgui.ImVec2(130, 24)) then
                            local sid = tonumber(ffi.string(presetBlockIdBuf)) or (curB and curB.serverId)
                            if not sid or sid <= 0 then
                                toast_text = "Укажите ID блока!"; toast_timer = 120
                            else
                                if curB and curB.serverId ~= sid then curB.serverId = sid; scriptBlocks[scriptViewId] = blocks; saveScriptBlocks() end
                                applyBlockActorAnim(sid, "RESET")
                                showBlockPresetsModal = false
                            end
                        end
                    end
                end

            imgui.PopStyleVar()
            imgui.PopStyleColor(3)
            if not closePM[0] then showBlockPresetsModal = false end
            imgui.End()
        end

        if showCreateBlock then
            local closeBlk = imgui.new.bool(true)
            imgui.SetNextWindowSize(imgui.ImVec2(360, 190), imgui.Cond.Always)
            imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5, 0.5))
            imgui.PushStyleColor(imgui.Col.TitleBgActive, accentColorA(1.0))
            imgui.Begin(u8"Создание ивент блока##createblockwin", closeBlk, imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse)
                imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1.0), u8"Название типа ивент блока")
                imgui.SameLine(220)
                imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1.0), u8"Код блока")
                imgui.Separator()
                for _, t in ipairs(blockTypes) do
                    local isSel = (createBlockSelected == t.id)
                    if isSel then imgui.PushStyleColor(imgui.Col.Header, accentColorA(0.55)) end
                    if imgui.Selectable(t.name .. "##blocktype_" .. t.id, isSel, imgui.SelectableFlags.SpanAllColumns) then
                        createBlockSelected = t.id
                    end
                    if isSel then imgui.PopStyleColor() end
                    imgui.SameLine(220)
                    imgui.TextColored(t.color, t.code)
                end
                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                if imgui.Button(u8"Создать##createblockok", imgui.ImVec2(150, 32)) then
                    sampSendChat("/createblock " .. createBlockSelected)
                    local blocks = scriptBlocks[scriptViewId] or {}
                    table.insert(blocks, {type = createBlockSelected, date = os.time()})
                    scriptBlocks[scriptViewId] = blocks
                    saveScriptBlocks()
                    pendingNewBlockScriptId = scriptViewId
                    showCreateBlock = false
                end
                imgui.SameLine(0, 8)
                if imgui.Button(u8"Выход##createblockcancel", imgui.ImVec2(150, 32)) then
                    showCreateBlock = false
                end
            imgui.PopStyleColor()
            if not closeBlk[0] then showCreateBlock = false end
            imgui.End()
        end

        imgui.Unindent(10)
        return
    end

    imgui.SameLine(imgui.GetContentRegionAvail().x - 110)
    if imgui.Button(u8"+ \xc4\xee\xe1\xe0\xe2\xe8\xf2\xfc##scadd", imgui.ImVec2(100, 22)) then showScriptAdd = true end
    imgui.Spacing()
    imgui.PushItemWidth(-1)
    imgui.InputTextWithHint(u8"##scsearch", u8"Поиск...", scriptSearchBuf, 128)
    imgui.PopItemWidth()
    imgui.Spacing()
    if imgui.Button(u8"Все##sc0", imgui.ImVec2(60,24)) then activeScriptTab=0 end
    imgui.SameLine()
    local sci = 1
    for catName, _ in pairs(scriptCategories) do
        if imgui.Button(catName.."##scat_"..sci, imgui.ImVec2(100,24)) then activeScriptTab=sci end
        if imgui.IsItemClicked(1) then ctxScript=catName; ctxScriptPos={x=imgui.GetMousePos().x, y=imgui.GetMousePos().y} end
        imgui.SameLine(); sci=sci+1
    end
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    local CARD_W = 220
    local CARD_H = 80
    local PAD    = 10
    local cols   = math.max(1, math.floor((W + PAD) / (CARD_W + PAD)))
    local col    = 0

    imgui.BeginChild(u8"##scriptslist", imgui.ImVec2(0,0), false)
    local q = ffi.string(scriptSearchBuf):lower()
    for i, s in ipairs(scripts) do
        local show = activeScriptTab == 0
        if not show then
            local ci2 = 1
            for cn, cd in pairs(scriptCategories) do
                if ci2 == activeScriptTab and cd[tostring(i)] then show=true end
                ci2=ci2+1
            end
        end
        if q ~= "" and not s.name:lower():find(q,1,true) and not tostring(s.id):find(q,1,true) then show=false end
        if not show then goto continue_sc end

        if col > 0 then imgui.SameLine(0, PAD) end
        imgui.BeginGroup()
            local p = imgui.GetCursorScreenPos()
            imgui.GetWindowDrawList():AddRectFilled(
                imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x+CARD_W, p.y+CARD_H), 0xFF1E1E1E, 8)
            imgui.GetWindowDrawList():AddRect(
                imgui.ImVec2(p.x, p.y), imgui.ImVec2(p.x+CARD_W, p.y+CARD_H), 0x55E07200, 8)
            imgui.InvisibleButton("##sccard_"..i, imgui.ImVec2(CARD_W, CARD_H))
            local sclicked  = imgui.IsItemClicked(0)
            local srclicked = imgui.IsItemClicked(1)
            local shovered  = imgui.IsItemHovered()
            if shovered then
                imgui.GetWindowDrawList():AddRectFilled(
                    imgui.ImVec2(p.x,p.y), imgui.ImVec2(p.x+CARD_W,p.y+CARD_H), 0x15E07200, 8)
            end
            imgui.SetCursorScreenPos(imgui.ImVec2(p.x+10, p.y+10))
            imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_CODE)
            imgui.SameLine()
            imgui.TextColored(imgui.ImVec4(1.0,1.0,1.0,1.0), s.name)
            imgui.SetCursorScreenPos(imgui.ImVec2(p.x+10, p.y+30))
            imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1.0), u8"ID: "..tostring(s.id))
            imgui.SetCursorScreenPos(imgui.ImVec2(p.x+10, p.y+50))
            if s.note and s.note ~= "" then
                imgui.TextColored(imgui.ImVec4(0.55,0.75,0.55,1.0), fa.ICON_COMMENT.." "..s.note)
            else
                imgui.TextColored(imgui.ImVec4(0.45,0.45,0.45,1.0), u8"ЛКМ — /scr | ПКМ — меню")
            end
            if sclicked then
                safeSendScr(s.id)
            end
            if srclicked then ctxScript=i; ctxScriptPos={x=imgui.GetMousePos().x, y=imgui.GetMousePos().y} end
        imgui.EndGroup()
        col = col+1
        if col >= cols then col=0; imgui.Spacing() end
        ::continue_sc::
    end
    if #scripts == 0 then
        imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1.0), u8"  Скриптов нет. Нажмите '+ Добавить'.")
    end
    imgui.EndChild()

    -- ПКМ скрипта
    if ctxScript and ctxScriptPos and type(ctxScript) == "number" then
        imgui.SetNextWindowPos(imgui.ImVec2(ctxScriptPos.x, ctxScriptPos.y), imgui.Cond.Always)
        imgui.Begin(u8"##ctxscript", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.AlwaysAutoResize)
            if not imgui.IsWindowHovered() and imgui.IsMouseClicked(0) then ctxScript=nil; ctxScriptPos=nil; showScriptCatCreate=false end
            if imgui.Button(fa.ICON_CODE .. u8"  Открыть (/scr)##scopen", imgui.ImVec2(185,0)) then
                safeSendScr(scripts[ctxScript].id)
                ctxScript=nil; ctxScriptPos=nil
            end
            if imgui.Button(fa.ICON_TRASH .. u8" Удалить##scdel", imgui.ImVec2(185,0)) then
                table.remove(scripts, ctxScript); saveScripts()
                ctxScript=nil; ctxScriptPos=nil
            end
            if imgui.Button(fa.ICON_PENCIL .. u8" \xcf\xe5\xf0\xe5\xe8\xec\xe5\xed\xee\xe2\xe0\xf2\xfc##scren", imgui.ImVec2(185,0)) then
                renameScript = ctxScript
                imgui.StrCopy(renameScriptBuf, scripts[ctxScript] and scripts[ctxScript].name or "")
                ctxScript=nil; ctxScriptPos=nil
            end
            if imgui.Button(fa.ICON_PENCIL .. u8" Заметки##scnote", imgui.ImVec2(185,0)) then
                editScriptNote = ctxScript
                local cur = scripts[ctxScript] and scripts[ctxScript].note or ""
                imgui.StrCopy(editScriptNoteBuf, cur)
                ctxScript=nil; ctxScriptPos=nil
            end
            imgui.Separator()
            imgui.Text(u8"Категория:")
            imgui.Separator()
            if showScriptCatCreate then
                imgui.PushItemWidth(140)
                if imgui.InputText(u8"##nsccn", scriptCatNameBuf, 64, imgui.InputTextFlags.EnterReturnsTrue) then
                    local cn = ffi.string(scriptCatNameBuf)
                    if cn~="" then if not scriptCategories[cn] then scriptCategories[cn]={} end; scriptCategories[cn][tostring(ctxScript)]=true; saveScriptCategories() end
                    imgui.StrCopy(scriptCatNameBuf,''); showScriptCatCreate=false; ctxScript=nil; ctxScriptPos=nil
                end
                imgui.PopItemWidth()
            else
                if imgui.Button(u8"+ Создать категорию##scc", imgui.ImVec2(185,0)) then showScriptCatCreate=true end
                for cn, cd in pairs(scriptCategories) do
                    local inCat = cd[tostring(ctxScript)]
                    if imgui.Button((inCat and "- " or "+ ")..cn.."##scc_"..cn, imgui.ImVec2(155,0)) then
                        if inCat then cd[tostring(ctxScript)]=nil else cd[tostring(ctxScript)]=true end
                        saveScriptCategories(); ctxScript=nil; ctxScriptPos=nil
                    end
                    imgui.SameLine()
                    if imgui.Button(u8"X##scdel_"..cn, imgui.ImVec2(26,0)) then
                        scriptCategories[cn]=nil; saveScriptCategories()
                        if activeScriptTab~=0 then activeScriptTab=0 end; ctxScript=nil; ctxScriptPos=nil
                    end
                end
            end
        imgui.End()
    end

    -- ПКМ категории
    if ctxScript and ctxScriptPos and type(ctxScript) == "string" then
        imgui.SetNextWindowPos(imgui.ImVec2(ctxScriptPos.x, ctxScriptPos.y), imgui.Cond.Always)
        imgui.Begin(u8"##ctxscriptcat", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.AlwaysAutoResize)
            if not imgui.IsWindowHovered() and imgui.IsMouseClicked(0) then ctxScript=nil; ctxScriptPos=nil end
            if imgui.Button(fa.ICON_TRASH .. u8" Удалить категорию##sccatdel", imgui.ImVec2(185,0)) then
                scriptCategories[ctxScript]=nil; saveScriptCategories()
                if activeScriptTab~=0 then activeScriptTab=0 end; ctxScript=nil; ctxScriptPos=nil
            end
        imgui.End()
    end

    -- Окно редактирования заметки
    if editScriptNote then
        imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5,0.5))
        imgui.SetNextWindowSize(imgui.ImVec2(340, 148), imgui.Cond.Always)
        imgui.Begin(u8"Заметка##scnotewin", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize)
            imgui.Text(u8"Заметка к скрипту:")
            imgui.PushItemWidth(-1)
            imgui.InputText(u8"##scnoteinp", editScriptNoteBuf, 256)
            imgui.PopItemWidth()
            imgui.Spacing(); imgui.Separator()
            if imgui.Button(u8"Сохранить##scnotesv", imgui.ImVec2(155,28)) then
                local txt = ffi.string(editScriptNoteBuf)
                if scripts[editScriptNote] then scripts[editScriptNote].note = txt end
                saveScripts(); editScriptNote = nil
            end
            imgui.SameLine()
            if imgui.Button(u8"Отмена##scnotecn", imgui.ImVec2(155,28)) then
                editScriptNote = nil
            end
        imgui.End()
    end

    -- Окно Добавить скрипт
    imgui.Indent(10)
end

local function renderTabCompare()
    imgui.Indent(10)
    local W = imgui.GetContentRegionAvail().x
    imgui.Spacing()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_COLUMNS .. u8"  СРАВНЕНИЕ ОБЫЕПТОВ")
    imgui.SameLine()
    imgui.TextColored(imgui.ImVec4(0.45,0.45,0.45,1), u8"  (добавьте до 3 объёктов двойным кликом в Каталоге или Недавних)")
    imgui.Spacing()
    if imgui.Button(fa.ICON_TRASH .. u8" Очистить##clrcmp", imgui.ImVec2(120,24)) then compareList={} end
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()
    if #compareList == 0 then
        imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"  Пусто. Добавьте объёкты двойным кликом из Последних или Поиска.")
        return
    end
    local colW = math.floor((W - 10*(#compareList-1)) / #compareList)
    for ci, obj in ipairs(compareList) do
        if ci > 1 then imgui.SameLine(0,10) end
        imgui.BeginGroup()
            local p = imgui.GetCursorScreenPos()
            local cardH = 260
            imgui.GetWindowDrawList():AddRectFilled(
                imgui.ImVec2(p.x,p.y), imgui.ImVec2(p.x+colW,p.y+cardH), 0xFF161616, 10)
            imgui.GetWindowDrawList():AddRect(
                imgui.ImVec2(p.x,p.y), imgui.ImVec2(p.x+colW,p.y+cardH), 0xAAE07200, 10)
            imgui.Dummy(imgui.ImVec2(colW, 4))
            -- картинка
            local tex = getTex(obj.id)
            if tex then
                local imgS = math.min(colW-20, 140)
                imgui.SetCursorPosX(imgui.GetCursorPosX() + (colW-imgS)/2)
                imgui.Image(tex, imgui.ImVec2(imgS,imgS))
            else
                imgui.Dummy(imgui.ImVec2(colW,80))
            end
            imgui.Spacing()
            local padX = imgui.GetCursorPosX() + 8
            imgui.SetCursorPosX(padX)
            imgui.TextColored(imgui.ImVec4(1,1,1,1), obj.name)
            imgui.SetCursorPosX(padX)
            imgui.TextColored(imgui.ImVec4(0.55,0.55,0.55,1), u8"ID: "..obj.id)
            imgui.Spacing()
            imgui.SetCursorPosX(padX)
            -- размеры
            local function statRow(label, val)
                imgui.SetCursorPosX(padX)
                imgui.TextColored(imgui.ImVec4(0.88,0.45,0,1), label)
                imgui.SameLine()
                imgui.Text(tostring(val))
            end
            statRow(u8"Радиус:", obj.radius)
            statRow(u8"Длина:", obj.length)
            statRow(u8"Ширина:", obj.width)
            statRow(u8"Высота:", obj.height)
            imgui.Spacing()
            imgui.SetCursorPosX(padX)
            if imgui.SmallButton(fa.ICON_PLUS .. u8" Создать##cmpcreat_"..ci) then
                addToRecent(obj); sampSendChat("/cr "..obj.id)
                winOpen[0]=false;
            end
            imgui.SameLine()
            if imgui.SmallButton(fa.ICON_TIMES .. "##cmpdel_"..ci) then
                table.remove(compareList, ci)
                imgui.EndGroup(); break
            end
        imgui.EndGroup()
    end
    imgui.Indent(10)
end

local function HelpMarker(desc)
    imgui.TextDisabled(fa.ICON_QUESTION_CIRCLE or fa.ICON_QUESTION_CIRCLE_O or "(?)")
    if imgui.IsItemHovered() then
        imgui.BeginTooltip()
        imgui.PushTextWrapPos(imgui.GetFontSize() * 25)
        imgui.TextUnformatted(desc)
        imgui.PopTextWrapPos()
        imgui.EndTooltip()
    end
end

hkWaitModVk = 0
hkWaitModTime = 0
hkWaitModReleased = false

local function renderHotkeyRow(id, label, help, displayBuf, isWaitingFn, setWaitingFn, onCapture, onReset, resetLabel)
    local W = imgui.GetContentRegionAvail().x
    imgui.Columns(2, "##hkcol_" .. id, false)
    imgui.SetColumnWidth(0, math.max(120, W - 305))
    imgui.Text(label or u8"Комбинация:")
    if help then imgui.SameLine() HelpMarker(help) end
    imgui.TextColored(imgui.ImVec4(1.00, 0.75, 0.20, 1.0), ffi.string(displayBuf))
    imgui.NextColumn()

    if isWaitingFn() then
        imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.80, 0.20, 0.10, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.90, 0.30, 0.10, 1.0))
        imgui.Button(u8"  >> Нажмите клавишу <<  ##" .. id .. "_wait", imgui.ImVec2(-1, 28))
        imgui.PopStyleColor(2)
        local captured = false
        for vk = 1, 254 do
            if isKeyDown(vk) and vk~=0x12 and vk~=0x11 and vk~=0x10
            and vk~=0xA0 and vk~=0xA1 and vk~=0xA2 and vk~=0xA3 and vk~=0xA4 and vk~=0xA5 then
                hkWaitModVk = 0
                hkWaitModReleased = false
                onCapture(vk)
                setWaitingFn(false)
                captured = true
                break
            end
        end
        if not captured then
            local altD   = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
            local ctrlD  = isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)
            local shiftD = isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)
            local curMod = altD and 0x12 or (ctrlD and 0x11 or (shiftD and 0x10 or 0))
            if curMod ~= 0 then
                if hkWaitModVk == curMod and hkWaitModReleased and (os.clock() - hkWaitModTime) <= 1.0 then
                    hkWaitModVk = 0
                    hkWaitModReleased = false
                    onCapture(curMod)
                    setWaitingFn(false)
                elseif hkWaitModVk ~= curMod then
                    hkWaitModVk = curMod
                    hkWaitModTime = os.clock()
                    hkWaitModReleased = false
                end
            else
                if hkWaitModVk ~= 0 then
                    if (os.clock() - hkWaitModTime) <= 1.0 then
                        hkWaitModReleased = true
                    else
                        hkWaitModVk = 0
                        hkWaitModReleased = false
                    end
                end
            end
        end
    else
        if imgui.Button(u8"Изменить##" .. id .. "_ch", imgui.ImVec2(140, 28)) then
            setWaitingFn(false)
            hkWaitModVk = 0
            hkWaitModReleased = false
            lua_thread.create(function()
                repeat wait(0) until not isKeyDown(0x01) and not isKeyDown(0x02)
                wait(200)
                hkWaitModVk = 0
                hkWaitModReleased = false
                setWaitingFn(true)
            end)
        end
        imgui.SameLine(0, 8)
        if imgui.Button((resetLabel or u8"Сброс") .. "##" .. id .. "_rs", imgui.ImVec2(140, 28)) then
            onReset()
        end
    end
    imgui.Columns(1)
end

