end

local function renderTabSettings()
    local W = imgui.GetContentRegionAvail().x
    local H = imgui.GetContentRegionAvail().y
    local ac = accentColor()
    local qSearch = cyrLower(ffi.string(settingsSearchBuf))

    -- =========================================================================
    -- ВЕРХНЯЯ ПАНЕЛЬ НАСТРОЕК (Top Bar)
    -- =========================================================================
    local topBarH = 34.0
    imgui.BeginChild("##settings_top_bar", imgui.ImVec2(0, topBarH), false)
        imgui.AlignTextToFramePadding()
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(ac.x, ac.y, ac.z, 0.95))
        imgui.Text(fa.ICON_SLIDERS .. u8"  Настройки Trinity Mapper Tools")
        imgui.PopStyleColor()

        local sBoxW = 270.0
        local availTopW = imgui.GetContentRegionAvail().x + imgui.GetCursorPosX()
        imgui.SameLine(math.max(160.0, availTopW - sBoxW))
        imgui.AlignTextToFramePadding()
        imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(ac.x, ac.y, ac.z, 0.85))
        imgui.Text(fa.ICON_SEARCH)
        imgui.PopStyleColor()
        imgui.SameLine()
        imgui.PushItemWidth(sBoxW - 55)
        imgui.InputTextWithHint("##settings_search", u8"Поиск по настройкам...", settingsSearchBuf, 128)
        imgui.PopItemWidth()
        if ffi.string(settingsSearchBuf) ~= "" then
            imgui.SameLine()
            if imgui.Button(fa.ICON_TIMES .. "##clr_settings_srch", imgui.ImVec2(24, 22)) then
                imgui.StrCopy(settingsSearchBuf, "")
            end
            if imgui.IsItemHovered() then imgui.SetTooltip(u8"Сбросить поиск") end
        end
    imgui.EndChild()

    imgui.Separator()
    imgui.Spacing()

    -- =========================================================================
    -- ДВУХКОЛОНОЧНЫЙ МАКЕТ (Сайдбар слева + Контент справа)
    -- =========================================================================
    local sidebarW = 205.0

    -- --- ЛЕВЫЙ САЙДБАР ---
    imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding, 6.0)
    imgui.BeginChild("##settings_sidebar", imgui.ImVec2(sidebarW, 0), true)
    imgui.PopStyleVar()

        local sbDraw = imgui.GetWindowDrawList()
        local sbAvailW = imgui.GetContentRegionAvail().x

        local settingsCategories = {
            { id = 1, icon = fa.ICON_KEYBOARD_O,  title = u8"Клавиши",      desc = u8"Бинды, хоткеи, активация" },
            { id = 2, icon = fa.ICON_PAINT_BRUSH, title = u8"Интерфейс",    desc = u8"Темы, сетка, анимации" },
            { id = 3, icon = fa.ICON_CROSSHAIRS,  title = u8"Инструменты",  desc = u8"Сканер объектов, CamHack" },
            { id = 4, icon = fa.ICON_WRENCH,      title = u8"Мини-панели",  desc = u8"Быстрые текстуры и объекты" },
            { id = 5, icon = fa.ICON_BELL,        title = u8"Оповещения",   desc = u8"Уведомления и оверлеи" },
            { id = 6, icon = fa.ICON_INFO_CIRCLE, title = u8"Справка",      desc = u8"Горячие клавиши и команды" },
            { id = 7, icon = fa.ICON_DOWNLOAD,    title = u8"Обновление",   desc = u8"Версия и автообновление" }
        }

        for _, cat in ipairs(settingsCategories) do
            local isSel = (settingsSubTab == cat.id and qSearch == "")
            local itemH = 46.0
            local curP = imgui.GetCursorScreenPos()
            local clicked = imgui.InvisibleButton("##set_cat_btn_" .. cat.id, imgui.ImVec2(sbAvailW, itemH))
            local isHov = imgui.IsItemHovered()

            if clicked then
                settingsSubTab = cat.id
                imgui.StrCopy(settingsSearchBuf, "")
            end

            -- Фон карточки категории
            local bgCol
            if isSel then
                bgCol = 0x38000000 + accentColorHex()
            elseif isHov then
                bgCol = 0x22FFFFFF
            else
                bgCol = 0xFF000000 + cardBgHex()
            end
            sbDraw:AddRectFilled(curP, imgui.ImVec2(curP.x + sbAvailW, curP.y + itemH), bgCol, 6.0)

            local bordCol = isSel and (0xFF000000 + accentColorHex()) or (isHov and (0x66000000 + accentColorHex()) or 0x22FFFFFF)
            sbDraw:AddRect(curP, imgui.ImVec2(curP.x + sbAvailW, curP.y + itemH), bordCol, 6.0)

            -- Вертикальная полоска индикатора слева для активной категории
            if isSel then
                local indH = 22.0
                local indY = curP.y + (itemH - indH) * 0.5
                sbDraw:AddRectFilled(imgui.ImVec2(curP.x + 1, indY), imgui.ImVec2(curP.x + 4.5, indY + indH), 0xFF000000 + accentColorHex(), 2.0)
            end

            -- Иконка (плашка 28x28)
            local badgeSz = 28.0
            local badgeX = curP.x + 7.0
            local badgeY = curP.y + (itemH - badgeSz) * 0.5
            local badgeBg = isSel and (0x55000000 + accentColorHex()) or (isHov and 0x33FFFFFF or 0x18FFFFFF)
            sbDraw:AddRectFilled(imgui.ImVec2(badgeX, badgeY), imgui.ImVec2(badgeX + badgeSz, badgeY + badgeSz), badgeBg, 5.0)

            local iconSz = imgui.CalcTextSize(cat.icon)
            local iconCol = isSel and (0xFF000000 + accentColorHex()) or 0xFFFFFFFF
            sbDraw:AddText(imgui.ImVec2(badgeX + (badgeSz - iconSz.x) * 0.5, badgeY + (badgeSz - iconSz.y) * 0.5), iconCol, cat.icon)

            -- Текст: Заголовок и Описание
            local txX = curP.x + 42.0
            sbDraw:PushClipRect(imgui.ImVec2(txX, curP.y), imgui.ImVec2(curP.x + sbAvailW - 4, curP.y + itemH), true)
            sbDraw:AddText(imgui.ImVec2(txX, curP.y + 6.0), isSel and (0xFF000000 + accentColorHex()) or 0xFFFFFFFF, cat.title)
            sbDraw:AddText(imgui.ImVec2(txX, curP.y + 24.0), 0x99FFFFFF, cat.desc)
            sbDraw:PopClipRect()

            imgui.Spacing()
        end

        imgui.Separator()
        imgui.Spacing()
        imgui.TextDisabled(u8("Версия: v" .. SCRIPT_VERSION))
        if imgui.Button((fa.ICON_DOWNLOAD or "") .. u8" Обновление##chk_upd_btn", imgui.ImVec2(sbAvailW, 26)) then
            settingsSubTab = 7
            imgui.StrCopy(settingsSearchBuf, "")
        end
        if updateStatusText ~= "" then
            imgui.TextColored(accentColorA(0.95), updateStatusText)
        end
    imgui.EndChild()

    imgui.SameLine(0, 10)

    -- --- ПРАВАЯ ОБЛАСТЬ КОНТЕНТА ---
    imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding, 6.0)
    imgui.BeginChild("##settings_content", imgui.ImVec2(0, 0), true)
    imgui.PopStyleVar()

    local contentW = imgui.GetContentRegionAvail().x - 10

    local showKeys     = (qSearch == "" and settingsSubTab == 1) or (qSearch ~= "" and (u8"клавиши бинды хоткеи создание удаление джетпак меню"):find(qSearch, 1, true))
    local showUI       = (qSearch == "" and settingsSubTab == 2) or (qSearch ~= "" and (u8"интерфейс темы сетка анимации оверлей префабы"):find(qSearch, 1, true))
    local showTools    = (qSearch == "" and settingsSubTab == 3) or (qSearch ~= "" and (u8"инструменты сканер camhack камера свободна fov"):find(qSearch, 1, true))
    local showPanels   = (qSearch == "" and settingsSubTab == 4) or (qSearch ~= "" and (u8"мини-панели быстрые текстуры объекты группы quicktex quickobj quickgrp"):find(qSearch, 1, true))
    local showNotify   = (qSearch == "" and settingsSubTab == 5) or (qSearch ~= "" and (u8"оповещения уведомления glist grouplist подсказки cr"):find(qSearch, 1, true))
    local showHelp     = (qSearch == "" and settingsSubTab == 6) or (qSearch ~= "" and (u8"справка команды del gr mgr gdel tex grset gtex objlist"):find(qSearch, 1, true))
    local showUpdate   = (qSearch == "" and settingsSubTab == 7) or (qSearch ~= "" and (u8"обновление версия скачать проверить github"):find(qSearch, 1, true))

    -- ==========================================
    -- 1. ГОРЯЧИЕ КЛАВИШИ И БИНДЫ
    -- ==========================================
    if showKeys then
        renderSectionHeader(fa.ICON_KEYBOARD_O, u8"Главное меню")
        renderHotkeyRow("mainhk", fa.ICON_BARS .. u8"  Меню скрипта:", u8"Главная клавиша для открытия/закрытия интерфейса.",
            hotkey_display,
            function() return waiting_for_key end,
            function(v) waiting_for_key = v end,
            function(vk)
                hotkey_key[0]   = vk
                hotkey_alt[0]   = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
                hotkey_ctrl[0]  = isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)
                hotkey_shift[0] = isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)
                _hk_alt   = hotkey_alt[0] == true
                _hk_ctrl  = hotkey_ctrl[0] == true
                _hk_shift = hotkey_shift[0] == true
                hotkey_just_set = true
                updateHotkeyDisplay(); saveSettings()
            end,
            function()
                hotkey_alt[0]=true; hotkey_ctrl[0]=false; hotkey_shift[0]=false; hotkey_key[0]=78
                _hk_alt=true; _hk_ctrl=false; _hk_shift=false
                updateHotkeyDisplay(); saveSettings()
            end,
            u8"По умолч. Alt+N")

        imgui.Spacing()
        renderSectionHeader(fa.ICON_BOLT, u8"Быстрые действия маппинга")
        renderHotkeyRow("quickcreate", fa.ICON_PLUS_CIRCLE .. u8"  Быстрое создание:", u8"Создать последний выбранный объект под прицелом.",
            quick_display,
            function() return waiting_quick end,
            function(v) waiting_quick = v end,
