        imgui.PushItemWidth(240)
        if imgui.BeginCombo("##theme_combo", currentThemeName) then
            for key, themeData in pairs(THEMES) do
                local is_selected = (currentTheme == key)
                if imgui.Selectable(themeData.name, is_selected) then
                    currentTheme = key
                    applyTheme(key)
                    saveSettings()
                end
                if is_selected then
                    imgui.SetItemDefaultFocus()
                end
            end
            imgui.EndCombo()
