        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
        imgui.TextColored(accentColor(), fa.ICON_KEYBOARD_O .. u8"  Управление и горячие клавиши:")
        imgui.Spacing()
        local hotkeyHints = {
            {u8"ЛКМ",                    u8" - Выбрать объект / Скопировать ID при зажатом Ctrl"},
            {u8"ПКМ",                    u8" - Открыть быстрое меню действий объекта"},
            {u8"2x ЛКМ",                 u8" - Мгновенный телепорт к выбранному объекту"},
            {u8"Пробел (в /ed)",         u8" - Свободное вращение камерой вокруг объекта при активном Gizmo"},
            {u8"Alt (в замере/пипетке)", u8" - Показать курсор мыши для наведения и клика"},
            {u8"ESC",                    u8" - Закрыть текущее окно / Снять выбор / Выйти из режима"},
        }
        for _, h in ipairs(hotkeyHints) do
            imgui.TextColored(imgui.ImVec4(1.00, 0.75, 0.20, 1.0), h[1])
            imgui.SameLine()
            imgui.Text(h[2])
            imgui.Spacing()
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
        imgui.TextColored(accentColor(), fa.ICON_TERMINAL .. u8"  Основные команды маппинга:")
        imgui.Spacing()
        local baseHints = {
            {u8"/del",                   u8" - Удалить выбранный объект"},
            {u8"/undodel (или /rdel)",   u8" - Восстановить случайно удаленный объект"},
            {u8"/gr [id группы] [id1] [id2]", u8" - Создать группу объектов"},
            {u8"/mgr",                   u8" - Открыть меню групп объектов"},
            {u8"/gdel",                  u8" - Удалить группу объектов"},
            {u8"/mgmove",                u8" - Меню перемещения группы"},
            {u8"/tex [id группы]",       u8" - Текстурирование всей группы"},
            {u8"/greset [id группы]",    u8" - Сброс текстур группы"},
            {u8"/grset [1-100]",         u8" - Наложить текстуру на группу (или /gtex)"},
            {u8"/mtex [слоты...] [текстура]", u8" - Быстрое наложение текстур"},
            {u8"/objlist",               u8" - Список объектов в стриме"},
            {u8"/vw",                    u8" - Менеджер виртуального мира и погоды"},
            {u8"/st [0-23]",             u8" - Установить время суток (визуально)"},
            {u8"/sw [0-45]",             u8" - Установить погоду (визуально)"},
        }
        for _, h in ipairs(baseHints) do
            imgui.TextColored(imgui.ImVec4(0.40, 0.75, 1.00, 1.0), h[1])
            imgui.SameLine()
            imgui.Text(h[2])
            imgui.Spacing()
        end

    end

    if showUpdate then
        renderSectionHeader(fa.ICON_DOWNLOAD, u8"Обновление Trinity Mapper Tools")
        imgui.Spacing()
        imgui.Text(u8("Текущая установленная версия: "))
        imgui.SameLine()
        imgui.TextColored(accentColor(), u8("v" .. SCRIPT_VERSION))
        imgui.Spacing()

        if updateChecking then
            imgui.Button(u8"Проверка обновлений...##upd_tab_chk_busy", imgui.ImVec2(220, 28))
        else
            if imgui.Button((fa.ICON_REFRESH or "") .. u8"  Проверить обновления##upd_tab_chk", imgui.ImVec2(220, 28)) then
                checkForUpdates(true)
            end
        end
        if updateStatusText ~= "" then
            imgui.SameLine(0, 12)
            imgui.AlignTextToFramePadding()
            imgui.TextColored(accentColorA(0.95), updateStatusText)
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        if updateAvailable ~= nil then
            imgui.TextColored(imgui.ImVec4(0.25, 0.95, 0.45, 1.0), fa.ICON_CHECK_CIRCLE .. u8("  Доступна новая версия: v" .. tostring(updateAvailable.version)))
            imgui.Spacing()
            imgui.TextDisabled(u8"Список изменений:")
            imgui.BeginChild("##tmt_upd_tab_changelog", imgui.ImVec2(contentW, 140), true)
                local clText = (updateAvailable.changelog and updateAvailable.changelog ~= "") and safeU8(updateAvailable.changelog) or u8"Улучшения и исправления ошибок."
                imgui.TextWrapped(clText)
            imgui.EndChild()

            imgui.Spacing()
            if updateDownloading then
                imgui.Button(u8"Загрузка и установка обновления...##upd_tab_busy", imgui.ImVec2(260, 32))
            else
                imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(0.15, 0.45, 0.22, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.20, 0.58, 0.30, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(0.25, 0.68, 0.36, 1.0))
                if imgui.Button(fa.ICON_DOWNLOAD .. u8"  Обновить сейчас##upd_tab_now", imgui.ImVec2(260, 32)) then
                    downloadAndApplyUpdate()
                end
                imgui.PopStyleColor(3)
            end
        else
            imgui.TextDisabled(u8"Новых обновлений пока не найдено. Нажмите «Проверить обновления», чтобы свериться с GitHub.")
        end
    end

    imgui.EndChild()
end
-- ============================================================================
-- ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ ЦВЕТОВ (HSV, ГАРМОНИЯ, ГРАДИЕНТ)
-- ============================================================================
function rgbToHsv(r, g, b)
    local maxC = math.max(r, g, b)
    local minC = math.min(r, g, b)
    local delta = maxC - minC
    local h, s, v = 0, 0, maxC
    if maxC > 0 then s = delta / maxC end
    if delta > 0 then
        if maxC == r then
            h = (g - b) / delta
            if g < b then h = h + 6 end
        elseif maxC == g then
            h = (b - r) / delta + 2
        else
            h = (r - g) / delta + 4
        end
        h = h / 6
    end
    return h, s, v
end

function hsvToRgb(h, s, v)
    if s == 0 then return v, v, v end
    h = (h % 1.0) * 6
    local i = math.floor(h)
    local f = h - i
    local p = v * (1 - s)
    local q = v * (1 - s * f)
    local t = v * (1 - s * (1 - f))
    if i == 0 then return v, t, p
    elseif i == 1 then return q, v, p
    elseif i == 2 then return p, v, t
    elseif i == 3 then return p, q, v
    elseif i == 4 then return t, p, v
    else return v, p, q
    end
end

function generateSampGradient(text, r1, g1, b1, r2, g2, b2, byWords)
    if not text or text == "" then return "" end
    local res = {}
    if byWords then
        local words = {}
        for w in text:gmatch("%S+") do table.insert(words, w) end
        local total = #words
        for i, w in ipairs(words) do
            local t = (total > 1) and ((i - 1) / (total - 1)) or 0
            local r = math.floor((r1 + (r2 - r1) * t) * 255 + 0.5)
            local g = math.floor((g1 + (g2 - g1) * t) * 255 + 0.5)
            local b = math.floor((b1 + (b2 - b1) * t) * 255 + 0.5)
            table.insert(res, string.format("{%02X%02X%02X}%s", r, g, b, w))
        end
        return table.concat(res, " ")
    else
        local chars = {}
        for c in text:gmatch("[%z\1-\127\194-\244][\128-\191]*") do
            table.insert(chars, c)
        end
        if #chars == 0 then
            for i = 1, #text do table.insert(chars, text:sub(i, i)) end
        end
        local total = #chars
        for i, c in ipairs(chars) do
            if c == " " then
                table.insert(res, " ")
            else
                local t = (total > 1) and ((i - 1) / (total - 1)) or 0
                local r = math.floor((r1 + (r2 - r1) * t) * 255 + 0.5)
                local g = math.floor((g1 + (g2 - g1) * t) * 255 + 0.5)
                local b = math.floor((b1 + (b2 - b1) * t) * 255 + 0.5)
                table.insert(res, string.format("{%02X%02X%02X}%s", r, g, b, c))
            end
        end
        return table.concat(res, "")
    end
end

-- ============================================================================
-- ВКЛАДКА: ЦВЕТА И ПАЛИТРА
-- ============================================================================
function renderTabColors()
    imgui.Indent(10)
    imgui.Spacing()
    imgui.TextColored(accentColor(), fa.ICON_PAINT_BRUSH .. safeU8("  Выбор цвета и палитра"))
    imgui.Separator(); imgui.Spacing()

    -- ------------------------------------------------------------------------
    -- ВЕРХНЯЯ ЧАСТЬ: ЦВЕТОВОЙ КРУГ, ТЕКУЩИЙ ЦВЕТ И МОЯ ПАЛИТРА
    -- ------------------------------------------------------------------------
    imgui.PushItemWidth(190)
    imgui.ColorPicker3("##colorwheel", pickerColor,
        imgui.ColorEditFlags.PickerHueWheel + imgui.ColorEditFlags.NoSidePreview + imgui.ColorEditFlags.NoSmallPreview)
    imgui.PopItemWidth()

    local hexR = math.floor(pickerColor[0]*255 + 0.5)
    local hexG = math.floor(pickerColor[1]*255 + 0.5)
    local hexB = math.floor(pickerColor[2]*255 + 0.5)
    local hex = string.format("#%02X%02X%02X", hexR, hexG, hexB)
    local hexNoHash = hex:sub(2)

    imgui.SameLine(0, 16)
    imgui.BeginGroup()
        imgui.Text(safeU8("Текущий цвет:"))
        imgui.TextColored(imgui.ImVec4(pickerColor[0], pickerColor[1], pickerColor[2], 1.0), hex)
        imgui.TextDisabled(string.format("RGB: %d, %d, %d", hexR, hexG, hexB))
        local curH, curS, curV = rgbToHsv(pickerColor[0], pickerColor[1], pickerColor[2])
        imgui.TextDisabled(string.format("HSV: %d°, %d%%, %d%%", math.floor(curH * 360 + 0.5), math.floor(curS * 100 + 0.5), math.floor(curV * 100 + 0.5)))
        imgui.Spacing()

        if imgui.Button(fa.ICON_FILES_O .. safeU8("  Скопировать HEX##colcopy"), imgui.ImVec2(185, 26)) then
            setClipboardText(hexNoHash)
            showToastQuick(safeU8("Скопировано"), hex)
        end
        imgui.Spacing()
        if imgui.Button(fa.ICON_PLUS .. safeU8("  Сохранить в палитру##colsave"), imgui.ImVec2(185, 26)) then
            local exists = false
            for _, c in ipairs(savedColors) do
                if c == hex then exists = true; break end
            end
            if not exists then
                table.insert(savedColors, 1, hex)
                if #savedColors > 40 then table.remove(savedColors) end
                saveSettings()
                showToastQuick(safeU8("Цвет сохранён"), hex)
            end
        end

        imgui.Spacing()
        imgui.TextDisabled(safeU8("Форматы:"))
        imgui.SameLine()
        if imgui.SmallButton(hex .. "##cp_hex") then
            setClipboardText(hex)
            showToastQuick(safeU8("Скопировано"), hex)
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Скопировать #RRGGBB")) end
        imgui.SameLine(0, 4)
        if imgui.SmallButton("{" .. hexNoHash .. "}##cp_samp") then
            setClipboardText("{" .. hexNoHash .. "}")
            showToastQuick(safeU8("Скопировано"), "{" .. hexNoHash .. "}")
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Скопировать в формате SA-MP чата/диалогов: {RRGGBB}")) end
        imgui.SameLine(0, 4)
        if imgui.SmallButton("0x" .. hexNoHash .. "##cp_0x") then
            setClipboardText("0x" .. hexNoHash)
            showToastQuick(safeU8("Скопировано"), "0x" .. hexNoHash)
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Скопировать в шестнадцатеричном формате: 0xRRGGBB")) end
    imgui.EndGroup()

    -- ПАНЕЛЬ: МОЯ ПАЛИТРА (СОХРАНЁННЫЕ ЦВЕТА)
    imgui.SameLine(0, 20)
    local paletteBoxW = math.max(260, imgui.GetContentRegionAvail().x - 10)
    imgui.BeginChild("##my_palette_panel", imgui.ImVec2(paletteBoxW, 190), true)
        imgui.TextColored(accentColor(), fa.ICON_TH .. safeU8("  Моя палитра"))
        imgui.SameLine()
        imgui.TextDisabled(safeU8("(ЛКМ — в пикер | ПКМ — удалить)"))
        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        if #savedColors == 0 then
            imgui.Spacing()
            imgui.TextDisabled(safeU8("Палитра пуста."))
            imgui.TextDisabled(safeU8("Нажмите '+ Сохранить в палитру' слева."))
        else
            local swatch    = 30
            local gap       = 6
            local avail     = imgui.GetContentRegionAvail().x
            local perRow    = math.max(1, math.floor((avail + gap) / (swatch + gap)))
            local removeIdx = nil

            for i, c in ipairs(savedColors) do
                local r = tonumber(c:sub(2,3), 16) / 255
                local g = tonumber(c:sub(4,5), 16) / 255
                local b = tonumber(c:sub(6,7), 16) / 255
                if (i - 1) % perRow > 0 then imgui.SameLine(0, gap) end

                imgui.PushStyleColor(imgui.Col.Button,        imgui.ImVec4(r, g, b, 1.0))
                imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(r, g, b, 0.8))
                imgui.PushStyleColor(imgui.Col.ButtonActive,  imgui.ImVec4(r, g, b, 0.6))
                if imgui.Button("##sw" .. i, imgui.ImVec2(swatch, swatch)) then
                    pickerColor[0] = r
                    pickerColor[1] = g
                    pickerColor[2] = b
                    setClipboardText(c:sub(2))
                    showToastQuick(safeU8("Цвет выбран"), c)
                end
                if imgui.IsItemClicked(1) then
                    removeIdx = i
                end
                if imgui.IsItemHovered() then
                    imgui.SetTooltip(c .. "\n{" .. c:sub(2) .. "}\n" .. safeU8("ЛКМ — применить в пикер\nПКМ — удалить из палитры"))
                end
                imgui.PopStyleColor(3)
            end

            if removeIdx then
                table.remove(savedColors, removeIdx)
                saveSettings()
            end
        end
    imgui.EndChild()

    -- ------------------------------------------------------------------------
    -- ГЕНЕРАТОР ГРАДИЕНТА ДЛЯ ВЫВЕСОК И ТЕКСТА
    -- ------------------------------------------------------------------------
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()
    imgui.TextColored(accentColor(), fa.ICON_FONT .. safeU8("  Генератор градиента для вывесок и текста"))
    imgui.Spacing()

    -- Автоматическая синхронизация цветов из блока "Выбор цвета"
    if gradAutoType == 1 then -- В белый
        if not gradInverted then
            gradCol1[0] = pickerColor[0]; gradCol1[1] = pickerColor[1]; gradCol1[2] = pickerColor[2]
            gradCol2[0] = 1.0; gradCol2[1] = 1.0; gradCol2[2] = 1.0
        else
            gradCol1[0] = 1.0; gradCol1[1] = 1.0; gradCol1[2] = 1.0
            gradCol2[0] = pickerColor[0]; gradCol2[1] = pickerColor[1]; gradCol2[2] = pickerColor[2]
        end
    elseif gradAutoType == 2 then -- В тень
        local sr = pickerColor[0] * 0.15
        local sg = pickerColor[1] * 0.15
        local sb = pickerColor[2] * 0.15
        if not gradInverted then
            gradCol1[0] = pickerColor[0]; gradCol1[1] = pickerColor[1]; gradCol1[2] = pickerColor[2]
            gradCol2[0] = sr; gradCol2[1] = sg; gradCol2[2] = sb
        else
            gradCol1[0] = sr; gradCol1[1] = sg; gradCol1[2] = sb
            gradCol2[0] = pickerColor[0]; gradCol2[1] = pickerColor[1]; gradCol2[2] = pickerColor[2]
        end
    elseif gradAutoType == 3 then -- Контраст (комплементарный)
        local curH, curS, curV = rgbToHsv(pickerColor[0], pickerColor[1], pickerColor[2])
        local cr, cg, cb = hsvToRgb((curH + 0.5) % 1.0, curS, curV)
        if not gradInverted then
            gradCol1[0] = pickerColor[0]; gradCol1[1] = pickerColor[1]; gradCol1[2] = pickerColor[2]
            gradCol2[0] = cr; gradCol2[1] = cg; gradCol2[2] = cb
        else
            gradCol1[0] = cr; gradCol1[1] = cg; gradCol1[2] = cb
            gradCol2[0] = pickerColor[0]; gradCol2[1] = pickerColor[1]; gradCol2[2] = pickerColor[2]
        end
    elseif gradAutoType == 4 then -- Аналог (соседний оттенок)
        local curH, curS, curV = rgbToHsv(pickerColor[0], pickerColor[1], pickerColor[2])
        local ar, ag, ab = hsvToRgb((curH + 0.12) % 1.0, curS, curV)
        if not gradInverted then
            gradCol1[0] = pickerColor[0]; gradCol1[1] = pickerColor[1]; gradCol1[2] = pickerColor[2]
            gradCol2[0] = ar; gradCol2[1] = ag; gradCol2[2] = ab
        else
            gradCol1[0] = ar; gradCol1[1] = ag; gradCol1[2] = ab
            gradCol2[0] = pickerColor[0]; gradCol2[1] = pickerColor[1]; gradCol2[2] = pickerColor[2]
        end
    elseif gradAutoType == 0 then -- Вручную
        if gradActiveSlot == 1 then
            gradCol1[0] = pickerColor[0]; gradCol1[1] = pickerColor[1]; gradCol1[2] = pickerColor[2]
        else
            gradCol2[0] = pickerColor[0]; gradCol2[1] = pickerColor[1]; gradCol2[2] = pickerColor[2]
        end
    end

    -- Ряд 1: Настройка цветов, авто-пары и режима
    imgui.Text(safeU8("Цвет 1:"))
    imgui.SameLine()
    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(gradCol1[0], gradCol1[1], gradCol1[2], 1.0))
    if imgui.Button("##grad_btn1", imgui.ImVec2(28, 22)) then
        gradAutoType = 0
        gradActiveSlot = 1
        pickerColor[0] = gradCol1[0]; pickerColor[1] = gradCol1[1]; pickerColor[2] = gradCol1[2]
    end
    imgui.PopStyleColor()
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Цвет 1 (начало)\nКлик — перейти в ручной режим и выбрать в пикер")) end

    imgui.SameLine(0, 8)
    if imgui.Button("<->##swap_grad", imgui.ImVec2(28, 22)) then
        if gradAutoType ~= 0 then
            gradInverted = not gradInverted
        else
            local r1, g1, b1 = gradCol1[0], gradCol1[1], gradCol1[2]
            gradCol1[0] = gradCol2[0]; gradCol1[1] = gradCol2[1]; gradCol1[2] = gradCol2[2]
            gradCol2[0] = r1; gradCol2[1] = g1; gradCol2[2] = b1
            if gradActiveSlot == 1 then
                pickerColor[0] = gradCol1[0]; pickerColor[1] = gradCol1[1]; pickerColor[2] = gradCol1[2]
            else
                pickerColor[0] = gradCol2[0]; pickerColor[1] = gradCol2[1]; pickerColor[2] = gradCol2[2]
            end
        end
    end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Поменять цвета местами (развернуть градиент)")) end

    imgui.SameLine(0, 8)
    imgui.Text(safeU8("Цвет 2:"))
    imgui.SameLine()
    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(gradCol2[0], gradCol2[1], gradCol2[2], 1.0))
    if imgui.Button("##grad_btn2", imgui.ImVec2(28, 22)) then
        gradAutoType = 0
        gradActiveSlot = 2
        pickerColor[0] = gradCol2[0]; pickerColor[1] = gradCol2[1]; pickerColor[2] = gradCol2[2]
    end
    imgui.PopStyleColor()
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Цвет 2 (конец)\nКлик — перейти в ручной режим и выбрать в пикер")) end

    imgui.SameLine(0, 16)
    imgui.TextDisabled(safeU8("Авто-пара:"))
    imgui.SameLine(0, 4)
    if imgui.RadioButtonBool(safeU8("В белый##gaut1"), gradAutoType == 1) then gradAutoType = 1 end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Плавный переход от выбранного в пикере цвета к белому")) end
    imgui.SameLine(0, 6)
    if imgui.RadioButtonBool(safeU8("В тень##gaut2"), gradAutoType == 2) then gradAutoType = 2 end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Плавное затемнение выбранного цвета в глубокую тень")) end
    imgui.SameLine(0, 6)
    if imgui.RadioButtonBool(safeU8("Контраст##gaut3"), gradAutoType == 3) then gradAutoType = 3 end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Комплементарный контрастный градиент (противоположный цвет круга)")) end
    imgui.SameLine(0, 6)
    if imgui.RadioButtonBool(safeU8("Аналог##gaut4"), gradAutoType == 4) then gradAutoType = 4 end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Мягкий градиент в соседний гармоничный оттенок")) end
    imgui.SameLine(0, 6)
    if imgui.RadioButtonBool(safeU8("Вручную##gaut0"), gradAutoType == 0) then gradAutoType = 0 end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Ручной выбор обоих цветов через пикер")) end

    if gradAutoType == 0 then
        imgui.SameLine(0, 6)
        imgui.TextDisabled("(")
        imgui.SameLine(0, 2)
        if imgui.RadioButtonBool("1##man_s1", gradActiveSlot == 1) then
            gradActiveSlot = 1
            pickerColor[0] = gradCol1[0]; pickerColor[1] = gradCol1[1]; pickerColor[2] = gradCol1[2]
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Редактировать Цвет 1 в пикере")) end
        imgui.SameLine(0, 2)
        if imgui.RadioButtonBool("2##man_s2", gradActiveSlot == 2) then
            gradActiveSlot = 2
            pickerColor[0] = gradCol2[0]; pickerColor[1] = gradCol2[1]; pickerColor[2] = gradCol2[2]
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Редактировать Цвет 2 в пикере")) end
        imgui.SameLine(0, 2)
        imgui.TextDisabled(")")
    end

    imgui.SameLine(0, 16)
    imgui.Text(safeU8("Режим:"))
    imgui.SameLine(0, 4)
    if imgui.RadioButtonBool(safeU8("Буквы##grm0"), gradMode == 0) then gradMode = 0 end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Градиент плавно меняется на каждой букве")) end
    imgui.SameLine(0, 4)
    if imgui.RadioButtonBool(safeU8("Слова##grm1"), gradMode == 1) then gradMode = 1 end
    if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Каждое слово окрашивается своим цветом")) end

    -- Ряд 2: Текст вывески
    imgui.Spacing()
    imgui.Text(safeU8("Текст:"))
    imgui.SameLine()
    imgui.PushItemWidth(340)
    imgui.InputTextWithHint("##grad_inp_txt", safeU8("Введите текст вывески..."), gradTextBuf, 256)
    imgui.PopItemWidth()

    local srcTxt = ffi.string(gradTextBuf)
    if srcTxt ~= "" then
        local gradFormatted = generateSampGradient(srcTxt, gradCol1[0], gradCol1[1], gradCol1[2], gradCol2[0], gradCol2[1], gradCol2[2], gradMode == 1)

        -- Ряд 3: Живое визуальное превью градиента
        imgui.SameLine(0, 16)
        imgui.Text(safeU8("Превью: "))
        imgui.SameLine(0, 4)

        if gradMode == 1 then
            local words = {}
            for w in srcTxt:gmatch("%S+") do table.insert(words, w) end
            local total = #words
            for i, w in ipairs(words) do
                local t = (total > 1) and ((i - 1) / (total - 1)) or 0
                local r = gradCol1[0] + (gradCol2[0] - gradCol1[0]) * t
                local g = gradCol1[1] + (gradCol2[1] - gradCol1[1]) * t
                local b = gradCol1[2] + (gradCol2[2] - gradCol1[2]) * t
                imgui.TextColored(imgui.ImVec4(r, g, b, 1.0), safeU8(w))
                imgui.SameLine(0, 4)
            end
        else
            local chars = {}
            for c in srcTxt:gmatch("[%z\1-\127\194-\244][\128-\191]*") do table.insert(chars, c) end
            if #chars == 0 then for i = 1, #srcTxt do table.insert(chars, srcTxt:sub(i, i)) end end
            local total = #chars
            for i, c in ipairs(chars) do
                local t = (total > 1) and ((i - 1) / (total - 1)) or 0
                local r = gradCol1[0] + (gradCol2[0] - gradCol1[0]) * t
                local g = gradCol1[1] + (gradCol2[1] - gradCol1[1]) * t
                local b = gradCol1[2] + (gradCol2[2] - gradCol1[2]) * t
                imgui.TextColored(imgui.ImVec4(r, g, b, 1.0), safeU8(c))
                imgui.SameLine(0, 0)
            end
        end
        imgui.NewLine()

        -- Ряд 4: Кнопки действий
        imgui.Spacing()
        if imgui.Button(fa.ICON_CLIPBOARD .. safeU8("  Скопировать градиент##copy_grad_btn"), imgui.ImVec2(220, 28)) then
            setClipboardText(gradFormatted)
            showToastQuick(safeU8("Градиент скопирован"), safeU8("Готов к вставке в 3D-текст"))
        end
        if imgui.IsItemHovered() then
            imgui.SetTooltip(gradFormatted .. safeU8("\nНажмите, чтобы скопировать строку с тегами цвета в буфер обмена"))
        end

        if otextTextBuf then
            imgui.SameLine(0, 10)
            if imgui.Button(fa.ICON_PENCIL .. safeU8("  Вставить в 3D-текст (/otext)##paste_to_otext"), imgui.ImVec2(240, 28)) then
                imgui.StrCopy(otextTextBuf, gradFormatted)
                setClipboardText(gradFormatted)
                SwitchTab(15)
                selectedObj = nil
                showToastQuick(safeU8("Вставлено в 3D-текст"), safeU8("Градиент скопирован и применён"))
            end
            if imgui.IsItemHovered() then
                imgui.SetTooltip(safeU8("Вставить градиент в поле 3D-текста и перейти на вкладку 'Текст'"))
            end
        end
    end

    imgui.Unindent(10)
end
function scanObjectsForPrefab(radius)
    if not PLAYER_PED or not doesCharExist(PLAYER_PED) then return end
    local px, py, pz = getCharCoordinates(PLAYER_PED)
    local heading = getCharHeading(PLAYER_PED)

    local rad = math.rad(-heading)
    local fx = math.sin(rad)
    local fy = math.cos(rad)
    local rx = fy
    local ry = -fx

    local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
    local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
    local fwdX, fwdY, fwdZ = 0, 1, 0
    if okCam and okAt and camX and atX then
        fwdX, fwdY, fwdZ = atX - camX, atY - camY, atZ - camZ
    end
    local sw, sh = getScreenResolution()
    local onlyFront = prefabCaptureOnlyFront and (prefabCaptureOnlyFront[0] == true)

    toast_text  = "Сканирование объектов..."
    toast_text2 = string.format("Радиус: %.1f м (перед игроком)", radius)
    toast_timer = 80

    local function isObjectInFrontAndScreen(ox, oy, oz)
        if not onlyFront then return true end

        -- 1. Не сзади персонажа игрока
        local dx = ox - px
        local dy = oy - py
        local locFwd = dx * fx + dy * fy
        if locFwd < -0.5 then
            return false
        end

        -- 2. Не сзади камеры
        if okCam and okAt and camX and atX then
            local toCamX = ox - camX
            local toCamY = oy - camY
            local toCamZ = oz - camZ
            local dotCam = fwdX * toCamX + fwdY * toCamY + fwdZ * toCamZ
            if dotCam <= 0 then
                return false
            end
        end

        -- 3. На экране перед игроком (с запасом 100 пикселей для краев построек)
        local sx, sy = convert3DCoordsToScreen(ox, oy, oz)
        if not sx or not sy then
            return false
        end
        if sx < -100 or sx > (sw + 100) or sy < -100 or sy > (sh + 100) then
            return false
        end

        return true
    end

    prefabCaptureOrigin = { x = px, y = py, z = pz, heading = heading }
    prefabCapturedList = {}

    local foundIds = {}

    -- 1. Сканируем нативные 3D-тексты SA-MP
    for id = 0, 2047 do
        local ok, defined = pcall(sampIs3dTextDefined, id)
        if ok and defined then
            local ok2, text3d, _, lx, ly, lz = pcall(sampGet3dTextInfoById, id)
            if ok2 and text3d and text3d ~= "" then
                local cleanText = text3d:gsub("{%x%x%x%x%x%x}", "")
                local oNum, mNum = cleanText:match("#(%d+)%s*[-–—]%s*#(%d+)")
                if not oNum then
                    oNum, mNum = cleanText:match("#(%d+).-#(%d+)")
                end
                if oNum and mNum and not foundIds[oNum] then
                    local dist = getDistanceBetweenCoords3d(px, py, pz, lx, ly, lz)
                    if dist <= radius and isObjectInFrontAndScreen(lx, ly, lz) then
                        foundIds[oNum] = {
                            id = oNum,
                            modelId = tonumber(mNum),
                            x = lx, y = ly, z = lz,
                            dist = dist
                        }
                    end
                end
            end
        end
    end

    -- 2. Проверяем labelCache
    if labelCache then
        for _, lbl in pairs(labelCache) do
            if lbl and lbl.text then
                local cleanText = lbl.text:gsub("{%x%x%x%x%x%x}", "")
                local oNum, mNum = cleanText:match("#(%d+)%s*[-–—]%s*#(%d+)")
                if not oNum then
                    oNum, mNum = cleanText:match("#(%d+).-#(%d+)")
                end
                if oNum and mNum and not foundIds[oNum] then
                    local dist = getDistanceBetweenCoords3d(px, py, pz, lbl.x, lbl.y, lbl.z)
                    if dist <= radius and isObjectInFrontAndScreen(lbl.x, lbl.y, lbl.z) then
                        foundIds[oNum] = {
                            id = oNum,
                            modelId = tonumber(mNum),
                            x = lbl.x, y = lbl.y, z = lbl.z,
                            dist = dist
                        }
                    end
                end
            end
        end
    end

    -- 3. Проверяем knownMapObjects
    if knownMapObjects then
        for oNum, inf in pairs(knownMapObjects) do
            if inf and inf.x and not foundIds[oNum] then
                local dist = getDistanceBetweenCoords3d(px, py, pz, inf.x, inf.y, inf.z)
                if dist <= radius and isObjectInFrontAndScreen(inf.x, inf.y, inf.z) then
                    foundIds[oNum] = {
                        id = oNum,
                        modelId = tonumber(inf.modelId),
                        x = inf.x, y = inf.y, z = inf.z,
                        dist = dist
                    }
                end
            end
        end
    end


    -- Формируем элементы списка с точной привязкой к физическим GTA-объектам
    local usedHandles = {}
    local sortedIds = {}
    for oNum, inf in pairs(foundIds) do
        table.insert(sortedIds, { oNum = oNum, inf = inf })
    end
    table.sort(sortedIds, function(a, b) return a.inf.dist < b.inf.dist end)

    for _, entry in ipairs(sortedIds) do
        local oNum = entry.oNum
        local inf = entry.inf
        local sId = tostring(oNum)
        local mId = inf.modelId
        local mName = getModelNameById(mId)
        local ox, oy, oz = inf.x, inf.y, inf.z
        local orx, ory, orz = 0.0, 0.0, 0.0

        -- Если есть в oinfoCache
        local oinfo = oinfoCache and oinfoCache[sId]
        if oinfo then
            if oinfo.modelId and not mId then
                mId = oinfo.modelId
                mName = getModelNameById(mId)
            end
        end

        -- Сверяем и берем ТОЧНЫЕ координаты и углы из физического GTA-объекта (а не с 3D-ярлыка!)
        local hObj = findGtaObjectHandle({modelId = mId, x = ox, y = oy, z = oz}, sId, usedHandles)
        if hObj and doesObjectExist(hObj) then
            usedHandles[hObj] = true
            local gx, gy, gz = getObjectCoordsSafe(hObj)
            if gx and gy and gz then
                ox, oy, oz = gx, gy, gz
            end
            local ex, ey, ez = getObjectEuler(hObj)
            if ex then orx, ory, orz = ex, ey, ez end
        end

        -- Относительные координаты относительно игрока при захвате
        local dx = ox - px
        local dy = oy - py
        local dz = oz - pz
        local locFwd   = dx * fx + dy * fy
        local locRight = dx * rx + dy * ry
        local locUp    = dz
        local relRZ    = shortestAngleDelta(orz, heading)

        -- Материалы и цвета
        local mats = {}
        if oinfo and oinfo.materials then
            for _, m in ipairs(oinfo.materials) do
                local hasTex = (m.texId and m.texId ~= "" and m.texId ~= "0")
                local hasCol = (m.color and m.color ~= "" and m.color ~= "0" and m.color ~= "00000000")
                if hasTex or hasCol then
                    table.insert(mats, {
                        mat = tostring(m.mat or "0"),
                        texId = hasTex and tostring(m.texId) or nil,
                        color = hasCol and tostring(m.color) or nil
                    })
                end
            end
        end

        local tracked = trackedObjMaterials and trackedObjMaterials[sId]
        if tracked then
            for slot, texId in pairs(tracked) do
                local already = false
                for _, existing in ipairs(mats) do
                    if existing.mat == tostring(slot) then
                        if texId and texId ~= "" and texId ~= "0" then existing.texId = tostring(texId) end
                        already = true; break
                    end
                end
                if not already and texId and texId ~= "" and texId ~= "0" then
                    table.insert(mats, { mat = tostring(slot), texId = tostring(texId), color = nil })
                end
            end
        end

        local trackedCol = trackedObjColors and trackedObjColors[sId]
        if trackedCol then
            for slot, col in pairs(trackedCol) do
                local already = false
                for _, existing in ipairs(mats) do
                    if existing.mat == tostring(slot) then
                        if col and col ~= "" and col ~= "0" then existing.color = tostring(col) end
                        already = true; break
                    end
                end
                if not already and col and col ~= "" and col ~= "0" then
                    table.insert(mats, { mat = tostring(slot), texId = nil, color = tostring(col) })
                end
            end
        end

        table.insert(prefabCapturedList, {
            selected     = true,
            objId        = sId,
            modelId      = mId or 0,
            modelName    = mName or ("Model #" .. tostring(mId or 0)),
            x = ox, y = oy, z = oz,
            rx = orx, ry = ory, rz = orz,
            rawRX = orx,
            rawRY = ory,
            rawRZ = orz,
            dist         = getDistanceBetweenCoords3d(px, py, pz, ox, oy, oz),
            localForward = locFwd,
            localRight   = locRight,
            localUp      = locUp,
            relRX        = orx,
            relRY        = ory,
            relRZ        = relRZ,
            materials    = (#mats > 0) and mats or nil
        })
    end
    table.sort(prefabCapturedList, function(a, b) return a.dist < b.dist end)
    toast_text  = "Сканирование завершено"
    toast_text2 = string.format("Обнаружено объектов: %d", #prefabCapturedList)
    toast_timer = 90
end


-- ============================================================================
-- [STAGE 3] PREFAB 3D GHOST PREVIEW, MIRRORING & CLIPBOARD SHARING
-- ============================================================================
prefabGhostActive = false
prefabGhostTarget = nil
prefabGhostYaw = 0.0
prefabGhostZOffset = 0.0
prefabGhostBounds = nil

local function computePrefabBounds(p)
    if not p then return nil end
    local minFwd, maxFwd = 99999, -99999
    local minRight, maxRight = 99999, -99999
    local minUp, maxUp = 99999, -99999
    local pts = {}
    if p.isCaptured and p.objects and #p.objects > 0 then
        for _, obj in ipairs(p.objects) do
            local f = obj.localForward or 0.0
            local r = obj.localRight or 0.0
            local u = obj.localUp or 0.0
            table.insert(pts, {f = f, r = r, u = u, modelId = obj.modelId})
            if f - 0.8 < minFwd then minFwd = f - 0.8 end
            if f + 0.8 > maxFwd then maxFwd = f + 0.8 end
            if r - 0.8 < minRight then minRight = r - 0.8 end
            if r + 0.8 > maxRight then maxRight = r + 0.8 end
            if u < minUp then minUp = u end
            if u + 1.2 > maxUp then maxUp = u + 1.2 end
        end
    elseif p.steps and #p.steps > 0 then
        local curX, curY, curZ = 0.0, 0.0, 0.0
        table.insert(pts, {f = 0.0, r = 0.0, u = 0.0})
        for _, line in ipairs(p.steps) do
            local cmd, val = line:match("^/(%a+)%s+([%-%d%.]+)")
            if cmd and val then
                local num = tonumber(val) or 0.0
                if cmd == "ox" then curX = curX + num
                elseif cmd == "oy" then curY = curY + num
                elseif cmd == "oz" then curZ = curZ + num
                elseif cmd == "cr" or cmd == "clone" then
                    table.insert(pts, {f = curY, r = curX, u = curZ})
                end
                if curY - 0.8 < minFwd then minFwd = curY - 0.8 end
                if curY + 0.8 > maxFwd then maxFwd = curY + 0.8 end
                if curX - 0.8 < minRight then minRight = curX - 0.8 end
                if curX + 0.8 > maxRight then maxRight = curX + 0.8 end
                if curZ < minUp then minUp = curZ end
                if curZ + 1.2 > maxUp then maxUp = curZ + 1.2 end
            end
        end
    end
    if minFwd > maxFwd then
        minFwd, maxFwd = -1.5, 1.5
        minRight, maxRight = -1.5, 1.5
        minUp, maxUp = 0.0, 2.0
    end
    local centerFwd = (minFwd + maxFwd) * 0.5
    local centerRight = (minRight + maxRight) * 0.5
    return {
        minFwd = minFwd, maxFwd = maxFwd,
        minRight = minRight, maxRight = maxRight,
        minUp = minUp, maxUp = maxUp,
        centerFwd = centerFwd, centerRight = centerRight,
        width = math.max(0.5, maxRight - minRight),
        length = math.max(0.5, maxFwd - minFwd),
        height = math.max(0.5, maxUp - minUp),
        points = pts
    }
end

prefabGhostObjects = {}

local function safeLoadModel(modelId)
    local m = tonumber(modelId)
    if not m or m <= 0 then return false end
    local ok, loaded = pcall(hasModelLoaded, m)
    if ok and loaded then return true end
    pcall(requestModel, m)
    pcall(loadAllModelsNow)
    local ok2, loaded2 = pcall(hasModelLoaded, m)
    return ok2 and loaded2
end

function clearPrefabGhostObjects()
    if prefabGhostObjects and #prefabGhostObjects > 0 then
        for _, item in ipairs(prefabGhostObjects) do
            if item.handle and item.handle ~= 0 then
                pcall(setObjectCollision, item.handle, false)
                pcall(setObjectCoordinates, item.handle, 0.0, 0.0, -3000.0)
                pcall(deleteObject, item.handle)
                pcall(destroyObject, item.handle)
                pcall(markObjectAsNoLongerNeeded, item.handle)
                item.handle = nil
            end
            if item.modelId then
                pcall(markModelAsNoLongerNeeded, item.modelId)
            end
        end
    end
    prefabGhostObjects = {}
end

local function spawnPrefabGhostObjects(p)
    clearPrefabGhostObjects()
    if not p then return end

    local items = {}
    if p.isCaptured and p.objects and #p.objects > 0 then
        for _, obj in ipairs(p.objects) do
            if obj.modelId and tonumber(obj.modelId) and tonumber(obj.modelId) > 0 then
                table.insert(items, {
                    modelId = tonumber(obj.modelId),
                    f = obj.localForward or 0.0,
                    r = obj.localRight or 0.0,
                    u = obj.localUp or 0.0,
                    rawRX = obj.rawRX, rawRY = obj.rawRY, rawRZ = obj.rawRZ,
                    relRX = obj.relRX or 0.0, relRY = obj.relRY or 0.0, relRZ = obj.relRZ or 0.0,
                    handle = nil
                })
            end
            if #items >= 120 then break end
        end
    elseif p.steps and #p.steps > 0 then
        local curId = nil
        local curDX, curDY, curDZ = 0.0, 0.0, 0.0
        local curRX, curRY, curRZ = 0.0, 0.0, 0.0

        local function flushStepObj()
            if not curId then return end
            table.insert(items, {
                modelId = tonumber(curId),
                f = curDY,
                r = curDX,
                u = curDZ,
                relRX = curRX, relRY = curRY, relRZ = curRZ,
                handle = nil
            })
        end

        for _, step in ipairs(p.steps) do
            local nm, arg = step:match("^/(%a+)%s*(.-)%s*$")
            if nm then
                nm = nm:lower()
                if nm == "cr" or nm == "clone" then
                    flushStepObj()
                    curId = arg:match("%d+")
                    curDX, curDY, curDZ = 0.0, 0.0, 0.0
                    curRX, curRY, curRZ = 0.0, 0.0, 0.0
                elseif nm == "ox" then curDX = curDX + (tonumber(arg) or 0.0)
                elseif nm == "oy" then curDY = curDY + (tonumber(arg) or 0.0)
                elseif nm == "oz" then curDZ = curDZ + (tonumber(arg) or 0.0)
                elseif nm == "rx" then curRX = curRX + (tonumber(arg) or 0.0)
                elseif nm == "ry" then curRY = curRY + (tonumber(arg) or 0.0)
                elseif nm == "rz" then curRZ = curRZ + (tonumber(arg) or 0.0)
                end
            end
            if #items >= 120 then break end
        end
        flushStepObj()
    end

    local px, py, pz = getCharCoordinates(PLAYER_PED)
    for _, it in ipairs(items) do
        local mId = it.modelId
        if safeLoadModel(mId) then
            local ok, handle = pcall(createObject, mId, px, py, pz - 200.0)
            if ok and handle and handle ~= 0 then
                pcall(setObjectCollision, handle, false)
                it.handle = handle
                table.insert(prefabGhostObjects, it)
            end
        end
    end
end

function startPrefabGhost(p)
    if not p then return end
    clearPrefabGhostObjects()
    winOpen[0] = false
    prefabGhostTarget = p
    prefabGhostYaw = getCharHeading(PLAYER_PED)
    prefabGhostZOffset = 0.0
    prefabGhostBounds = computePrefabBounds(p)
    prefabGhostActive = true

    -- Создаем визуальные 3D-объекты призрака
    spawnPrefabGhostObjects(p)

    showToastQuick("3D Предпросмотр префаба", "ЛКМ - Построить | Колесико - Поворот | ESC - Отмена")
end

function mirrorPrefabCurrent(idx, axis)
    local curP = (type(idx) == "number") and prefabs[idx] or nil
    if curP and curP.isCaptured and curP.objects then
        for _, obj in ipairs(curP.objects) do
            if axis == "X" then
                obj.localRight = -(obj.localRight or 0.0)
                if obj.relRZ then obj.relRZ = shortestAngleDelta(-obj.relRZ, 0) end
                if obj.relRY then obj.relRY = shortestAngleDelta(-obj.relRY, 0) end
            else
                obj.localForward = -(obj.localForward or 0.0)
                if obj.relRZ then obj.relRZ = shortestAngleDelta(180.0 - obj.relRZ, 0) end
                if obj.relRX then obj.relRX = shortestAngleDelta(-obj.relRX, 0) end
            end
        end
        savePrefabs()
    end

    local raw = ffi.string(editPrefabBuf)
    local newLines = {}
    for line in raw:gmatch("[^\r\n]+") do
        local t = line:match("^%s*(.-)%s*$")
        if t ~= "" then
            local cmd, val = t:match("^/(%a+)%s+([%-%d%.]+)")
            if cmd and val then
                local num = tonumber(val) or 0.0
                if axis == "X" then
                    if cmd == "ox" then
                        t = string.format("/ox %.2f", -num)
                    elseif cmd == "rz" then
                        t = string.format("/rz %.2f", shortestAngleDelta(-num, 0))
                    elseif cmd == "ry" then
                        t = string.format("/ry %.2f", shortestAngleDelta(-num, 0))
                    end
                else
                    if cmd == "oy" then
                        t = string.format("/oy %.2f", -num)
                    elseif cmd == "rz" then
                        t = string.format("/rz %.2f", shortestAngleDelta(180.0 - num, 0))
                    elseif cmd == "rx" then
                        t = string.format("/rx %.2f", shortestAngleDelta(-num, 0))
                    end
                end
            end
            table.insert(newLines, t)
        end
    end
    imgui.StrCopy(editPrefabBuf, table.concat(newLines, "\n"))
    showToastQuick("Отражение префаба", string.format("Префаб успешно отражен по оси %s", axis))
end

function exportPrefabToClipboard(p)
    if not p then return end
    local cpName = safeCP1251(p.name or "Префаб")
    local exportData = {
        v = 1,
        name = cpName,
        isCaptured = p.isCaptured or false,
        originHeading = p.originHeading,
        objects = p.objects,
        steps = p.steps
    }
    local ok, encoded = pcall(json.encode, exportData)
    if ok and encoded then
        local shareStr = "[TMT-PREFAB-V1]:" .. encoded
        setClipboardText(shareStr)
        showToastQuick("Экспорт префаба", string.format("'%s' скопирован в буфер", cpName))
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Постройка {FF9326}'%s'{FFFFFF} скопирована в буфер обмена!", cpName), -1)
    else
        showToastQuick("Ошибка", "Не удалось экспортировать префаб")
    end
end

function importPrefabFromClipboard()
    local clip = getClipboardText()
    if not clip or clip == "" then
        showToastQuick("Буфер обмена", "Буфер обмена пуст")
        return
    end
    local jsonPayload = clip:match("%[TMT%-PREFAB%-V%d%]:%s*(.+)$") or clip
    local ok, data = pcall(json.decode, jsonPayload)
    if ok and type(data) == "table" and (data.objects or data.steps) then
        local newName = safeCP1251(data.name or "Импортированный префаб")
        local imported = {
            name = newName,
            isCaptured = data.isCaptured or false,
            originHeading = data.originHeading,
            objects = data.objects,
            steps = data.steps,
            date = os.time(),
            preview = nil
        }
        table.insert(prefabs, imported)
        savePrefabs()
        showToastQuick("Префаб импортирован", string.format("'%s' добавлен в библиотеку", newName))
        sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Префаб {FF9326}'%s'{FFFFFF} успешно добавлен в библиотеку!", newName), -1)
    else
        showToastQuick("Ошибка импорта", "Неверный формат данных префаба TMT")
    end
end

local function playPrefab(prefab, customX, customY, customZ, customHeading)
    clearPrefabGhostObjects()
    prefabGhostActive = false
    if not prefab then return end
    if prefabPlaying then
        showToastQuick("Префаб уже спавнится", "Пожалуйста, подождите.")
        return
    end

    -- Режим 1: Захваченные объекты (точное позиционирование)
    if prefab.isCaptured and prefab.objects and #prefab.objects > 0 then
        lua_thread.create(function()
            prefabPlaying = true
            local prefTitle = safeCP1251(prefab.name or "Префаб")
            toast_text = "Спавн префаба: " .. (prefab.name or "")
            toast_text2 = prefTitle .. " (" .. #prefab.objects .. " об.)"
            toast_timer = 150
            sampAddChatMessage(string.format('{FF9326}[TMT]{FFFFFF} Спавн префаба {FF9326}"%s"{FFFFFF} (%d об.)...', prefTitle, #prefab.objects), -1)

            -- Заморозка персонажа и блокировка управления
            pcall(freezeCharPosition, PLAYER_PED, true)
            pcall(lockPlayerControl, true)

            local px, py, pz = getCharCoordinates(PLAYER_PED)
            local heading = getCharHeading(PLAYER_PED)
            if customX and customY and customZ then
                px, py, pz = customX, customY, customZ
            end
            if customHeading then
                heading = customHeading
            end

            local rad = math.rad(-heading)
            local fx = math.sin(rad)
            local fy = math.cos(rad)
            local rx = fy
            local ry = -fx

            local deltaHeading = 0.0
            if prefab.originHeading then
                deltaHeading = shortestAngleDelta(heading, prefab.originHeading)
            end

            local function sendOffsetAxis(cmdName, delta)
                local remaining = delta
                local stepLimit = 5.0
                while math.abs(remaining) > 0.005 do
                    if not prefabPlaying then break end
                    local step = remaining
                    if step > stepLimit then step = stepLimit end
                    if step < -stepLimit then step = -stepLimit end
                    local sendStep = math.floor(step * 100 + (step >= 0 and 0.5 or -0.5)) / 100
                    if math.abs(sendStep) < 0.01 then break end
                    sampSendChat(string.format("%s %.2f", cmdName, sendStep))
                    remaining = remaining - sendStep
                    wait(350)
                end
            end

            for objIdx, obj in ipairs(prefab.objects) do
                if not prefabPlaying then break end

                toast_text  = string.format("Спавн (%d/%d)", objIdx, #prefab.objects)
                toast_text2 = string.format("Модель #%d (%s)", obj.modelId, obj.modelName or "")
                toast_timer = 120

                local targetX = px + obj.localForward * fx + obj.localRight * rx
                local targetY = py + obj.localForward * fy + obj.localRight * ry
                local targetZ = pz + (obj.localUp or 0.0)

                local targetRX, targetRY, targetRZ
                if obj.rawRX and obj.rawRY and obj.rawRZ then
                    targetRX, targetRY, targetRZ = rotateEulerYaw(obj.rawRX, obj.rawRY, obj.rawRZ, deltaHeading)
                else
                    targetRX = obj.relRX or 0.0
                    targetRY = obj.relRY or 0.0
                    targetRZ = (heading + (obj.relRZ or 0.0)) % 360
                end

                local existingHandles = {}
                for _, h in pairs(getAllObjects()) do existingHandles[h] = true end

                sampSendChat("/cr " .. tostring(obj.modelId))

                local newHandle = nil
                local timeout = os.clock() + 3.0
                while os.clock() < timeout do
                    if not prefabPlaying then break end
                    wait(50)
                    for _, h in pairs(getAllObjects()) do
                        if not existingHandles[h] and doesObjectExist(h) then
                            local okM, m = pcall(getObjectModel, h)
                            if okM and m == obj.modelId then
                                newHandle = h
                                break
                            end
                        end
                    end
                    if newHandle then break end
                end

                if not prefabPlaying then break end

                if newHandle and doesObjectExist(newHandle) then
                    wait(450)
                    if not prefabPlaying then break end

                    -- 1. Смещение координат
                    local curX, curY, curZ = getObjectCoordsSafe(newHandle)
                    if curX and curY and curZ then
                        local dx = targetX - curX
                        local dy = targetY - curY
                        local dz = targetZ - curZ
                        if math.abs(dx) > 0.01 and prefabPlaying then sendOffsetAxis("/ox", dx) end
                        if math.abs(dy) > 0.01 and prefabPlaying then sendOffsetAxis("/oy", dy) end
                        if math.abs(dz) > 0.01 and prefabPlaying then sendOffsetAxis("/oz", dz) end
                    end
                    if not prefabPlaying then break end

                    -- 2. Вращение
                    local curRX, curRY, curRZ = getObjectEuler(newHandle)
                    if curRX then
                        local drx = shortestAngleDelta(targetRX, curRX)
                        local dry = shortestAngleDelta(targetRY, curRY)
                        local drz = shortestAngleDelta(targetRZ, curRZ)
                        local EPS_ROT = 0.05
                        if math.abs(drx) > EPS_ROT and prefabPlaying then sampSendChat(string.format("/rx %.2f", drx)); wait(350) end
                        if math.abs(dry) > EPS_ROT and prefabPlaying then sampSendChat(string.format("/ry %.2f", dry)); wait(350) end
                        if math.abs(drz) > EPS_ROT and prefabPlaying then sampSendChat(string.format("/rz %.2f", drz)); wait(350) end
                    end
                    if not prefabPlaying then break end

                    -- 3. Доводка координат
                    wait(200)
                    if not prefabPlaying then break end
                    local postX, postY, postZ = getObjectCoordsSafe(newHandle)
                    if postX and postY and postZ then
                        local fdx = targetX - postX
                        local fdy = targetY - postY
                        local fdz = targetZ - postZ
                        if math.abs(fdx) >= 0.015 and prefabPlaying then sampSendChat(string.format("/ox %.2f", fdx)); wait(300) end
                        if math.abs(fdy) >= 0.015 and prefabPlaying then sampSendChat(string.format("/oy %.2f", fdy)); wait(300) end
                        if math.abs(fdz) >= 0.015 and prefabPlaying then sampSendChat(string.format("/oz %.2f", fdz)); wait(300) end
                    end
                    if not prefabPlaying then break end

                    -- 4. Установка текстур слотов
                    if obj.materials and #obj.materials > 0 then
                        wait(200)
                        for _, mat in ipairs(obj.materials) do
                            if not prefabPlaying then break end
                            local slot = tostring(mat.mat or "0")
                            if mat.texId and mat.texId ~= "" and mat.texId ~= "0" then
                                sampSendChat(string.format("/mtset %s %s", slot, tostring(mat.texId)))
                                wait(350)
                            end
                            if mat.color and mat.color ~= "" and mat.color ~= "0" and mat.color ~= "00000000" then
                                sampSendChat(string.format("/mtcol %s %s", slot, tostring(mat.color)))
                                wait(350)
                            end
                        end
                    end
                else
                    -- Объект не появился (сервер отклонил /cr)
                    break
                end
                wait(200)
            end

            pcall(freezeCharPosition, PLAYER_PED, false)
            pcall(lockPlayerControl, false)

            if prefabPlaying then
                prefabPlaying = false
                toast_text  = "Префаб спавнен!"
                toast_text2 = prefTitle .. " (" .. #prefab.objects .. " об.)"
                toast_timer = 150
                sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Постройка {FF9326}'%s'{FFFFFF} успешно установлена ({00FF88}%d об.{FFFFFF})!", prefTitle, #prefab.objects), -1)
            end
        end)
        return
    end

    -- Режим 2: Режим по шагам (/cr /ox /oy /oz /rx /ry /rz)
    if not prefab.steps or #prefab.steps == 0 then return end

    lua_thread.create(function()
        prefabPlaying = true
        toast_text  = "Префаб: " .. (prefab.name or "Макрос")
        toast_preencoded = true
        toast_text2 = "Выполнение макроса..."
        toast_tex   = nil
        toast_timer = 120

        local firstObjDone = false
        for _, cmd in ipairs(prefab.steps) do
            if not prefabPlaying then break end
            sampSendChat(cmd)
            local name = cmd:match("^/(%a+)")
            if name == "cr" or name == "clone" then
                wait(500)
                if not firstObjDone and customX and customY and customZ then
                    firstObjDone = true
                    local curPedX, curPedY, curPedZ = getCharCoordinates(PLAYER_PED)
                    local bdx = customX - curPedX
                    local bdy = customY - curPedY
                    local bdz = customZ - curPedZ
                    if math.abs(bdx) > 0.01 and prefabPlaying then sampSendChat(string.format("/ox %.2f", bdx)); wait(300) end
                    if math.abs(bdy) > 0.01 and prefabPlaying then sampSendChat(string.format("/oy %.2f", bdy)); wait(300) end
                    if math.abs(bdz) > 0.01 and prefabPlaying then sampSendChat(string.format("/oz %.2f", bdz)); wait(300) end
                end
            else
                wait(250)
            end
        end

        pcall(freezeCharPosition, PLAYER_PED, false)
        pcall(lockPlayerControl, false)

        if prefabPlaying then
            prefabPlaying = false
            toast_text  = "Префаб: " .. (prefab.name or "Макрос")
            toast_preencoded = true
            toast_text2 = #prefab.steps .. " команд выполнено."
            toast_tex   = nil
            toast_timer = 120
        end
    end)
end

prefabSearchBuf = prefabSearchBuf or imgui.new.char[64]()
prefabFilterType = prefabFilterType or 0 -- 0: Все, 1: Захваченные, 2: Макросы

local function renderTabPrefabs()
    imgui.Indent(10)
    imgui.Spacing()

    -- ========================================================================
    -- [1] РЕЖИМ ЗАХВАТА ОБЛАСТИ ОБЪЕКТОВ В ПРЕФАБ
    -- ========================================================================
    if prefabCaptureOpen then
        imgui.BeginGroup()
            if imgui.Button(fa.ICON_ARROW_LEFT .. safeU8"  Назад к библиотеке##cap_back", imgui.ImVec2(180, 28)) then
                prefabCaptureOpen = false
            end
            imgui.SameLine(0, 15)
            imgui.TextColored(accentColor(), fa.ICON_CROSSHAIRS .. safeU8"  ЗАХВАТ ОБЛАСТИ ОБЪЕКТОВ")
        imgui.EndGroup()
        imgui.Separator(); imgui.Spacing()

        imgui.TextDisabled(safeU8"Сканирует сервером созданные объекты в указанном радиусе и позволяет объединить их в единый префаб.")
        imgui.Spacing()

        -- Панель настроек сканирования
        imgui.PushItemWidth(200)
        if imgui.SliderFloat(safeU8"Радиус (м)##scan_rad", prefabScanRadius, 3.0, 60.0, "%.1f м") then
            scanObjectsForPrefab(prefabScanRadius[0])
        end
        imgui.PopItemWidth()

        imgui.SameLine(0, 12)
        if imgui.Checkbox(safeU8"Только спереди##pref_only_front", prefabCaptureOnlyFront) then
            scanObjectsForPrefab(prefabScanRadius[0])
        end

        imgui.SameLine(0, 12)
        imgui.Checkbox(safeU8"3D ESP Подсветка##pref_esp", prefabCaptureEspEnabled)

        imgui.SameLine(0, 14)
        if imgui.Button(fa.ICON_REFRESH .. safeU8"  Обновить##rescan_btn", imgui.ImVec2(130, 26)) then
            scanObjectsForPrefab(prefabScanRadius[0])
        end

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        local selCount = 0
        local exclCount = 0
        for _, it in ipairs(prefabCapturedList) do
            if it.selected then
                selCount = selCount + 1
            else
                exclCount = exclCount + 1
            end
        end

        if prefabCapViewMode == 0 then
            imgui.TextColored(accentColor(), fa.ICON_LIST .. safeU8"  СПИСОК ОБЪЕКТОВ")
            imgui.SameLine()
            imgui.TextDisabled(safeU8(string.format("(Выбрано: %d из %d)", selCount, #prefabCapturedList)))

            imgui.SameLine(0, 15)
            if imgui.Button(safeU8"Выбрать все##sel_all", imgui.ImVec2(100, 24)) then
                for _, it in ipairs(prefabCapturedList) do it.selected = true end
            end
            imgui.SameLine(0, 6)
            if imgui.Button(safeU8"Снять все##desel_all", imgui.ImVec2(90, 24)) then
                for _, it in ipairs(prefabCapturedList) do it.selected = false end
            end

            imgui.SameLine(0, 10)
            local exclLabel = string.format("Исключенные (%d)##open_excl", exclCount)
            if imgui.Button(fa.ICON_BAN .. "  " .. safeU8(exclLabel), imgui.ImVec2(150, 24)) then
                prefabCapViewMode = 1
            end
        else
            imgui.TextColored(imgui.ImVec4(0.95, 0.4, 0.4, 1.0), fa.ICON_BAN .. safeU8"  ИСКЛЮЧЕННЫЕ ОБЪЕКТЫ")
            imgui.SameLine()
            imgui.TextDisabled(safeU8(string.format("(Исключено: %d из %d)", exclCount, #prefabCapturedList)))

            imgui.SameLine(0, 15)
            if imgui.Button(fa.ICON_ARROW_LEFT .. safeU8"  К активным##back_active", imgui.ImVec2(140, 24)) then
                prefabCapViewMode = 0
            end

            imgui.SameLine(0, 8)
            if imgui.Button(fa.ICON_UNDO .. safeU8"  Вернуть все##restore_all", imgui.ImVec2(150, 24)) then
                for _, it in ipairs(prefabCapturedList) do it.selected = true end
                prefabCapViewMode = 0
            end
        end

        imgui.Spacing()

        -- Скроллируемая сетка захваченных объектов
        imgui.BeginChild("##pref_cap_list", imgui.ImVec2(-1, 260), true)
            local displayedList = {}
            for _, it in ipairs(prefabCapturedList) do
                if prefabCapViewMode == 1 then
                    if not it.selected then table.insert(displayedList, it) end
                else
                    if it.selected then table.insert(displayedList, it) end
                end
            end

            if #displayedList == 0 then
                imgui.Spacing(); imgui.Spacing()
                if #prefabCapturedList == 0 then
                    imgui.TextDisabled(safeU8("В радиусе " .. string.format("%.1f", prefabScanRadius[0]) .. " м не найдено серверных объектов."))
                    imgui.TextDisabled(safeU8"Подойдите ближе к объектам или увеличьте радиус сканирования.")
                elseif prefabCapViewMode == 1 then
                    imgui.TextDisabled(safeU8"Нет исключенных объектов.")
                else
                    imgui.TextDisabled(safeU8"Все объекты исключены.")
                end
            else
                local availW = imgui.GetContentRegionAvail().x
                local cardW = 86
                local cardH = 96
                local padX = 8
                local padY = 8
                local cols = math.max(1, math.floor((availW + padX) / (cardW + padX)))
                local col = 0

                for i, it in ipairs(displayedList) do
                    if col > 0 then imgui.SameLine(0, padX) end

                    imgui.BeginGroup()
                        local p = imgui.GetCursorScreenPos()
                        local isSel = it.selected
                        local bgCol = isSel and 0xEE14241B or 0xDD241414
                        local borderCol = isSel and 0xCC2ECC71 or 0xCC994444

                        local dl = imgui.GetWindowDrawList()
                        dl:AddRectFilled(p, imgui.ImVec2(p.x + cardW, p.y + cardH), bgCol, 5.0)
                        dl:AddRect(p, imgui.ImVec2(p.x + cardW, p.y + cardH), borderCol, 5.0, 15, 1.2)

                        if isSel then
                            dl:AddCircleFilled(imgui.ImVec2(p.x + 12, p.y + 12), 6.5, 0xEE2ECC71)
                            dl:AddText(imgui.ImVec2(p.x + 8, p.y + 5), 0xFFFFFFFF, fa.ICON_CHECK)
                        else
                            dl:AddCircleFilled(imgui.ImVec2(p.x + 12, p.y + 12), 6.5, 0xEECC3333)
                            dl:AddText(imgui.ImVec2(p.x + 9, p.y + 5), 0xFFFFFFFF, fa.ICON_TIMES)
                        end

                        local tex = getTex(it.modelId)
                        local imgSize = 48
                        local imgX = p.x + (cardW - imgSize) * 0.5
                        local imgY = p.y + 6

                        if tex then
                            dl:AddImage(tex, imgui.ImVec2(imgX, imgY), imgui.ImVec2(imgX + imgSize, imgY + imgSize))
                        else
                            dl:AddRectFilled(imgui.ImVec2(imgX, imgY), imgui.ImVec2(imgX + imgSize, imgY + imgSize), 0x44000000, 4.0)
                            dl:AddText(imgui.ImVec2(imgX + 4, imgY + 16), 0xFFAAAAAA, string.format("#%d", it.modelId))
                        end

                        local textY1 = p.y + 58
                        local textY2 = p.y + 74
                        local idStr = "#" .. tostring(it.objId)
                        local distStr = string.format("%.1fм", it.dist or 0)

                        dl:AddText(imgui.ImVec2(p.x + 6, textY1), isSel and 0xFF2ECC71 or 0xFF888888, idStr)
                        dl:AddText(imgui.ImVec2(p.x + cardW - 36, textY1), 0xFFAAAAAA, safeU8(distStr))

                        local mName = it.modelName or ("#" .. tostring(it.modelId))
                        if #mName > 10 then mName = mName:sub(1, 9) .. ".." end
                        dl:AddText(imgui.ImVec2(p.x + 6, textY2), 0xFFCCCCCC, safeU8(mName))

                        imgui.InvisibleButton("##card_btn_" .. tostring(it.objId) .. "_" .. i, imgui.ImVec2(cardW, cardH))
                        if imgui.IsItemHovered() then
                            dl:AddRect(p, imgui.ImVec2(p.x + cardW, p.y + cardH), 0xFFFFFFFF, 5.0, 15, 1.8)
                            imgui.BeginTooltip()
                                if tex then imgui.Image(tex, imgui.ImVec2(90, 90)) end
                                imgui.TextColored(accentColor(), safeU8(it.modelName or ("Модель #" .. it.modelId)))
                                imgui.Separator()
                                imgui.Text(safeU8(string.format("Объект: #%s", tostring(it.objId))))
                                imgui.Text(safeU8(string.format("Модель ID: %d", it.modelId)))
                                imgui.Text(safeU8(string.format("Дистанция: %.1f м", it.dist or 0)))
                                if it.materials and #it.materials > 0 then
                                    imgui.TextColored(imgui.ImVec4(0.3, 0.9, 0.4, 1.0), safeU8(string.format("Текстур: %d", #it.materials)))
                                end
                                imgui.Spacing()
                                if isSel then
                                    imgui.TextColored(imgui.ImVec4(0.9, 0.4, 0.4, 1.0), safeU8"Клик: исключить из префаба")
                                else
                                    imgui.TextColored(imgui.ImVec4(0.4, 0.9, 0.4, 1.0), safeU8"Клик: включить в префаб")
                                end
                            imgui.EndTooltip()
                        end

                        if imgui.IsItemClicked(0) or imgui.IsItemClicked(1) then
                            it.selected = not it.selected
                        end
                    imgui.EndGroup()

                    col = col + 1
                    if col >= cols then col = 0 end
                end
            end
        imgui.EndChild()

        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        -- Нижняя панель сохранения
        imgui.Text(safeU8"Название префаба:")
        imgui.SameLine()
        imgui.PushItemWidth(300)
        imgui.InputText("##pref_cap_name", prefabCaptureNameBuf, 64)
        imgui.PopItemWidth()

        imgui.SameLine(0, 15)
        if imgui.Button(fa.ICON_CHECK .. safeU8("  Захватить и сохранить (" .. selCount .. " об.)##save_cap"), imgui.ImVec2(270, 32)) then
            if selCount == 0 then
                showToastQuick("Префабы", "Не выбрано ни одного объекта для сохранения!")
            else
                local name = ffi.string(prefabCaptureNameBuf)
                if name == "" then name = "Зона " .. os.date("%d.%m %H:%M") end

                local toProcess = {}
                for _, it in ipairs(prefabCapturedList) do
                    if it.selected then table.insert(toProcess, it) end
                end

                local savedObjects = {}
                local generatedSteps = {}

                lua_thread.create(function()
                    toast_text = "Захват..."
                    toast_text2 = "Считывание текстур объектов..."
                    toast_timer = 200

                    for _, it in ipairs(toProcess) do
                        local sId = tostring(it.objId)
                        local mats = getObjMaterialsList(sId)
                        table.insert(savedObjects, {
                            modelId   = it.modelId,
                            modelName = it.modelName,
                            x         = it.x,
                            y         = it.y,
                            z         = it.z,
                            rx        = it.rx,
                            ry        = it.ry,
                            rz        = it.rz,
                            materials = mats
                        })
                        table.insert(generatedSteps, string.format("/cr %d", it.modelId))
                        table.insert(generatedSteps, string.format("/ox %.2f", it.x - (prefabCaptureOrigin and prefabCaptureOrigin.x or 0)))
                        table.insert(generatedSteps, string.format("/oy %.2f", it.y - (prefabCaptureOrigin and prefabCaptureOrigin.y or 0)))
                        table.insert(generatedSteps, string.format("/oz %.2f", it.z - (prefabCaptureOrigin and prefabCaptureOrigin.z or 0)))
                        table.insert(generatedSteps, string.format("/rx %.2f", it.rx or 0))
                        table.insert(generatedSteps, string.format("/ry %.2f", it.ry or 0))
                        table.insert(generatedSteps, string.format("/rz %.2f", it.rz or 0))
                        if mats then
                            for _, m in ipairs(mats) do
                                if m.texId then table.insert(generatedSteps, string.format("/mtset %s %s", m.mat, m.texId)) end
                                if m.color then table.insert(generatedSteps, string.format("/mtcol %s %s", m.mat, m.color)) end
                            end
                        end
                        wait(50)
                    end

                    local cleanName = safeCP1251(name)
                    table.insert(prefabs, {
                        name = cleanName,
                        isCaptured = true,
                        date = os.time(),
                        captureDate = os.date("%d.%m.%Y %H:%M"),
                        originHeading = prefabCaptureOrigin and prefabCaptureOrigin.heading or getCharHeading(PLAYER_PED),
                        objects = savedObjects,
                        steps = generatedSteps
                    })
                    savePrefabs()

                    prefabCaptureOpen = false
                    showToastQuick("Префаб сохранен!", cleanName .. " (" .. #savedObjects .. " об.)")
                    sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Постройка {FF9326}'%s'{FFFFFF} сохранена в библиотеку ({00FF88}%d об.{FFFFFF})!", cleanName, #savedObjects), -1)
                end)
            end
        end

        imgui.SameLine(0, 10)
        if imgui.Button(safeU8"Отмена##cancel_cap", imgui.ImVec2(110, 32)) then
            prefabCaptureOpen = false
        end

        imgui.Unindent(10)
        return
    end

    -- ========================================================================
    -- [2] РЕЖИМ РЕДАКТОРА МАКРОСА ПРЕФАБА
    -- ========================================================================
    if editPrefabIdx then
        imgui.BeginGroup()
            if imgui.Button(fa.ICON_ARROW_LEFT .. safeU8"  Назад к библиотеке##edit_back", imgui.ImVec2(180, 28)) then
                editPrefabIdx = nil
            end
            imgui.SameLine(0, 15)
            imgui.TextColored(accentColor(), fa.ICON_CODE .. safeU8"  РЕДАКТОР ПРЕФАБА")
        imgui.EndGroup()
        imgui.Separator(); imgui.Spacing()

        local curP = (type(editPrefabIdx) == "number") and prefabs[editPrefabIdx] or nil
        local prevFile = (curP and curP.preview) or newPrefabPreviewName
        local prevTex = getPrefabPreviewTex(prevFile)

        -- Шапка карточки редактора
        imgui.BeginGroup()
            if prevTex then
                imgui.Image(prevTex, imgui.ImVec2(80, 80))
                if imgui.IsItemHovered() then
                    imgui.SetTooltip(safeU8"Клик: обновить снимок префаба (Камхак)")
                    if imgui.IsItemClicked(0) then
                        startPrefabPhotoMode(editPrefabIdx)
                    end
                end
            else
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.12, 0.14, 0.18, 0.9))
                if imgui.Button(fa.ICON_CAMERA .. safeU8"\n\nСделать\nфото##snap_edit", imgui.ImVec2(80, 80)) then
                    startPrefabPhotoMode(editPrefabIdx)
                end
                imgui.PopStyleColor()
                if imgui.IsItemHovered() then
                    imgui.SetTooltip(safeU8"Клик: сделать снимок префаба (Камхак)")
                end
            end
        imgui.EndGroup()

        imgui.SameLine(0, 15)

        imgui.BeginGroup()
            imgui.Text(safeU8"Название префаба:")
            imgui.PushItemWidth(350)
            imgui.InputText("##prefeditname", editPrefabNameBuf, 64)
            imgui.PopItemWidth()
            imgui.Spacing()

            if imgui.Button(fa.ICON_ARROWS_H .. safeU8"  Отразить X##pref_mirx", imgui.ImVec2(130, 26)) then
                mirrorPrefabCurrent(editPrefabIdx, "X")
            end
            imgui.SameLine(0, 6)
            if imgui.Button(fa.ICON_ARROWS_V .. safeU8"  Отразить Y##pref_miry", imgui.ImVec2(130, 26)) then
                mirrorPrefabCurrent(editPrefabIdx, "Y")
            end
            imgui.SameLine(0, 6)
            if imgui.Button(fa.ICON_SHARE .. safeU8"  В буфер##pref_expe", imgui.ImVec2(110, 26)) then
                local expP = (type(editPrefabIdx) == "number") and prefabs[editPrefabIdx] or {
                    name = ffi.string(editPrefabNameBuf),
                    steps = {}
                }
                exportPrefabToClipboard(expP)
            end
        imgui.EndGroup()

        imgui.Spacing(); imgui.Spacing()
        imgui.Text(safeU8"Текст макроса (команды спавна и трансформации по одной на строку):")
        imgui.TextDisabled(safeU8"Поддерживаются: /cr, /clone, /ox, /oy, /oz, /rx, /ry, /rz, /mtset, /mtcol")
        imgui.Spacing()

        imgui.PushItemWidth(-1)
        imgui.InputTextMultiline("##prefeditcmds", editPrefabBuf, 8192, imgui.ImVec2(-1, 260))
        imgui.PopItemWidth()
        imgui.Spacing()

        local raw = ffi.string(editPrefabBuf)
        local parsed, bad = {}, {}
        for line in raw:gmatch("[^\r\n]+") do
            local t = line:match("^%s*(.-)%s*$")
            if t ~= "" then
                local nm = t:match("^/(%a+)")
                if nm and PREFAB_CMDS and PREFAB_CMDS[nm:lower()] then
                    table.insert(parsed, t)
                else
                    table.insert(bad, t)
                end
            end
        end

        if #bad > 0 then
            imgui.TextColored(imgui.ImVec4(1.00, 0.35, 0.30, 1.0), safeU8("Неизвестных команд: " .. #bad .. "  (строки будут пропущены)"))
        else
            imgui.TextDisabled(safeU8("Корректных команд в макросе: " .. #parsed))
        end
        imgui.Spacing(); imgui.Separator(); imgui.Spacing()

        if imgui.Button(fa.ICON_CHECK .. safeU8"  Сохранить##prefeditok", imgui.ImVec2(150, 32)) then
            local nm = ffi.string(editPrefabNameBuf)
            if nm == "" then nm = "Новый префаб" end
            local cleanName = safeCP1251(nm)
            if #parsed > 0 then
                if editPrefabIdx == "new" then
                    table.insert(prefabs, { name = cleanName, steps = parsed, date = os.time(), preview = newPrefabPreviewName })
                    newPrefabPreviewName = nil
                elseif prefabs[editPrefabIdx] then
                    prefabs[editPrefabIdx].name  = cleanName
                    prefabs[editPrefabIdx].steps = parsed
                end
                savePrefabs()
                showToastQuick("Префабы", "Префаб сохранен")
                editPrefabIdx = nil
            else
                showToastQuick("Ошибка", "Макрос пуст! Введите хотя бы одну команду")
            end
        end
        imgui.SameLine(0, 8)
        if imgui.Button(fa.ICON_BUILDING .. safeU8"  3D Тест (Призрак)##prefedittest", imgui.ImVec2(170, 32)) then
            if #parsed > 0 then
                local testP = (type(editPrefabIdx) == "number" and prefabs[editPrefabIdx]) or { name = ffi.string(editPrefabNameBuf), steps = parsed }
                startPrefabGhost(testP)
            else
                showToastQuick("Ошибка", "Макрос пуст!")
            end
        end
        imgui.SameLine(0, 8)
        if imgui.Button(safeU8"Отмена##prefeditcancel", imgui.ImVec2(120, 32)) then
            editPrefabIdx = nil
        end

        imgui.Unindent(10)
        return
    end

    -- ========================================================================
    -- [3] ГЛАВНЫЙ ЭКРАН БИБЛИОТЕКИ ПРЕФАБОВ
    -- ========================================================================
    imgui.BeginGroup()
        imgui.TextColored(accentColor(), fa.ICON_CUBES .. safeU8"  БИБЛИОТЕКА ПРЕФАБОВ")
        imgui.TextDisabled(safeU8"Комплексные постройки, захваченные зоны и макросы создания объектов")
    imgui.EndGroup()
    imgui.Spacing()

    -- Кнопки действий
    if not prefabRecording then
        if imgui.Button(fa.ICON_CROSSHAIRS .. safeU8"  Захват области##prefcap", imgui.ImVec2(175, 30)) then
            prefabCaptureOpen = true
            scanObjectsForPrefab(prefabScanRadius[0])
            imgui.StrCopy(prefabCaptureNameBuf, safeU8("Зона " .. os.date("%d.%m %H:%M")))
        end
        imgui.SameLine(0, 8)
        if imgui.Button(fa.ICON_PLUS .. safeU8"  Создать макрос##prefnew", imgui.ImVec2(170, 30)) then
            editPrefabIdx = "new"
            imgui.StrCopy(editPrefabNameBuf, safeU8"Новый макрос")
            imgui.StrCopy(editPrefabBuf, "")
        end
        imgui.SameLine(0, 8)
        if imgui.Button(fa.ICON_DOWNLOAD .. safeU8"  Импорт из буфера##prefimp", imgui.ImVec2(185, 30)) then
            importPrefabFromClipboard()
        end
        imgui.SameLine(0, 8)
        if imgui.Button(fa.ICON_CIRCLE .. safeU8"  Запись макроса##prefrec", imgui.ImVec2(165, 30)) then
            prefabRecording = true
            prefabSteps = {}
            prefabStepLabels = {}
            winOpen[0] = false
            showToastQuick("Запись макроса", "Выполняйте команды маппинга. По завершении откройте /tmt")
        end
    else
        imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.80, 0.18, 0.15, 1.0))
        imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.95, 0.25, 0.20, 1.0))
        if imgui.Button(fa.ICON_STOP .. safeU8("  Остановить запись (" .. #prefabSteps .. " ком.)##prefstop"), imgui.ImVec2(240, 30)) then
            prefabRecording = false
            if #prefabSteps > 0 then
                showPrefabSaveDlg = true
                imgui.StrCopy(prefabSaveNameBuf, safeU8("Макрос " .. os.date("%d.%m %H:%M")))
            end
        end
        imgui.PopStyleColor(2)
        imgui.SameLine()
        imgui.TextColored(imgui.ImVec4(1.00, 0.35, 0.30, 1.0), safeU8("Идет запись: шагов " .. #prefabSteps))
    end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- Строка поиска и фильтрации
    imgui.PushItemWidth(250)
    imgui.InputTextWithHint("##prefsrch", safeU8"Поиск по названию...", prefabSearchBuf, 64)
    imgui.PopItemWidth()

    local srchQuery = ffi.string(prefabSearchBuf):lower():gsub("^%s*(.-)%s*$", "%1")

    -- Подсчет категорий
    local totalPrefabs = #prefabs
    local countCaptured = 0
    local countMacros = 0
    for _, p in ipairs(prefabs) do
        if p.isCaptured and p.objects and #p.objects > 0 then
            countCaptured = countCaptured + 1
        else
            countMacros = countMacros + 1
        end
    end

    imgui.SameLine(0, 15)
    local function filterBtn(label, modeIdx, count)
        local isActive = (prefabFilterType == modeIdx)
        if isActive then
            imgui.PushStyleColor(imgui.Col.Button, accentColor())
            imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0, 0, 0, 1))
        else
            imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.14, 0.16, 0.20, 0.9))
        end
        local btnTitle = string.format("%s (%d)##pfilt%d", label, count, modeIdx)
        if imgui.Button(safeU8(btnTitle), imgui.ImVec2(0, 24)) then
            prefabFilterType = modeIdx
        end
        imgui.PopStyleColor(isActive and 2 or 1)
    end

    filterBtn("Все", 0, totalPrefabs)
    imgui.SameLine(0, 6)
    filterBtn("Захваченные", 1, countCaptured)
    imgui.SameLine(0, 6)
    filterBtn("Макросы", 2, countMacros)

    imgui.Spacing()

    -- Список карточек префабов
    imgui.BeginChild("##prefabs_list_view", imgui.ImVec2(-1, -1), false)
        if totalPrefabs == 0 then
            imgui.Spacing(); imgui.Spacing()
            imgui.TextDisabled(safeU8"  В библиотеке пока нет сохраненных префабов.")
            imgui.TextDisabled(safeU8"  Используйте 'Захват области', чтобы захватить готовую постройку, или 'Создать макрос'.")
        else
            local removeIdx = nil
            local visibleCount = 0

            for i, p in ipairs(prefabs) do
                local isCap = (p.isCaptured and p.objects and #p.objects > 0)
                local matchesFilter = true
                if prefabFilterType == 1 and not isCap then matchesFilter = false end
                if prefabFilterType == 2 and isCap then matchesFilter = false end

                local pNameLower = tostring(p.name or ""):lower()
                if matchesFilter and srchQuery ~= "" and not pNameLower:find(srchQuery, 1, true) then
                    matchesFilter = false
                end

                if matchesFilter then
                    visibleCount = visibleCount + 1
                    local cardW = imgui.GetContentRegionAvail().x
                    local cardH = 96
                    local pPos = imgui.GetCursorScreenPos()
                    local dl = imgui.GetWindowDrawList()

                    -- Фон и скругленная рамка карточки
                    local ac = accentColor()
                    local tTheme = THEMES and THEMES[currentTheme]
                    local baseBg = (tTheme and tTheme.FrameBg) or imgui.ImVec4(0.12, 0.12, 0.12, 1.0)
                    local cardBgU32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(baseBg.x * 0.75, baseBg.y * 0.75, baseBg.z * 0.75, 0.95))
                    local cardBorderU32 = imgui.ColorConvertFloat4ToU32(imgui.ImVec4(ac.x, ac.y, ac.z, 0.45))
                    dl:AddRectFilled(pPos, imgui.ImVec2(pPos.x + cardW, pPos.y + cardH), cardBgU32, 6.0)
                    dl:AddRect(pPos, imgui.ImVec2(pPos.x + cardW, pPos.y + cardH), cardBorderU32, 6.0, 15, 1.0)

                    -- [1] Превью картинка (78x78)
                    local pTex = getPrefabPreviewTex(p.preview)
                    local imgX, imgY = pPos.x + 9, pPos.y + 9
                    local imgSz = 78
                    if pTex then
                        dl:AddImage(pTex, imgui.ImVec2(imgX, imgY), imgui.ImVec2(imgX + imgSz, imgY + imgSz))
                    else
                        dl:AddRectFilled(imgui.ImVec2(imgX, imgY), imgui.ImVec2(imgX + imgSz, imgY + imgSz), 0x33000000, 4.0)
                        dl:AddText(imgui.ImVec2(imgX + 22, imgY + 28), 0x88FFFFFF, fa.ICON_CAMERA)
                    end

                    -- Клик по превью для скриншота
                    imgui.SetCursorScreenPos(imgui.ImVec2(imgX, imgY))
                    imgui.InvisibleButton("##prev_click_" .. i, imgui.ImVec2(imgSz, imgSz))
                    if imgui.IsItemHovered() then
                        dl:AddRect(imgui.ImVec2(imgX, imgY), imgui.ImVec2(imgX + imgSz, imgY + imgSz), 0xFF00FF88, 4.0, 15, 1.5)
                        imgui.SetTooltip(safeU8"Клик: сделать новый снимок префаба (Камхак)")
                        if imgui.IsItemClicked(0) then
                            startPrefabPhotoMode(i)
                        end
                    end

                    -- [2] Текстовая информация
                    local textX = pPos.x + 98
                    local dispName = safeU8(p.name or "Префаб #" .. i)
                    dl:AddText(imgui.ImVec2(textX, pPos.y + 10), 0xFFFFAA00, dispName)

                    local badgeX = textX + imgui.CalcTextSize(dispName).x + 12
                    if isCap then
                        local bStr = safeU8(string.format("[ Захваченный: %d об. ]", #p.objects))
                        dl:AddText(imgui.ImVec2(badgeX, pPos.y + 10), 0xFF00E5FF, bStr)
                    else
                        local bStr = safeU8(string.format("[ Макрос: %d ком. ]", #(p.steps or {})))
                        dl:AddText(imgui.ImVec2(badgeX, pPos.y + 10), 0xFF2ECC71, bStr)
                    end

                    local dateStr = p.captureDate or (p.date and os.date("%d.%m.%Y %H:%M", p.date)) or ""
                    local subLine = "Создан: " .. dateStr
                    if isCap and #p.objects > 0 then
                        local minX, maxX = 999999, -999999
                        local minY, maxY = 999999, -999999
                        local minZ, maxZ = 999999, -999999
                        for _, obj in ipairs(p.objects) do
                            if obj.x and obj.y and obj.z then
                                if obj.x < minX then minX = obj.x end
                                if obj.x > maxX then maxX = obj.x end
                                if obj.y < minY then minY = obj.y end
                                if obj.y > maxY then maxY = obj.y end
                                if obj.z < minZ then minZ = obj.z end
                                if obj.z > maxZ then maxZ = obj.z end
                            end
                        end
                        if maxX >= minX then
                            local dimW = maxX - minX
                            local dimL = maxY - minY
                            local dimH = maxZ - minZ
                            subLine = subLine .. string.format("   |   Габариты: %.1f x %.1f x %.1f м", dimW, dimL, dimH)
                        end
                    end
                    dl:AddText(imgui.ImVec2(textX, pPos.y + 34), 0xFF8899AA, safeU8(subLine))

                    imgui.SetCursorScreenPos(imgui.ImVec2(textX, pPos.y + 58))
                    imgui.BeginGroup()
                        if imgui.Button(fa.ICON_SHARE .. safeU8" Поделиться##sh"..i, imgui.ImVec2(115, 24)) then
                            exportPrefabToClipboard(p)
                        end
                        imgui.SameLine(0, 6)
                        if imgui.Button(fa.ICON_PENCIL .. safeU8" Имя##rn"..i, imgui.ImVec2(75, 24)) then
                            renamePrefabIdx = i
                            imgui.StrCopy(renamePrefabBuf, safeU8(p.name or ""))
                        end
                        imgui.SameLine(0, 6)
                        if imgui.Button(fa.ICON_CODE .. safeU8" Редактор##ed"..i, imgui.ImVec2(95, 24)) then
                            editPrefabIdx = i
                            imgui.StrCopy(editPrefabNameBuf, safeU8(p.name or ""))
                            imgui.StrCopy(editPrefabBuf, table.concat(p.steps or {}, "\n"))
                        end
                        imgui.SameLine(0, 6)
                        if imgui.Button(fa.ICON_CUBES .. safeU8" В 3D##sced"..i, imgui.ImVec2(80, 24)) then
                            loadPrefabIntoScene(p)
                        end
                        imgui.SameLine(0, 6)
                        if prefabDeleteConfirm == i then
                            imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.85, 0.15, 0.15, 1.0))
                            imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(1.00, 0.25, 0.25, 1.0))
                            if imgui.Button(fa.ICON_TRASH .. safeU8" Точно?##del"..i, imgui.ImVec2(85, 24)) then
                                removeIdx = i
                            end
                            imgui.PopStyleColor(2)
                        else
                            if imgui.Button(fa.ICON_TRASH .. safeU8" Удалить##del"..i, imgui.ImVec2(85, 24)) then
                                prefabDeleteConfirm = i
                            end
                        end
                    imgui.EndGroup()

                    local spawnW = 145
                    local spawnH = 40
                    local spawnX = pPos.x + cardW - spawnW - 14
                    local spawnY = pPos.y + (cardH - spawnH) * 0.5
                    imgui.SetCursorScreenPos(imgui.ImVec2(spawnX, spawnY))
                    local tTheme = THEMES and THEMES[currentTheme]
                    local btnCol = (tTheme and tTheme.ButtonH) or accentColorA(0.85)
                    local btnColH = (tTheme and tTheme.ButtonA) or accentColorA(1.00)
                    local btnColA = (tTheme and tTheme.HeaderA) or accentColorA(0.70)
                    imgui.PushStyleColor(imgui.Col.Button, btnCol)
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, btnColH)
                    imgui.PushStyleColor(imgui.Col.ButtonActive, btnColA)
                    if imgui.Button(fa.ICON_BUILDING .. safeU8"  Построить##sp"..i, imgui.ImVec2(spawnW, spawnH)) then
                        startPrefabGhost(p)
                    end
                    imgui.PopStyleColor(3)
                    if imgui.IsItemHovered() then
                        imgui.BeginTooltip()
                            imgui.TextColored(accentColor(), safeU8(p.name or "Префаб"))
                            imgui.Separator()
                            imgui.Text(safeU8"ЛКМ: запуск 3D-призрака для точной расстановки")
                            imgui.Text(safeU8"Колесико мыши: вращение угла поворота призрака")
                            imgui.Spacing()
                            imgui.TextColored(imgui.ImVec4(0.4, 0.9, 0.5, 1.0), safeU8"Shift + Клик: мгновенный спавн на позицию персонажа")
                        imgui.EndTooltip()
                        if imgui.IsMouseClicked(0) and isKeyDown(0x10) then
                            winOpen[0] = false
                            pcall(sampSetCursorMode, 0, false)
                            playPrefab(p)
                        end
                    end

                    imgui.SetCursorScreenPos(imgui.ImVec2(pPos.x, pPos.y + cardH + 8))
                end
            end

            if visibleCount == 0 and totalPrefabs > 0 then
                imgui.Spacing(); imgui.Spacing()
                imgui.TextDisabled(safeU8"  По запросу ничего не найдено.")
            end

            if removeIdx then
                table.remove(prefabs, removeIdx)
                prefabDeleteConfirm = nil
                savePrefabs()
                showToastQuick("Префабы", "Префаб удален")
            end
        end
    imgui.EndChild()

    imgui.Unindent(10)
end

texTemplates = {}
texSubTab = 0
texTplNameBuf = imgui.new.char[64]()
texTplSlotBufs = {}
for s = 0, 14 do
    texTplSlotBufs[s] = imgui.new.char[16]()
end
texTplEditIdx = nil

function saveTexTemplates()
    local f = io.open(TEX_TPL_PATH, "w")
    if f then f:write(json.encode(texTemplates)); f:close() end
end

function loadTexTemplates()
    if not doesFileExist(TEX_TPL_PATH) then return end
    local f = io.open(TEX_TPL_PATH, "r")
    if not f then return end
    local ok, data = pcall(json.decode, f:read("*all"))
    f:close()
    if ok and type(data) == "table" then texTemplates = data end
end

function clearTexTplForm()
    ffi.fill(texTplNameBuf, 64, 0)
    for s = 0, 14 do
        ffi.fill(texTplSlotBufs[s], 16, 0)
    end
    texTplEditIdx = nil
end

function applyTexTemplate(tpl)
    if not tpl or type(tpl.slots) ~= "table" then return end
    local sid = ffi.string(selObjBuf)
    lua_thread.create(function()
        if sid ~= "" then
            sampSendChat("/sel " .. sid)
            wait(280)
        end
        local applied = 0
        for s = 0, 14 do
            local tid = tpl.slots[tostring(s)] or tpl.slots[s]
            if tid and tostring(tid) ~= "" then
                sampSendChat("/mtset " .. tostring(s) .. " " .. tostring(tid))
                applied = applied + 1
                wait(250)
            end
        end
        sampAddChatMessage(string.format('{FF9326}[TMT]{CFCFCF} Шаблон текстурирования {FF9326}"%s"{CFCFCF} применён (%d слотов).', u8:decode(tpl.name or "Шаблон"), applied), -1)
    end)
end

