        imgui.TextDisabled(u8"Укажите название и впишите ID текстур в нужные слоты материалов (0–14). Пустые слоты пропускаются.")
        imgui.Spacing()

        imgui.Text(u8"Название шаблона:")
        imgui.SameLine()
        imgui.PushItemWidth(240)
        imgui.InputTextWithHint(u8"##textplname", u8"Например: Кирпич + Дерево", texTplNameBuf, 64)
        imgui.PopItemWidth()
        imgui.Spacing()

        local availW = imgui.GetContentRegionAvail().x
        local cellW = math.floor((availW - 32) / 5)
