            local tname = ffi.string(texTplNameBuf)
            local slots = {}
            local slotCount = 0
            for s = 0, 14 do
                local val = ffi.string(texTplSlotBufs[s]):match("^%s*(%d+)%s*$")
                if val and val ~= "" then
                    slots[tostring(s)] = val
                    slotCount = slotCount + 1
                end
            end
            if tname == "" then
                tname = u8("Шаблон #" .. tostring(#texTemplates + 1))
