                toast_timer = 140
            else
                if texTplEditIdx and texTemplates[texTplEditIdx] then
                    texTemplates[texTplEditIdx] = { name = tname, slots = slots }
                else
                    table.insert(texTemplates, { name = tname, slots = slots })
