    imgui.TextColored(imgui.ImVec4(0.5,0.5,0.5,1), u8"\x97 \xee\xf7\xe8\xf1\xf2\xe8\xf2\xfc \xe2\xf1\xe5 15 \xf1\xeb\xee\xf2\xee\xe2 (/mtset 0-14 0)")

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- Таблица материалов
