        if texId ~= "" then
            sampSendChat("/mtset " .. i .. " " .. texId)
        else
            sampSendChat("/mtset " .. i)
        end
    end
        imgui.SameLine(numW + btnApply + 20)

        -- Кнопка "Сбросить"
