-- ============================================================================
-- [ВКЛАДКА 18] КАТАЛОГ ТЕКСТУР GTA:SA (TEXTURE CATALOG)
-- ============================================================================
-- (Функции и таблицы каталога текстур вынесены выше)

function renderTabTextureCatalog()
    loadTextureCatalog()

    imgui.Indent(10)
    imgui.Spacing()
    local ac = accentColor()
    imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], fa.ICON_TH_LARGE .. u8"  КАТАЛОГ ТЕКСТУР GTA:SA")
    imgui.SameLine()
    imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.60, 1.0), string.format(u8"— база из %d нативных текстур для маппинга", #textureCatalog))
    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- 1. Верхняя панель: поиск, выбор целевого слота, быстрая вставка
    imgui.PushItemWidth(260)
    imgui.InputTextWithHint(u8"##texcatsearch", u8"Поиск текстуры или TXD...", texCatSearchBuf, 128)
    imgui.PopItemWidth()

    imgui.SameLine(0, 16)
    imgui.Text(u8"Целевой слот:")
    imgui.SameLine(0, 8)
    imgui.PushItemWidth(100)
    imgui.SliderInt(u8"##cat_target_slot", texCatSlot, 0, 14, u8"Слот #%d")
    imgui.PopItemWidth()

    imgui.SameLine(0, 16)
    local bCol, bHov, bAct = getBrightThemeBtnColors()
    imgui.PushStyleColor(imgui.Col.Button, bCol)
    imgui.PushStyleColor(imgui.Col.ButtonHovered, bHov)
    imgui.PushStyleColor(imgui.Col.ButtonActive, bAct)
    imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(1.0, 1.0, 1.0, 1.0))
    if imgui.Button(fa.ICON_PAINT_BRUSH .. u8"  Панель текстур##goto_tex_tab", imgui.ImVec2(175, 26)) then
        SwitchTab(5)
    end
    imgui.PopStyleColor(4)

    imgui.Spacing()

    -- 2. Фильтры категорий с динамическим переносом строк (без скроллбаров и вылетов)
    local isAllActive = (texCatActiveFilter == 0)
    if not isAllActive then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.14, 0.14, 0.16, 1.0)) end
    if imgui.Button(string.format(safeU8("Все (%d)##cat_filter_0"), #textureCatalog), imgui.ImVec2(0, 22)) then
        if texCatActiveFilter ~= 0 then
            texCatActiveFilter = 0
            texCatCurrentPage = 1
            texCatImageCache = {}
        end
    end
    if not isAllActive then imgui.PopStyleColor() end

    local winMaxX = imgui.GetWindowPos().x + imgui.GetWindowWidth() - 25
    for idx, cat in ipairs(textureCategories) do
        local catName = safeU8(cat.name or "")
        local catBtnLabel = string.format("%s (%d)##cat_filter_%d", catName, cat.count, idx)
        local btnTextOnly = string.format("%s (%d)", catName, cat.count)
        local btnW = imgui.CalcTextSize(btnTextOnly).x + imgui.GetStyle().FramePadding.x * 2 + 8
        local lastX = imgui.GetItemRectMax().x

        if lastX + 6 + btnW < winMaxX then
            imgui.SameLine(0, 6)
        end

        local isCatActive = (texCatActiveFilter == idx)
        if not isCatActive then imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.14, 0.14, 0.16, 1.0)) end
        if imgui.Button(catBtnLabel, imgui.ImVec2(0, 22)) then
            if texCatActiveFilter ~= idx then
                texCatActiveFilter = idx
                texCatCurrentPage = 1
                texCatImageCache = {}
            end
        end
        if not isCatActive then imgui.PopStyleColor() end
    end

    imgui.Spacing(); imgui.Separator(); imgui.Spacing()

    -- 3. Поиск и пагинация
    local q = ffi.string(texCatSearchBuf):lower()
    local selectedCatName = (texCatActiveFilter > 0 and textureCategories[texCatActiveFilter]) and textureCategories[texCatActiveFilter].name or nil

    local filtered = {}
    for _, item in ipairs(textureCatalog) do
        local matchCat = (not selectedCatName) or (item.category == selectedCatName)
        if matchCat then
            if q == "" or item.name:lower():find(q, 1, true) ~= nil or item.txd:lower():find(q, 1, true) ~= nil or (item.category and item.category:lower():find(q, 1, true) ~= nil) then
                table.insert(filtered, item)
            end
        end
    end

    local totalItems = #filtered
    local totalPages = math.max(1, math.ceil(totalItems / texCatItemsPerPage))
    if texCatCurrentPage > totalPages then texCatCurrentPage = totalPages end
    if texCatCurrentPage < 1 then texCatCurrentPage = 1 end

    -- Инфо-панель и пагинация
    imgui.TextColored(imgui.ImVec4(0.65, 0.65, 0.70, 1.0), string.format(safeU8("Найдено: %d текстур  |  Страница %d из %d"), totalItems, texCatCurrentPage, totalPages))

    local rightX = imgui.GetContentRegionAvail().x - 220
    if rightX > 180 then
        imgui.SameLine(imgui.GetCursorPosX() + rightX)
        if imgui.Button(fa.ICON_ANGLE_DOUBLE_LEFT .. "##texcat_first", imgui.ImVec2(30, 24)) then
            if texCatCurrentPage > 1 then texCatCurrentPage = 1; texCatImageCache = {} end
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Первая страница")) end

        imgui.SameLine(0, 4)
        if imgui.Button(fa.ICON_CHEVRON_LEFT .. "##texcat_prev", imgui.ImVec2(30, 24)) then
            if texCatCurrentPage > 1 then texCatCurrentPage = texCatCurrentPage - 1; texCatImageCache = {} end
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Предыдущая страница")) end

        imgui.SameLine(0, 8)
        imgui.Text(string.format("%d / %d", texCatCurrentPage, totalPages))

        imgui.SameLine(0, 8)
        if imgui.Button(fa.ICON_CHEVRON_RIGHT .. "##texcat_next", imgui.ImVec2(30, 24)) then
            if texCatCurrentPage < totalPages then texCatCurrentPage = texCatCurrentPage + 1; texCatImageCache = {} end
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Следующая страница")) end

        imgui.SameLine(0, 4)
        if imgui.Button(fa.ICON_ANGLE_DOUBLE_RIGHT .. "##texcat_last", imgui.ImVec2(30, 24)) then
            if texCatCurrentPage < totalPages then texCatCurrentPage = totalPages; texCatImageCache = {} end
        end
        if imgui.IsItemHovered() then imgui.SetTooltip(safeU8("Последняя страница")) end
    end

    imgui.Spacing()

    -- 4. Сетка карточек текстур (BeginChild гарантирует идеальное выравнивание колонок)
    imgui.BeginChild(safeU8("##texcat_grid"), imgui.ImVec2(0, 0), false)
    if totalItems == 0 then
        imgui.Spacing(); imgui.Spacing()
        imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), safeU8("Текстуры не найдены. Попробуйте изменить поисковый запрос или категорию."))
    else
        local availW = imgui.GetContentRegionAvail().x
        local cols = math.max(1, math.floor(availW / 185))
        local pad = 10
        local cardW = math.floor((availW - pad * (cols - 1) - 14) / cols)
        local cardH = 175
        local imgH = 95

        local startIdx = (texCatCurrentPage - 1) * texCatItemsPerPage + 1
        local endIdx = math.min(totalItems, startIdx + texCatItemsPerPage - 1)

        local col = 0

        local favTexMap = {}
        for fIdx, fav in ipairs(favTextures or {}) do
            if fav.name then favTexMap[fav.name:lower()] = fIdx end
            if fav.id then favTexMap[tostring(fav.id):lower()] = fIdx end
            if fav.file then
                favTexMap[fav.file:lower()] = fIdx
                favTexMap[fav.file:lower():gsub("%.png$", "")] = fIdx
            end
        end

        for idx = startIdx, endIdx do
            local item = filtered[idx]
            if col > 0 then imgui.SameLine(0, pad) end

            local lowerName = item.name:lower()
            local favIdx = favTexMap[lowerName]
            local isFav = (favIdx ~= nil)

            imgui.PushStyleVarFloat(imgui.StyleVar.ChildRounding, 6.0)
            imgui.PushStyleVarVec2(imgui.StyleVar.WindowPadding, imgui.ImVec2(6, 6))

            if isFav then
                imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.14, 0.13, 0.08, 0.95))
                imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(1.0, 0.85, 0.15, 0.95))
            else
                imgui.PushStyleColor(imgui.Col.ChildBg, imgui.ImVec4(0.10, 0.12, 0.15, 0.95))
                imgui.PushStyleColor(imgui.Col.Border, imgui.ImVec4(ac.x, ac.y, ac.z, 0.40))
            end

            imgui.BeginChild("##catcard_" .. idx, imgui.ImVec2(cardW, cardH), true, bit.bor(imgui.WindowFlags.NoScrollbar, imgui.WindowFlags.NoScrollWithMouse))

            local innerW = imgui.GetContentRegionAvail().x
            local tex = getCatalogTex(item.file)
            if tex then
                imgui.Image(tex, imgui.ImVec2(innerW, imgH))
            else
                local p = imgui.GetCursorScreenPos()
                local dl = imgui.GetWindowDrawList()
                dl:AddRectFilled(p, imgui.ImVec2(p.x + innerW, p.y + imgH), 0xFF181C24, 4.0)
                dl:AddText(imgui.ImVec2(p.x + innerW * 0.5 - 28, p.y + imgH * 0.5 - 7), 0x77FFFFFF, safeU8("Загрузка..."))
                imgui.Dummy(imgui.ImVec2(innerW, imgH))
            end

            imgui.Spacing()
            local dispName = item.name
            if #dispName > 18 then dispName = dispName:sub(1, 16) .. ".." end
            if isFav then
                imgui.TextColored(imgui.ImVec4(1.0, 0.90, 0.40, 1.0), dispName)
            else
                imgui.Text(dispName)
            end
            if imgui.IsItemHovered() then
                imgui.SetTooltip(item.name)
            end

            local subInfo = string.format("%s (%s)", item.category or "", item.txd or "")
            if #subInfo > 24 then subInfo = subInfo:sub(1, 22) .. ".." end
            imgui.TextDisabled(safeU8(subInfo))
            if imgui.IsItemHovered() then
                imgui.SetTooltip(u8"Категория: " .. safeU8(item.category or "-") .. "\nTXD: " .. tostring(item.txd or "-"))
            end

            imgui.Spacing()
            local applyBtnW = math.max(60, innerW - 56)
            if imgui.Button(fa.ICON_CHECK .. safeU8(" Нанести") .. "##cat_ap_" .. idx, imgui.ImVec2(applyBtnW, 20)) then
                local slot = texCatSlot[0] or 0
                setClipboardText(item.name)
                imgui.StrCopy(mtSearchBuf, item.name)
                sampSendChat(string.format("/mtset %d %s", slot, item.name))
                showToastQuick(safeU8("Текстура нанесена"), safeU8(string.format("Слот #%d: %s", slot, item.name)))
            end
            if imgui.IsItemHovered() then
                imgui.SetTooltip(safeU8(string.format("Нанести в слот #%d (/mtset %d %s)", texCatSlot[0] or 0, texCatSlot[0] or 0, item.name)))
            end

            imgui.SameLine(0, 4)
            if imgui.Button(fa.ICON_FILES_O .. "##cat_cp_" .. idx, imgui.ImVec2(24, 20)) then
                setClipboardText(item.name)
                imgui.StrCopy(mtSearchBuf, item.name)
                showToastQuick(safeU8("Скопировано"), safeU8(item.name))
            end
            if imgui.IsItemHovered() then
                imgui.SetTooltip(safeU8("Скопировать имя текстуры: " .. item.name))
            end

            imgui.SameLine(0, 4)
            if isFav then
                imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.85, 0.70, 0.10, 0.90))
                imgui.PushStyleColor(imgui.Col.Text, imgui.ImVec4(0.10, 0.10, 0.10, 1.0))
            end
            if imgui.Button(fa.ICON_STAR .. "##cat_fav_" .. idx, imgui.ImVec2(24, 20)) then
                if isFav then
                    table.remove(favTextures, favIdx)
                    saveFavTextures()
                    showToastQuick(safeU8("Избранное"), safeU8("Удалено: " .. item.name))
                else
                    table.insert(favTextures, { name = item.name, id = item.name, note = item.category or "", file = item.file })
                    saveFavTextures()
                    showToastQuick(safeU8("В избранное"), safeU8("Добавлено: " .. item.name))
                end
            end
            if isFav then
                imgui.PopStyleColor(2)
            end
            if imgui.IsItemHovered() then
                imgui.SetTooltip(isFav and safeU8("Удалить из избранных текстур") or safeU8("Добавить в избранные текстуры"))
            end

            imgui.EndChild()

            if imgui.IsItemHovered() then
                local dl = imgui.GetWindowDrawList()
                if isFav then
                    dl:AddRect(imgui.GetItemRectMin(), imgui.GetItemRectMax(), 0xFFFFD700, 6.0, 15, 2.0)
                else
                    dl:AddRect(imgui.GetItemRectMin(), imgui.GetItemRectMax(), 0xAA00E5FF, 6.0, 15, 1.5)
                end
            end

            imgui.PopStyleColor(2)
            imgui.PopStyleVar(2)

            col = col + 1
            if col >= cols then
                col = 0
                imgui.Spacing()
            end
        end
    end
    imgui.EndChild()

    imgui.Unindent(10)
end




