-- ============================================================================
-- EVENT BLOCK AUTO-CONFIGURATOR (ПОЛНЫЙ ФУНКЦИОНАЛ ИЗ SCRIPT-HELPER)
-- ============================================================================
local EBLOCK_CONFIG_DIR  = getWorkingDirectory() .. '\\config'
local EBLOCK_CONFIG_PATH = EBLOCK_CONFIG_DIR .. '\\EventBlockTools.ini'

local function eblock_loadConfig()
    local res = {}
    local f = io.open(EBLOCK_CONFIG_PATH, 'r')
    if not f then return res end
    for line in f:lines() do
        local k, v = line:match('^%s*([%w_]+)%s*=%s*(.-)%s*$')
        if k then res[k] = v end
    end
    f:close()
    return res
end

local eblock_cfg = eblock_loadConfig()
local function eblock_cfgBool(v, def)
    if v == nil then return def end
    return v == true or v == 'true'
end

eblock = {
    windowOpen = imgui.new.bool(false),
    currentTab = 1,

    inputMapId    = imgui.new.char[16](eblock_cfg.map_id or '18'),
    inputScriptId = imgui.new.char[16](eblock_cfg.script_id or '177'),

    savedMaps = {},
    savedScripts = {},

    newMapId      = imgui.new.char[16](''),
    newMapName    = imgui.new.char[64](''),
    newScriptId   = imgui.new.char[16](''),
    newScriptName = imgui.new.char[64](''),

    objMode       = tonumber(eblock_cfg.obj_mode) or 1, -- 0 = Один объект, 1 = Диапазон, 2 = Список
    inputObjStart = imgui.new.char[16](eblock_cfg.obj_start or '1'),
    inputObjEnd   = imgui.new.char[16](eblock_cfg.obj_end or '50'),
    inputObjList  = imgui.new.char[512](eblock_cfg.obj_list or '111, 113, 441, 221'),

    editExistingBlocks = imgui.new.bool(eblock_cfgBool(eblock_cfg.edit_existing, false)),
    blockEditMode      = tonumber(eblock_cfg.block_edit_mode) or 0, -- 0 = по порядку, 1 = списком
    inputStartBlockId  = imgui.new.char[16](eblock_cfg.start_block_id or '1'),
    inputBlockList     = imgui.new.char[512](eblock_cfg.block_list or '13, 77, 23, 41'),
    targetBlockList    = {},

    setMovType         = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_mov_type, true)),
    movTypeSelect      = tonumber(eblock_cfg.mov_type_sel) or 1, -- 0 = Одностороннее, 1 = Двустороннее

    setAutoReturn      = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_auto_return, false)),
    inputAutoReturn    = imgui.new.char[16](eblock_cfg.auto_return or '5'),

    setShiftX          = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_shift_x, false)),
    inputShiftX        = imgui.new.char[16](eblock_cfg.shift_x or '0.000'),

    setShiftY          = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_shift_y, false)),
    inputShiftY        = imgui.new.char[16](eblock_cfg.shift_y or '0.000'),

    setShiftZ          = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_shift_z, true)),
    inputShiftZ        = imgui.new.char[16](eblock_cfg.shift_z or '13.89'),

    setRotX            = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_rot_x, false)),
    inputRotX          = imgui.new.char[16](eblock_cfg.rot_x or '0.000'),

    setRotY            = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_rot_y, false)),
    inputRotY          = imgui.new.char[16](eblock_cfg.rot_y or '0.000'),

    setRotZ            = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_rot_z, false)),
    inputRotZ          = imgui.new.char[16](eblock_cfg.rot_z or '0.000'),

    setSpeed           = imgui.new.bool(eblock_cfgBool(eblock_cfg.set_speed, false)),
    inputSpeed         = imgui.new.char[16](eblock_cfg.speed or '1.000'),

    useRandomValues    = imgui.new.bool(eblock_cfgBool(eblock_cfg.use_random, true)),
    password           = imgui.new.char[64](eblock_cfg.eblock_password or ''),

    statusText         = u8'Ожидание запуска',
    state              = 0, -- 0=IDLE, 1=COLLECTING_OINFO, 2=CREATING_BLOCKS, 3=IN_BLOCK_MENU, 4=DELETING_BLOCKS, 5=MOVING_BLOCKS
    autoTimeout        = 0,

    collectedList      = {},
    collectIndex       = 1,
    curCollectObjId    = 0,
    createIndex        = 1,

    currentQueue       = {},
    queueIdx           = 1,

    deleteBlockList    = {},
    deleteIndex        = 1,
    curDeletingBlockId = 0,

    moveBlockList      = {},
    moveIndex          = 1,
    curMovingBlockId   = 0,
}

if eblock_cfg.saved_maps then
    for item in eblock_cfg.saved_maps:gmatch('([^;]+)') do
        local mid, mname = item:match('^(%d+):(.*)$')
        if mid then table.insert(eblock.savedMaps, { id = mid, name = mname }) end
    end
end
if #eblock.savedMaps == 0 then
    table.insert(eblock.savedMaps, { id = '18', name = 'Основная локация' })
end

if eblock_cfg.saved_scripts then
    for item in eblock_cfg.saved_scripts:gmatch('([^;]+)') do
        local sid, sname = item:match('^(%d+):(.*)$')
        if sid then table.insert(eblock.savedScripts, { id = sid, name = sname }) end
    end
end
if #eblock.savedScripts == 0 then
    table.insert(eblock.savedScripts, { id = '177', name = 'Новый скрипт' })
end

function eblock.saveConfig()
    createDirectory(EBLOCK_CONFIG_DIR)
    local f = io.open(EBLOCK_CONFIG_PATH, 'w')
    if not f then return end

    f:write('[settings]\n')
    f:write('eblock_password=' .. tostring(ffi.string(eblock.password)) .. '\n')
    f:write('map_id='          .. tostring(ffi.string(eblock.inputMapId)) .. '\n')
    f:write('script_id='       .. tostring(ffi.string(eblock.inputScriptId)) .. '\n')
    f:write('obj_mode='        .. tostring(eblock.objMode) .. '\n')
    f:write('obj_start='       .. tostring(ffi.string(eblock.inputObjStart)) .. '\n')
    f:write('obj_end='         .. tostring(ffi.string(eblock.inputObjEnd)) .. '\n')
    f:write('obj_list='        .. tostring(ffi.string(eblock.inputObjList)) .. '\n')
    f:write('edit_existing='   .. tostring(eblock.editExistingBlocks[0]) .. '\n')
    f:write('block_edit_mode=' .. tostring(eblock.blockEditMode) .. '\n')
    f:write('start_block_id='  .. tostring(ffi.string(eblock.inputStartBlockId)) .. '\n')
    f:write('block_list='      .. tostring(ffi.string(eblock.inputBlockList)) .. '\n')
    f:write('set_mov_type='    .. tostring(eblock.setMovType[0]) .. '\n')
    f:write('mov_type_sel='    .. tostring(eblock.movTypeSelect) .. '\n')
    f:write('set_auto_return=' .. tostring(eblock.setAutoReturn[0]) .. '\n')
    f:write('auto_return='     .. tostring(ffi.string(eblock.inputAutoReturn)) .. '\n')
    f:write('set_shift_x='     .. tostring(eblock.setShiftX[0]) .. '\n')
    f:write('shift_x='         .. tostring(ffi.string(eblock.inputShiftX)) .. '\n')
    f:write('set_shift_y='     .. tostring(eblock.setShiftY[0]) .. '\n')
    f:write('shift_y='         .. tostring(ffi.string(eblock.inputShiftY)) .. '\n')
    f:write('set_shift_z='     .. tostring(eblock.setShiftZ[0]) .. '\n')
    f:write('shift_z='         .. tostring(ffi.string(eblock.inputShiftZ)) .. '\n')
    f:write('set_rot_x='       .. tostring(eblock.setRotX[0]) .. '\n')
    f:write('rot_x='           .. tostring(ffi.string(eblock.inputRotX)) .. '\n')
    f:write('set_rot_y='       .. tostring(eblock.setRotY[0]) .. '\n')
    f:write('rot_y='           .. tostring(ffi.string(eblock.inputRotY)) .. '\n')
    f:write('set_rot_z='       .. tostring(eblock.setRotZ[0]) .. '\n')
    f:write('rot_z='           .. tostring(ffi.string(eblock.inputRotZ)) .. '\n')
    f:write('set_speed='       .. tostring(eblock.setSpeed[0]) .. '\n')
    f:write('speed='           .. tostring(ffi.string(eblock.inputSpeed)) .. '\n')
    f:write('use_random='      .. tostring(eblock.useRandomValues[0]) .. '\n')

    local mItems = {}
    for _, m in ipairs(eblock.savedMaps) do table.insert(mItems, m.id .. ':' .. m.name) end
    f:write('saved_maps=' .. table.concat(mItems, ';') .. '\n')

    local sItems = {}
    for _, s in ipairs(eblock.savedScripts) do table.insert(sItems, s.id .. ':' .. s.name) end
    f:write('saved_scripts=' .. table.concat(sItems, ';') .. '\n')

    f:close()
end

function eblock.say(text)
    sampAddChatMessage('{2787F5}[Event Tools] {DEDEDE}' .. text, -1)
end

function eblock.resolveParamValue(raw)
    if not eblock.useRandomValues[0] then return raw end
    local s = tostring(raw):gsub('%s+', '')
    local minStr, maxStr = s:match('^([%-+]?%d+%.?%d*)%-(.*)$')
    if minStr and maxStr and maxStr ~= '' then
        local minV, maxV = tonumber(minStr), tonumber(maxStr)
        if minV and maxV then
            if minV > maxV then minV, maxV = maxV, minV end
            local isFloat = (minStr:find('%.') or maxStr:find('%.')) ~= nil
            if isFloat then
                local rnd = minV + math.random() * (maxV - minV)
                return string.format('%.3f', rnd)
            else
                local rnd = math.random(math.floor(minV), math.floor(maxV))
                return tostring(rnd)
            end
        end
    end
    return raw
end

function eblock.stopAutomation(msg)
    eblock.state = 0
    eblock.collectedList = {}
    eblock.deleteBlockList = {}
    eblock.moveBlockList = {}
    if msg then
        eblock.say('{FF5555}' .. msg)
        eblock.statusText = u8(msg)
    else
        eblock.say('{FF5555}Процесс остановлен.')
        eblock.statusText = u8'Остановлено'
    end
end

function eblock.findDialogRow(text, pattern, isExact)
    local clean = text:gsub('{%x%x%x%x%x%x}', '')
    local row = 0
    for line in clean:gmatch('[^\r\n]+') do
        local trimmed = line:gsub('^%s*(.-)%s*$', '%1')
        if isExact then
            if trimmed == pattern then return row end
        else
            if trimmed:find(pattern, 1, true) then return row end
        end
        row = row + 1
    end
    return nil
end

function eblock.buildQueueForBlock(gIdx)
    local q = {}
    table.insert(q, { kind = 'action_type' })
    table.insert(q, { kind = 'obj_idx', val = gIdx })
    if eblock.setMovType[0] then
        local tName = (eblock.movTypeSelect == 1) and 'Двустороннее' or 'Одностороннее'
        if eblock.editExistingBlocks[0] or eblock.movTypeSelect == 1 then
            table.insert(q, { kind = 'mov_type', val = tName })
        end
    end
    if eblock.setAutoReturn[0] then table.insert(q, { kind = 'param', search = 'Автовозврат', val = eblock.resolveParamValue(ffi.string(eblock.inputAutoReturn)) }) end
    if eblock.setShiftX[0]     then table.insert(q, { kind = 'param', search = 'Сдвиг X',     val = eblock.resolveParamValue(ffi.string(eblock.inputShiftX)) }) end
    if eblock.setShiftY[0]     then table.insert(q, { kind = 'param', search = 'Сдвиг Y',     val = eblock.resolveParamValue(ffi.string(eblock.inputShiftY)) }) end
    if eblock.setShiftZ[0]     then table.insert(q, { kind = 'param', search = 'Сдвиг Z',     val = eblock.resolveParamValue(ffi.string(eblock.inputShiftZ)) }) end
    if eblock.setRotX[0]       then table.insert(q, { kind = 'param', search = 'Вращение X',  val = eblock.resolveParamValue(ffi.string(eblock.inputRotX)) }) end
    if eblock.setRotY[0]       then table.insert(q, { kind = 'param', search = 'Вращение Y',  val = eblock.resolveParamValue(ffi.string(eblock.inputRotY)) }) end
    if eblock.setRotZ[0]       then table.insert(q, { kind = 'param', search = 'Вращение Z',  val = eblock.resolveParamValue(ffi.string(eblock.inputRotZ)) }) end
    if eblock.setSpeed[0]      then table.insert(q, { kind = 'param', search = 'Скорость',    val = eblock.resolveParamValue(ffi.string(eblock.inputSpeed)) }) end
    return q
end

function eblock.nextOinfoQuery()
    if eblock.collectIndex > #eblock.collectedList then
        eblock.statusText = u8'Сбор завершен! Переход в режим скрипта...'
        eblock.say(string.format('{27F527}Успешно собрано %d объектов. Переключаем режим...', #eblock.collectedList))
        local sId = ffi.string(eblock.inputScriptId)
        lua_thread.create(function()
            wait(1000)
            sampSendChat('/map')
            wait(2500)
            sampSendChat('/scr ' .. sId)
            wait(2500)

            eblock.createIndex = 1
            eblock.autoTimeout = os.clock() + 15
            local cur = eblock.collectedList[eblock.createIndex]
            if not cur then return end

            if eblock.editExistingBlocks[0] then
                local bId = eblock.targetBlockList[eblock.createIndex]
                eblock.say(string.format('Редактирование блока #{FFFFFF}%s{DEDEDE} [1/%d] (объект #%d)...', tostring(bId), #eblock.collectedList, cur.objId))
                eblock.statusText = u8(string.format('Редактирование блока #%s (1/%d)...', tostring(bId), #eblock.collectedList))
                eblock.currentQueue = eblock.buildQueueForBlock(cur.gIdx)
                eblock.queueIdx = 1
                eblock.state = 3 -- ST.IN_BLOCK_MENU
                sampSendChat('/blockcp ' .. tostring(bId))
            else
                eblock.state = 2 -- ST.CREATING_BLOCKS
                eblock.statusText = u8(string.format('Создание блока 1/%d (для объекта #%d)...', #eblock.collectedList, cur.objId))
                sampSendChat('/createblock action')
            end
        end)
        return
    end

    eblock.curCollectObjId = eblock.collectedList[eblock.collectIndex].objId
    eblock.statusText = u8(string.format('Сбор IDX [%d/%d]: объект #%d', eblock.collectIndex, #eblock.collectedList, eblock.curCollectObjId))
    eblock.autoTimeout = os.clock() + 15
    sampSendChat('/oinfo ' .. tostring(eblock.curCollectObjId))
end

function eblock.startAutomation()
    if eblock.state ~= 0 then
        eblock.stopAutomation()
        return
    end

    eblock.saveConfig()

    local mapId = tonumber(ffi.string(eblock.inputMapId))
    local scrId = tonumber(ffi.string(eblock.inputScriptId))
    if not mapId or not scrId then eblock.say('{FF5555}Укажите корректные ID карты и скрипта!') return end

    eblock.collectedList = {}

    -- 0: Один объект
    if eblock.objMode == 0 then
        local sId = tonumber(ffi.string(eblock.inputObjStart))
        if not sId then eblock.say('{FF5555}Укажите корректный ID объекта!') return end
        table.insert(eblock.collectedList, { objId = sId, gIdx = nil })

    -- 1: Диапазон от и до
    elseif eblock.objMode == 1 then
        local sId = tonumber(ffi.string(eblock.inputObjStart))
        local eId = tonumber(ffi.string(eblock.inputObjEnd))
        if not sId or not eId or eId < sId then eblock.say('{FF5555}Проверьте диапазон объектов!') return end
        for id = sId, eId do
            table.insert(eblock.collectedList, { objId = id, gIdx = nil })
        end

    -- 2: Произвольный список (через запятую или пробелы)
    elseif eblock.objMode == 2 then
        for id in ffi.string(eblock.inputObjList):gmatch('%d+') do
            table.insert(eblock.collectedList, { objId = tonumber(id), gIdx = nil })
        end
        if #eblock.collectedList == 0 then
            eblock.say('{FF5555}В списке объектов не найдено ни одного ID!')
            return
        end
    end

    -- Подготовка списка целевых блоков (если включено редактирование)
    eblock.targetBlockList = {}
    if eblock.editExistingBlocks[0] then
        if eblock.blockEditMode == 0 then
            local sBId = tonumber(ffi.string(eblock.inputStartBlockId)) or 1
            for i = 1, #eblock.collectedList do
                table.insert(eblock.targetBlockList, sBId + (i - 1))
            end
        else
            for bId in ffi.string(eblock.inputBlockList):gmatch('%d+') do
                table.insert(eblock.targetBlockList, tonumber(bId))
            end
            if #eblock.targetBlockList < #eblock.collectedList then
                eblock.say(string.format('{FF5555}ОШИБКА: в списке блоков (%d шт.) меньше, чем выбранных объектов (%d шт.)!', #eblock.targetBlockList, #eblock.collectedList))
                return
            end
        end
    end

    eblock.collectIndex = 1
    eblock.say(string.format('Вход на карту #{FFFFFF}%d{DEDEDE} и сбор данных об объектах (%d шт.)...', mapId, #eblock.collectedList))
    eblock.statusText = u8('Вход в режим карты /map ' .. mapId .. '...')

    lua_thread.create(function()
        sampSendChat('/map ' .. mapId)
        wait(2500)
        eblock.state = 1 -- ST.COLLECTING_OINFO
        eblock.nextOinfoQuery()
    end)
end

function eblock.processNextBlockMove()
    if eblock.moveIndex > #eblock.moveBlockList then
        eblock.state = 0
        eblock.say('{27F527}Все указанные блоки успешно перенесены (/moveblock)!')
        eblock.statusText = u8'Перемещение завершено'
        return
    end

    eblock.curMovingBlockId = eblock.moveBlockList[eblock.moveIndex]
    eblock.statusText = u8(string.format('Перемещение блока #%d [%d/%d]...', eblock.curMovingBlockId, eblock.moveIndex, #eblock.moveBlockList))
    eblock.say(string.format('Выполнение: /moveblock {FFFFFF}%d', eblock.curMovingBlockId))
    sampSendChat('/moveblock ' .. tostring(eblock.curMovingBlockId))

    eblock.moveIndex = eblock.moveIndex + 1
    lua_thread.create(function()
        wait(1200)
        eblock.processNextBlockMove()
    end)
end

function eblock.startBlockMove(arg)
    if eblock.state ~= 0 then
        eblock.say('{FF5555}Скрипт уже выполняет другое действие!')
        return
    end

    local cleanArg = arg:gsub('^%s*(.-)%s*$', '%1')
    if cleanArg == '' then
        eblock.say('{FF5555}Использование: /eblockmove [ID или диапазон (напр: 34 или 1-10 или 5,8,12)]')
        return
    end

    eblock.moveBlockList = {}
    local rStart, rEnd = cleanArg:match('^(%d+)%s*[%-%s%.]+%s*(%d+)$')
    if rStart and rEnd then
        rStart, rEnd = tonumber(rStart), tonumber(rEnd)
        local step = (rStart <= rEnd) and 1 or -1
        for id = rStart, rEnd, step do
            table.insert(eblock.moveBlockList, id)
        end
    else
        for id in cleanArg:gmatch('%d+') do
            table.insert(eblock.moveBlockList, tonumber(id))
        end
    end

    if #eblock.moveBlockList == 0 then
        eblock.say('{FF5555}Не удалось распознать ID блоков для перемещения!')
        return
    end

    eblock.moveIndex = 1
    eblock.state = 5 -- ST.MOVING_BLOCKS
    eblock.say(string.format('Запуск перемещения блоков: {FFFFFF}%d шт.{DEDEDE}.', #eblock.moveBlockList))
    eblock.processNextBlockMove()
end

function eblock.processNextBlockDelete()
    if eblock.deleteIndex > #eblock.deleteBlockList then
        eblock.state = 0
        eblock.say('{27F527}Все указанные блоки успешно удалены!')
        eblock.statusText = u8'Удаление завершено'
        return
    end

    eblock.curDeletingBlockId = eblock.deleteBlockList[eblock.deleteIndex]
    eblock.statusText = u8(string.format('Удаление блока #%d [%d/%d]...', eblock.curDeletingBlockId, eblock.deleteIndex, #eblock.deleteBlockList))
    eblock.autoTimeout = os.clock() + 10
    sampSendChat('/blockcp ' .. tostring(eblock.curDeletingBlockId))
end

function eblock.startBlockDelete(arg)
    if eblock.state ~= 0 then
        eblock.say('{FF5555}Скрипт уже выполняет другое действие!')
        return
    end

    local pass = ffi.string(eblock.password)
    if pass == '' then
        eblock.say('{FF5555}Пароль не задан! Введите команду: /eblockpassword [ваш пароль]')
        return
    end

    local cleanArg = arg:gsub('^%s*(.-)%s*$', '%1')
    if cleanArg == '' then
        eblock.say('{FF5555}Использование: /blockdelete [ID или диапазон (напр: 34 или 1-10 или 5,8,12)]')
        return
    end

    eblock.deleteBlockList = {}
    local rStart, rEnd = cleanArg:match('^(%d+)%s*[%-%s%.]+%s*(%d+)$')
    if rStart and rEnd then
        rStart, rEnd = tonumber(rStart), tonumber(rEnd)
        local step = (rStart <= rEnd) and 1 or -1
        for id = rStart, rEnd, step do
            table.insert(eblock.deleteBlockList, id)
        end
    else
        for id in cleanArg:gmatch('%d+') do
            table.insert(eblock.deleteBlockList, tonumber(id))
        end
    end

    if #eblock.deleteBlockList == 0 then
        eblock.say('{FF5555}Не удалось распознать ID блоков для удаления!')
        return
    end

    eblock.deleteIndex = 1
    eblock.state = 4 -- ST.DELETING_BLOCKS
    eblock.say(string.format('Запуск удаления блоков: {FFFFFF}%d шт.{DEDEDE}. Ожидание...', #eblock.deleteBlockList))
    eblock.processNextBlockDelete()
end

function eblock.onServerMessage(color, msg)
    if eblock.state == 1 and msg:find('базы данных') then
        lua_thread.create(function()
            wait(1200)
            if eblock.state == 1 then
                eblock.autoTimeout = os.clock() + 8
                sampSendChat('/oinfo ' .. tostring(eblock.curCollectObjId))
            end
        end)
        return true
    end

    if eblock.state == 2 then
        local clean = msg:gsub('{%x%x%x%x%x%x}', '')
        local bId = clean:match('Вы успешно создали новый ивент блок%s*#(%d+)')
        if bId then
            local cur = eblock.collectedList[eblock.createIndex]
            if cur then
                eblock.say(string.format('Блок #{FFFFFF}%s{DEDEDE} создан для объекта #{FFFFFF}%d{DEDEDE} (Global: %s)', bId, cur.objId, tostring(cur.gIdx or '?')))
                eblock.currentQueue = eblock.buildQueueForBlock(cur.gIdx)
                eblock.queueIdx = 1
                eblock.state = 3 -- ST.IN_BLOCK_MENU
                eblock.autoTimeout = os.clock() + 10

                lua_thread.create(function()
                    wait(300)
                    sampSendChat('/blockcp ' .. bId)
                end)
                return true
            end
        end
    end

    return false
end

function eblock.handleDialog(dialogId, style, title, button1, button2, text)
    if eblock.state == 0 then return false end

    local cleanTitle = title:gsub('{%x%x%x%x%x%x}', '')
    local cleanText  = text:gsub('{%x%x%x%x%x%x}', '')

    if cleanText:find('Ждем ответа', 1, true) or cleanTitle:find('Ждем ответа', 1, true) then
        eblock.autoTimeout = os.clock() + 15
        return true, false
    end

    eblock.autoTimeout = os.clock() + 15

    -- ЭТАП 1: Информация об объекте (/oinfo)
    if eblock.state == 1 and cleanTitle:find('Информация об ивент объекте') then
        local gIdx = cleanText:match('Глобальный IDX:%s*global%s*(%d+)')
        sampSendDialogResponse(dialogId, 0, -1, '')

        if gIdx and eblock.collectedList[eblock.collectIndex] then
            eblock.collectedList[eblock.collectIndex].gIdx = gIdx
            eblock.say(string.format('Объект #{FFFFFF}%d{DEDEDE} -> Global IDX: {27F527}global %s', eblock.curCollectObjId, gIdx))
            eblock.statusText = u8(string.format('Считан объект #%d (IDX: %s). Пауза...', eblock.curCollectObjId, gIdx))
            eblock.collectIndex = eblock.collectIndex + 1

            lua_thread.create(function()
                wait(1500)
                eblock.nextOinfoQuery()
            end)
        else
            eblock.stopAutomation('Не найден Global IDX для объекта #' .. tostring(eblock.curCollectObjId))
        end
        return true, false
    end

    -- ЭТАП 2: Настройка блока в скрипте (/blockcp)
    if eblock.state == 3 then
        if cleanTitle:find('Управление ивент блоком') then
            if eblock.queueIdx > #eblock.currentQueue then
                sampSendDialogResponse(dialogId, 0, -1, '')
                eblock.createIndex = eblock.createIndex + 1
                if eblock.createIndex <= #eblock.collectedList then
                    lua_thread.create(function()
                        wait(350)
                        local cur = eblock.collectedList[eblock.createIndex]
                        if not cur then return end

                        if eblock.editExistingBlocks[0] then
                            local bId = eblock.targetBlockList[eblock.createIndex]
                            eblock.say(string.format('Редактирование блока #{FFFFFF}%s{DEDEDE} [%d/%d] (объект #%d)...', tostring(bId), eblock.createIndex, #eblock.collectedList, cur.objId))
                            eblock.statusText = u8(string.format('Редактирование блока #%s (%d/%d)...', tostring(bId), eblock.createIndex, #eblock.collectedList))
                            eblock.currentQueue = eblock.buildQueueForBlock(cur.gIdx)
                            eblock.queueIdx = 1
                            eblock.state = 3
                            eblock.autoTimeout = os.clock() + 10
                            sampSendChat('/blockcp ' .. tostring(bId))
                        else
                            eblock.state = 2
                            eblock.statusText = u8(string.format('Создание блока %d/%d (объект #%d)...', eblock.createIndex, #eblock.collectedList, cur.objId))
                            sampSendChat('/createblock action')
                        end
                    end)
                else
                    eblock.state = 0
                    eblock.say('{27F527}Все ивент блоки успешно обработаны и настроены!')
                    eblock.statusText = u8'Работа полностью завершена!'
                end
                return true, false
            end

            local item = eblock.currentQueue[eblock.queueIdx]
            if item.kind == 'action_type' then
                local row = eblock.findDialogRow(cleanText, 'Тип действия:')
                if row then sampSendDialogResponse(dialogId, 1, row, '') return true, false end
            elseif item.kind == 'obj_idx' then
                local row = eblock.findDialogRow(cleanText, 'IDX ивент объекта:')
                if row then sampSendDialogResponse(dialogId, 1, row, '') return true, false end
            elseif item.kind == 'mov_type' then
                local row = eblock.findDialogRow(cleanText, 'Тип движения:')
                if row then sampSendDialogResponse(dialogId, 1, row, '') return true, false end
            elseif item.kind == 'param' then
                local row = eblock.findDialogRow(cleanText, item.search)
                if row then sampSendDialogResponse(dialogId, 1, row, '') return true, false end
            end
        end

        if cleanTitle:find('Выберите тип действия') then
            local row = 0
            for line in cleanText:gmatch('[^\r\n]+') do
                local trimmed = line:gsub('^%s*(.-)%s*$', '%1')
                if trimmed == 'Движение ивент объекта' then
                    sampSendDialogResponse(dialogId, 1, row, '')
                    return true, false
                end
                row = row + 1
            end
        end

        if cleanText:find('Одностороннее') and cleanText:find('Двустороннее') then
            local row = 1
            local item = eblock.currentQueue[eblock.queueIdx]
            if (item and item.val and tostring(item.val):find('Односторон')) or eblock.movTypeSelect == 0 then
                row = 0
            end
            sampSendDialogResponse(dialogId, 1, row, '')
            return true, false
        end

        if (cleanTitle:find('Редактирование') or cleanText:find('Введите') or cleanText:find('Укажите'))
           and not cleanText:find('было установлено')
           and not cleanText:find('уже установлен') then
            local item = eblock.currentQueue[eblock.queueIdx]
            if item and item.val then
                sampSendDialogResponse(dialogId, 1, -1, tostring(item.val))
                return true, false
            end
        end

        if cleanText:find('уже установлен')
           or cleanText:find('изменили тип действия')
           or cleanText:find('будет передвигаться')
           or cleanText:find('установлено')
           or cleanText:find('установлен')
           or cleanText:find('автовозврата')
           or style == 0 or button2 == '' or button1 == 'X' or button1 == 'Х' then
            sampSendDialogResponse(dialogId, 1, -1, '')
            eblock.queueIdx = eblock.queueIdx + 1
            return true, false
        end
    end

    -- ЭТАП 3: Удаление ивент блоков (/blockdelete)
    if eblock.state == 4 then
        if cleanTitle:find('Управление ивент блоком') then
            local row = eblock.findDialogRow(cleanText, 'Удалить блок')
            if row then
                sampSendDialogResponse(dialogId, 1, row, '')
                return true, false
            else
                eblock.stopAutomation('Пункт "Удалить блок" не найден в блоке #' .. tostring(eblock.curDeletingBlockId))
                return true, false
            end
        end

        if cleanTitle:find('Удаление блока') or cleanText:find('пароль') then
            sampSendDialogResponse(dialogId, 1, -1, ffi.string(eblock.password))
            return true, false
        end

        if cleanText:find('успешно удал') or cleanText:find('был успешно') then
            sampSendDialogResponse(dialogId, 1, -1, '')
            eblock.say(string.format('Блок #{FFFFFF}%d{DEDEDE} успешно удален [%d/%d].', eblock.curDeletingBlockId, eblock.deleteIndex, #eblock.deleteBlockList))
            eblock.deleteIndex = eblock.deleteIndex + 1

            lua_thread.create(function()
                wait(400)
                eblock.processNextBlockDelete()
            end)
            return true, false
        end
    end

    return false
end

function eblock.render()
    if eblock.currentTab == 3 or (eblock.currentTab ~= 1 and eblock.currentTab ~= 2 and eblock.currentTab ~= 4) then
        eblock.currentTab = 1
    end
    applyTheme(currentTheme)
    local sw, sh = getScreenResolution()
    imgui.SetNextWindowPos(imgui.ImVec2(sw / 2, sh / 2), imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(880, 580), imgui.Cond.FirstUseEver)

    if imgui.IsKeyPressed(imgui.Key.Escape) then
        eblock.windowOpen[0] = false
        eblock.saveConfig()
    end

    local flags = imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse + imgui.WindowFlags.NoTitleBar
    if imgui.Begin(u8'##event_block_helper', eblock.windowOpen, flags) then
        -- Шапка окна
        imgui.TextColored(accentColor(), fa.ICON_CUBES .. u8'  Event Block Automation Tools')
        imgui.SameLine()
        imgui.TextDisabled(u8'v2.5')

        imgui.SameLine(imgui.GetWindowWidth() - 32)
        if imgui.Button(fa.ICON_TIMES .. '##eb_close', imgui.ImVec2(24, 24)) then
            eblock.windowOpen[0] = false
            eblock.saveConfig()
        end

        imgui.Separator()

        -- Левая боковая панель
        -- Левая боковая панель (Только Главная, Скрипты, Настройки)
        imgui.BeginChild(u8'##eb_sidebar', imgui.ImVec2(200, -1), true)
            local navIcon1 = (fa and (fa.ICON_MAGIC .. ' ')) or ''
            local navIcon3 = (fa and (fa.ICON_CODE .. ' ')) or ''
            local navIcon4 = (fa and (fa.ICON_COG .. ' ')) or ''

            local isTab1 = (eblock.currentTab == 1)
            if isTab1 then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
            if imgui.Button(navIcon1 .. u8'Автоматизация##eb_tab1', imgui.ImVec2(-1, 46)) then eblock.currentTab = 1 end
            if isTab1 then imgui.PopStyleColor() end

            imgui.Spacing()

            local isTab4 = (eblock.currentTab == 4)
            if isTab4 then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
            if imgui.Button(navIcon3 .. u8'Скрипты##eb_tab3', imgui.ImVec2(-1, 46)) then eblock.currentTab = 4 end
            if isTab4 then imgui.PopStyleColor() end

            imgui.Spacing()

            local isTab2 = (eblock.currentTab == 2)
            if isTab2 then imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85)) end
            if imgui.Button(navIcon4 .. u8'Настройки##eb_tab4', imgui.ImVec2(-1, 46)) then eblock.currentTab = 2 end
            if isTab2 then imgui.PopStyleColor() end
        imgui.EndChild()

        imgui.SameLine()

        -- Правая часть (Контент)
        imgui.BeginChild(u8'##eb_content', imgui.ImVec2(0, -1), true)
            if eblock.currentTab == 1 then
                local title = u8'АВТОМАТИЗАЦИЯ ИВЕНТ БЛОКОВ'
                imgui.SetWindowFontScale(1.15)
                local titleW = imgui.CalcTextSize(title).x
                imgui.SetCursorPosX((imgui.GetWindowContentRegionWidth() - titleW) / 2)
                imgui.TextColored(accentColor(), title)
                imgui.SetWindowFontScale(1.0)

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                -- Привязка ID карты и скрипта
                imgui.Text(u8'ID карты (/map):')
                imgui.SameLine(150)
                imgui.PushItemWidth(80)
                imgui.InputText('##eb_map_id', eblock.inputMapId, 16)
                imgui.PopItemWidth()

                imgui.SameLine(250)
                imgui.Text(u8'ID скрипта (/scr):')
                imgui.SameLine(380)
                imgui.PushItemWidth(80)
                imgui.InputText('##eb_scr_id', eblock.inputScriptId, 16)
                imgui.PopItemWidth()

                imgui.Spacing()

                -- Режим работы с блоками
                imgui.Checkbox(u8'Редактировать существующие блоки (без создания новых)##eb_edex', eblock.editExistingBlocks)
                if eblock.editExistingBlocks[0] then
                    imgui.SameLine()
                    if imgui.RadioButtonBool(u8'По порядку##b_seq', eblock.blockEditMode == 0) then eblock.blockEditMode = 0 end
                    imgui.SameLine()
                    if imgui.RadioButtonBool(u8'Списком##b_lst', eblock.blockEditMode == 1) then eblock.blockEditMode = 1 end

                    if eblock.blockEditMode == 0 then
                        imgui.Text(u8'Начальный номер блока:')
                        imgui.SameLine(190)
                        imgui.PushItemWidth(80)
                        imgui.InputText('##eb_start_block_id', eblock.inputStartBlockId, 16)
                        imgui.PopItemWidth()
                    else
                        imgui.Text(u8'Список блоков:')
                        imgui.SameLine(140)
                        imgui.PushItemWidth(380)
                        imgui.InputText('##eb_block_list_inp', eblock.inputBlockList, 512)
                        imgui.PopItemWidth()
                        imgui.TextDisabled(u8'Укажите номера блоков через запятую или пробел (напр: 13, 77, 23, 41)')
                    end
                end

                imgui.Spacing()

                -- Выбор режима работы с объектами
                imgui.TextColored(accentColor(), u8'Режим выбора объектов:')
                if imgui.RadioButtonBool(u8'Один объект##eb_obj0', eblock.objMode == 0) then eblock.objMode = 0 end
                imgui.SameLine()
                if imgui.RadioButtonBool(u8'Диапазон (от-до)##eb_obj1', eblock.objMode == 1) then eblock.objMode = 1 end
                imgui.SameLine()
                if imgui.RadioButtonBool(u8'Списком (1,2,3...)##eb_obj2', eblock.objMode == 2) then eblock.objMode = 2 end
                imgui.Spacing()

                if eblock.objMode == 0 then
                    imgui.Text(u8'ID объекта:')
                    imgui.SameLine(140)
                    imgui.PushItemWidth(100)
                    imgui.InputText('##eb_start_id_single', eblock.inputObjStart, 16)
                    imgui.PopItemWidth()

                elseif eblock.objMode == 1 then
                    imgui.Text(u8'С объекта ID:')
                    imgui.SameLine(120)
                    imgui.PushItemWidth(80)
                    imgui.InputText('##eb_start_id', eblock.inputObjStart, 16)
                    imgui.PopItemWidth()

                    imgui.SameLine(220)
                    imgui.Text(u8'По объект ID:')
                    imgui.SameLine(330)
                    imgui.PushItemWidth(80)
                    imgui.InputText('##eb_end_id', eblock.inputObjEnd, 16)
                    imgui.PopItemWidth()

                elseif eblock.objMode == 2 then
                    imgui.Text(u8'Список ID:')
                    imgui.SameLine(120)
                    imgui.PushItemWidth(360)
                    imgui.InputText('##eb_obj_list', eblock.inputObjList, 512)
                    imgui.PopItemWidth()
                    imgui.TextDisabled(u8'Указывайте ID через запятую или пробел (напр: 111, 113, 441, 221)')
                end

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                imgui.TextColored(accentColor(), u8'Параметры блока (отметьте нужные):')
                imgui.SameLine(360)
                if imgui.Checkbox(u8'Рандомизировать диапазоны (напр: 14-99)##eb_rnd', eblock.useRandomValues) then
                    eblock.saveConfig()
                end
                imgui.Spacing()

                -- Настройки типа движения
                imgui.Checkbox(u8'Тип движения##eb_use_mov', eblock.setMovType)
                if eblock.setMovType[0] then
                    imgui.SameLine(160)
                    imgui.PushItemWidth(160)
                    local curMovName = (eblock.movTypeSelect == 1) and u8'Двустороннее' or u8'Одностороннее'
                    if imgui.BeginCombo('##eb_mov_val', curMovName) then
                        if imgui.Selectable(u8'Одностороннее##mov0', eblock.movTypeSelect == 0) then
                            eblock.movTypeSelect = 0
                            eblock.saveConfig()
                        end
                        if imgui.Selectable(u8'Двустороннее##mov1', eblock.movTypeSelect == 1) then
                            eblock.movTypeSelect = 1
                            eblock.saveConfig()
                        end
                        imgui.EndCombo()
                    end
                    imgui.PopItemWidth()
                end

                -- Автовозврат
                imgui.Checkbox(u8'Автовозврат##eb_use_ar', eblock.setAutoReturn)
                if eblock.setAutoReturn[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_ar_val', eblock.inputAutoReturn, 16); imgui.PopItemWidth()
                    imgui.SameLine()
                    imgui.TextDisabled(u8'сек (0-60)')
                end

                -- Сдвиги
                imgui.Checkbox(u8'Сдвиг X##eb_use_sx', eblock.setShiftX)
                if eblock.setShiftX[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_sx_val', eblock.inputShiftX, 16); imgui.PopItemWidth()
                end

                imgui.Checkbox(u8'Сдвиг Y##eb_use_sy', eblock.setShiftY)
                if eblock.setShiftY[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_sy_val', eblock.inputShiftY, 16); imgui.PopItemWidth()
                end

                imgui.Checkbox(u8'Сдвиг Z##eb_use_sz', eblock.setShiftZ)
                if eblock.setShiftZ[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_sz_val', eblock.inputShiftZ, 16); imgui.PopItemWidth()
                end

                -- Вращения
                imgui.Checkbox(u8'Вращение X##eb_use_rx', eblock.setRotX)
                if eblock.setRotX[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_rx_val', eblock.inputRotX, 16); imgui.PopItemWidth()
                end

                imgui.Checkbox(u8'Вращение Y##eb_use_ry', eblock.setRotY)
                if eblock.setRotY[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_ry_val', eblock.inputRotY, 16); imgui.PopItemWidth()
                end

                imgui.Checkbox(u8'Вращение Z##eb_use_rz', eblock.setRotZ)
                if eblock.setRotZ[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_rz_val', eblock.inputRotZ, 16); imgui.PopItemWidth()
                end

                -- Скорость
                imgui.Checkbox(u8'Скорость##eb_use_spd', eblock.setSpeed)
                if eblock.setSpeed[0] then
                    imgui.SameLine(160); imgui.PushItemWidth(110)
                    imgui.InputText('##eb_spd_val', eblock.inputSpeed, 16); imgui.PopItemWidth()
                end

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                imgui.TextColored(accentColor(), u8'Статус: ')
                imgui.SameLine()
                imgui.Text(eblock.statusText)

                imgui.Spacing()

                local isRunning = (eblock.state ~= 0)
                local btnText = isRunning and (fa.ICON_STOP .. u8'  ОСТАНОВИТЬ') or (fa.ICON_PLAY .. u8'  ЗАПУСТИТЬ АВТОМАТИЗАЦИЮ')
                if isRunning then
                    imgui.PushStyleColor(imgui.Col.Button, imgui.ImVec4(0.75, 0.18, 0.18, 1.0))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, imgui.ImVec4(0.85, 0.25, 0.25, 1.0))
                else
                    imgui.PushStyleColor(imgui.Col.Button, accentColorA(0.85))
                    imgui.PushStyleColor(imgui.Col.ButtonHovered, accentColor())
                end
                if imgui.Button(btnText .. '##eb_start_stop', imgui.ImVec2(-1, 38)) then
                    if isRunning then
                        eblock.stopAutomation()
                    else
                        eblock.startAutomation()
                    end
                end
                imgui.PopStyleColor(2)

            elseif eblock.currentTab == 4 then
                -- ВКЛАДКА: СОХРАНЕННЫЕ СКРИПТЫ
                local title = u8'СОХРАНЕННЫЕ СКРИПТЫ'
                imgui.SetWindowFontScale(1.15)
                local titleW = imgui.CalcTextSize(title).x
                imgui.SetCursorPosX((imgui.GetWindowContentRegionWidth() - titleW) / 2)
                imgui.TextColored(accentColor(), title)
                imgui.SetWindowFontScale(1.0)

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                -- Добавление нового скрипта
                imgui.Text(u8'Добавить скрипт в список:')
                imgui.Text(u8'ID:')
                imgui.SameLine(40)
                imgui.PushItemWidth(70)
                imgui.InputText('##eb_add_scr_id', eblock.newScriptId, 16)
                imgui.PopItemWidth()

                imgui.SameLine(120)
                imgui.Text(u8'Название:')
                imgui.SameLine(190)
                imgui.PushItemWidth(220)
                imgui.InputText('##eb_add_scr_name', eblock.newScriptName, 64)
                imgui.PopItemWidth()

                imgui.SameLine(420)
                if imgui.Button(fa.ICON_PLUS .. u8'  Добавить скрипт##eb_add_scr_btn', imgui.ImVec2(150, 24)) then
                    local sid = ffi.string(eblock.newScriptId)
                    if sid ~= '' then
                        local rawNm = ffi.string(eblock.newScriptName)
                        local sName = rawNm ~= '' and rawNm or ('Скрипт #' .. sid)
                        table.insert(eblock.savedScripts, { id = sid, name = sName })
                        imgui.StrCopy(eblock.newScriptId, '')
                        imgui.StrCopy(eblock.newScriptName, '')
                        eblock.saveConfig()
                    end
                end

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                -- Список скриптов (безопасный рендеринг без падений)
                imgui.BeginChild(u8'##eb_scripts_scroll', imgui.ImVec2(0, -1), false)
                for i, s in ipairs(eblock.savedScripts) do
                    local sIdStr = tostring(s.id or "")
                    local sRawName = tostring(s.name or ("Скрипт #" .. sIdStr))
                    imgui.TextColored(accentColor(), string.format('#%s', sIdStr))
                    imgui.SameLine(60)

                    local ok, u8Name = pcall(u8, sRawName)
                    imgui.Text(ok and u8Name or sRawName)

                    imgui.SameLine(imgui.GetWindowContentRegionWidth() - 210)
                    if imgui.Button(fa.ICON_CHECK .. u8'  Выбрать##eb_use_s' .. i, imgui.ImVec2(120, 22)) then
                        imgui.StrCopy(eblock.inputScriptId, sIdStr)
                        eblock.currentTab = 1
                        eblock.saveConfig()
                        eblock.say('Выбран скрипт: {FFFFFF}#' .. sIdStr .. ' (' .. sRawName .. ')')
                    end

                    imgui.SameLine(imgui.GetWindowContentRegionWidth() - 80)
                    if imgui.Button(fa.ICON_TRASH .. u8'  Удалить##eb_del_s' .. i, imgui.ImVec2(80, 22)) then
                        table.remove(eblock.savedScripts, i)
                        eblock.saveConfig()
                        break
                    end
                    imgui.Separator()
                end
                imgui.EndChild()
            elseif eblock.currentTab == 2 then
                -- ВКЛАДКА: НАСТРОЙКИ
                local title = u8'ПАРАМЕТРЫ СКРИПТА'
                imgui.SetWindowFontScale(1.15)
                local titleW = imgui.CalcTextSize(title).x
                imgui.SetCursorPosX((imgui.GetWindowContentRegionWidth() - titleW) / 2)
                imgui.TextColored(accentColor(), title)
                imgui.SetWindowFontScale(1.0)

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                imgui.TextColored(accentColor(), fa.ICON_ADJUST .. u8'  Тема оформления:')
                imgui.SameLine()
                imgui.TextDisabled(u8'Синхронизирована с темой Trinity Mapper Tools')

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()

                imgui.Text(u8'Пароль для удаления блоков:')
                imgui.PushItemWidth(240)
                if imgui.InputText('##eb_acc_pass', eblock.password, 64) then
                    eblock.saveConfig()
                end
                imgui.PopItemWidth()
                imgui.TextDisabled(u8'Также можно задать быстрой командой: /eblockpassword [пароль]')

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                if imgui.Button(fa.ICON_CLIPBOARD .. u8'  Сохранить параметры вручную##eb_save_manual', imgui.ImVec2(320, 32)) then
                    eblock.saveConfig()
                    eblock.say('{27F527}Все настройки успешно сохранены в INI-файл!')
                end

                imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                imgui.TextColored(accentColor(), fa.ICON_CODE .. u8'  Быстрые команды в чате:')
                imgui.BulletText(u8'/eblock - открыть / закрыть автоконфигуратор')
                imgui.BulletText(u8'/eblockmove [ID/диапазон] - массовое перемещение блоков к вам (/moveblock)')
                imgui.BulletText(u8'/blockdelete [ID/диапазон] - массовое удаление блоков с авто-вводом пароля')
                imgui.BulletText(u8'/eblockpassword [пароль] - сохранить пароль для удаления')
                imgui.BulletText(u8'/eblockstop - экстренная остановка автоматизации')
            end
        imgui.EndChild()

        imgui.End()
    end
end

local eblockFrame = imgui.OnFrame(
    function() return eblock.windowOpen[0] end,
    function()
        applyTheme(currentTheme)
        eblock.render()
    end
)
eblockFrame.HideCursor = false
eblockFrame.LockPlayer = false



-- ============================================================================
-- [STAGE 1] ПЛАВАЮЩИЙ ТУЛБАР ПРИВЯЗКИ ДЛЯ 3D GIZMO
-- ============================================================================
-- [STAGE 1] ОВЕРЛЕЙ И ИНТЕРАКТИВ 3D ЛИНЕЙКИ (RULER)
-- ============================================================================
rulerFrame = imgui.OnFrame(
    function()
        return rulerActive
    end,
    function(self)
        if not rulerActive then return end
        local altDown = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
        if self then
            self.HideCursor = not altDown
            self.LockPlayer = false
        end

        local drawList = imgui.GetBackgroundDrawList()
        local sw, sh = getScreenResolution()
        local cx, cy = sw * 0.5, sh * 0.5
        local aimX, aimY = cx, cy
        if altDown then
            local mp = imgui.GetMousePos()
            aimX, aimY = mp.x, mp.y
            drawList:AddCircle(imgui.ImVec2(aimX, aimY), 6.5, 0xFF00E5FF, 16, 1.8)
            drawList:AddCircleFilled(imgui.ImVec2(aimX, aimY), 2.5, 0xFFFFFFFF)
        end

        -- Прицел по центру экрана
        drawList:AddCircle(imgui.ImVec2(cx, cy), 6.0, 0x8800E5FF, 16, 1.2)
        drawList:AddLine(imgui.ImVec2(cx - 12, cy), imgui.ImVec2(cx - 4, cy), 0xDD00E5FF, 1.5)
        drawList:AddLine(imgui.ImVec2(cx + 4, cy), imgui.ImVec2(cx + 12, cy), 0xDD00E5FF, 1.5)
        drawList:AddLine(imgui.ImVec2(cx, cy - 12), imgui.ImVec2(cx, cy - 4), 0xDD00E5FF, 1.5)
        drawList:AddLine(imgui.ImVec2(cx, cy + 4), imgui.ImVec2(cx, cy + 12), 0xDD00E5FF, 1.5)
        drawList:AddCircleFilled(imgui.ImVec2(cx, cy), 2.0, 0xFFFFFFFF)

        -- Координаты камеры и вектор взгляда
        local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
        local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
        local fwdX, fwdY, fwdZ = 0, 1, 0
        if okCam and okAt and camX and atX then
            fwdX, fwdY, fwdZ = atX - camX, atY - camY, atZ - camZ
            local len = math.sqrt(fwdX*fwdX + fwdY*fwdY + fwdZ*fwdZ)
            if len > 0.0001 then
                fwdX, fwdY, fwdZ = fwdX/len, fwdY/len, fwdZ/len
            end
        else
            camX, camY, camZ = 0, 0, 0
        end

        -- Трассировка луча
        local maxRay = 160.0
        local toX, toY, toZ = camX + fwdX * maxRay, camY + fwdY * maxRay, camZ + fwdZ * maxRay
        local okLos, hit, colPt = pcall(processLineOfSight, camX, camY, camZ, toX, toY, toZ, true, true, false, true, false, false, false, false)
        if okLos and hit and colPt and colPt.pos then
            local hx = colPt.pos[1] or colPt.pos.x
            local hy = colPt.pos[2] or colPt.pos.y
            local hz = colPt.pos[3] or colPt.pos.z
            rulerHoverPoint = {x = hx, y = hy, z = hz}
        else
            rulerHoverPoint = {x = camX + fwdX * 15.0, y = camY + fwdY * 15.0, z = camZ + fwdZ * 15.0}
        end

        -- Проверка примагничивания к известным объектам маппинга
        local bestObj = getHoveredObject(aimX, aimY)
        if bestObj then
            rulerHoverPoint = {x = bestObj.x, y = bestObj.y, z = bestObj.z}
            rulerHoverObj = bestObj
        else
            rulerHoverObj = nil
        end

        -- Отрисовка маркера на текущей точке наведения
        if rulerHoverPoint then
            local toCX = rulerHoverPoint.x - camX
            local toCY = rulerHoverPoint.y - camY
            local toCZ = rulerHoverPoint.z - camZ
            local dot = toCX * fwdX + toCY * fwdY + toCZ * fwdZ
            if dot > 0.1 then
                local sx, sy = convert3DCoordsToScreen(rulerHoverPoint.x, rulerHoverPoint.y, rulerHoverPoint.z)
                if sx and sy then
                    local colRing = rulerHoverObj and 0xFF00FF88 or 0xFF00E5FF
                    drawList:AddCircle(imgui.ImVec2(sx, sy), 8.0, colRing, 12, 1.5)
                    drawList:AddCircleFilled(imgui.ImVec2(sx, sy), 3.0, 0xFFFFFFFF)
                    if rulerHoverObj then
                        local badge = string.format("#%s: %s", tostring(rulerHoverObj.id), rulerHoverObj.modelName or "")
                        local tw = imgui.CalcTextSize(u8(badge)).x
                        drawList:AddRectFilled(imgui.ImVec2(sx - tw*0.5 - 6, sy - 26), imgui.ImVec2(sx + tw*0.5 + 6, sy - 8), 0xEE112211, 4.0)
                        drawList:AddRect(imgui.ImVec2(sx - tw*0.5 - 6, sy - 26), imgui.ImVec2(sx + tw*0.5 + 6, sy - 8), 0xFF00FF88, 4.0, 15, 1.2)
                        drawList:AddText(imgui.ImVec2(sx - tw*0.5, sy - 24), 0xFFFFFFFF, u8(badge))
                    end
                end
            end
        end

        -- Обработка кликов
        local now = os.clock()
        if not sampIsChatInputActive() and not sampIsDialogActive() then
            -- ESC: выход
            if isKeyJustPressed(0x1B) then
                rulerActive = false
                rulerPointA = nil
                rulerPointB = nil
                rulerMode = 0
                showToastQuick("3D Линейка", "Работа с линейкой завершена")
                return
            end

            -- C или ПКМ: сброс
            if isKeyJustPressed(0x43) or isKeyJustPressed(0x02) then
                rulerPointA = nil
                rulerPointB = nil
                rulerMode = 0
                showToastQuick("3D Линейка", "Точки замера сброшены")
            end

            -- ЛКМ или '1' / '2'
            local lmb = isKeyJustPressed(0x01) or isKeyJustPressed(0x31) or isKeyJustPressed(0x32)
            if lmb and (now - lastRulerClickTime > 0.3) and rulerHoverPoint then
                lastRulerClickTime = now
                if rulerMode == 0 then
                    rulerPointA = {x = rulerHoverPoint.x, y = rulerHoverPoint.y, z = rulerHoverPoint.z}
                    rulerPointB = nil
                    rulerMode = 1
                    showToastQuick("Точка A установлена", string.format("X: %.1f  Y: %.1f  Z: %.1f", rulerPointA.x, rulerPointA.y, rulerPointA.z))
                elseif rulerMode == 1 then
                    rulerPointB = {x = rulerHoverPoint.x, y = rulerHoverPoint.y, z = rulerHoverPoint.z}
                    rulerMode = 2
                    local dx = rulerPointB.x - rulerPointA.x
                    local dy = rulerPointB.y - rulerPointA.y
                    local dz = rulerPointB.z - rulerPointA.z
                    local dist = math.sqrt(dx*dx + dy*dy + dz*dz)
                    showToastQuick("Точка B зафиксирована!", string.format("Дистанция: %.2f м (XY: %.2f, dZ: %+.2f)", dist, math.sqrt(dx*dx + dy*dy), dz))
                elseif rulerMode == 2 then
                    rulerPointA = {x = rulerHoverPoint.x, y = rulerHoverPoint.y, z = rulerHoverPoint.z}
                    rulerPointB = nil
                    rulerMode = 1
                    showToastQuick("Новый замер: Точка A", string.format("X: %.1f  Y: %.1f  Z: %.1f", rulerPointA.x, rulerPointA.y, rulerPointA.z))
                end
            end
        end

        -- Отрисовка замера (если точка A установлена)
        if rulerPointA and rulerMode >= 1 then
            local targetPt = (rulerMode == 2 and rulerPointB) or rulerHoverPoint
            if targetPt then
                local dx = targetPt.x - rulerPointA.x
                local dy = targetPt.y - rulerPointA.y
                local dz = targetPt.z - rulerPointA.z
                local dist3D = math.sqrt(dx*dx + dy*dy + dz*dz)
                local dist2D = math.sqrt(dx*dx + dy*dy)
                local azimuth = math.deg(math.atan2(dy, dx))
                if azimuth < 0 then azimuth = azimuth + 360 end

                local dotA = (rulerPointA.x - camX)*fwdX + (rulerPointA.y - camY)*fwdY + (rulerPointA.z - camZ)*fwdZ
                local dotB = (targetPt.x - camX)*fwdX + (targetPt.y - camY)*fwdY + (targetPt.z - camZ)*fwdZ
                local sxA, syA = nil, nil
                local sxB, syB = nil, nil
                if dotA > 0.1 then sxA, syA = convert3DCoordsToScreen(rulerPointA.x, rulerPointA.y, rulerPointA.z) end
                if dotB > 0.1 then sxB, syB = convert3DCoordsToScreen(targetPt.x, targetPt.y, targetPt.z) end

                -- Маркер точки A
                if sxA and syA then
                    drawList:AddCircleFilled(imgui.ImVec2(sxA, syA), 5.0, 0xFFFFAA00)
                    drawList:AddCircle(imgui.ImVec2(sxA, syA), 9.0, 0xFFFFFFFF, 12, 1.5)
                    local lblA = u8"Точка A"
                    drawList:AddRectFilled(imgui.ImVec2(sxA + 8, syA - 10), imgui.ImVec2(sxA + 60, syA + 10), 0xCC111116, 3.0)
                    drawList:AddText(imgui.ImVec2(sxA + 12, syA - 8), 0xFFFFAA00, lblA)
                end

                -- Маркер точки B
                if sxB and syB then
                    local colB = (rulerMode == 2) and 0xFF00FF88 or 0xFF00E5FF
                    drawList:AddCircleFilled(imgui.ImVec2(sxB, syB), 5.0, colB)
                    drawList:AddCircle(imgui.ImVec2(sxB, syB), 9.0, 0xFFFFFFFF, 12, 1.5)
                    local lblB = (rulerMode == 2) and u8"Точка B" or u8"Прицел"
                    drawList:AddRectFilled(imgui.ImVec2(sxB + 8, syB - 10), imgui.ImVec2(sxB + 60, syB + 10), 0xCC111116, 3.0)
                    drawList:AddText(imgui.ImVec2(sxB + 12, syB - 8), colB, lblB)
                end

                -- 3D лазерная линия
                if sxA and syA and sxB and syB then
                    local colLaser = (rulerMode == 2) and 0xFF00FF88 or 0xFF00E5FF
                    local colGlow  = (rulerMode == 2) and 0x5500FF88 or 0x5500E5FF
                    drawList:AddLine(imgui.ImVec2(sxA, syA), imgui.ImVec2(sxB, syB), colGlow, 5.0)
                    drawList:AddLine(imgui.ImVec2(sxA, syA), imgui.ImVec2(sxB, syB), colLaser, 2.0)
                end

                -- 3D плашка в средней точке
                local mx = (rulerPointA.x + targetPt.x) * 0.5
                local my = (rulerPointA.y + targetPt.y) * 0.5
                local mz = (rulerPointA.z + targetPt.z) * 0.5
                local dotM = (mx - camX)*fwdX + (my - camY)*fwdY + (mz - camZ)*fwdZ
                if dotM > 0.1 then
                    local smx, smy = convert3DCoordsToScreen(mx, my, mz)
                    if smx and smy and smx > 50 and smx < sw - 150 and smy > 50 and smy < sh - 100 then
                        local cardW = 175
                        local cardH = 72
                        local cx1 = smx - cardW * 0.5
                        local cy1 = smy - cardH * 0.5
                        drawList:AddRectFilled(imgui.ImVec2(cx1, cy1), imgui.ImVec2(cx1 + cardW, cy1 + cardH), 0xEE12141A, 6.0)
                        
                        drawList:AddText(imgui.ImVec2(cx1 + 10, cy1 + 6), (rulerMode == 2) and 0xFF00FF88 or 0xFF00E5FF, safeU8(string.format("Дистанция: %.2f м", dist3D)))
                        drawList:AddText(imgui.ImVec2(cx1 + 10, cy1 + 24), 0xFFDDDDDD, safeU8(string.format("Гориз. (XY): %.2f м", dist2D)))
                        drawList:AddText(imgui.ImVec2(cx1 + 10, cy1 + 40), 0xFFDDDDDD, safeU8(string.format("Высота (dZ): %+.2f м", dz)))
                        drawList:AddText(imgui.ImVec2(cx1 + 10, cy1 + 56), 0xFFAAAAAA, safeU8(string.format("Азимут: %.1f град.", azimuth)))
                    end
                end

                -- Статическая сводка в левом верхнем углу (всегда видна)
                local hudW = 210
                local hudH = 92
                local hx = 24
                local hy = 75
                drawList:AddRectFilled(imgui.ImVec2(hx, hy), imgui.ImVec2(hx + hudW, hy + hudH), 0xEE12141A, 8.0)

                drawList:AddText(imgui.ImVec2(hx + 12, hy + 8), 0xFFFFFFFF, safeU8"3D ЛИНЕЙКА")
                drawList:AddText(imgui.ImVec2(hx + hudW - 80, hy + 8), (rulerMode == 2) and 0xFF00FF88 or 0xFFFFAA00, (rulerMode == 2) and safeU8"[ФИКС]" or safeU8"[ЗАМЕР]")
                drawList:AddLine(imgui.ImVec2(hx + 10, hy + 26), imgui.ImVec2(hx + hudW - 10, hy + 26), 0x44FFFFFF, 1.0)

                drawList:AddText(imgui.ImVec2(hx + 12, hy + 32), (rulerMode == 2) and 0xFF00FF88 or 0xFF00E5FF, safeU8(string.format("Дистанция: %.2f м", dist3D)))
                drawList:AddText(imgui.ImVec2(hx + 12, hy + 50), 0xFFEEEEEE, safeU8(string.format("Горизонталь: %.2f м", dist2D)))
                drawList:AddText(imgui.ImVec2(hx + 12, hy + 66), 0xFFEEEEEE, safeU8(string.format("Перепад (dZ): %+.2f м", dz)))
                drawList:AddText(imgui.ImVec2(hx + hudW - 75, hy + 66), 0xFFAAAAAA, safeU8(string.format("%.1f град.", azimuth)))
            end
        end

        -- Нижняя панель подсказок управления
        local hintStr
        if rulerMode == 0 then
            hintStr = safeU8"[ ЛКМ / 1 ] - Установить точку A   |   [ ESC / /truler ] - Выход"
        elseif rulerMode == 1 then
            hintStr = safeU8"[ ЛКМ / 2 ] - Зафиксировать точку B   |   [ ПКМ / C ] - Сброс   |   [ ESC ] - Выход"
        else
            hintStr = safeU8"[Замер зафиксирован]   |   [ ПКМ / C ] - Новый замер   |   [ ESC ] - Выход"
        end

        local tw = imgui.CalcTextSize(hintStr).x
        local pW = tw + 32
        local pH = 34
        local px1 = (sw - pW) * 0.5
        local py1 = sh - pH - 24
        drawList:AddRectFilled(imgui.ImVec2(px1, py1), imgui.ImVec2(px1 + pW, py1 + pH), 0xEE111822, 6.0)
        drawList:AddText(imgui.ImVec2(px1 + 16, py1 + 8), 0xFFFFFFFF, hintStr)
    end
)
rulerFrame.HideCursor = true
rulerFrame.LockPlayer = false

