local function renderPrefabGhostPreview(drawList)
    if not prefabGhostActive or not prefabGhostTarget or not prefabGhostBounds then return end
    local sw, sh = getScreenResolution()
    local b = prefabGhostBounds

    -- 1. Трассировка луча от камеры на поверхность
    local okCam, camX, camY, camZ = pcall(getActiveCameraCoordinates)
    local okAt, atX, atY, atZ = pcall(getActiveCameraPointAt)
    local fwdX, fwdY, fwdZ = 0, 1, 0
    if okCam and okAt and camX and atX then
        fwdX, fwdY, fwdZ = atX - camX, atY - camY, atZ - camZ
        local l = math.sqrt(fwdX*fwdX + fwdY*fwdY + fwdZ*fwdZ)
        if l > 0.0001 then fwdX, fwdY, fwdZ = fwdX/l, fwdY/l, fwdZ/l end
    else
        camX, camY, camZ = 0, 0, 0
    end

    local maxRay = 90.0
    local toX, toY, toZ = camX + fwdX * maxRay, camY + fwdY * maxRay, camZ + fwdZ * maxRay
    local okLos, hit, colPt = pcall(processLineOfSight, camX, camY, camZ, toX, toY, toZ, true, true, false, true, false, false, false, false)
    local gx, gy, gz
    if okLos and hit and colPt and colPt.pos then
        gx = colPt.pos[1] or colPt.pos.x
        gy = colPt.pos[2] or colPt.pos.y
        gz = (colPt.pos[3] or colPt.pos.z) + prefabGhostZOffset
    else
        local px, py, pz = getCharCoordinates(PLAYER_PED)
        local head = getCharHeading(PLAYER_PED)
        local rHead = math.rad(-head)
        gx = px + math.sin(rHead) * 7.0
        gy = py + math.cos(rHead) * 7.0
        gz = pz + prefabGhostZOffset
    end

    -- Векторы ориентации префаба
    local rad = math.rad(-prefabGhostYaw)
    local ufx = math.sin(rad)
    local ufy = math.cos(rad)
    local urx = ufy
    local ury = -ufx

    -- Базовые координаты (px, py, pz) для спавна
    local px = gx - (b.centerFwd * ufx + b.centerRight * urx)
    local py = gy - (b.centerFwd * ufy + b.centerRight * ury)
    local pz = gz - b.minUp

    -- Вычисляем 8 вершин габаритного бокса
    local function cornerWorld(f, r, u)
        return px + f * ufx + r * urx, py + f * ufy + r * ury, pz + u
    end

    local cWorld = {
        {cornerWorld(b.minFwd, b.minRight, b.minUp)},   -- 1: BLB
        {cornerWorld(b.maxFwd, b.minRight, b.minUp)},   -- 2: FLB
        {cornerWorld(b.maxFwd, b.maxRight, b.minUp)},   -- 3: FRB
        {cornerWorld(b.minFwd, b.maxRight, b.minUp)},   -- 4: BRB
        {cornerWorld(b.minFwd, b.minRight, b.maxUp)},   -- 5: BLT
        {cornerWorld(b.maxFwd, b.minRight, b.maxUp)},   -- 6: FLT
        {cornerWorld(b.maxFwd, b.maxRight, b.maxUp)},   -- 7: FRT
        {cornerWorld(b.minFwd, b.maxRight, b.maxUp)},   -- 8: BRT
    }

    local cScreen = {}
    for i = 1, 8 do
        local wx, wy, wz = cWorld[i][1], cWorld[i][2], cWorld[i][3]
        local dot = (wx - camX)*fwdX + (wy - camY)*fwdY + (wz - camZ)*fwdZ
        if dot > 0.1 then
            local sx, sy = convert3DCoordsToScreen(wx, wy, wz)
            if sx and sy then
                cScreen[i] = imgui.ImVec2(sx, sy)
            end
        end
    end

    -- Рисуем нижнюю грань (площадку на земле)
    if cScreen[1] and cScreen[2] and cScreen[3] and cScreen[4] then
        drawList:AddQuadFilled(cScreen[1], cScreen[2], cScreen[3], cScreen[4], 0x3300FF88)
    end

    -- 12 ребер параллелепипеда
    local edges = {
        {1,2}, {2,3}, {3,4}, {4,1},
        {5,6}, {6,7}, {7,8}, {8,5},
        {1,5}, {2,6}, {3,7}, {4,8}
    }
    local colWire = 0xFF00FF88
    local colWireGlow = 0x5500FF88
    for _, e in ipairs(edges) do
        local p1, p2 = cScreen[e[1]], cScreen[e[2]]
        if p1 and p2 then
            drawList:AddLine(p1, p2, colWireGlow, 4.0)
            drawList:AddLine(p1, p2, colWire, 1.8)
        end
    end

    -- Стрелка направления (на нижней грани)
    local arrowStartWx = px + b.centerFwd * ufx + b.centerRight * urx
    local arrowStartWy = py + b.centerFwd * ufy + b.centerRight * ury
    local arrowEndWx = px + b.maxFwd * ufx + b.centerRight * urx
    local arrowEndWy = py + b.maxFwd * ufy + b.centerRight * ury
    local dotAS = (arrowStartWx - camX)*fwdX + (arrowStartWy - camY)*fwdY + (gz - camZ)*fwdZ
    local dotAE = (arrowEndWx - camX)*fwdX + (arrowEndWy - camY)*fwdY + (gz - camZ)*fwdZ
    if dotAS > 0.1 and dotAE > 0.1 then
        local asx, asy = convert3DCoordsToScreen(arrowStartWx, arrowStartWy, gz)
        local aex, aey = convert3DCoordsToScreen(arrowEndWx, arrowEndWy, gz)
        if asx and asy and aex and aey then
            drawList:AddLine(imgui.ImVec2(asx, asy), imgui.ImVec2(aex, aey), 0xFFFFAA00, 3.0)
            drawList:AddCircleFilled(imgui.ImVec2(aex, aey), 4.5, 0xFFFFAA00)
        end
    end

    -- Точки отдельных объектов внутри бокса
    -- 2. Обновление координат и вращения визуальных 3D-объектов призрака
    local deltaHeading = 0.0
    if prefabGhostTarget.originHeading then
        deltaHeading = shortestAngleDelta(prefabGhostYaw, prefabGhostTarget.originHeading)
    end

    local hasVisualObjects = false
    if prefabGhostObjects and #prefabGhostObjects > 0 then
        for _, item in ipairs(prefabGhostObjects) do
            if item.handle and doesObjectExist(item.handle) then
                hasVisualObjects = true
                local wx = px + item.f * ufx + item.r * urx
                local wy = py + item.f * ufy + item.r * ury
                local wz = pz + item.u

                local wrx, wry, wrz
                if item.rawRX and item.rawRY and item.rawRZ then
                    wrx, wry, wrz = rotateEulerYaw(item.rawRX, item.rawRY, item.rawRZ, deltaHeading)
                else
                    wrx = item.relRX or 0.0
                    wry = item.relRY or 0.0
                    wrz = (prefabGhostYaw + (item.relRZ or 0.0)) % 360
                end

                pcall(setObjectCoordinates, item.handle, wx, wy, wz)
                pcall(setObjectRotation, item.handle, wrx, wry, wrz)
            end
        end
    end

    -- Точки центров объектов (рисуются только если визуальные объекты недоступны)
    if not hasVisualObjects and b.points and #b.points > 0 and #b.points <= 120 then
        for _, pt in ipairs(b.points) do
            local owx = px + pt.f * ufx + pt.r * urx
            local owy = py + pt.f * ufy + pt.r * ury
            local owz = pz + pt.u
            local odot = (owx - camX)*fwdX + (owy - camY)*fwdY + (owz - camZ)*fwdZ
            if odot > 0.1 then
                local osx, osy = convert3DCoordsToScreen(owx, owy, owz)
                if osx and osy then
                    drawList:AddCircleFilled(imgui.ImVec2(osx, osy), 3.0, 0xCC00FF88)
                end
            end
        end
    end

    local prefTitle = safeU8(prefabGhostTarget.name or "Префаб")
    local objCount = prefabGhostTarget.objects and #prefabGhostTarget.objects or #(prefabGhostTarget.steps or {})
    local line1 = safeU8("3D ПРЕДПРОСМОТР ПРЕФАБА: ") .. prefTitle
    local line2 = safeU8(string.format("Габариты: %.1f x %.1f x %.1f м   |   Объектов: %d   |   Угол: %.0f°", b.width, b.length, b.height, objCount, prefabGhostYaw))
    local line3 = safeU8("[ ЛКМ ] Построить   |   [ Q / E / Колесико ] Поворот   |   [ Стрелки ] Высота   |   [ ESC / ПКМ ] Отмена")

    local w1 = imgui.CalcTextSize(line1).x
    local w2 = imgui.CalcTextSize(line2).x
    local w3 = imgui.CalcTextSize(line3).x
    local maxTextW = math.max(w1, math.max(w2, w3))
    local hudW = math.max(820.0, maxTextW + 64.0)
    if hudW > sw - 24.0 then hudW = sw - 24.0 end
    local hudH = 82.0
    local hx = (sw - hudW) * 0.5
    local hy = sh - hudH - 28.0

    drawList:AddRectFilled(imgui.ImVec2(hx, hy), imgui.ImVec2(hx + hudW, hy + hudH), 0xEE12141A, 8.0)
    drawList:AddRect(imgui.ImVec2(hx, hy), imgui.ImVec2(hx + hudW, hy + hudH), 0x33FFFFFF, 8.0, 15, 1.0)

    drawList:AddText(imgui.ImVec2(hx + 20.0, hy + 9.0), 0xFF00FF88, line1)
    drawList:AddText(imgui.ImVec2(hx + 20.0, hy + 31.0), 0xFFDDDDDD, line2)
    drawList:AddText(imgui.ImVec2(hx + 20.0, hy + 53.0), 0xFFFFAA00, line3)

    -- Управление
    if not sampIsChatInputActive() and not sampIsDialogActive() then
        if isKeyJustPressed(0x1B) or isKeyJustPressed(0x02) or imgui.IsMouseClicked(1) then
            clearPrefabGhostObjects()
            prefabGhostActive = false
            showToastQuick("Префабы", "Предпросмотр закрыт")
            return
        end

        if isKeyJustPressed(0x51) then
            local step = isKeyDown(0x10) and 45.0 or (isKeyDown(0x12) and 1.0 or 15.0)
            prefabGhostYaw = (prefabGhostYaw + step) % 360
        elseif isKeyJustPressed(0x45) then
            local step = isKeyDown(0x10) and 45.0 or (isKeyDown(0x12) and 1.0 or 15.0)
            prefabGhostYaw = (prefabGhostYaw - step + 360) % 360
        end

        if isKeyJustPressed(0x26) then
            prefabGhostZOffset = prefabGhostZOffset + (isKeyDown(0x10) and 0.5 or 0.1)
        elseif isKeyJustPressed(0x28) then
            prefabGhostZOffset = prefabGhostZOffset - (isKeyDown(0x10) and 0.5 or 0.1)
        end

        local lmb = isKeyJustPressed(0x01) or imgui.IsMouseClicked(0)
        if lmb then
            clearPrefabGhostObjects()
            prefabGhostActive = false
            playPrefab(prefabGhostTarget, px, py, pz, prefabGhostYaw)
        end
    end
end

-- ============================================================================
-- [STAGE 3] 3D ПРЕДПРОСМОТР ПРЕФАБА В МИРЕ (GHOST 3D BOUNDING BOX)
-- ============================================================================
prefabGhostFrame = imgui.OnFrame(
    function()
        return prefabGhostActive
    end,
    function(self)
        if not prefabGhostActive then return end
        local altDown = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
        if self then
            self.HideCursor = not altDown
            self.LockPlayer = false
        end
        local drawList = imgui.GetBackgroundDrawList()
        renderPrefabGhostPreview(drawList)
    end
)
prefabGhostFrame.HideCursor = true
prefabGhostFrame.LockPlayer = false



local mainFrame = imgui.OnFrame(
    function() return winOpen[0] and not quickTexPositioning and not quickObjPositioning and not quickGrpPositioning end,
    function()
        UpdateAnimations()
        resetTexCounter()
        local curSearchStr = (searchBuf and ffi.string(searchBuf)) or ""
        local currentFilterSig = tostring(activeTab) .. "_" .. tostring(activeCatFilter) .. "_" .. tostring(activeInterior and activeInterior.name or "") .. "_" .. tostring(catGameMode) .. "_" .. curSearchStr .. "_" .. tostring(sortMode) .. "_" .. tostring(#shownObjects)
        if currentFilterSig ~= lastFilterSig or currentPage ~= lastCatalogPage then
            local si_keep = math.max(1, (currentPage - 3) * PAGE_SIZE + 1)
            local ei_keep = math.min((currentPage + 1) * PAGE_SIZE, #shownObjects)
            local protectedIds = {}
            for i = si_keep, ei_keep do
                if shownObjects[i] then
                    local oid = shownObjects[i].id
                    protectedIds[oid] = true
                    if textures[oid] then texLastUsed[oid] = os.clock() end
                end
            end

            -- Очищаем кэш только при превышении лимита (LRU), сохраняя пройденные и ближайшие страницы
            local totalCached = 0
            for _ in pairs(textures) do totalCached = totalCached + 1 end
            if totalCached > MAX_CACHED_TEXTURES then
                local candidates = {}
                for id in pairs(textures) do
                    if not protectedIds[id] then
                        candidates[#candidates + 1] = { id = id, t = texLastUsed[id] or texLoadTimes[id] or 0 }
                    end
                end
                table.sort(candidates, function(a, b) return a.t < b.t end)
                local toDrop = totalCached - 400
                for i = 1, math.min(toDrop, #candidates) do
                    local cid = candidates[i].id
                    if textures[cid] then
                        pcall(imgui.ReleaseTexture, textures[cid])
                        textures[cid] = nil
                        texLastUsed[cid] = nil
                    end
                end
            end

            lastPageIds = protectedIds
            lastCatalogPage = currentPage
            lastFilterSig = currentFilterSig
        end
        
        -- ESC: закрыть детальный просмотр или всё окно
        if isKeyJustPressed(0x1B) then
            if selectedObj then
                selectedObj = nil
            else
                winOpen[0] = false
            
            end
        end

        applyTheme(currentTheme)
        imgui.SetNextWindowPos(imgui.ImVec2(sw / 2, sh / 2), imgui.Cond.Appearing, imgui.ImVec2(0.5, 0.5))
        imgui.SetNextWindowSize(imgui.ImVec2(sw * 0.90, sh * 0.86), imgui.Cond.Always)
        imgui.Begin(u8"TMT##w", winOpen, imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize)

        -- ШАПКА
        imgui.TextColored(accentColor(), "\xef\x83\xa3")
        imgui.SameLine(0, 6)
        imgui.Text(u8"TRINITY MAPPER TOOLS 8.0")
        if imgui.IsItemHovered() then
            imgui.SetTooltip(u8"Автор скрипта Богдан Номинов, сделано с любовью страстью и уважением к каждому созданному объекту")
        end
        imgui.SameLine()
        local closeButtonW = 24
        local faqBtnW = 86
        local histBtnW = 190
        local rightPad = imgui.GetStyle().WindowPadding.x
        imgui.SetCursorPosX(imgui.GetWindowWidth() - rightPad - closeButtonW - faqBtnW - histBtnW - 12)
        imgui.PushStyleVarFloat(imgui.StyleVar.FrameRounding, 4.0)

        local tTheme = THEMES and THEMES[currentTheme]
        local isFaqActive = (activeTab == 16)
        local faqBg = isFaqActive and ((tTheme and tTheme.ButtonA) or accentColorA(0.85)) or ((tTheme and tTheme.Button) or accentColorA(0.20))
        local faqHov = (tTheme and tTheme.ButtonH) or accentColorA(0.70)
        local faqAct = (tTheme and tTheme.ButtonA) or accentColorA(0.90)

        imgui.PushStyleColor(imgui.Col.Button, faqBg)
        imgui.PushStyleColor(imgui.Col.ButtonHovered, faqHov)
        imgui.PushStyleColor(imgui.Col.ButtonActive, faqAct)
        if imgui.Button(fa.ICON_QUESTION_CIRCLE .. safeU8" F.A.Q.##top_faq_btn", imgui.ImVec2(faqBtnW, closeButtonW)) then
            SwitchTab(16); selectedObj = nil
        end
        imgui.PopStyleColor(3)

        imgui.SameLine(0, 6)
        local isHistActive = (activeTab == 14)
        local histBg = isHistActive and ((tTheme and tTheme.ButtonA) or accentColorA(0.85)) or ((tTheme and tTheme.Button) or accentColorA(0.20))
        local histHov = (tTheme and tTheme.ButtonH) or accentColorA(0.70)
        local histAct = (tTheme and tTheme.ButtonA) or accentColorA(0.90)

