        imgui.End() -- закрываем главное окно TMT##w

        -- Модальные окна добавления (Карты, Скрипты, Текстуры) с полноэкранным затемнением фона
        local anyModalOpen = showMapAdd or showScriptAdd or showTexAdd
        local modalKey = showMapAdd and "mapadd" or (showScriptAdd and "scriptadd" or (showTexAdd and "texadd" or nil))
        if not modalKey then
            if popupShouldDraw("mapadd", false) then modalKey = "mapadd"
            elseif popupShouldDraw("scriptadd", false) then modalKey = "scriptadd"
            elseif popupShouldDraw("texadd", false) then modalKey = "texadd"
            end
        end

        if modalKey then
            local a = popupFadeAlpha(modalKey, anyModalOpen)
            if a > 0.005 then
                -- 1. ПОЛНОЭКРАННОЕ ЗАТЕМНЕНИЕ ВСЕГО ЭКРАНА
                imgui.SetNextWindowPos(imgui.ImVec2(0, 0), imgui.Cond.Always)
