                    imgui.SetNextWindowSize(imgui.ImVec2(440, 230), imgui.Cond.Always)
                    imgui.SetNextWindowBgAlpha(0.98 * a)
                    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, a)
                    imgui.Begin(u8"Добавить карту##mapwin", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.NoScrollbar)
                        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"  ДОБАВИТЬ КАРТУ")
                        imgui.Separator(); imgui.Spacing()
                        imgui.Text(u8"Название карты:")
                        imgui.PushItemWidth(-1); imgui.InputText(u8"##mn", mapNameBuf, 64); imgui.PopItemWidth()
                        imgui.Spacing()
                        imgui.Text(u8"Номер карты:")
                        imgui.PushItemWidth(-1); imgui.InputText(u8"##mi", mapIDBuf, 16); imgui.PopItemWidth()
                        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                        local btnW = (imgui.GetContentRegionAvail().x - 10) / 2
                        if imgui.Button(u8"Сохранить##mpsv", imgui.ImVec2(btnW, 36)) then
                            local mn = ffi.string(mapNameBuf); local mi = ffi.string(mapIDBuf)
                            if mn~="" and mi~="" then table.insert(maps,{name=mn,id=mi}); saveMaps() end
                            imgui.StrCopy(mapNameBuf,''); imgui.StrCopy(mapIDBuf,''); showMapAdd=false
                        end
                        imgui.SameLine(0, 10)
                        if imgui.Button(u8"Отмена##mpcn", imgui.ImVec2(btnW, 36)) then
                            imgui.StrCopy(mapNameBuf,''); imgui.StrCopy(mapIDBuf,''); showMapAdd=false
                        end
                    imgui.End()
                    imgui.PopStyleVar()
                elseif popupShouldDraw("scriptadd", showScriptAdd) then
                    imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5,0.5))
                    imgui.SetNextWindowSize(imgui.ImVec2(440, 230), imgui.Cond.Always)
                    imgui.SetNextWindowBgAlpha(0.98 * a)
                    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, a)
                    imgui.Begin(u8"Добавить скрипт##scaddwin", nil, imgui.WindowFlags.NoTitleBar+imgui.WindowFlags.NoResize+imgui.WindowFlags.NoScrollbar)
                        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"  ДОБАВИТЬ СКРИПТ")
                        imgui.Separator(); imgui.Spacing()
                        imgui.Text(u8"Название скрипта:")
                        imgui.PushItemWidth(-1); imgui.InputText(u8"##scn", scriptNameBuf, 64); imgui.PopItemWidth()
                        imgui.Spacing()
                        imgui.Text(u8"Номер скрипта:")
                        imgui.PushItemWidth(-1); imgui.InputText(u8"##sci", scriptIDBuf, 16); imgui.PopItemWidth()
                        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                        local btnW = (imgui.GetContentRegionAvail().x - 10) / 2
                        if imgui.Button(u8"Сохранить##scaddsv", imgui.ImVec2(btnW, 36)) then
                            local sn = ffi.string(scriptNameBuf); local si = ffi.string(scriptIDBuf)
                            if sn~="" and si~="" then table.insert(scripts,{name=sn,id=si,note=""}); saveScripts() end
                            imgui.StrCopy(scriptNameBuf,''); imgui.StrCopy(scriptIDBuf,''); showScriptAdd=false
                        end
                        imgui.SameLine(0, 10)
                        if imgui.Button(u8"Отмена##scaddcn", imgui.ImVec2(btnW, 36)) then
                            imgui.StrCopy(scriptNameBuf,''); imgui.StrCopy(scriptIDBuf,''); showScriptAdd=false
                        end
                    imgui.End()
                    imgui.PopStyleVar()
                elseif popupShouldDraw("texadd", showTexAdd) then
                    imgui.SetNextWindowPos(imgui.ImVec2(sw/2, sh/2), imgui.Cond.Always, imgui.ImVec2(0.5,0.5))
                    imgui.SetNextWindowSize(imgui.ImVec2(440, 245), imgui.Cond.Always)
                    imgui.SetNextWindowBgAlpha(0.98 * a)
                    imgui.PushStyleVarFloat(imgui.StyleVar.Alpha, a)
                    imgui.Begin(u8"Добавить текстуру##texaddwin", nil,
                        imgui.WindowFlags.NoTitleBar + imgui.WindowFlags.NoResize + imgui.WindowFlags.NoScrollbar)
                        imgui.TextColored(imgui.GetStyle().Colors[imgui.Col.ButtonActive], u8"  ДОБАВИТЬ ТЕКСТУРУ")
                        imgui.Separator(); imgui.Spacing()
                        imgui.Text(u8"Название:")
                        imgui.PushItemWidth(-1); imgui.InputText(u8"##txn", texNameBuf, 64); imgui.PopItemWidth()
                        imgui.Spacing()
                        imgui.Text(u8"Номер или название текстуры:")
                        imgui.PushItemWidth(-1); imgui.InputTextWithHint(u8"##txi", u8"Например: 1183 или badge01", texIDBuf, 64); imgui.PopItemWidth()
                        imgui.Spacing(); imgui.Separator(); imgui.Spacing()
                        local btnW = (imgui.GetContentRegionAvail().x - 10) / 2
                        if imgui.Button(u8"Сохранить##texaddsv", imgui.ImVec2(btnW, 36)) then
                            local tn = ffi.string(texNameBuf)
                            local ti = ffi.string(texIDBuf)
                            if ti ~= "" then
                                if tn == "" then tn = ti end
                                table.insert(favTextures, {name=tn, id=ti, note=""})
                                saveFavTextures()
                                showToastQuick("Избранные текстуры", "Текстура добавлена: " .. tn)
                            end
                            imgui.StrCopy(texNameBuf,''); imgui.StrCopy(texIDBuf,'')
