                        end
                    imgui.End()
                    imgui.PopStyleVar()
                end
            end
        end

    end)
    mainFrame.HideCursor = false
    mainFrame.LockPlayer = false

    lua_thread.create(function()
        while not isSampAvailable() do wait(100) end

        local lastCursorMode, lastCursorBlock = nil, nil
        local cursorReassertTimer = 0
        local cursorForceBurst = 0
        while true do
            wait(0)

            -- пока идёт цепочка авто-кликов по диалогам (чулан, пресеты блоков и т.д.) -
            -- держим управление разблокированным каждый кадр, независимо от клавиши ассистента
            if pendingFuAction or dialogMacroQueue or otextQueueActive then
                pcall(lockPlayerControl, false)
                pcall(sampSetCursorMode, 0, false)

                if otextQueueActive and (os.clock() - (otextLastDialogRecvTime or 0)) > 5.0 then
                    otextDebug("!! ТАЙМАУТ 5с: сервер не прислал диалог, шаг " .. tostring(otextQueueIdx))
                    otextQueueActive = false
                    otextTaskQueue = nil
                    otextTriedMainMenu = {}
                    if sampIsDialogActive() and sampCloseCurrentDialogWithButton then
                        pcall(sampCloseCurrentDialogWithButton, 0)
                    end
                end

                -- Сброс при истечении таймаута ожидания ответа сервера
                if dialogMacroQueue and os.clock() > dialogMacroTimeout then
                    dialogMacroQueue = nil
                    dialogMacroState = nil
                    toast_text  = "Таймаут шаблона"
                    toast_text2 = "Сервер не ответил"
                    toast_tex   = nil
                    toast_timer = 120
                end
            end

            if hotkey_just_set then
                hotkey_just_set = false
            elseif isHotkeyPressed() then
                winOpen[0] = not winOpen[0]
            end

            -- Камхак: настраиваемый хоткей — вкл/выкл, ESC — только выход
            if camHackJustSet then
                camHackJustSet = false
            elseif isCamHackPressed() then
                if camHackActive then stopCamHack() else startCamHack() end
            end
            if camHackActive and isKeyJustPressed(0x1B) then
                stopCamHack()
            end

            local scanVk = objScanHotkey_key[0]
            local scanModsOk = scanVk and scanVk > 0
                and (isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)) == (objScanHotkey_alt[0]   == true)
                and (isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)) == (objScanHotkey_ctrl[0]  == true)
                and (isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)) == (objScanHotkey_shift[0] == true)
            local kDown = scanModsOk and isKeyDown(scanVk)
            local objScanTrigger = kDown
                and not winOpen[0]
                and not sampIsChatInputActive() and not sampIsDialogActive()
            objScanCircleVisible = objScanTrigger and objScanCircleEnabled[0]

            if sampIsChatInputActive() and objScanEnabled then
                objScanEnabled = false
                objScanResult = nil
                objScanSubmenu = false
            end

            if objScanTrigger and objScanSubmenu ~= "tex" and objScanSubmenu ~= "rot" then
                objScanRescanCounter = (objScanRescanCounter or 0) + 1
                if objScanRescanCounter >= 5 then
                    objScanRescanCounter = 0
                    local scanned = scanNearestObjLabel()
                    if scanned then
                        objScanResult = scanned
                        objScanEnabled = true
                    end
                end
            else
                objScanRescanCounter = 0
            end
            objScanTriggerDown = objScanTrigger

            if not objScanTrigger and objScanEnabled then
                objScanEnabled = false
                objScanResult = nil
                objScanSubmenu = false
                pcall(lockPlayerControl, false)
                sampSetCursorMode(0, false)
                cursorForceBurst = 20
            end

            if vwLockTime and vwLockTime[0] then
                pcall(setTimeOfDay, vwHour[0], vwMinute[0])
            end

            if vwWinOpen[0] and isKeyJustPressed(0x1B) and not sampIsDialogActive() and not sampIsChatInputActive() then
                vwWinOpen[0] = false
                sampSetCursorMode(0, false)
                cursorForceBurst = 20
            end

            if objListWinOpen[0] and isKeyJustPressed(0x1B) and not sampIsDialogActive() and not sampIsChatInputActive() then
                objListWinOpen[0] = false
                sampSetCursorMode(0, false)
                cursorForceBurst = 20
            end

            if objScanGroupPromptOpen and isKeyJustPressed(0x1B) then
                objScanGroupPromptOpen = false
                sampSetCursorMode(0, false)
                cursorForceBurst = 20
            end

            if (objEditorActive or activeEditingGroupId) and isKeyJustPressed(0x1B) then
                objEditorActive = false
                activeEditingGroupId = nil
                sampSetCursorMode(0, false)
            end

            if objEditorActive and prefabRecording and not prefabPlaying
            and isKeyJustPressed(0x12) then -- Alt: сервер клонирует объект при зажатии во время перетаскивания
                addPrefabStep("/clone", u8"Клонирование: Alt")
            end

            -- Тихий запрос /oinfo при наведении Ассистентом объектов
            if objScanEnabled and objScanResult and objScanResult.type ~= "furniture" and objScanResult.id then
                local curIdStr = tostring(objScanResult.id)
                if oinfoHoverObjId ~= curIdStr then
                    oinfoHoverObjId = curIdStr
                    oinfoHoverStartTime = os.clock()
                end
                if not oinfoCache[curIdStr]
                   and not oinfoSilentPendingId
                   and (os.clock() - (oinfoHoverStartTime or 0)) >= 0.18
                   and (os.clock() - (oinfoLastReqTime or 0)) >= 0.75
                   and not sampIsDialogActive()
                   and not sampIsChatInputActive()
                   and not pendingFuAction
                   and not dialogMacroQueue
                   and not otextQueueActive
                   and not otextPendingApplyAfterCreate
                   and os.clock() > (otextBusyUntil or 0) then
                    oinfoSilentPendingId = curIdStr
                    oinfoSilentExpireTime = os.clock() + 3.5
                    oinfoLastReqTime = os.clock()
                    sampSendChat("/oinfo " .. curIdStr)
                end
            else
                oinfoHoverObjId = nil
            end

            if objScanEnabled and objScanResult then
                if objScanResult.type == "furniture" then
                    if isObjScanActionPressed(0x31) then
                        sendObjScanCommand("/ed " .. objScanResult.id)
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        objEditorActive = true
                        sampSetCursorMode(2, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x32) then
                        pendingFuAction = {mode = "closet", id = objScanResult.id}
                        sendObjScanCommand("/fu " .. objScanResult.id)
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x33) then
                        local objId = objScanResult.id
                        lua_thread.create(function()
                            sampSendChat("/sel " .. objId)
                            wait(300)
                            for slot = 0, 14 do
                                sampSendChat("/mtset " .. slot .. " 0")
                                wait(300)
                            end
                        end)
                    elseif isObjScanActionPressed(0x34) then
                        local clip = getClipboardText() or ""
                        clip = clip:gsub("^%s*(.-)%s*$", "%1")
                        if clip ~= "" then
                            imgui.StrCopy(mtSearchBuf, clip)
                            local objId = objScanResult.id
                            oinfoCache[tostring(objId)] = nil
                            lua_thread.create(function()
                                sampSendChat("/sel " .. objId)
                                wait(300)
                                sampSendChat("/mtset 0 " .. clip)
                            end)
                            showToastQuick("Ассистент", "Нанесено из буфера: " .. clip)
                        else
                            showToastQuick("Буфер пуст", "В буфере обмена нет текста")
                        end
                    elseif isObjScanActionPressed(0x35) then
                        objScanSubmenu = false
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x32) then
                        objScanGroupPromptObjId = objScanResult.id
                        imgui.StrCopy(objScanGroupNumBuf, tostring(objScanSelectedGroup or 1))
                        objScanGroupPromptOpen = true
                        objScanEnabled = false
                        objScanResult = nil
                        objScanSubmenu = false
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(2, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x33) then
                        local objId = objScanResult.id
                        sendObjScanCommand("/gr " .. objId .. " 0")
                        toast_text  = "Объект #" .. tostring(objId) .. " удалён из группы"
                        toast_text2 = ""
                        toast_tex   = nil
                        toast_timer = 150
                        objScanEnabled = false
                        objScanResult = nil
                        objScanSubmenu = false
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x34) then
                        objScanSubmenu = false
                    elseif isKeyJustPressed(0x1B) then
                        objScanEnabled = false
                        objScanResult = nil
                        objScanSubmenu = false
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                    end
                elseif objScanSubmenu == "rot" then
                    local objId = objScanResult.id
                    local function rot(cmd)
                        lua_thread.create(function()
                            sampSendChat("/sel " .. objId)
                            wait(300)
                            sampSendChat(cmd)
                        end)
                    end
                    if isObjScanActionPressed(0x31) then rot("/rz 45")
                    elseif isObjScanActionPressed(0x32) then rot("/rz 90")
                    elseif isObjScanActionPressed(0x33) then rot("/ry 90")
                    elseif isObjScanActionPressed(0x34) then rot("/ry 180")
                    elseif isObjScanActionPressed(0x35) then rot("/rx 45")
                    elseif isObjScanActionPressed(0x36) then rot("/rx 90")
                    elseif isObjScanActionPressed(0x37) then
                        objScanSubmenu = false
                    elseif isKeyJustPressed(0x1B) then
                        objScanEnabled = false
                        objScanResult = nil
                        objScanSubmenu = false
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                    end
                elseif objScanSubmenu == "tex" then
                    if isObjScanActionPressed(0x31) then
                        local curTex = ffi.string(mtSearchBuf)
                        local objId = objScanResult.id
                        oinfoCache[tostring(objId)] = nil
                        lua_thread.create(function()
                            sampSendChat("/sel " .. objId)
                            wait(300)
                            if curTex ~= "" then
                                sampSendChat("/mtset 0 " .. curTex)
                            else
                                sampSendChat("/mtset 0")
                            end
                        end)
                    elseif isObjScanActionPressed(0x32) then
                        local objId = objScanResult.id
                        lua_thread.create(function()
                            sampSendChat("/sel " .. objId)
                            wait(300)
                            sampSendChat("/mtset 0 0")
                        end)
                    elseif isObjScanActionPressed(0x33) then
                        local objId = objScanResult.id
                        lua_thread.create(function()
                            sampSendChat("/sel " .. objId)
                            wait(300)
                            for slot = 0, 14 do
                                sampSendChat("/mtset " .. slot .. " 0")
                                wait(300)
                            end
                        end)
                    elseif isObjScanActionPressed(0x34) then
                        objScanSubmenu = false
                    elseif isKeyJustPressed(0x1B) then
                        objScanEnabled = false
                        objScanResult = nil
                        objScanSubmenu = false
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                    end
                else
                    if isObjScanActionPressed(0x31) then
                        objEditorActive = false
                        sendObjScanCommand("/sel " .. objScanResult.id)
                        ffi.copy(objCtrlIdBuf, objScanResult.id)
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                        cursorForceBurst = 10
                    elseif isObjScanActionPressed(0x32) then
                        sendObjScanCommand("/ed " .. objScanResult.id)
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        objEditorActive = true
                        sampSetCursorMode(2, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x33) then
                        sendObjScanCommand("/del " .. objScanResult.id)
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x34) then
                        sendObjScanCommand("/clone " .. objScanResult.id)
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x35) then
                        sendObjScanCommand("/gotoo " .. objScanResult.id)
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                        cursorForceBurst = 20
                    elseif isObjScanActionPressed(0x36) then
                        objScanSubmenu = "tex"
                    elseif isObjScanActionPressed(0x37) then
                        objScanSubmenu = "group"
                    elseif isObjScanActionPressed(0x38) then
                        objScanSubmenu = "rot"
                    elseif isObjScanActionPressed(0x46) then
                        local oinfo = objScanResult.id and oinfoCache[tostring(objScanResult.id)] or nil
                        if oinfo and (oinfo.gIdxNum ~= "" or oinfo.gIdxFull) then
                            local copyVal = (oinfo.gIdxNum ~= "" and oinfo.gIdxNum) or oinfo.gIdxFull
                            setClipboardText(copyVal)
                            toast_text  = "GLOBAL IDX скопирован: " .. tostring(copyVal)
                            toast_text2 = "Объект #" .. tostring(objScanResult.id)
                            toast_tex   = nil
                            toast_timer = 150
                        else
                            toast_text  = "GLOBAL IDX ещё загружается..."
                            toast_text2 = "Подождите секунду"
                            toast_tex   = nil
                            toast_timer = 120
                        end
                    elseif isKeyJustPressed(0x1B) then
                        objScanEnabled = false
                        objScanResult = nil
                        pcall(lockPlayerControl, false)
                        sampSetCursorMode(0, false)
                    end
                end
            end

            if quickTexJustSet then
                quickTexJustSet = false
            elseif isQuickTexPressed() then
                quickTexOpen = not quickTexOpen
                saveSettings()
            end
            do
                local desiredMode, desiredBlock = nil, nil
                if (winOpen[0] or objScanGroupPromptOpen or objListWinOpen[0] or vwWinOpen[0] or (arrayWinOpen and arrayWinOpen[0])) and not sampIsChatInputActive() and not sampIsDialogActive() then
                    desiredMode, desiredBlock = 2, false
                elseif objEditorActive and not isKeyDown(0x20) and not sampIsChatInputActive() and not sampIsDialogActive() then
                    desiredMode, desiredBlock = 2, false
                elseif (quickTexPositioning or quickObjPositioning or quickGrpPositioning)
                and not sampIsChatInputActive() and not sampIsDialogActive() then
                    desiredMode, desiredBlock = 2, false
                elseif inspectActive and not sampIsChatInputActive() and not sampIsDialogActive() then
                    desiredMode, desiredBlock = 2, false
                elseif (rulerActive or eyedropperActive or prefabGhostActive or quickTexOpen or quickObjOpen or quickGrpOpen) and not winOpen[0]
                and not sampIsChatInputActive() and not sampIsDialogActive() then
                    local altDown = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
                    if altDown then
                        desiredMode, desiredBlock = 2, false
                    else
                        desiredMode, desiredBlock = 0, false
                    end
                elseif not winOpen[0] and not sampIsChatInputActive() and not sampIsDialogActive() then
                    desiredMode, desiredBlock = 0, false
                end

                if cursorForceBurst > 0 and desiredMode then
                    sampSetCursorMode(desiredMode, desiredBlock)
                    lastCursorMode, lastCursorBlock = desiredMode, desiredBlock
                    cursorForceBurst = cursorForceBurst - 1
                elseif desiredMode and (desiredMode ~= lastCursorMode or desiredBlock ~= lastCursorBlock) then
                    sampSetCursorMode(desiredMode, desiredBlock)
                    lastCursorMode, lastCursorBlock = desiredMode, desiredBlock
                end
            end
            -- быстрое создание последнего объёкта
            if quick_just_set then
                quick_just_set = false
            elseif isQuickPressed() and lastCreatedObj then
                addToRecent(lastCreatedObj)
                sampSendChat("/cr "..lastCreatedObj.id)
                sampAddChatMessage(u8"{E07200}[TMT] Быстрое создание: "..lastCreatedObj.name.." ["..lastCreatedObj.id.."]", -1)
            end
            if quickObjJustSet then
                quickObjJustSet = false
            elseif isQuickObjPressed() then
                quickObjOpen = not quickObjOpen
                saveSettings()
            end
            if quickGrpJustSet then
                quickGrpJustSet = false
            elseif isQuickGrpPressed() then
                quickGrpOpen = not quickGrpOpen
                saveSettings()
            end

            if delObjJustSet then
                delObjJustSet = false
            elseif isDelObjPressed() then
                sampSendChat("/del")
            end

            local jetpackDownNow = isJetpackPressed()
            if jetpackJustSet then
                jetpackJustSet = false
            elseif jetpackDownNow and not jetpackKeyWasDown then
                local wearing = false
                if isPlayerWearingJetpack then
                    local ok, res = pcall(isPlayerWearingJetpack, PLAYER_HANDLE)
                    if ok and res then
                        wearing = true
                    end
                end

                if wearing then
                    sampSendChat("/unjpme")
                    jetpackActiveToggle = false
                elseif isPlayerWearingJetpack and (pcall(isPlayerWearingJetpack, PLAYER_HANDLE)) then
                    sampSendChat("/jpme")
                    jetpackActiveToggle = true
                else
                    jetpackActiveToggle = not jetpackActiveToggle
                    if jetpackActiveToggle then
                        sampSendChat("/jpme")
                    else
                        sampSendChat("/unjpme")
                    end
                end
            end
            jetpackKeyWasDown = jetpackDownNow

            if editObjJustSet then
                editObjJustSet = false
            elseif isEditObjPressed() then
                sampSendChat("/ed")
            end

            if cloneObjJustSet then
                cloneObjJustSet = false
            elseif isCloneObjPressed() then
                sampSendChat("/clone")
            end

            if cloneGrpJustSet then
                cloneGrpJustSet = false
            elseif isCloneGrpPressed() then
                if activeEditingGroupId then
                    local gid = tostring(activeEditingGroupId)
                    activeEditingGroupId = nil
                    objEditorActive = false
                    lua_thread.create(function()
                        -- 1. Закрываем GIZMO на клиенте через эмуляцию RPC_SCRCANCELEDIT (118) без нажатия ESC (чтобы Alt+ESC не сворачивал игру!)
                        local bsCancel = raknetNewBitStream()
                        raknetEmulRpcReceiveBitStream(118, bsCancel)
                        raknetDeleteBitStream(bsCancel)

                        -- 2. Отправляем серверу пакет завершения редактирования RPC_EDITOBJECT (117), чтобы сервер снял блокировку с группы
                        if lastGizmoObjectId then
                            local px, py, pz = 0.0, 0.0, 0.0
                            local rx, ry, rz = 0.0, 0.0, 0.0
                            local resp = 0 -- 0 = отмена/закрытие, 1 = сохранение новой позиции
                            if lastGizmoPos and lastGizmoRot then
                                px, py, pz = lastGizmoPos.x, lastGizmoPos.y, lastGizmoPos.z
                                rx, ry, rz = lastGizmoRot.x, lastGizmoRot.y, lastGizmoRot.z
                                resp = 1
                            else
                                local hObj = sampGetObjectHandleBySampId(lastGizmoObjectId)
                                if hObj and hObj ~= -1 and doesObjectExist(hObj) then
                                    local _, ox, oy, oz = getObjectCoordinates(hObj)
                                    px, py, pz = ox or 0.0, oy or 0.0, oz or 0.0
                                end
                            end
                            local bsEdit = raknetNewBitStream()
                            raknetBitStreamWriteBool(bsEdit, lastGizmoPlayerObject and true or false)
                            raknetBitStreamWriteInt16(bsEdit, lastGizmoObjectId)
                            raknetBitStreamWriteInt32(bsEdit, resp)
                            raknetBitStreamWriteFloat(bsEdit, px)
                            raknetBitStreamWriteFloat(bsEdit, py)
                            raknetBitStreamWriteFloat(bsEdit, pz)
                            raknetBitStreamWriteFloat(bsEdit, rx)
                            raknetBitStreamWriteFloat(bsEdit, ry)
                            raknetBitStreamWriteFloat(bsEdit, rz)
                            raknetSendRpc(117, bsEdit)
                            raknetDeleteBitStream(bsEdit)
                        end

                        sampSetCursorMode(0, false)
                        forceCursorNormal()
                        wait(250)
                        sampSendChat("/gclone " .. gid)
                    end)
                end
            end

            if favMapsHotkey_mode[0] then
                favMapsOpen = isFavMapsHeld()
            else
                if favMapsJustSet then
                    favMapsJustSet = false
                elseif isFavMapsPressed() then
                    favMapsOpen = not favMapsOpen
                end
            end

            if favObjHotkey_mode[0] then
                favObjOpen = isFavObjHeld()
            else
                if favObjJustSet then
                    favObjJustSet = false
                elseif isFavObjPressed() then
                    favObjOpen = not favObjOpen
                end
            end

            if assistantHotkey_mode[0] then
                checkboxRenderAll = isAssistantHeld()
                if checkboxRenderAll then checkboxRenderByRule = false end
            else
                if assistantJustSet then
                    assistantJustSet = false
                elseif isAssistantPressed() then
                    checkboxRenderAll = not checkboxRenderAll
                    if checkboxRenderAll then checkboxRenderByRule = false; hideExistingAccessories() end
                end
            end
        end
    end)

function onWindowMessage(msg, wparam, lparam)
    if (msg == 0x100 or msg == 0x101) and wparam == 0x1B then
        if eyedropperActive then
            consumeWindowMessage(true, false)
            eyedropperActive = false
            showToastQuick("Пипетка текстур", "Режим выключен")
            return
        end
        if prefabGhostActive then
            consumeWindowMessage(true, false)
            clearPrefabGhostObjects()
            prefabGhostActive = false
            showToastQuick("Отмена", "Размещение префаба отменено")
            return
        end
        if rulerActive then
            consumeWindowMessage(true, false)
            rulerActive = false
            rulerPointA = nil
            rulerPointB = nil
            rulerMode = 0
            showToastQuick("3D Линейка", "Замер отменен")
            return
        end
        if arrayWinOpen and arrayWinOpen[0] then
            consumeWindowMessage(true, false)
            arrayWinOpen[0] = false
            return
        end
        if winOpen[0] then
            consumeWindowMessage(true, false)
            if selectedObj then
                selectedObj = nil
            else
                winOpen[0] = false
            end
            return
        end
    end

    -- Колесо мыши во время осмотра - приближение/отдаление от объекта
    if msg == 0x20A and prefabGhostActive then
        local delta = bit.arshift(wparam, 16)
        local step = isKeyDown(0x10) and 45.0 or (isKeyDown(0x12) and 1.0 or 15.0)
        if delta > 0 then
            prefabGhostYaw = (prefabGhostYaw + step) % 360
        elseif delta < 0 then
            prefabGhostYaw = (prefabGhostYaw - step + 360) % 360
        end
        consumeWindowMessage(true, false)
        return
    end

    if msg == 0x20A and inspectActive then
        local delta = bit.arshift(wparam, 16)
        if delta > 0 then
            inspectCamDist[0] = math.max(0.5, inspectCamDist[0] - 1.0)
        elseif delta < 0 then
            inspectCamDist[0] = math.min(300.0, inspectCamDist[0] + 1.0)
        end
        consumeWindowMessage(true, false)
    end
end

function main()
    while not isSampAvailable() do wait(100) end
    clearGalleryCache()
    loadIdebaseCategories()
    loadCategories()
    loadMaps()
    loadSettings()
    objScanFont = renderCreateFont("Arial", 9, 1)
    toast_font  = toast_font or renderCreateFont("Arial", 9, 1)
    hintFont    = hintFont   or renderCreateFont("Arial", 8, 1)
    lua_thread.create(function()
        wait(3000)
        checkForUpdates(false)
    end)
    updateHotkeyDisplay()
    updateQuickDisplay()
    updateQuickTexDisplay()
    updateQuickObjDisplay()
    updateQuickGrpDisplay()
    loadMapCategories()
    loadDB()
    loadParticles()
    buildCatCounts()
    loadFavorites()
    loadPrefabs()
    loadAliases()
    loadNotes()
    loadRecent()
    loadScripts()
    loadScriptBlocks()
    loadScriptCards()
    loadScriptCategories()
    loadMapNotes()
    loadFavTextures()
    loadObjExceptions()
    loadObjSearchGroups()
    loadTexCategories()
    loadTexTemplates()
    loadActionArchive()
    applyFilter()
    sampRegisterChatCommand("truler", cmd_ruler)
    sampRegisterChatCommand("drop", cmd_drop)
    sampRegisterChatCommand("dropo", cmd_drop)
    sampRegisterChatCommand("snap", cmd_snap)
    sampRegisterChatCommand("array", cmd_array)
    sampRegisterChatCommand("line", cmd_array)
    sampRegisterChatCommand("tpip", cmd_eyedrop)
    sampRegisterChatCommand("tpp", cmd_eyedrop)
    sampRegisterChatCommand("batchtex", cmd_batchtex)
    local function cmd_prefab_dispatch(param)
        param = param and param:gsub("^%s*(.-)%s*$", "%1") or ""
        if param == "" then
            SwitchTab(13)
            selectedObj = nil
            winOpen[0] = true
            sampSetCursorMode(2)
        else
            local p = nil
            local idx = tonumber(param)
            if idx and prefabs[idx] then
                p = prefabs[idx]
            else
                local low = param:lower()
                for _, pref in ipairs(prefabs) do
                    if pref.name and pref.name:lower():find(low, 1, true) then
                        p = pref
                        break
                    end
                end
            end
            if p then
                startPrefabGhost(p)
            else
                sampAddChatMessage(string.format("{FF9326}[TMT]{FFFFFF} Префаб '%s' не найден.", param), -1)
            end
        end
    end
    sampRegisterChatCommand("prefab", cmd_prefab_dispatch)
    sampRegisterChatCommand("prefabs", cmd_prefab_dispatch)
    sampRegisterChatCommand("TMT", function()
        winOpen[0] = not winOpen[0]
    end)
    sampRegisterChatCommand("tmt", function()
        winOpen[0] = not winOpen[0]
    end)

    lua_thread.create(function()
        while not isSampAvailable() do wait(100) end
        while true do
            if PLAYER_PED and doesCharExist(PLAYER_PED) then
                local ok, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
                if ok and myId and myId ~= -1 then
                    local nick = sampGetPlayerNickname(myId)
                    if nick and nick ~= "" and not nick:find("Invalid") then
                        break
                    end
                end
            end
            wait(300)
        end
        wait(1000)
        local nick = "Player"
        if PLAYER_PED and doesCharExist(PLAYER_PED) then
            local ok, myId = sampGetPlayerIdByCharHandle(PLAYER_PED)
            if ok and myId and myId ~= -1 then
                local n = sampGetPlayerNickname(myId)
                if n and n ~= "" then nick = n end
            end
        end
        local hk = ffi.string(hotkey_display)
        if not hk or hk == "" then hk = "N" end
        sampAddChatMessage('{FF9326}[Trinity Mapper Tools] {FFFFFF}Добро пожаловать на сервер, маппер {FF9326}' .. nick, -1)
        sampAddChatMessage('{FFFFFF}Для активации меню скрипта используйте клавишу {FF9326}' .. hk .. '{FFFFFF} или команду {FF9326}/tmt', -1)
    end)

    sampRegisterChatCommand("del", function(params)
        local ids = {}
        for id in params:gmatch("%d+") do
            table.insert(ids, id)
        end

        if #ids == 0 then
            local targetObj = (objScanResult and objScanResult.id) or lastEditedObjId
            if not targetObj then
                local nearest = scanNearestObjLabel and scanNearestObjLabel()
                if nearest and nearest.id then targetObj = nearest.id end
            end
            if targetObj then
                local snap = snapshotObject(targetObj)
                if snap then lastDeletedSnapshot = snap end
            end
            sampSendChat("/del")
            return
        end

        lua_thread.create(function()
            for _, id in ipairs(ids) do
                local snap = snapshotObject(id)
                if snap then lastDeletedSnapshot = snap end
                sampSendChat("/del " .. id)
                wait(300)
            end
        end)
    end)

    sampRegisterChatCommand("undodel", function()
        if not lastDeletedSnapshot then
            sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Нет сохранённых удалённых объектов для восстановления.", -1)
            return
        end
        restoreDeletedObject(lastDeletedSnapshot)
    end)

    sampRegisterChatCommand("rdel", function()
        if not lastDeletedSnapshot then
            sampAddChatMessage("{FF9326}[TMT]{FFFFFF} Нет сохранённых удалённых объектов для восстановления.", -1)
            return
        end
        restoreDeletedObject(lastDeletedSnapshot)
    end)

    sampRegisterChatCommand("gr", function(params)
        -- Диапазон: /gr [номер группы] [от-до]
        local rangeGroupId, rangeStart, rangeEnd = params:match("^%s*(%d+)%s+(%d+)%s*%-%s*(%d+)%s*$")
        if rangeGroupId then
            rangeStart = tonumber(rangeStart)
            rangeEnd   = tonumber(rangeEnd)
            if rangeStart > rangeEnd then
                sampAddChatMessage("{CFCFCF}[TMT] Ошибка:{CFCFCF} начальный ID не может быть больше конечного.", -1)
                return
            end
            lua_thread.create(function()
                for i = rangeStart, rangeEnd do
                    sampSendChat("/gr " .. i .. " " .. rangeGroupId)
                    wait(300)
                end
            end)
            return
        end

        -- Список ID через пробел: /gr [номер группы] [ID1 ID2 ID3]
        local nums = {}
        for n in params:gmatch("%d+") do
            table.insert(nums, n)
        end

        if #nums < 2 then
            sampAddChatMessage('{CFCFCF}Подсказка: {FF9326}/gr [номер группы] [ID1 ID2 ID3]', -1)
            sampAddChatMessage('{CFCFCF}Или диапазон: {FF9326}/gr [номер группы] [от-до]{CFCFCF}, например {FF9326}/gr 1 5-25', -1)
            sampAddChatMessage('{CFCFCF}Данная команда добавляет в группу один, или несколько объектов.', -1)
            return
        end

        local groupId = nums[1]
        lua_thread.create(function()
            for i = 2, #nums do
                sampSendChat("/gr " .. nums[i] .. " " .. groupId)
                wait(300)
            end
        end)
    end)

-- Переменная для хранения потока удаления
mdelThread = nil

function cmd_mdel(arg)
    -- Если поток уже запущен, останавливаем его
    if mdelThread and mdelThread:status() ~= "dead" then
        mdelThread:terminate()
        mdelThread = nil
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое удаление остановлено.", -1)
        return
    end

    local start_id, end_id = arg:match("^(%d+)%s*%-%s*(%d+)$")
    if not start_id or not end_id then
            sampAddChatMessage('{CFCFCF}Подсказка: {FF9326}/mdel [значение от и до]', -1)
            sampAddChatMessage('{CFCFCF}Данная команда удаляет объекты от и до.', -1)
            sampAddChatMessage(' ', -1)
            sampAddChatMessage('{CFCFCF}Пример: {FF9326}/mdel 10-25, {CFCFCF}скрипт удалит объекты {FF9326}от 10 до 25{CFCFCF}.', -1)
            sampAddChatMessage('{CFCFCF}Чтобы остановить удаление объектов, введите команду {FF9326}/mdel {CFCFCF}снова.', -1)
        return
    end

    start_id = tonumber(start_id)
    end_id = tonumber(end_id)

    if start_id > end_id then
        sampAddChatMessage("{FF9326}[TMT] Ошибка:{CFCFCF} Начальный ID не может быть больше конечного.", -1)
        return
    end

    sampAddChatMessage(string.format("{FF9326}[TMT]{CFCFCF} Массовое удаление с %d по %d запущено.", start_id, end_id), -1)
    
    mdelThread = lua_thread.create(function()
        for i = start_id, end_id do
            sampSendChat("/del " .. i)
            wait(500) -- задержка 0.5 секунд
        end
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое удаление успешно завершено.", -1)
        mdelThread = nil
    end)
end

sampRegisterChatCommand("mdel", cmd_mdel)

-- Переменная для хранения потока массового добавления в группу
mgrThread = nil

function cmd_mgr(arg)
    -- Если поток уже запущен, останавливаем его
    if mgrThread and mgrThread:status() ~= "dead" then
        mgrThread:terminate()
        mgrThread = nil
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое добавление в группу остановлено.", -1)
        return
    end

    -- Парсим аргументы (ищем шаблон "число-число число")
    local start_id, end_id, group_id = arg:match("^(%d+)%s*%-%s*(%d+)%s+(%d+)$")
    if not start_id or not end_id or not group_id then
        sampAddChatMessage('{CFCFCF}Подсказка: {FF9326}/mgr [значение от и до] [номер группы]', -1)
        sampAddChatMessage('{CFCFCF}Пример: {FF9326}/mgr 1-50 1, {CFCFCF}скрипт добавит объекты {FF9326}от 1 до 50 {CFCFCF}в группу {FF9326}1.', -1)
        sampAddChatMessage(' ', -1)
        sampAddChatMessage('{CFCFCF}Чтобы остановить добавление объектов, введите команду {FF9326}/mgr {CFCFCF}снова.', -1)
        sampAddChatMessage('{CFCFCF}Данная команда добавляет объекты от и до в указанную группу.', -1)
        return
    end

    start_id = tonumber(start_id)
    end_id   = tonumber(end_id)
    group_id = tonumber(group_id)

    if start_id > end_id then
        sampAddChatMessage("{FF9326}[TMT] Ошибка:{CFCFCF} Начальный ID не может быть больше конечного.", -1)
        return
    end

    sampAddChatMessage(string.format("{FF9326}[TMT]{CFCFCF} Массовое добавление в группу %d (объекты %d-%d) запущено.", group_id, start_id, end_id), -1)

    mgrThread = lua_thread.create(function()
        for i = start_id, end_id do
            sampSendChat("/gr " .. i .. " " .. group_id)
            wait(500) -- задержка 0.5 секунд
        end
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое добавление в группу успешно завершено.", -1)
        mgrThread = nil
    end)
end

sampRegisterChatCommand("mgr", cmd_mgr)

