    local hNum = tonumber(h)
    if hNum and hNum >= 0 and hNum <= 23 then
        local mNum = tonumber(m) or 0
        applyVwTime(hNum, mNum, true)
        sampAddChatMessage(string.format('{FF9326}[TMT]{CFCFCF} Установлено время суток: {FF9326}%02d:%02d{CFCFCF}. (Сброс: /st без параметров)', vwHour[0], vwMinute[0]), -1)
    else
        vwLockTime[0] = false
        patchSampTimeSet(false)
        sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Фиксация времени отключена. Подсказка: {FF9326}/st [0-23]{CFCFCF} или меню {FF9326}/vw', -1)
    end
end)

sampRegisterChatCommand("sw", function(params)
    local wNum = tonumber(params:match("^%s*(%d+)%s*$"))
    if wNum and wNum >= 0 and wNum <= 45 then
        applyVwWeather(wNum)
        sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Установлена погода: {FF9326}#' .. tostring(vwWeather[0]), -1)
    else
        sampAddChatMessage('{CFCFCF}Подсказка: {FF9326}/sw [0-45]{CFCFCF} или откройте меню с ползунками {FF9326}/vw', -1)
    end
end)

sampRegisterChatCommand("greset", function(params)
    local gid, slotArg = params:match("^%s*(%d+)%s*(%d*)%s*$")
    if gid and gid ~= "" then
        if slotArg and slotArg ~= "" then
            sampSendChat("/gmtset " .. gid .. " " .. slotArg .. " 0")
            sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Текстура слота ' .. slotArg .. ' сброшена у группы #' .. gid .. '.', -1)
        else
            sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Сброс текстур для группы #' .. gid .. ' запущен...', -1)
            lua_thread.create(function()
                for s = 0, 14 do
                    sampSendChat("/gmtset " .. gid .. " " .. s .. " 0")
                    wait(300)
                end
                sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Текстуры группы #' .. gid .. ' сброшены.', -1)
            end)
        end
        return
    end
    ffi.fill(objScanGroupNumBuf, 8, 0)
    sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Запомненный номер группы в ассистенте сброшен. (Для сброса текстур группы: {FF9326}/greset [id группы]{CFCFCF})', -1)
end)

function cmd_grset(params)
    local num = tonumber(params:match("^%s*(%d+)%s*$"))
    if not num or num < 1 or num > 100 then
        local cur = tostring(objScanSelectedGroup or 1)
        sampAddChatMessage('{CFCFCF}Использование: {FF9326}/grset [номер группы 1-100]{CFCFCF} (Текущая группа: #{FF9326}' .. cur .. '{CFCFCF})', -1)
        sampAddChatMessage('{CFCFCF}Устанавливает номер группы для быстрого добавления в {FF9326}Ассистенте объектов{CFCFCF}.', -1)
        return
    end
    objScanSelectedGroup = num
    imgui.StrCopy(objScanGroupNumBuf, tostring(num))
    sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Группа для ассистента объектов установлена: {FF9326}#' .. tostring(num) .. '{CFCFCF}.', -1)
end
sampRegisterChatCommand("grset", cmd_grset)
sampRegisterChatCommand("gtex", cmd_grset)

sampRegisterChatCommand("tex", function(params)
    local texId = params:match("^%s*(%d+)%s*$")
    if not texId then
        sampAddChatMessage('{CFCFCF}Подсказка: {FF9326}/tex [номер текстуры]', -1)
        sampAddChatMessage('{CFCFCF}Устанавливает текстуру, которая будет {FF9326}применяться{CFCFCF} из ассистента по объектам.', -1)
        return
    end
    ffi.fill(mtSearchBuf, 16, 0)
    ffi.copy(mtSearchBuf, texId)
    sampAddChatMessage('{FF9326}[TMT]{CFCFCF} Текстура для ассистента установлена: ' .. texId, -1)
end)

-- Переменная для хранения потока массового перемещения групп
mgmoveThread = nil

function cmd_mgmove(arg)
    -- Если поток уже запущен, останавливаем его
    if mgmoveThread and mgmoveThread:status() ~= "dead" then
        mgmoveThread:terminate()
        mgmoveThread = nil
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое перемещение групп остановлено.", -1)
        return
    end

    -- Парсим аргументы: первое число — куда переместить (или 0 для сброса), остальные — какие группы переместить
    local nums = {}
    for n in arg:gmatch("%d+") do
        table.insert(nums, tonumber(n))
    end

    if #nums < 2 then
        sampAddChatMessage('{CFCFCF}Подсказка: {FF9326}/mgmove [номер группы] [группа1] [группа2] [группа3]', -1)
        sampAddChatMessage('{CFCFCF}Пример: {FF9326}/mgmove 5 1 2 3{CFCFCF}, скрипт переместит группы {FF9326}1{CFCFCF}, {FF9326}2{CFCFCF} и {FF9326}3{CFCFCF} в группу 5.', -1)
        sampAddChatMessage(' ', -1)
        sampAddChatMessage('{CFCFCF}Чтобы остановить перемещение групп, введите команду {FF9326}/mgmove {CFCFCF}снова.', -1)
        return
    end

    local dest = nums[1]
    local groups = {}
    for i = 2, #nums do
        table.insert(groups, nums[i])
    end

    sampAddChatMessage(string.format("{FF9326}[TMT]{CFCFCF} Массовое перемещение %d групп(ы) в группу %d запущено.", #groups, dest), -1)

    mgmoveThread = lua_thread.create(function()
        for _, g in ipairs(groups) do
            sampSendChat("/gmove " .. g .. " " .. dest)
            wait(500) -- задержка 0.5 секунд
        end
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое перемещение групп успешно завершено.", -1)
        mgmoveThread = nil
    end)
end

sampRegisterChatCommand("mgmove", cmd_mgmove)

-- Переменная для хранения потока массового нанесения текстур на объекты
mtexThread = nil

function cmd_mtex(arg)
    if mtexThread and mtexThread:status() ~= "dead" then
        mtexThread:terminate()
        mtexThread = nil
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое нанесение текстуры остановлено.", -1)
        return
    end

    local nums = {}
    for n in arg:gmatch("%d+") do
        table.insert(nums, tonumber(n))
    end

    if #nums < 2 then
        sampAddChatMessage('{CFCFCF}Подсказка: {FF9326}/mtex [объект1] [объект2] [объект3] [номер текстуры]', -1)
        sampAddChatMessage('{CFCFCF}Пример: {FF9326}/mtex 1 2 3 8993{CFCFCF}, скрипт нанесёт текстуру {FF9326}8993{CFCFCF} на объекты {FF9326}1{CFCFCF}, {FF9326}2{CFCFCF} и {FF9326}3{CFCFCF}.', -1)
        sampAddChatMessage(' ', -1)
        sampAddChatMessage('{CFCFCF}Чтобы остановить нанесение текстуры, введите команду {FF9326}/mtex {CFCFCF}снова.', -1)
        return
    end

    local texId = nums[#nums]
    local objs = {}
    for i = 1, #nums - 1 do
        table.insert(objs, nums[i])
    end

    sampAddChatMessage(string.format("{FF9326}[TMT]{CFCFCF} Массовое нанесение текстуры %d на %d объект(ов) запущено.", texId, #objs), -1)

    mtexThread = lua_thread.create(function()
        for _, objId in ipairs(objs) do
            sampSendChat("/sel " .. objId)
            wait(300)
            sampSendChat("/mtset 0 " .. texId)
            wait(300)
        end
        sampAddChatMessage("{FF9326}[TMT]{CFCFCF} Массовое нанесение текстуры успешно завершено.", -1)
        mtexThread = nil
    end)
end

sampRegisterChatCommand("mtex", cmd_mtex)

    
