lua_thread.create(function()
        local hintActions = {
            {label = "Удалить объект",       alt=delObjHotkey_alt,   ctrl=delObjHotkey_ctrl,   shift=delObjHotkey_shift,   key=delObjHotkey_key},
            {label = "Редактировать объект",  alt=editObjHotkey_alt,  ctrl=editObjHotkey_ctrl,  shift=editObjHotkey_shift,  key=editObjHotkey_key},
            {label = "Клонировать объект",    alt=cloneObjHotkey_alt, ctrl=cloneObjHotkey_ctrl, shift=cloneObjHotkey_shift, key=cloneObjHotkey_key},
            {label = "Клонировать группу",    alt=cloneGrpHotkey_alt, ctrl=cloneGrpHotkey_ctrl, shift=cloneGrpHotkey_shift, key=cloneGrpHotkey_key},
        }

        while true do
            wait(0)
            if hintsEnabled and hintFont and not sampIsChatInputActive() and not sampIsDialogActive() then
                local altDown   = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
                local ctrlDown  = isKeyDown(0x11) or isKeyDown(0xA2) or isKeyDown(0xA3)
                local shiftDown = isKeyDown(0x10) or isKeyDown(0xA0) or isKeyDown(0xA1)

                if altDown or ctrlDown or shiftDown then
                    local lines = {}
                    for _, act in ipairs(hintActions) do
                        if act.key[0] > 0
                        and (act.alt[0]   == true) == altDown
                        and (act.ctrl[0]  == true) == ctrlDown
                        and (act.shift[0] == true) == shiftDown then
                            local parts = {}
                            if act.alt[0]   then parts[#parts+1] = "Alt"   end
                            if act.ctrl[0]  then parts[#parts+1] = "Ctrl"  end
                            if act.shift[0] then parts[#parts+1] = "Shift" end
                            local kname = keyName(act.key[0])
                            if parts[#parts] ~= kname then parts[#parts+1] = kname end
                            table.insert(lines, table.concat(parts, " + ") .. " - " .. act.label)
                        end
                    end

                    if #lines > 0 then
                        local boxW = 260
                        local boxH = 22 + #lines * 16
                        local x = sw - boxW - 20
                        local y = sh - 95 - boxH - 10
                        local hintAccent = 0xFF000000 + accentColorHex()
                        renderDrawBox(x, y, boxW, boxH, 0xCC111111)
                        renderDrawBox(x, y, 4, boxH, hintAccent)
                        renderFontDrawText(hintFont, "Подсказки", x + 12, y + 6, hintAccent)
                        for i, line in ipairs(lines) do
                            renderFontDrawText(hintFont, line, x + 12, y + 6 + 16 * i, 0xFFFFFFFF)
                        end
                    end
                end
            end
        end
    end)

    lua_thread.create(function()
        while true do
            wait(0)
            local xKeyHeld = xMenuHotkey_key[0] and xMenuHotkey_key[0] > 0 and isKeyDown(xMenuHotkey_key[0])
            if (checkboxRenderAll or checkboxRenderByRule or xKeyHeld)
            and not sampIsChatInputActive() and not sampIsDialogActive() then
                local altDown = isKeyDown(0x12) or isKeyDown(0xA4) or isKeyDown(0xA5)
                if not altDown and not objScanEnabled and PLAYER_PED and doesCharExist(PLAYER_PED) then
                    local px, py, pz = getCharCoordinates(PLAYER_PED)
                    local best, bestScreenDist = nil, 350.0
                    local cx, cy = sw / 2, sh / 2
                    xMenuActiveHandle = nil
                    for _, v in pairs(getAllObjects()) do
                        if isObjectOnScreen(v) and not isPauseMenuActive() then
                            local _, x, y, z = getObjectCoordinates(v)
                            local model = getObjectModel(v)
                            if sampObjectModelNames[model] then
                                local dist = getDistanceBetweenCoords3d(x, y, z, px, py, pz)
                                if dist > 1.5 and dist < 60.0 then
                                    local sx, sy = convert3DCoordsToScreen(x, y, z)
                                    if sx and sy then
                                        local screenDist = math.sqrt((sx - cx)^2 + (sy - cy)^2)
                                        if screenDist < bestScreenDist then
                                            bestScreenDist = screenDist
                                            best = {model = model, name = sampObjectModelNames[model], sx = sx, sy = sy}
                                            xMenuActiveHandle = v
                                        end
                                    end
                                end
                            end
                        end
                    end

                    if best then
                        local boxW, boxH = 260, 100
                        local x = best.sx + 24
                        local y = best.sy - boxH / 2
                        if x + boxW > sw then x = best.sx - boxW - 24 end
                        if y < 10 then y = 10 end
                        if y + boxH > sh - 10 then y = sh - boxH - 10 end

                        local imgSize = 64
                        local tex = getNativeTex(tostring(best.model))
                        local textX = x + 12

                        local xMenuAccent = 0xFF000000 + accentColorHex()

                        renderDrawBox(x, y, boxW, boxH, 0xCC111111)
                        renderDrawBox(x, y, 4, boxH, xMenuAccent)

                        if tex then
                            renderDrawTexture(tex, x + boxW - imgSize - 10, y + (boxH - imgSize) / 2, imgSize, imgSize, 0, -1)
                            textX = x + 12
                        end

                        if not hintFont then hintFont = renderCreateFont("Arial", 8, 1) end
                        if hintFont then
                            renderFontDrawText(hintFont, tostring(best.name or "") .. " (" .. tostring(best.model) .. ")", textX, y + 6, xMenuAccent)
                            renderFontDrawText(hintFont, "1 - В избранное", textX, y + 30, 0xFFFFFFFF)
                            renderFontDrawText(hintFont, "2 - Скопировать ID", textX, y + 48, 0xFFFFFFFF)
                            renderFontDrawText(hintFont, "3 - Создать объект", textX, y + 66, 0xFFFFFFFF)
                        end

                        local modelStr = tostring(best.model)

                        if isKeyJustPressed(0x31) then -- "1"
                            favorites[modelStr] = true
                            saveFavorites()
                            toast_text  = "Добавлено в избранное"
                            toast_text2 = best.name
                            toast_timer = 150
                            toast_tex   = nil
                        elseif isKeyJustPressed(0x32) then -- "2"
                            setClipboardText(modelStr)
                            toast_text  = "ID скопирован: " .. modelStr
                            toast_text2 = best.name
                            toast_timer = 150
                            toast_tex   = nil
                        elseif isKeyJustPressed(0x33) then -- "3"
                            sampSendChat("/cr " .. modelStr)
                            addToRecent({id = modelStr, name = best.name})
                            toast_text  = "Создание объекта"
                            toast_text2 = best.name
                            toast_timer = 150
                            toast_tex   = nil
                        end
                    end
                else
                    xMenuActiveHandle = nil
                end
            end
        end
    end)

