                                    end
                                    if traser then
                                        if rgbtraser then
                                            renderDrawLine(x10, y10, x1, y1, 1.0, color)
                                        else
                                            renderDrawLine(x10, y10, x1, y1, 1.0, -1)
                                        end
                                    end
                                end
                            end
                        elseif isSearchTarget then
                            renderFontDrawText(
                                objRenderFont,
                                "model: " .. (sampObjectModelNames[model] or objSearchTargets[model]) .. "(" .. model .. ")",
                                x1, y1, 0xFF00FF00
                            )
                            if traser then
                                if rgbtraser then
                                    renderDrawLine(x10, y10, x1, y1, 1.0, color)
                                else
                                    renderDrawLine(x10, y10, x1, y1, 1.0, -1)
                                end
                            end
                        end
                    end
                end
            end
        end
    end)

    wait(-1)

end
function onScriptTerminate(script, quitGame)
    if script == thisScript() then
        clearPrefabGhostObjects()
        clearGalleryCache()
    end
end
